/* ÇEVİRİ id · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("id","olay",{
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Pembunuhan Sultan İbrahim", "bc4eb452"], "d": ["Dengan alasan pemborosan dan krisis pemerintahan, aliansi ocak-ulama menurunkan İbrahim dari takhta; sepuluh hari kemudian ia dicekik berdasarkan fatwa. Mehmed IV yang berusia tujuh tahun naik takhta; kekuasaan secara de facto beralih ke tangan valide agung Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Wafatnya Kâtib Çelebi", "e167e89d"], "d": ["Tokoh puncak sejarah ilmu Utsmaniyah dengan bibliografi Keşfü'z-zunûn dan geografi Cihannümâ; dikenal dengan pendekatan perintisnya yang menggunakan sumber-sumber Eropa.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Peristiwa Edirne — pemakzulan Mustafa II", "0291c1cd"], "d": ["Kemarahan atas menetapnya sultan di Edirne dan pengaruh Feyzullah Efendi berubah menjadi pemberontakan besar tentara-pedagang; şeyhülislâm dilinci, sultan diturunkan dari takhta, dan istana kembali ke Istanbul.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Duta besar ke Paris: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["Kedutaan besar yang dikirim ke Prancis adalah pengamatan sistematis pertama yang mengkaji Barat di tempat; Sefâretnâme-nya mengilhami pembaruan Era Tulip.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Percetakan Utsmaniyah pertama didirikan", "4943f7e5"], "d": ["Izin mencetak buku berbahasa Turki diberikan; karya pertama, Kamus Vankulu, dicetak pada 1729. Percetakan adalah warisan paling abadi dari pembaruan Era Tulip.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Kapitulasi dijadikan permanen", "d044a79e"], "d": ["Imtiyaz yang diberikan kepada Prancis dikeluarkan dari batas sultan dan diikat dalam perjanjian permanen; rezim kapitulasi yang tidak dapat lagi dibatalkan secara sepihak baru dapat dihapus di Lausanne.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Mühendishâne-i Bahrî-i Hümâyun didirikan", "9bf3f439"], "d": ["Sekolah teknik yang didirikan untuk mendidik perwira laut modern setelah bencana Çeşme ini adalah lembaga pendidikan teknik bergaya Barat pertama yang permanen; sekolah teknik darat menyusul pada 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Kedutaan tetap pertama di London", "6b5630eb"], "d": ["Sebagai bagian dari program Nizâm-ı Cedîd, kedutaan tetap dibuka di ibu kota-ibu kota Eropa; diplomasi Utsmaniyah beralih ke asas timbal balik.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Wafatnya Alemdar Mustafa Paşa", "4426534e"], "d": ["Dalam pemberontakan janisari yang dimulai pada malam 15 November 1808, sadrazam reformis yang terkepung di Bâbıâli menyulut gudang amunisi pada hari berikutnya ketika bantuan yang ditunggu tidak datang dan tewas bersama ratusan penyerang; tatanan Sened-i İttifak dan percobaan reformasi pertama dikubur bersamanya.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Surat kabar resmi pertama: Takvîm-i Vekāyi", "c637f623"], "d": ["Surat kabar resmi negara mulai terbit; ini awal tradisi opini publik modern dan pengumuman resmi.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Perjanjian Dagang Balta Limanı", "e790b383"], "d": ["Inggris diberi kedudukan paling istimewa bahkan dalam perdagangan dalam negeri, sistem yed-i vahit (monopoli) dihapus; ketika produksi lokal dibiarkan tanpa perlindungan, perjanjian ini menjadi dokumen pembukaan penuh pasar Utsmaniyah bagi perdagangan bebas.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Berakhirnya Emirat Lebanon — pencopotan Beşîr Şihâb III", "f85ae454"], "d": ["Emir Beşîr II (III), yang tidak dapat mengendalikan pertikaian Kristen-Druze dan keseimbangan internal di wilayah Shuf, dicopot pada Januari 1842; tatanan emirat lokal yang berlangsung sejak 1516 (melalui keluarga Ma'noğulları dan kemudian Şihâboğulları) berakhir, dan wilayah itu beralih ke pemerintahan langsung Utsmaniyah, lalu ke sistem dua kaymakam.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: tatanan Mecidiye", "c77be809"], "d": ["Dengan reformasi moneter, koin-koin yang kadarnya rusak ditarik; tatanan dwi-logam yang stabil berbasis lira emas (Mecidiye) dibentuk.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Berakhirnya kekuasaan lokal keluarga Harfûş di Baalbek", "8438f4ae"], "d": ["Pengaruh keluarga Harfûş, yang sejak 1521 (setelah pemberontakan Canbirdi Gazâlî) memerintah Baalbek sebagai dinasti lokal kecil, berakhir dengan penataan administratif baru Bâbıâli; kota itu dijadikan pusat kaza biasa yang terikat pada vilayet Damaskus.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Şirket-i Hayriyye didirikan", "462830e7"], "d": ["Perusahaan yang didirikan untuk mengoperasikan kapal uap di Bosporus ini dianggap perseroan terbatas Utsmaniyah pertama; dermaga kapal uap mewarnai kehidupan kota.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Kontrak utang luar negeri pertama", "9017c579"], "d": ["Untuk membiayai Perang Krimea, pinjaman luar negeri pertama diambil dari pasar London; titik yang dicapai dengan 15 kali pinjaman dalam 21 tahun adalah moratorium 1875 dan Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Jalur telegraf di Istanbul", "d320f39f"], "d": ["Jalur telegraf pertama, yang dibangun karena kebutuhan Perang Krimea, dibuka untuk operasi; dalam beberapa puluh tahun kekaisaran memiliki salah satu jaringan telegraf terluas di dunia.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Kanunname Tanah (Arazi Kanunnâmesi)", "6bae243a"], "d": ["Kanunname yang memodernisasi hukum pertanahan ini mengikat penguasaan faktual atas tanah mîrî pada tapu; ia salah satu dokumen dasar tatanan kepemilikan Timur Tengah masa kini.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Kuliah pertama di Dârülfünun", "08f74066"], "d": ["Dârülfünun, yang akan memberi pendidikan tingkat universitas, mulai bekerja dengan kuliah umum; lembaga yang berlanjut dengan jeda ini dibuka secara permanen pada 1900 dan menjadi inti Universitas Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Peraturan Vilayet (Vilâyet Nizamnâmesi)", "ad20853b"], "d": ["Organisasi vilayet model Prancis didirikan menggantikan tatanan eyalet; menjadikan penerapan Midhat Paşa di Vilayet Danube sebagai contoh, ia diperluas ke seluruh negeri.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Perjalanan Abdülaziz ke Eropa", "9ff0fa1e"], "d": ["Perjalanan pertama seorang sultan Utsmaniyah ke Eropa dengan tujuan damai; pameran Paris dan kunjungan ke London berfungsi sebagai etalase diplomasi sekaligus modernisasi.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Galatasaray Mekteb-i Sultânîsi dibuka", "f9688524"], "d": ["Lisée berbahasa Prancis ini, dengan komposisi murid yang tidak membedakan agama dan bangsa, menjadi simbol cita-cita kesetaraan Tanzimat dalam pendidikan.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Kitab pertama Mecelle berlaku", "6475461c"], "d": ["Mecelle, yang menghimpun bidang perikatan dan benda dalam hukum Islam dengan teknik perundang-undangan modern, dianggap kitab undang-undang perdata Islam pertama; panitia di bawah Cevdet Paşa menyelesaikan 16 kitab pada 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Pemakzulan Abdülaziz", "eb7397ea"], "d": ["Para negarawan konstitusionalis dan petinggi militer menurunkan Abdülaziz dalam kudeta senyap; kematiannya yang mencurigakan lima hari kemudian dan peristiwa Çırağan yang menyusul melahirkan perhitungan yang berlangsung bertahun-tahun.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Serbuan Çırağan (peristiwa Ali Suâvi)", "d2a9ac87"], "d": ["Jurnalis Ali Suâvi menyerbu Çırağan untuk menaikkan kembali Murad V ke takhta; serbuan itu ditumpas secara berdarah, dan rezim Abdülhamid memperketat lingkar keamanannya secara permanen.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Administrasi Régie didirikan (monopoli tembakau)", "bad9b030"], "d": ["Pendapatan tembakau diserahkan kepada perusahaan Régie bermodal asing di bawah Düyûn-ı Umûmiyye; bentrokan 'penyelundupan Régie' antara petani dan penjaga berlangsung selama puluhan tahun. Permukiman lain yang lepas pada tanggal yang sama: Zeyla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Kunjungan Kaisar Wilhelm II ke Istanbul dan Yerusalem", "2988cd06"], "d": ["Kunjungan kedua kaisar Jerman memperkuat kedekatan Utsmaniyah-Jerman; jalan konsesi kereta api Baghdad terbuka, dan di Damaskus diucapkan pidato 'sahabat tiga ratus juta Muslim'.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Kereta Api Hijaz di Madinah", "95009b9c"], "d": ["Jalur sepanjang 1464 km yang dibangun hanya dengan sumbangan Muslim dan teknik lokal mencapai Madinah; perjalanan haji berkurang dari minggu menjadi hari. Ini karya infrastruktur terbesar masa Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Peristiwa 31 Mart", "1d7c2bb2"], "d": ["Pemberontakan besar anti-konstitusi merebut Istanbul; Tentara Aksi (Hareket Ordusu) yang datang dari Selanik menumpas pemberontakan dan Abdülhamid II diturunkan dari takhta.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Pengepungan Edirne dimulai", "234d9b28"], "d": ["Pertahanan Şükrü Paşa selama lima bulan menjadi epos perlawanan di tengah bencana Balkan; kota jatuh karena kelaparan dan direbut kembali pada Juli 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Serbuan Bâb-ı Âli", "b304d02d"], "d": ["Pemerintah yang bersiap menyerahkan Edirne digulingkan oleh serbuan bersenjata kaum Ittihadis; Menteri Perang Nâzım Paşa terbunuh. Masa kekuasaan penuh Komite Persatuan dan Kemajuan dimulai.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Penghapusan Mutasarrifat Gunung Lebanon", "b5639051"], "d": ["Tatanan mutasarrifat otonom yang didirikan dengan Règlement Organique 1861 dan didasarkan pada protokol internasional yang diperbarui pada 1864 dibatalkan sepihak oleh Negara Utsmaniyah selama Perang Dunia I; Kementerian Dalam Negeri mulai mengangkat mutasarrıf Muslim langsung ke wilayah itu. Masa otonomi ketika delapan mutasarrıf bertugas antara 1861-1915 pun tertutup.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Pembagian negeri di antara para şehzade", "82f26bfb"], "d": ["Setelah kekalahan Ankara, Süleyman Çelebi menyeberang ke Rumelia dan memproklamasikan kesultanan di Edirne; İsa Çelebi menguasai Bursa, sedangkan Çelebi Mehmed menguasai wilayah Amasya-Tokat-Sivas. Di peta ketiga bagian ini ditampilkan dengan warna berbeda.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Perjanjian Gelibolu: pesisir Laut Hitam hingga Misivri diserahkan kepada Bizantium", "a4164eca"], "d": ["Emir Süleyman, yang ingin bertahan di Rumelia setelah kekalahan Ankara, menandatangani perjanjian dengan Kaisar Bizantium Manuel di Gelibolu. Ia menyerahkan Kartal, Pendik, dan Gebze serta beberapa pulau, Selanik dan Thessalia di Rumelia, dan jalur pesisir hingga Misivri di Laut Hitam kepada Bizantium; pajak yang dibayar Bizantium kepada Utsmaniyah juga dihapus. Ahtapolu, İğneada, dan Rezve di pesisir Istranca dengan demikian tetap di bawah administrasi Bizantium selama dua puluh satu tahun; Murad II merebut kembali sebagian besar tempat ini dengan perdamaian 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Wafatnya Yıldırım Bayezid dalam tahanan", "7e968d83"], "d": ["Sultan yang ditawan Timur wafat di Akşehir; jenazahnya dibawa ke Bursa dan dimakamkan. Kematiannya membuat perebutan takhta antar-şehzade tak dapat dibalikkan.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Perjanjian Gelibolu — konsesi kepada Bizantium", "dfacbd00"], "d": ["Süleyman Çelebi, yang ingin mengamankan kedudukannya di Rumelia, bersepakat dengan Bizantium dan negara-negara Latin dan mengembalikan Selanik, pesisir Marmara, dan beberapa pulau; ia bahkan menerima membayar upeti.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Pertempuran Ulubat — kekalahan İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, yang menguasai Bursa, dikalahkan oleh saudaranya Mehmed di Ulubat; beberapa upaya pemulihan juga tidak membuahkan hasil.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Lenyapnya İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, yang beberapa kali kembali ke Anatolia dengan dukungan Süleyman Çelebi, menghilang setelah kekalahan terakhirnya; bagiannya beralih ke Çelebi Mehmed dan di peta wilayah Mehmed meluas ke barat.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi menyeberang ke Wallachia", "8441267a"], "d": ["Çelebi Mehmed, yang kehilangan Bursa dan Ankara di hadapan Süleyman Çelebi dan mundur ke Tokat-Amasya, mendorong saudaranya Musa pergi ke Rumelia. Musa menerima undangan Voivode Wallachia Mircea dan mencapai Wallachia melalui laut; dari sini ia akan memulai perjuangan yang akan menjepit Süleyman di antara dua front.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed merebut kembali Bursa dan Ankara — bagian Anatolia lepas dari Süleyman Çelebi", "bfb69f12"], "d": ["Atas keberhasilan Mûsâ Çelebi di Rumelia (Yanbolu, 13 Februari 1410), Emir Süleyman Çelebi yang berada di Anatolia menyeberang ke Rumelia. Setelah kepergian Süleyman dari Anatolia, Mehmed Çelebi merebut kembali kawasan Bursa termasuk Ankara dan, sebagai tanda naiknya ke takhta, mencetak koin bertahun 813. Di peta sisi Anatolia Marmara beralih dari bagian Emir Süleyman ke warna Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Pertempuran Kosmidion", "0efc2caa"], "d": ["Dalam pertempuran di depan tembok Istanbul dengan dukungan Bizantium, Süleyman Çelebi mengalahkan saudaranya Musa; namun dukungannya di Rumelia mulai cepat terkikis.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Pengepungan Istanbul oleh Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, yang ingin menghukum Bizantium yang mendukung Süleyman, mengepung Istanbul; pengepungan ini mendorong Bizantium beraliansi dengan Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Wafatnya Emir Süleyman — Musa menguasai Rumelia", "325c1549"], "d": ["Süleyman Çelebi, yang ditangkap saat melarikan diri dari Edirne, dibunuh; seluruh Rumelia jatuh ke tangan Musa Çelebi. Di peta Rumelia berubah dari warna biru menjadi warna ungu.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Pertempuran Çamurlu — pendirian kembali persatuan", "0b23173e"], "d": ["Çelebi Mehmed, yang memperoleh dukungan Bizantium, despotat Serbia, dan para bey Rumelia, mengalahkan saudaranya Musa secara telak di Çamurlu; Musa tewas saat melarikan diri. Rumelia di tangan Musa beralih kepada Mehmed bersama Edirne, dan Mehmed Çelebi menyatakan dirinya penguasa tunggal Negara Utsmaniyah di Edirne. Masa Fetret sebelas tahun berakhir; bagian-bagian şehzade di peta menyatu dalam satu tubuh.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Keputusan ekspedisi Wina — perdamaian Vasvár tidak diperbarui, sasaran dialihkan dari Yanıkkale ke Wina", "1bf278f2"], "d": ["Kaisar Leopold I menginginkan pembaruan Perjanjian Vasvár yang belum habis masa berlakunya, dan Mehmed IV pun tampak condong ke damai. Namun Sadrazam Merzifonlu Kara Mustafa Paşa, dengan dalih keluhan Imre Thököly yang ia nyatakan sebagai raja Hongaria Tengah, tidak membiarkan perdamaian diperbarui; ia menggerakkan para pendakwah, terutama Vânî Mehmed Efendi, dan membujuk sultan berperang. Dalam musyawarah ditetapkan bahwa sultan tinggal di Beograd dan serdar-ı ekrem maju merebut Yanıkkale; namun dalam musyawarah di Beograd, meski ada keberatan Khan Krimea Murad Giray dan gubernur Buda Uzun İbrâhim Paşa, sasaran diubah menjadi pengepungan Wina.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Pengepungan Wina II dimulai — pasukan di depan Wina", "bb542e49"], "d": ["Pasukan Utsmaniyah di bawah komando Wazir Agung Kara Mustafa Paşa tiba di depan Wina pada 14 Juli 1683. Kaisar Leopold I menyerahkan pertahanan kota kepada Starhemberg dan mundur ke pedalaman Austria. Pengepungan kedua ini, yang tidak seperti yang pertama dipersiapkan dengan sasaran langsung Wina, akan berlangsung hingga 12 September.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Kekalahan Párkány dan hilangnya Esztergom", "a7366740"], "d": ["Pasukan yang mundur dari Wina dikalahkan untuk kedua kalinya di Párkány; kemudian Esztergom, salah satu benteng kunci Hongaria, jatuh. Penarikan mulai berubah menjadi keruntuhan.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Eksekusi Merzifonlu Kara Mustafa Paşa", "ce8b10ac"], "d": ["Sadrazam yang dianggap bertanggung jawab atas kekalahan Wina dicekik di Beograd; namun eksekusinya tidak memperbaiki front maupun mengembalikan gengsi negara yang terguncang.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Liga Suci dibentuk", "060280d0"], "d": ["Liga Suci (Mukaddes İttifak) melawan Utsmaniyah dibentuk antara Austria, Polandia, dan Venesia di bawah pimpinan kepausan; pada 1686 Rusia juga bergabung. Dengan demikian kekaisaran memasuki perang multi-front yang akan berlangsung enam belas tahun.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Pertahanan Buda pertama", "ccc43630"], "d": ["Pengepungan Buda pertama oleh pasukan Liga Suci dipukul mundur oleh pertahanan keras kepala benteng selama empat bulan; namun benteng-benteng di Hongaria terus jatuh satu per satu.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Hilangnya Uyvar", "689ab78c"], "d": ["Benteng Uyvar, yang tetap di tangan Utsmaniyah selama dua puluh dua tahun dan menjadi peribahasa di Eropa, jatuh; keberadaan Utsmaniyah di Hongaria Atas terurai.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Penangkapan Thököly di Várad — Kerajaan Hongaria Tengah bubar, benteng-benteng Hongaria Atas menyerah", "1741aaaf"], "d": ["Setelah kekalahan Wina, Utsmaniyah mulai menganggap Thököly juga termasuk yang menyebabkan perang dan kekalahan. Pada 15 Oktober 1685, atas perintah Serdar Melek İbrâhim Paşa, beylerbeyi Várad Ahmed Paşa menangkap Thököly yang datang membantu; diharapkan dengan menyerahkannya kepada Habsburg syarat perdamaian yang lebih baik dapat diperoleh. Ketika kabar penangkapan menyebar, semua benteng dan kota Kerajaan Hongaria Tengah, kecuali Munkács yang dipertahankan istrinya Ilona Zrínyi, menyerah kepada Habsburg; sebagian besar prajurit Kuruc beralih ke pasukan Habsburg. Ketika Thököly dibebaskan di Beograd pada 2 Januari 1686, kerajaan itu sudah lenyap.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Hilangnya Buda — ibu kota Hongaria berusia 145 tahun", "70800e2b"], "d": ["Buda jatuh pada akhir pengepungan selama tujuh puluh delapan hari; beylerbeyi terakhir Abdurrahman Abdi Paşa gugur sebagai syahid di tembok. Hilangnya kota yang berada di bawah pemerintahan Utsmaniyah sejak 1541 itu dianggap simbol lepasnya Hongaria. Permukiman lain yang lepas pada tanggal yang sama: Peşte.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Kekalahan Mohács kedua (Harsány) — hilangnya Transilvania dan Mohács", "a7922681"], "d": ["Di dataran tempat kemenangan besar diraih pada 1526, kali ini kekalahan berat diderita; pasukan bubar, dan prajurit pemberontak memaksa pemecatan sadrazam. Kekalahan itu juga menyebabkan hilangnya Transilvania.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Hilangnya Athena dan ledakan Parthenon", "b6691730"], "d": ["Sebuah granat yang ditembakkan artileri Venesia meledakkan Parthenon yang digunakan Utsmaniyah sebagai gudang amunisi; kuil berusia dua ribu tahun itu menjadi reruntuhan. Kota jatuh ke tangan Venesia (akan direbut kembali pada 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Pemakzulan Mehmed IV dan naik takhtanya Süleyman II", "9f53037c"], "d": ["Karena bencana di front dan pemberontakan pasukan, Mehmed IV dimakzulkan setelah pemerintahan 39 tahun; saudaranya Süleyman II, yang telah dikurung di kafes selama empat puluh tahun, dinaikkan menggantikannya.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Hilangnya Beograd untuk pertama kali — pengepungan Liga Suci", "c6b9b19a"], "d": ["Beograd, yang berada di tangan Utsmaniyah sejak 1521, menyerah kepada pasukan Liga Suci; gerbang Serbia terbuka bagi musuh dan bahaya mencapai garis Niš-Sofia. Permukiman lain dalam atlas yang beralih dari Utsmaniyah ke Habsburg pada tanggal yang sama: Hisarcık (Grocka) — mengikuti rantai abi-merkez Beograd (TDV belgrad; pendekatan yang dinyatakan).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden menyeberangi Morava di depan Pasarofça — Pasarofça jatuh ke Austria", "bcf3fc59"], "d": ["Margrave Ludwig von Baden menyeberangi Morava di Pasarofça pada Agustus 1689 dan maju ke arah Niš; kota tetap di tangan Austria hingga musim panas 1690 (TDV suleyman-ii menyebut Pasarofça direbut kembali pada 1690). Pembacaan hari dan Röder tidak diverifikasi ulang dalam sesi ini.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Hilangnya Niš — kemajuan Habsburg (mahkota Kerajaan Hongaria), tahun paling kritis", "c5e27b3f"], "d": ["Kemajuan Habsburg (mahkota Kerajaan Hongaria) juga merebut Niš dari pemerintahan Utsmaniyah; serbuan mencapai Üsküp dan Priştine. Vidin jatuh sesudahnya, pada Oktober 1689 (entri terpisah). Pada tahun tergelap perang itu, negara merasa ibu kotanya pun terancam.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova dan Fethülislâm dimasukkan ke garnisun Austria", "ee8dd875"], "d": ["Setelah direbutnya Vidin tanpa perang (Oktober 1689, TDV vidin), pada 25 Oktober 1689 Baden memperbaiki dan menggarnisun Orsova dan Fethülislâm; Orsova tetap di tangan Austria hingga musim gugur 1690. Hari bertumpu pada Bánlaky/Röder, tidak diverifikasi ulang dalam sesi ini.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš kembali ke Utsmaniyah", "0c4f44eb"], "d": ["Fâzıl Mustafa Paşa berangkat berekspedisi pada Juli 1690; setelah Şehirköy, Pasarofça, dan Güvercinlik direbut, Niš yang dikepung jatuh ke tangan Utsmaniyah pada 27 September 1690 (TDV semendire). Pada saat yang sama Vidin juga telah direbut kembali. Permukiman lain dalam atlas yang kembali dari Habsburg ke Utsmaniyah pada tanggal yang sama: Yagodina (Jagodina) dan Ürküp (Prokuplje) — karena hari tingkat tempat tidak ditemukan, hari Niš diambil (TDV semendire; pendekatan yang dinyatakan; Röder 1842 menulis bahwa wazir melewati Yagodina pada 8-24 September, pertentangan tidak terselesaikan).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Pasukan Austria di Semendire menyerah", "90da20c4"], "d": ["Setelah direbutnya Niš pada 27 September 1690, pasukan Austria di Semendire menyerah dengan pengepungan empat hari (TDV semendire). Bánlaky/Röder menyebut 24 September; sumber-sumber bertentangan, TDV dijadikan pegangan.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Beograd direbut kembali", "ab435838"], "d": ["Sadrazam Köprülüzâde Fâzıl Mustafa Paşa merebut kembali Beograd dari Austria pada 8 Oktober 1690; kota yang hilang pada 1688 itu pun kembali ke Utsmaniyah (TDV suleyman-ii). Permukiman lain dalam atlas yang kembali dari Habsburg ke Utsmaniyah pada tanggal yang sama: Hisarcık (Grocka) — mengikuti rantai abi-merkez Beograd (TDV suleyman-ii; pendekatan yang dinyatakan).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Kekalahan Slankamen — Fâzıl Mustafa Paşa gugur sebagai syahid", "10d626f1"], "d": ["Dalam salah satu pertempuran terbuka paling berdarah abad itu, sadrazam tertembak di dahi dan gugur sebagai syahid; pasukan bubar. Harapan pemulihan padam bersama pertempuran ini.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Hilangnya Pulau Sakız (Chios)", "07c084f8"], "d": ["Armada Venesia menduduki Sakız; kekuasaan Utsmaniyah di Aegea terancam. Pulau akan direbut kembali pada tahun berikutnya.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Keputusan Mustafa II untuk memimpin ekspedisi sendiri", "61c3ba9c"], "d": ["Sultan baru mengumumkan bahwa ia akan berangkat berekspedisi di kepala pasukan, mengikuti jalan leluhurnya; keputusan ini membangkitkan moral pasukan dan memulai periode ekspedisi pribadi yang akan berlangsung dua tahun.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Direbutnya kembali Sakız", "6b496fca"], "d": ["Mezomorto Hüseyin Paşa, yang mengalahkan armada Venesia dalam pertempuran laut Koyun Adaları, merebut kembali Sakız; ini tanda kebangkitan singkat pelayaran Utsmaniyah.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Kemenangan Lugoj — ekspedisi Austria pertama Mustafa II", "d5ee9b34"], "d": ["Dalam ekspedisi pertama yang diikuti sultan sendiri, Lipova direbut kembali dan pasukan Austria dikalahkan di Lugoj; patahan pertama dalam rantai kekalahan bertahun-tahun terjadi. Atlas juga menganggap Karánsebes (Caransebeș) kembali dari Habsburg ke Utsmaniyah dalam ekspedisi ini; sumber hanya memberi September 1695 (TDV mustafa-ii), hari atlas diambil dari catatan Lugoj (pendekatan yang dinyatakan).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Hilangnya Benteng Azak", "2b78b5cd"], "d": ["Petrus I, yang bertujuan menembus ke Laut Hitam, merebut Azak dalam pengepungan keduanya; Rusia untuk pertama kalinya menetap secara permanen di sebuah benteng Utsmaniyah dan mengambil langkah pertama menuju kekuatan laut.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Kemenangan Ulaş (Olašin)", "02ac9ca8"], "d": ["Kemenangan yang diraih di tepi Danube dalam ekspedisi kedua sultan menggagalkan rencana Austria merebut Timișoara; namun tidak mengubah keseimbangan umum perang.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Kekalahan Zenta — nasib perang ditentukan", "475c4a7b"], "d": ["Pasukan disergap mendadak oleh Pangeran Eugen ketika menyeberangi Sungai Tisza; kekuatan yang terbelah di dua tepi sungai dimusnahkan dalam beberapa jam, ribuan prajurit dan negarawan, termasuk sadrazam Elmas Mehmed Paşa, tewas. Zenta, salah satu kekalahan terberat dalam sejarah Utsmaniyah, membuat meja perdamaian tak terelakkan.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Perundingan damai Karlowitz dimulai", "1f395cf3"], "d": ["Dalam perundingan yang dimulai dengan mediasi Inggris dan Belanda, delegasi Utsmaniyah untuk pertama kalinya terpaksa menerima prinsip 'uti possidetis' (apa yang dikuasai tetap dimiliki); perundingan yang berlangsung tujuh puluh dua sidang dianggap kelahiran diplomasi Utsmaniyah modern.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali dari Kavala mendarat di Mesir", "514c943f"], "d": ["Dalam pasukan Utsmaniyah yang dikirim untuk merebut kembali Mesir dari pendudukan Prancis terdapat pula satuan sukarelawan yang dihimpun dari Kavala. Mehmed Ali, yang berusia tiga puluhan, adalah komandan kedua satuan ini; ia menginjakkan kaki di Mesir bukan sebagai gubernur, melainkan sebagai perwira sebuah kompi.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Prajurit Albania menggulingkan gubernur Mesir", "c76a0ec2"], "d": ["Pasukan Albania yang gajinya tidak dibayar memberontak dan memaksa gubernur Hüsrev Paşa melarikan diri dari benteng. Dalam kekosongan yang timbul dengan mundurnya Prancis, para bey Mamluk, ocak Albania, dan gubernur-gubernur yang diangkat Bâbıâli memasuki perebutan tiga sudut; Mehmed Ali tampil ke depan dengan menegakkan keseimbangan dalam segitiga ini. Permukiman lain yang lepas pada tanggal yang sama: Tâif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Ulama Kairo menyatakan Mehmed Ali sebagai gubernur", "a16752f2"], "d": ["Para pedagang dan ulama Kairo, yang tertekan pajak, memberontak di bawah pimpinan nakîbüleşraf Ömer Mekrem, menyatakan tidak mengakui gubernur Hurşid Paşa, dan mendudukkan Mehmed Ali pada jabatan gubernur. Dipilihnya seorang gubernur oleh rakyat adalah peristiwa yang jarang ditemui dalam sejarah Utsmaniyah.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Bâbıâli menerima fait accompli: firman gubernur Mesir", "b86736a3"], "d": ["Bâbıâli, yang tidak memiliki kekuatan untuk mempertahankan calonnya sendiri di Mesir, mengirimkan firman gubernur Mesir kepada Mehmed Ali dengan pangkat wazir. Di peta Mesir sejak tanggal ini beralih ke lapisan vasal (warna terang): secara hukum wilayah Utsmaniyah, secara de facto negeri dinasti Mehmed Ali. Permukiman lain yang beralih ke lapisan vasal pada tanggal yang sama: Kahire, İskenderiye, Dimyat, Asyut, Asvan, İbrim, Süveyş, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Ekspedisi Fraser Inggris mendarat di Iskandariyah", "4d6c31be"], "d": ["Sebagai balasan atas mendekatnya Utsmaniyah kepada Prancis, Inggris mengirim pasukan pendarat ke Mesir. Mehmed Ali saat itu sedang menghadapi Mamluk di Mesir Hulu; ia kembali dengan cepat dan mengorganisasi pertahanan.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Kekalahan Rosetta (Reşid) — Inggris dipukul mundur", "3636004c"], "d": ["Kolom Inggris yang memasuki kota Reşid menderita kerugian berat dalam pertempuran jalanan; pada bulan September pasukan mengosongkan Mesir sepenuhnya. Kemenangan ini memperkuat gengsi Mehmed Ali baik di Mesir maupun di Istanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Peristiwa Benteng: likuidasi bey-bey Mamluk", "84030b97"], "d": ["Para bey Mamluk yang diundang ke arak-arakan upacara untuk ekspedisi Hijaz dijebak di jalan sempit Benteng Kairo dan dilenyapkan. Pengaruh Mamluk selama lima abad berakhir dan Mehmed Ali tidak lagi memiliki saingan di Mesir.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Ekspedisi Hijaz dimulai — pasukan berbaris ke Yanbu dari Suez melalui laut dan melalui jalur haji di darat", "1c05c159"], "d": ["Merebut kembali Haramain, yang berada di bawah pemerintahan Saudi-Wahhabi sejak 1803, adalah persoalan legitimasi terbesar bagi Mahmud II; ketika Bâbıâli tidak mampu, tugas diberikan kepada gubernur Mesir. Mehmed Ali mengirim putranya Tosun yang berusia enam belas tahun di kepala pasukan.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu direbut — pangkalan pesisir pertama ekspedisi Hijaz", "179bc78d"], "d": ["Sekitar dua ribu infanteri Albania yang berangkat dari Suez dengan kapal-kapal yang baru dibuat mendarat di dekat Yanbu pada Oktober 1811; kota menyerah setelah perlawanan lemah selama dua hari. Pasukan berkuda di bawah komando Tosun, yang menyusuri jalur haji di darat melalui Aqaba dan Wajh, baru mencapai Yanbu dua minggu kemudian. Yanbu menjadi pangkalan pertama pasukan Mesir di Hijaz yang akan berbaris ke Madinah dan Makkah.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Kekalahan pertama di celah Safra-Jedîde", "99ef804d"], "d": ["Pasukan depan Mesir yang disergap di celah-celah gunung sempit tercerai-berai. Kekalahan itu menjadi pelajaran taktis ekspedisi: dipahami bahwa tidak mungkin berbaris di Hijaz tanpa dukungan suku-suku Badui.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Madinah direbut kembali", "6f6a5d55"], "d": ["Madinah menyerah setelah pengepungan panjang. Direbutnya kembali kota Rasulullah dirayakan di Istanbul dengan pesta meriam; sebagai hadiah, Mehmed Ali juga diberi jabatan gubernur Jeddah.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Makkah direbut kembali — jalur haji dibuka", "3d6d66a0"], "d": ["Pasukan Mesir yang memasuki Makkah kembali mengumandangkan khutbah di Ka'bah atas nama sultan Utsmaniyah. Rombongan haji yang terputus selama sepuluh tahun dapat berangkat kembali. Di peta Hijaz kembali ke kekuasaan Utsmaniyah, tetapi karena pemerintahannya berada di Kairo, ia ditampilkan dengan warna vasal. Tempat lain yang beralih ke pemerintahan vasal pada tanggal yang sama: Cidde.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Direbutnya kembali Tâif — selesainya ekspedisi Hijaz", "6315fb31"], "d": ["Setelah Madinah (Desember 1812) dan Makkah (Januari 1813), pasukan Mesir di bawah komando Tosun Paşa akhirnya merebut kembali Tâif dari kaum Wahhabi. Kekuasaan Saudi selama sepuluh tahun berakhir, dan ketiga pusat suci Hijaz kembali masuk ke kendali Utsmaniyah-Mesir.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali sendiri menyeberang ke Hijaz", "fda0ea2d"], "d": ["Gubernur yang melihat ekspedisi berjalan lamban mengambil alih pemerintahan secara langsung; dengan menawar kepada para kepala suku, ia berusaha menguraikan front Saudi dari dalam. Bagian Mesir dalam perdagangan Laut Merah juga membesar dengan ekspedisi ini.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Pertempuran Basel (Bisel): pasukan Saudi dikalahkan", "9c9ab91f"], "d": ["Kaum Saudi, yang menderita kekalahan berat dalam pertempuran terbuka, mundur ke pedalaman. Gencatan senjata yang dibuat tidak bertahan; dua tahun kemudian operasi akan dibawa ke jantung Najd. Setelah kemenangan ini atlas menganggap Türabe dan Hurma di timur Tâif lepas dari tangan Saudi (sumber peristiwa Lorimer, Gazetteer; kesaksian khusus tempat dan hari 13 Januari adalah pendekatan yang dinyatakan).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrâhim Paşa berangkat ke ekspedisi Najd", "d5ed80d1"], "d": ["İbrâhim Paşa, yang mengambil alih komando setelah wafatnya saudaranya Tosun, memulai pawai berat selama dua tahun di gurun. Pasukan yang maju sumur demi sumur menyingkirkan suku-suku satu per satu dan mencapai ibu kota Saudi.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Dir'iyah jatuh — Negara Saudi pertama berakhir", "aa96206d"], "d": ["Dir'iyah menyerah setelah pengepungan enam bulan dan dihancurkan. Emir Abdullah b. Suud dikirim ke Istanbul dan dieksekusi. Panji Utsmaniyah untuk pertama kalinya menjangkau sedalam ini ke pedalaman Arabia; garnisun Najd bertahan hingga 1824. Tempat-tempat lain yang bergabung pada tanggal yang sama: Dir'iye (Necid).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Ekspedisi Sudan dimulai", "b1fc6905"], "d": ["Tujuan Mehmed Ali rangkap tiga: menghimpun tentara untuk pasukannya, mencapai emas Sennar, dan memusnahkan sisa Mamluk yang melarikan diri. Pasukan di bawah komando putranya İsmâil Paşa menyusuri Nil ke arah selatan.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola direbut — sisa Mamluk dicerai-beraikan", "ba6bc24b"], "d": ["Pasukan yang memasuki Dongola di tikungan besar Nil melikuidasi kelompok Mamluk terakhir yang berlindung di sana. Di peta Sudan sejak tanggal ini muncul pada lapisan vasal: yang menaklukkan adalah Kairo, dan yang memerintah juga akan Kairo.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Kesultanan Sennar (Funj) menyerah", "3cac7dd2"], "d": ["Dinasti Funj yang berusia tiga abad menyerah tanpa pertempuran. Pada tahun yang sama, perkemahan yang didirikan di titik pertemuan dua cabang Nil dalam waktu singkat berubah menjadi Khartoum, pusat administrasi Sudan. Tempat-tempat lain yang bergabung pada tanggal yang sama: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan direbut", "06440602"], "d": ["Kolom kedua yang dikirim ke barat mengalahkan pasukan Darfur di Bâra dan merebut Kordofan bersama sekitar Nühûd. Kekuasaan Mesir atas Sudan dengan demikian meluas dari lembah Nil ke stepa barat.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Pasukan Mesir mendarat di Kreta", "835aee90"], "d": ["Ketika pemberontakan Yunani menjalar ke Kreta, Bâbıâli meminta pasukan Mesir dikirim ke pulau itu. Pengaruh Mehmed Ali di pulau bermula dengan intervensi ini dan delapan tahun kemudian berujung pada pemberian jabatan gubernur Kreta kepadanya.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Terbunuhnya İsmâil Paşa di Shendi", "223860c9"], "d": ["Emir lokal Nemir, yang murka atas tuntutan pajak dan prajurit yang berat, membakar rumah tempat İsmâil Paşa menginap dan membakar sang paşa beserta pengiringnya. Ekspedisi pembalasan menjadikan wilayah itu lautan darah; pemerintahan Sudan sesudahnya dibangun di atas kekerasan.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II meminta bantuan Mehmed Ali untuk Mora", "03594a42"], "d": ["Untuk pemberontakan Mora yang tidak dapat ditumpas selama tiga tahun oleh tentara janisari, sultan meminta bantuan pasukan Mesir yang dilatih ala Eropa. Sebagai imbalan dijanjikan jabatan gubernur Mora dan Kreta. Permintaan ini adalah pengakuan terbuka pertama bahwa kekaisaran telah membutuhkan provinsinya sendiri.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrâhim Paşa mendarat di Modon", "9c993dba"], "d": ["Pasukan pendarat yang dilindungi armada Mesir menginjakkan kaki di ujung barat daya Mora. Pasukan ini, yang dilengkapi infanteri nizamî dan artileri lapangan, dalam waktu singkat memperoleh keunggulan atas gerombolan pemberontak.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa direbut kembali — pusat Mora jatuh", "8a478c11"], "d": ["Dengan jatuhnya Tripolitsa, pusat administrasi pemberontakan, sebagian besar Mora kembali berada di bawah kendali. Di peta semenanjung muncul dengan warna vasal karena berada di tangan pasukan Mesir.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) jatuh", "07257f87"], "d": ["Kota direbut setelah pengepungan satu tahun. Namun gaung pertahanannya di pers Eropa membawa simpati terhadap perjuangan Yunani ke puncak dan menyiapkan landasan intervensi kekuatan-kekuatan besar.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Akropolis Athena direbut", "3b19f946"], "d": ["Dengan jatuhnya Akropolis, pemberontakan Yunani hampir selesai secara militer. Pada titik inilah persoalan itu berhenti menjadi pemberontakan dalam negeri dan menjadi pokok diplomasi Eropa.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Perjanjian London: tiga negara memaksakan otonomi Yunani", "7ce46fd8"], "d": ["Inggris, Prancis, dan Rusia memutuskan bertindak bersama untuk memaksakan gencatan senjata dan syarat otonomi antara Utsmaniyah dan Yunani; diberitahukan bahwa jika ditolak armada mereka akan melakukan intervensi. Bâbıâli menolak tawaran itu.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Konvensi Iskandariyah: keputusan Mesir mundur dari Mora", "cc978f37"], "d": ["Mehmed Ali, yang kehilangan armadanya di Navarino, bersepakat langsung dengan laksamana Inggris tanpa berkonsultasi dengan Istanbul dan menerima menarik pasukannya dari Mora. Seorang gubernur membuat perjanjian terpisah dengan kekuatan-kekuatan besar adalah pertanda krisis yang akan datang.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Pasukan Mesir mengosongkan Mora", "8fb742dd"], "d": ["Unit-unit terakhir dinaikkan ke kapal; semenanjung lepas secara de facto dan dengan Protokol London 1830 menjadi inti Yunani yang merdeka. Mehmed Ali tidak memperoleh jabatan gubernur Mora yang dijanjikan dan sebagai gantinya kehilangan armada dan pasukan yang besar. Permukiman lain yang lepas pada tanggal yang sama: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Pemerintahan Kreta diserahkan kepada Mehmed Ali", "7f76396d"], "d": ["Sebagai kompensasi atas kehilangan Mora, jabatan gubernur Kreta diberikan kepada Mehmed Ali. Pulau itu diperintah dari Kairo selama sepuluh tahun; di peta tampak dengan warna vasal selama masa itu. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kandiye (Girit).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrâhim Paşa memasuki Suriah — krisis pertama dimulai", "1a5cc386"], "d": ["Dalihnya adalah gubernur Akka yang tidak mengembalikan para fellah yang melarikan diri dari Mesir; alasan sebenarnya adalah kebutuhan Mehmed Ali akan kayu, pelabuhan, dan sumber daya manusia Suriah. Pasukan melintasi Sinai dan dengan cepat merebut pesisir Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Pengepungan Akka dimulai", "b211d96d"], "d": ["Benteng yang menghentikan Napoleon pada 1799 itu bertahan selama enam bulan. Pengepungan itu adalah ujian besar pertama artileri modern pasukan Mesir.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Akka jatuh", "0f47917b"], "d": ["Benteng direbut ketika baterai yang menghantam tembok membuka celah. Gerbang Suriah telah terbuka; pada hari-hari yang sama Bâbıâli menyatakan Mehmed Ali pemberontak dan mencabut jabatan gubernurnya.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damaskus menyerah", "48da3b62"], "d": ["Kota menyerah tanpa pertempuran. İbrâhim Paşa berusaha memenangkan dukungan lokal dengan mengumumkan tatanan pajak dan kesetaraan bagi non-Muslim; kebijakan yang sama beberapa tahun kemudian akan menjadi penyebab pemberontakan terhadapnya. Tempat-tempat lain yang bergabung pada hari-hari yang sama: Beyrut, Trablusşam, Sayda.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Pertempuran Homs", "867810ee"], "d": ["Pasukan Utsmaniyah yang dikirim untuk menyelamatkan Suriah dikalahkan di medan terbuka. Terlihat bahwa tentara baru yang dibentuk enam tahun setelah dihapuskannya janisari belum siap.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo direbut", "9c0ead76"], "d": ["Pusat dagang dan administrasi Suriah Utara juga jatuh. Dengan demikian pasukan Mesir mencapai kaki Pegunungan Taurus dan beralih ke celah-celah di gerbang Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Kekalahan celah Belen (Beylan) — Çukurova terbuka", "4bae872b"], "d": ["Garis pertahanan di celah sempit Pegunungan Amanos ditembus. Antakya, Adana, dan Tarsus beralih ke pasukan Mesir (menurut TDV pendudukan Maraş terjadi pada 1833, entri terpisah); di peta Çukurova kembali ke warna vasal. Jalan ke pedalaman Anatolia kini tak terlindungi.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Celah Gülek jatuh — pesisir İçel (Mersin, Silifke) masuk ke kendali Mesir", "d9049b5b"], "d": ["Celah Gülek, gerbang Çukurova di Pegunungan Taurus, jatuh ke tangan pasukan Mesir. İbrâhim Paşa mengangkat mütesellim-nya sendiri di Sancak İçel dan semua dermaga di pesisir masuk ke kendali Mesir. Di peta Mersin dan Silifke sejak hari ini (batas bawah; hari pengangkatan tidak ada dalam sumber) ditampilkan terikat pada Mesir; karena dalam keputusan Kütahya hanya muhassıllık Adana yang disebut, kendali ini berakhir dengan pengosongan Anatolia.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğli di bawah pendudukan Mesir — mulut Taurus jalur Konya–Adana", "fb908900"], "d": ["Ereğli, yang terletak di jalur pasukan Mesir yang melewati Celah Gülek menuju Konya, masuk ke pendudukan İbrâhim Paşa pada 1832 dan, ketika dikosongkan dengan penataan Kütahya 1833, kembali terikat pada vilayet Karaman. Di peta ini adalah titik tengah bersumber dari garis pendudukan antara Adana dan Konya; untuk Ulukışla dan Karapınar tidak ditemukan kesaksian tingkat kota.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Pasukan Mesir memasuki Konya", "13952a2d"], "d": ["Pasukan yang melintasi Pegunungan Taurus mencapai Anatolia Tengah. Pasukan seorang gubernur Utsmaniyah untuk pertama kalinya maju di wilayah inti kekaisaran. Tempat-tempat lain yang bergabung pada tanggal yang sama: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Pertempuran Konya: sadrazam tertawan", "ec82cc9a"], "d": ["Pasukan Utsmaniyah yang tercerai-berai dalam kabut menderita kekalahan berat dan sadrazam Reşid Mehmed Paşa tertawan. Tentara pusat negara tidak ada lagi; tidak ada kekuatan yang tersisa untuk menahan pasukan Mesir sebelum Istanbul.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş mengalami pendudukan Mesir", "f558e383"], "d": ["Menurut TDV, Maraş pada 1833 mengalami pendudukan İbrâhim Paşa dari Kavala dan tetap di bawah pemerintahannya hampir sembilan belas bulan. Karena Maraş berada di luar batas provinsi dalam penataan Kütahya, pemerintahan ini bersifat faktual, bukan hukum.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) mengalami pendudukan Mesir — jalur Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, yang terletak di jalur pasukan Mesir yang maju ke Kütahya setelah Pertempuran Konya, tetap di tangan İbrâhim Paşa untuk sementara pada 1833. Di peta ini adalah titik tengah bersumber dari garis pendudukan antara Konya dan Kütahya; untuk Akşehir, Ilgın, dan İshaklı tidak ditemukan kesaksian tingkat kota, sehingga mereka berwarna Utsmaniyah.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Pasukan Mesir mencapai Kütahya", "214f8df6"], "d": ["İbrâhim Paşa berhenti di Kütahya, tiga etape dari Istanbul. Tidak majunya ia lebih lanjut bukan karena alasan militer melainkan politik: intervensi Rusia dan reaksi Eropa telah diperhitungkan.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Armada Rusia di depan Büyükdere", "6f836d61"], "d": ["Mahmud II, yang tidak memperoleh bantuan dari Inggris dan Prancis, berpaling kepada Rusia, musuh kemarin. Keputusan ini, yang dikenang dengan ucapan sultan \"orang yang tenggelam akan berpegangan pada ular\", berujung pada mendaratnya prajurit Rusia di selat dan membunyikan lonceng alarm di Eropa.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Kesepakatan Kütahya (lisan) — Suriah dan Adana untuk Mehmed Ali", "25fe9985"], "d": ["Bâbıâli menyerahkan kepada Mehmed Ali, selain Mesir, Kreta, dan Hijaz, jabatan gubernur Damaskus, Aleppo, Tripoli, dan Sidon; dan muhassıllık Adana kepada İbrâhim Paşa. Sebagai imbalan, pasukan mundur ke selatan Pegunungan Taurus. Ini bukan perjanjian, melainkan berupa firman-firman yang diberikan sultan kepada seorang gubernur — persoalan tidak terselesaikan, hanya ditunda.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Penarikan pasukan Mesir dari Anatolia selesai melalui Gülek", "a53ac2a3"], "d": ["Setelah penataan Kütahya, pasukan Mesir mengosongkan Anatolia; menjelang pertengahan Juni seluruh pasukan melewati Celah Gülek ke Çukurova. Pesisir İçel (Mersin, Silifke) kembali ke pemerintahan Utsmaniyah; muhassıllık Adana dan Suriah tetap di tangan Mesir.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Perjanjian Hünkâr İskelesi", "da741d5c"], "d": ["Aliansi pertahanan timbal balik delapan tahun ditandatangani dengan Rusia. Menurut pasal rahasia, jika Rusia diserang, Utsmaniyah akan menutup selat bagi kapal perang. Ini menjadi salah satu keputusan paling diperdebatkan diplomasi Utsmaniyah dan membuat Inggris aktif dalam persoalan Mesir.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Pemberontakan Palestina-Nablus melawan pemerintahan Mesir", "4fe43e27"], "d": ["Wajib militer, pengumpulan senjata, dan pajak baru memicu pemberontakan luas di Palestina. Pemberontakan itu ditumpas keras; dukungan pemerintahan Mesir di kalangan penduduk setempat dengan cepat menyusut.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Berakhirnya pemerintahan Mesir atas Maraş (perkiraan)", "bb46ca42"], "d": ["Jika kalimat TDV 'hampir sembilan belas bulan' dihitung dari pendudukan 1833, pemerintahan Mesir berakhir sekitar musim panas 1834. Fakta bahwa Mustafa Bey dari Küçükalioğulları pada 1834 tidak dapat melawan pasukan Mesir dan mundur ke arah Maraş juga menunjukkan bahwa Maraş pada saat itu merupakan tempat perlindungan di luar kendali Mesir.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Pemberontakan Gunung Druze", "12e74626"], "d": ["Perlawanan yang pecah di wilayah Druze berlangsung dua tahun. Ketidakpuasan yang menumpuk di Suriah akan mengosongkan bagian belakang pasukan Mesir ketika armada sekutu mendarat di pesisir pada 1840.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali menyatakan niat merdeka", "48633bbd"], "d": ["Sang gubernur mengumumkan kepada konsul kekuatan-kekuatan besar bahwa ia mempertimbangkan memproklamasikan kemerdekaan Mesir dan Suriah. Inggris menentangnya dengan tegas: lahirnya negara yang kuat dan dekat dengan Prancis di Mediterania akan mengancam jalur India.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Pasukan Utsmaniyah menyeberangi Efrat", "9af1ea69"], "d": ["Mahmud II menggerakkan pasukannya ke perbatasan Suriah untuk merebut kembali apa yang hilang di Kütahya. Perwira Prusia Moltke, yang berada di pasukan sebagai penasihat, keberatan atas pemilihan posisi dan serangan dini; keberatannya tidak didengar.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Pertempuran Nizip — pasukan Utsmaniyah bubar", "156b3cdf"], "d": ["Pasukan Utsmaniyah yang ditempatkan dengan buruk dikalahkan dalam beberapa jam. Sultan wafat sebelum kabar kekalahan sampai ke Istanbul; dalam beberapa hari negara akan kehilangan pasukannya, penguasanya, dan kemudian armadanya.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Wafatnya Mahmud II", "07eccfff"], "d": ["Sultan yang selama pemerintahan tiga puluh satu tahun menghapus janisari dan membangun kembali pemerintahan sentral itu wafat tanpa sempat mengalahkan lawan terbesarnya. Penyakitnya tidak didiagnosis dengan tepat. Kematiannya disembunyikan hingga 30 Juni, sampai tindakan militer diambil di kota karena ketakutan bahwa mentalitas janisari akan bergerak.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Naik takhtanya Abdülmecid dan jenazah Mahmud II", "d0f3d2cc"], "d": ["Setelah wafatnya ayahnya, Abdülmecid yang berusia enam belas tahun naik takhta. Pada hari yang sama jenazah Mahmud II dibawa ke Istana Topkapı; kekacauan yang ditakutkan tidak terjadi, dan massa luas Muslim maupun non-Muslim ikut dalam arak-arakan jenazah.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Penyerahan armada ke Iskandariyah", "a53e6103"], "d": ["Kaptan-ı derya Ahmed Fevzi Paşa, karena curiga sadrazam Koca Hüsrev Paşa akan memberikan armada kepada Rusia, membawa armada ke Iskandariyah dan menyerahkannya kepada Mehmed Ali. Negara Utsmaniyah dalam bulan yang sama kehilangan pasukan, sultan, dan armada sekaligus.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota bersama kekuatan-kekuatan besar", "2a3b8316"], "d": ["Lima negara menyampaikan nota kepada Bâbıâli dan meminta agar tidak membuat kesepakatan sendiri dalam persoalan Mesir. Dengan demikian urusan dalam negeri secara resmi menjadi \"persoalan Eropa\"; negara Utsmaniyah secara de facto kehilangan wewenang menentukan nasib provinsinya sendiri.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Perjanjian London: empat negara di pihak Utsmaniyah", "a517f775"], "d": ["Perjanjian yang ditandatangani dengan menyingkirkan Prancis memberi ultimatum kepada Mehmed Ali: jika diterima dalam sepuluh hari, jabatan gubernur Mesir turun-temurun dan Akka seumur hidup; jika diterima dalam dua puluh hari, hanya Mesir; jika ditolak, tidak ada apa-apa. Sang gubernur menolak.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Pengeboman Beirut dan pendaratan sekutu", "0905ce92"], "d": ["Armada Inggris-Austria membombardir Beirut; senjata dibagikan kepada rakyat yang memberontak melawan pemerintahan Mesir di Gunung Lebanon. Kendali İbrâhim Paşa atas Suriah runtuh di antara pemberontakan dalam negeri dan intervensi luar.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut dan kota-kota pesisir lepas", "09bdaf23"], "d": ["Setelah pertempuran ke arah Baalbek, pasukan Mesir mundur dari pesisir. Di peta pesisir Lebanon keluar dari warna vasal dan kembali ke pemerintahan Utsmaniyah langsung.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akka jatuh dalam dua jam", "5aec21f0"], "d": ["Gudang amunisi benteng meledak dalam pengeboman armada sekutu dan Akka menyerah dalam beberapa jam. Benteng yang delapan tahun sebelumnya baru dapat direbut İbrâhim Paşa dalam enam bulan itu menunjukkan keunggulan artileri laut.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konvensi Iskandariyah", "85cb47b0"], "d": ["Mehmed Ali menerima melepaskan Suriah, Adana, Kreta, dan Hijaz, mengembalikan armada Utsmaniyah, dan mengakui kedaulatan sultan; sebagai imbalannya jabatan gubernur Mesir turun-temurun dijamin.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Pasukan Mesir mengosongkan Suriah dan Çukurova", "719a28dc"], "d": ["Pendudukan sembilan tahun berakhir; pasukan İbrâhim Paşa kembali ke Mesir melalui Sinai. Di peta, sabuk luas dari Aleppo ke Gaza dan dari Adana ke Kreta kembali ke pemerintahan langsung Utsmaniyah. Permukiman lain yang lepas pada tanggal yang sama: Urfa, Maraş, Tarsus, Antakya, Kandiye (Girit), Hama, Şam, Kudüs, Yafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firman: jabatan gubernur Mesir diwariskan kepada keluarga dari Kavala", "87b89ff8"], "d": ["Firman sultan mengakui jabatan gubernur diwariskan dari ayah ke anak dalam dinasti; sebagai imbalannya jumlah pasukan diturunkan menjadi delapan belas ribu, pajak diikatkan ke Istanbul, dan wewenang mencetak uang serta membuat perjanjian dihapus. Mesir tetap sebagai provinsi tetapi kini merupakan negeri sebuah dinasti tersendiri. Pemerintahan Hijaz dan Haramain kembali ke Bâbıâli. Permukiman lain yang kembali dari lapisan vasal ke lapisan langsung pada tanggal yang sama: Mekke, Medine, Cidde, Yenbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konvensi Selat London", "0e95a1ea"], "d": ["Konvensi yang menggantikan Hünkâr İskelesi menetapkan bahwa selat tertutup bagi semua kapal perang pada masa damai. Keistimewaan yang diperoleh Rusia sendirian dengan demikian menjadi jaminan bersama Eropa; persoalan selat memperoleh status internasional.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Paşa secara de facto menjadi gubernur Mesir", "9e14f5d9"], "d": ["Putranya İbrâhim Paşa diangkat menjadi gubernur menggantikan Mehmed Ali yang menua dan kehilangan kemampuan mentalnya. Namun beberapa bulan kemudian, pada November 1848, ia wafat mendahului ayahnya.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Wafatnya Kavalalı Mehmed Ali Paşa", "871310e0"], "d": ["Gubernur yang lahir di Kavala dan mendirikan dinasti di Mesir, yang dua kali membawa kekaisaran ke tepi jurang, wafat pada usia delapan puluh tahun. Dinasti yang ia dirikan memerintah Mesir hingga 1953; negara menutup luka yang ia buka dengan intervensi Eropa dan melangkah di jalan Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış kalah dan tewas di Ayn Salm; Antakya keluar dari Seljuk Anatolia", "0412dfa1"], "d": ["Süleyman b. Kutalmış, yang merebut Antakya dari Bizantium pada 1084, tewas dalam pertempuran Ayn Salm yang dilakukannya dengan penguasa Seljuk Suriah Tutuş; kota beralih ke kendali Sultan Seljuk Agung Melikşah dan Yağısıyan diangkat sebagai gubernur.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Melikşah wafat; Antakya bersama Yağısıyan terikat pada Tutuş dari Seljuk Suriah", "c61da1b4"], "d": ["Setelah wafatnya Sultan Seljuk Agung Melikşah, negara terbagi di antara para pewaris; gubernur Antakya Yağısıyan terikat pada Tutuş, penguasa Suriah.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["İznik menyerah kepada Tentara Salib; pusat Seljuk mundur ke Konya, Bizantium mulai merebut kembali Anatolia barat", "8a4e90fa"], "d": ["Setelah pengepungan İznik oleh Tentara Salib, kota menyerah kepada Bizantium pada 19 Juni 1097; sultan Seljuk Kılıcarslan I memindahkan pusatnya ke pedalaman, ke Konya, sementara Bizantium merebut kembali tempat-tempat di pesisir Anatolia barat seperti Efesus.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıcarslan II merebut Dorylaion (Eskişehir) dan Kütahya dari Bizantium", "3ddee6c2"], "d": ["Setelah Myriokephalon (1176), benteng Dorylaion dan Kütahya milik Bizantium di pedalaman Anatolia jatuh ke tangan Kılıcarslan II pada tahun-tahun terakhir Manuel/setelah wafatnya, yakni 576/1180.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoğlu Mehmed Bey diangkat sebagai subaşı Ermenek dan mengambil alih pemerintahan İç İl", "6d62be11"], "d": ["Karamanoğlu Mehmed Bey diangkat sebagai subaşı Ermenek pada tahun 675 (1276) dan menempatkan İç İl di bawah pemerintahannya; Ermenek menjadi pusat pertama Karamanoğulları, yang akan berbaris ke Konya pada tahun berikutnya.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Wafatnya Ertuğrul Gazi dan peralihan Osman Bey ke beylik — warisan Söğüt dan Domaniç", "395fb9fa"], "d": ["Menurut TDV, Ertuğrul Gazi wafat pada tahun 680 (1281-82); entri itu mencatat bahwa tahun 1288 dan 1289 juga diberikan. Osman Bey mewarisi dari ayahnya bukan sebuah kota yang ditaklukkan, melainkan dua alokasi yang diberikan sultan Seljuk kepada Ertuğrul, yang ditempatkan di garis terdepan wilayah uç: yurtluk (tempat musim dingin) di Söğüt dan yaylak (padang musim panas) di Domaniç. Jadi beylik memulai dengan dua alokasi padang, bukan warisan penaklukan; di peta kedua tempat ini ditampilkan sebagai 'warisan', bukan 'penaklukan'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vespri Siciliani — dinasti Anjou kehilangan Pulau Sisilia", "547db635"], "d": ["Pemberontakan yang pecah di Palermo pada waktu doa petang Senin Paskah melawan pemerintahan Charles I dari Anjou memisahkan Pulau Sisilia dari dinasti Anjou. Kerajaan Sisilia terbagi dua: pulau itu beralih ke Aragon, sedangkan dinasti Anjou bertahan di kerajaan daratan yang berpusat di Napoli. Wilayah luar dinasti di Adriatik dan Mediterania juga tetap terikat pada kerajaan ini: Korfu, yang mereka kuasai sejak 1267, dan Durrës, yang mereka pegang sejak 1270-an, berlanjut sebagai bagian Kerajaan Napoli; benteng-benteng Vlora, Kanina, dan Himara di pesisir Albania juga tetap dalam kerajaan yang berpusat di Napoli (komandan Vlora John of Taxis bertahan melawan Bizantium sepanjang 1282; Durrës, Vlora, dan Kanina kemungkinan besar beralih ke Bizantium pada awal 1285). Malta baru jatuh ke tangan Aragon pada 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Serbuan Kulacahisar — aksi militer pertama Osman Bey", "79b00b14"], "d": ["Entri Osman I di TDV: 'Ia menjarah dan membakar Benteng Kulaca kecil dekat İnegöl (684/1285).' Ini adalah gerakan militer pertama Osman Bey yang dapat ditanggali dalam sumber. Tidak ada permukiman permanen yang direbut; benteng dijarah dan dibakar, sehingga ia lebih berupa serbuan uç klasik daripada penaklukan. Dianggap titik awal aktivitas militer beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Penaklukan Karacahisar — perolehan kota pertama dan penguasaan atas Eskişehir", "178ae619"], "d": ["Entri Osman I di TDV: Osman Bey pada tahun 687 (1288) 'menaklukkan Karacahisar dan menjadi penguasa Eskişehir'. Ini adalah perolehan kota sungguhan pertama beylik, dan menurut riwayat dengan keberhasilan ini Osman Bey naik menjadi sancak beyi di uç; diriwayatkan bahwa khutbah Jumat pertama atas namanya dibacakan di Karacahisar dan kadi pertama diangkat ke sana. Entri Eskişehir di TDV mencatat bahwa tradisi Utsmaniyah memberi tanggal 1291, tetapi kebenarannya diragukan.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Jatuhnya Akka ke Mamluk — pembersihan Tentara Salib dari pesisir Suriah: Sayda dan Beirut", "3ca7a464"], "d": ["Akka, yang lama menjadi pusat Kerajaan Salib Yerusalem, ditaklukkan Sultan Mamluk el-Melikü'l-Eşref Halîl dan kekuasaan Tentara Salib di Palestina berakhir. Ksatria Templar yang mundur dari Akka berlindung di Sayda; ketika pasukan Mamluk mendekat, mereka meninggalkan benteng laut dan melarikan diri ke Siprus, dan kota beralih ke Mamluk pada musim panas yang sama. Beirut, yang berada di tangan Tentara Salib sejak 1197, juga direbut pada 1291 oleh gubernur Damaskus Sencer eş-Şücâî. Dengan demikian keberadaan Tentara Salib dua abad terhapus dari pesisir Suriah-Palestina.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Penaklukan Bilecik dan Yarhisar dengan serbuan malam", "f461b0af"], "d": ["Entri Bilecik di TDV: 'Meski tekfur Bilecik dan tekfur-tekfur lain di wilayah itu menyiapkan pembunuhan terhadap Osman Gazi, ketika persekongkolan ini diketahui, pasukan Utsmaniyah menaklukkan Yarhisar dan Bilecik dengan serbuan mendadak (1299).' Kedua benteng direbut dalam satu operasi, dalam serbuan malam yang sama. Tanggal ini adalah titik balik yang diterima sebagai tahun berdirinya Negara Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Pertempuran Koyunhisar (Bapheus) — kemenangan besar pertama atas pasukan Bizantium", "584a9512"], "d": ["Entri Osman I di TDV: Osman Bey bertempur melawan pasukan Bizantium di Bapheus (Koyunhisar) pada 27 Juli 1302 dan mengalahkannya. Kemenangan ini adalah titik balik yang mengangkat Osman Bey dari uç bey regional menjadi pendiri dinasti. Setelah pertempuran, dataran Bursa masuk ke kendali Utsmaniyah dan blokade İznik dimulai.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Kemenangan Dimbos dan kemudian direbutnya Kite dan Ulubat", "e168ab64"], "d": ["Entri Osman I di TDV: pada tahun 702 (1303), aliansi yang dibentuk para tekfur Bursa, Kestel, Kite, dan Adranos dikalahkan di Celah Dimbos; musuh didorong sambil bertempur hingga selat sempit dan tekfur Kestel tewas di medan perang. Segera setelah kemenangan, benteng Kite dan Ulubat direbut sehingga hubungan darat Bursa terputus dan blokadenya diperketat. Orhan muda juga ikut dalam pertempuran ini.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Ekspedisi Sakarya: direbutnya Leblebicihisar, Lefke, Mekece, dan Geyve", "a51ba4d3"], "d": ["Entri Osman I di TDV memberikan urutan ekspedisi Sakarya tahun 704 (1304): 'Ketika tiba di Leblebici Hisarı, tekfur tunduk... Ia sampai ke Lefke... Ia mencapai Mekece... Ia pergi ke Geyve dan merebut benteng yang didapatinya kosong.' Lefke adalah gerbang lembah Sakarya yang membuka ke Bilecik. Satu ekspedisi ini membawa rantai benteng di sepanjang lembah ke bawah kendali Utsmaniyah dan menutup sayap timur cekungan İznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Sakız beralih ke kendali keluarga Zaccaria dari Genoa", "9eebe4de"], "d": ["Menghadapi ancaman Aydınoğulları, kaisar Bizantium meminta bantuan Benedetto Zaccaria dari Genoa; pulau beralih ke kendalinya (vasalase Bizantium nominal). Kekuasaan Zaccaria berlangsung hingga 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos masuk ke kepemilikan orang Genoa (Zaccaria) di Sakız", "0e6f51e3"], "d": ["Keluarga Zaccaria dari Genoa, yang menguasai Sakız, juga menggabungkan Samos yang hampir kosong ke dalam kepemilikannya (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Penaklukan benteng-benteng Celah Geyve: Karaçepüş, Karatigin, dan Absu", "76907c78"], "d": ["Entri Orhan di TDV: Orhan pada ekspedisi Sakarya tahun 705 (1305) 'menaklukkan benteng Karaçepüş (Katoikia), Karatigin di depan İznik, dan Absu (Hypsu: di Celah Geyve)'. Ketiga benteng ini, dengan menutup lintasan antara lembah Sakarya dan cekungan İznik, memutus bantuan darat İznik sepenuhnya. Gazi Abdurrahman ditempatkan di Karaçepüş dan Absu di celah Geyve; kota kini hanya dapat direbut dengan kelaparan.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Ekspedisi Adranos (Orhaneli) — ekspedisi terakhir Osman Bey", "4811546c"], "d": ["Entri Orhan di TDV mencatat ekspedisi Benteng Adranos pada musim gugur 1323 sebagai ekspedisi terakhir Osman Bey. Tekfur Adranos adalah anggota aliansi tekfur yang dibentuk melawan Utsmaniyah di Dimbos dua puluh tahun sebelumnya; ekspedisi ini berarti penutupan perhitungan itu. Hari penaklukan pasti benteng tidak diketahui; operasi dilanjutkan oleh Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Wafatnya Osman Gazi dan peralihan Orhan Bey ke beylik", "021487cd"], "d": ["Osman Gazi, yang memberi nama pada beylik, wafat pada tahun 724 (1324) menurut kesaksian wakaf Asporça Hatun dan Mekece. Putranya Orhan, yang memimpin pasukan dalam ekspedisi sejak 1305, setelah wafatnya ayahnya naik ke kepala beylik tanpa perebutan takhta apa pun. Pengalihan panji oleh generasi pendiri tanpa guncangan menunjukkan bahwa dinasti melewati ujian besar pertamanya dengan tenang di jalan dari beylik uç menuju negara.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Sakız diambil dari Zaccaria dan diikat ke Bizantium", "f6741b26"], "d": ["Kaisar Andronikos III menyingkirkan Zaccaria dari pulau dan mengikat pulau ke Bizantium dengan gubernur Benedetto III. Pulau akan diduduki oleh Simone Vignosi dari Genoa pada 1346.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos kembali dari Zaccaria ke Bizantium (rantai Sakız)", "08034974"], "d": ["Dengan runtuhnya kekuasaan Zaccaria (terikatnya Sakız ke Bizantium pada 1329), kepemilikan Genoa di Samos juga berakhir.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Pertempuran Pelekanon (Maltepe) dan direbutnya seluruh Kocaeli", "389e7bd4"], "d": ["Entri Orhan di TDV: pada hari pertama pertempuran Orhan Gazi mengirim pasukan tiga ratus orang untuk menarik pasukan Bizantium; pada hari kedua dengan turunnya unit-unit di bawah komando Pazarlu ke dataran, pertempuran membesar, dan ketika kaisar terluka oleh panah, kepanikan melanda pasukan Bizantium. Hasilnya tegas: 'Orhan merebut seluruh Kocaeli; setelah kemenangan, orang İznik tidak punya harapan lagi.' Kota-kota pesisir dari Hereke hingga Üsküdar masuk ke kekuasaan Utsmaniyah, dan Gebze dijadikan pusat wilayah. Ini adalah pasukan kekaisaran Bizantium terakhir yang datang untuk menyelamatkan Istanbul.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Pendirian madrasah Utsmaniyah pertama di İznik", "c85fb625"], "d": ["Orhan Bey, segera setelah merebut İznik, mengangkat Çandarlı Kara Halil sebagai kadi di sana, mengubah sebuah basilika menjadi masjid, dan membangun sebuah imaret serta madrasah di sampingnya, memulai pembangunan kota. Menurut entri Dâvûd-i Kayserî di TDV, pembangunan madrasah selesai pada 1336 dan Orhan Gazi mendatangkan Dâvûd-i Kayserî sebagai müderris dengan 30 akçe sehari. Madrasah ini adalah langkah kelembagaan pertama kehidupan ilmu Utsmaniyah; beylik menambahkan tradisi ilmu di samping kekuatan penaklukan. Berubahnya sebuah ibu kota Bizantium yang direbut menjadi pusat ilmu Islam adalah tanda nyata pertama klaim Utsmaniyah sebagai negara menetap.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizantium diikat dengan upeti — pengepungan İzmit dan perjanjian", "0c1ec8d3"], "d": ["Entri Orhan di TDV: Orhan pada musim panas 733 (1333) mengepung İzmit dengan pasukan besar dan manjanik, kaisar setuju berdamai. Sebagai imbalan Orhan melepaskan pengepungan, Bizantium menerima membayar Orhan 12.000 emas (hyperper) per tahun; 'dengan demikian di mata emir Utsmaniyah, Bizantium menjadi negeri pembayar upeti'. Sebagai imbalannya Orhan akan menjadi sahabat kaisar dan tidak menyerang kota-kota yang terikat pada Bizantium. Sebuah beylik uç mengikat Romawi Timur dengan pajak adalah pernyataan betapa keseimbangan kekuatan telah berbalik.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samothrace beralih dari Venesia ke keluarga Gattilusio dari Genoa", "c499ed5f"], "d": ["Keluarga Gattilusio dari Genoa mengusir orang Venesia, yang menguasai pulau sejak 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Aneksasi Beylik Karesi: Balıkesir, Bergama, Biga, Edremit, dan Erdek", "c7cb0511"], "d": ["Entri Orhan di TDV (İnalcık) menempatkan aneksasi pada 735 (1334-35): setelah wafatnya Demirhan Bey, para gazi Karesi dan Hacı İlbey mengundang Dursun Bey ke takhta dan meminta bantuan Orhan. Orhan mula-mula berbaris ke Balıkesir; ketika Dursun Bey, yang pergi untuk perundingan damai, tewas oleh panah dari Benteng Bergama, beylik itu seluruhnya bergabung ke wilayah Utsmaniyah. Dalam operasi yang sama Kirmasti dan Mihaliç tunduk, Gölyazı direbut, dan Ulubat, yang sebelumnya dibiarkan dengan jaminan, direbut secara definitif. Orhan mengangkat Süleyman Paşa ke sancak Karesi dan menjadikan Biga pusat uç — dengan demikian kader pelaut untuk menyeberang ke Rumelia diperoleh. Catatan: entri Karesioğulları di TDV memberi tahun 746 (1345) untuk peristiwa yang sama; ensiklopedia bertentangan dengan dirinya sendiri. Tempat-tempat lain yang bergabung pada tanggal yang sama: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos masuk ke kepemilikan Maona Sakız", "01628b2f"], "d": ["Dengan direbutnya Sakız oleh Simone Vignosi dari Genoa dan diserahkannya pemerintahan kepada perusahaan Maona, Samos juga masuk ke kepemilikan orang Genoa Sakız (Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Kapitulasi pertama Orhan Gazi dengan Genoa", "e64cb196"], "d": ["Orhan Gazi, yang bersepakat dengan Genoa selama perang Venesia-Genoa, mengirim 1000 pemanah untuk pertahanan Pera setelah pertempuran Selat Februari 1352 dan menyediakan 60.000 emas untuk pengangkutan pasukan; sebagai imbalannya ia menganugerahkan kapitulasi pertama kepada Genoa. Teks lengkap perjanjian itu tidak sampai kepada kita. Ini adalah perjanjian resmi pertama Utsmaniyah dengan sebuah kekuatan laut Eropa dan akan diperbarui tiga puluh lima tahun kemudian pada 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Direbutnya Gelibolu — kepala jembatan permanen di Rumelia", "ba51a160"], "d": ["Gelibolu, yang mereka kenal wilayah sekitarnya antara 1349-1352 sebagai sekutu Kantakouzenos, direbut Utsmaniyah pada 1354; gempa besar yang meruntuhkan tembok kota menciptakan kesempatan. Kepala jembatan sempit di Çimpe dengan demikian menjadi pangkalan sejati di sisi Rumelia Selat dan pintu ke Thrakia terbuka lebar. Gelibolu akan lepas pada 1366 dengan Perang Salib Savoia, tetapi dengan penaklukan kedua pada 1376 masuk secara pasti ke kekuasaan Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Wafatnya penakluk Rumelia Süleyman Paşa", "2dc98228"], "d": ["Süleyman Paşa, putra sulung Orhan Bey dan arsitek penaklukan Rumelia, wafat jatuh dari kuda saat berburu pada musim gugur 1357, tanggal yang paling diterima dari tanggal-tanggal 758 (1357), 759, dan 760 (1359) dalam sumber. Wafatnya şehzade yang mendirikan keberadaan permanen Utsmaniyah di Rumelia dengan penyeberangannya antara 1352-1354 meninggalkan urutan putra mahkota kepada saudaranya Murad. Makam Süleyman Paşa yang dimakamkan di Bolayır tetap menjadi monumen dinasti tertua Utsmaniyah di Eropa.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Undang-Undang Pençik — diletakkannya dasar Korps Janisari", "e5877c2d"], "d": ["Setelah penaklukan Rumelia, atas saran Karamanlı Kara Rüstem dari kalangan ulama, sistem pençik diberlakukan, yang mengatur agar seperlima tawanan perang atau nilai uangnya diberikan kepada negara. Dengan dibesarkannya mereka yang dipilih dari tawanan ini di antara keluarga-keluarga Turki dan diambil menjadi prajurit, terbentuk inti kekuatan infanteri tetap yang terikat langsung kepada sultan — Korps Janisari. Berubahnya beylik uç yang berdasar pada kavaleri suku menjadi negara dengan tentara sentral dimulai dengan pengaturan ini.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Turun ke Thrakia Barat: penaklukan Gümülcine", "9ef69221"], "d": ["Pasukan uç yang beralih ke barat Maritsa setelah direbutnya Edirne merebut Gümülcine, pusat Thrakia Barat, di bawah komando Gazi Evrenos Bey. Kota itu menjadi markas depan tempat Evrenos Bey akan membawa serbuannya ke Makedonia. Dengan demikian bagian Thrakia yang membentang ke pesisir Aegea masuk ke kendali Utsmaniyah dan jalan ke Selanik terbuka.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna beralih ke Kepangeranan Dobruja dan menjadi ibu kota", "2bfe73f9"], "d": ["Dalam proses terurainya Kekaisaran Bulgaria, Varna di pesisir Laut Hitam bergabung dengan Kepangeranan Dobruja yang didirikan Dobrotiç dan dijadikan ibu kota negara kecil ini.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Sebelah barat Filibe: bergabungnya Tatarpazarcığı dan İhtiman", "1664d0e1"], "d": ["Setelah direbutnya Filibe pada 1372, Tatarpazarcığı di ujung hulu lembah Maritsa dan İhtiman yang menjaga celah yang membuka ke Sofia diikat ke pemerintahan Utsmaniyah. Garis ini, yang berada di tangan para bey lokal yang menjadi vasal setelah Pertempuran Çirmen, dibawa ke pemerintahan langsung sehingga jalur Filibe-Sofia menjadi tak terputus. Kemajuan ini adalah persiapan jalan menuju penaklukan Sofia dua belas tahun kemudian.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Pemberontakan Savcı Bey — pemberontakan bersama şehzade dan putra mahkota Bizantium", "75198c33"], "d": ["Savcı Bey, putra Murad I, dan Andronikos Palaiologos, putra Kaisar Bizantium Yohanes V, pada awal Mei 1373 memberontak terhadap ayah mereka secara serentak di Bursa dan Istanbul. Aliansi yang menyatukan putra mahkota kedua dinasti ini cepat ditumpas; Savcı Bey ditangkap, matanya dibutakan, dan ia dieksekusi. Tahun 787 (1385) yang diberikan riwayat Utsmaniyah untuk pemberontakan itu keliru; peristiwa ini jatuh tepat setelah tahun-tahun ketika Bizantium memasuki vasalase Utsmaniyah dan menunjukkan betapa dua istana saling terjalin.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Lembah Struma dan Mesta: bergabungnya Köstendil, Petriç, Nevrokop, dan Drama", "8c0980c4"], "d": ["Lembah Struma dan Mesta, yang berada di tangan para bey lokal Serbia dan Bulgaria yang mulai membayar upeti kepada Utsmaniyah setelah kemenangan Çirmen, dibawa ke pemerintahan langsung Utsmaniyah dengan kemajuan para uç bey. Dengan bergabungnya Köstendil, Petriç, Nevrokop, dan Drama, separuh timur Makedonia terbuka dan Selanik serta Serez masuk lingkaran pengepungan. Meluasnya Rumelia ke barat daya di peta adalah akibat operasi ini.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur merebut Herat: akhir dinasti Kert dan beralihnya Khurasan ke Timurid", "15f6019e"], "d": ["Pada 1380 Khurasan terpecah oleh perebutan antara Serbedar, Kert, dan Muzaffari. Setelah Timur mengirim putranya Mîrân Şah ke wilayah itu, ia sendiri berbaris ke Herat dan, setelah mengepung beberapa waktu, menerima penyerahan kota dari Raja Kert Gıyâseddin Pîr Ali. Pemberontakan yang pecah setelah kepergiannya ditumpas dengan darah oleh Mîrân Şah dan dinasti Kert yang memerintah Herat sejak 1255 diakhiri. Seluruh Khurasan dari Meshed hingga Nishapur masuk ke pemerintahan Timurid pada tanggal ini.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Berakhirnya Beylik Eretna dan berdirinya Negara Kadı Burhâneddin", "60dcaf57"], "d": ["Eretnaoğulları, yang lahir pada 1335 dari jabatan gubernur Ilkhan dan memerintah Anatolia Tengah yang berpusat di Sivas dan Kayseri selama empat puluh enam tahun, terurai karena pertikaian dalam istana. Kadı Burhâneddin, yang menjadi wazir pada Mei 1378, setelah menyingkirkan saingannya Kılıcarslan dan Hacı Şadgeldi, memproklamasikan kesultanannya pada musim gugur 1381, mengakhiri beylik dan mendirikan negara yang dikenal dengan namanya. Dengan demikian tetangga timur Utsmaniyah berganti; garis Sivas-Kayseri sesudahnya akan tetap di tangan Kadı Burhâneddin selama tujuh belas tahun.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Kemajuan ke dalam Makedonia: penaklukan Manastır dan Ohri", "63bb7838"], "d": ["Manastır di Via Egnatia dan Ohri di tepi danau masuk ke pemerintahan Utsmaniyah selama serbuan ke arah Albania. Keduanya adalah titik kunci jalan yang membentang ke Adriatik; Ohri juga merupakan pusat keuskupan agung Ortodoks tertua di Balkan. TDV mencatat bahwa tidak ada informasi pasti untuk tanggal penaklukan Ohri, bahwa tanggal 787 (1385) dan 797 (1395) setelah wafatnya Kraljević Marko dikemukakan; di sini 1385 dijadikan pegangan. Manastır pada abad-abad berikutnya akan menjadi salah satu pusat militer terpenting Rumelia.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Pertempuran Savra — terbukanya gerbang Albania", "dda6671b"], "d": ["Atas seruan bantuan bey Albania Karlo Thopia, yang terdesak menghadapi dinasti Balsha, pasukan Utsmaniyah mengalahkan pasukan Balsha II di dataran Savra; Balsha tewas di medan perang. Pertempuran yang dimasuki atas undangan seorang bey lokal ini memberi Utsmaniyah pengaruh permanen pertama di tanah Albania yang membentang hingga pesisir Adriatik. Kebijakan yang menjadikan bertikainya para bey di wilayah itu sebagai kesempatan ini akan menjadi metode tetap penaklukan Balkan selama abad berikutnya.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Ekspedisi tiga tahun' Timur: direbutnya Azerbaijan dan Iran Utara", "2a98ec51"], "d": ["Timur, yang melihat dari dekat keadaan Iran yang tercerai-berai selama ekspedisi Khurasan, berbaris ke barat pada 788 (1386). Dalam operasi 1386-1388 yang disebut 'ekspedisi tiga tahun', ia melewati Mazandaran, Luristan, dan Georgia ke Azerbaijan dan mencapai Karabakh; Tabriz, Ardabil, Urmia, dan Nakhchivan masuk ke pemerintahan Timurid. Direbutnya Iran Utara dan Azerbaijan juga menjadi awal persaingan panjang dengan Gerombolan Emas, seperti dahulu antara ulus Jochi dan Ilkhan.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Pertempuran Frenkyazısı dan pengepungan Konya — ekspedisi Karaman pertama", "af4e5d77"], "d": ["Murad I berangkat sendiri berekspedisi melawan Karamanoğlu Alâeddin Ali Bey, yang meski merupakan menantunya merasa terganggu oleh ekspansi Utsmaniyah di Anatolia Barat; dalam pertempuran di tempat bernama Frenk Yazısı, tentara Utsmaniyah yang terlatih dan berpengalaman mengalahkan pasukan Karaman. Kemudian Benteng Konya dikepung, tetapi dengan diampuninya Alâeddin Bey beylik tidak dihapus sepenuhnya. Ekspedisi ini adalah babak pembuka perhitungan panjang antara Utsmaniyah dan Karaman yang akan berlangsung satu abad dan baru berakhir dengan aneksasi definitif pada 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muş beralih dari pemerintahan Kara Koyunlu ke pemerintahan Timur (789/1387)", "ed2e7a11"], "d": ["Muş, yang beralih ke pemerintahan Kara Koyunlu setelah masa Mongol, masuk ke pemerintahan Timur, yang menguasai tanah Kara Koyunlu, pada 789 (1387). Dalam atlas Muş dicatat pada tahun ini beralih dari Kara Koyunlu ke Timurid.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Pendirian Galangan Gelibolu — kelahiran armada Utsmaniyah", "47546241"], "d": ["Galangan Utsmaniyah pertama yang terorganisasi didirikan pada 1390 oleh Yıldırım Bayezid di Gelibolu, di lokasi galangan peninggalan Bizantium. Dengan mewarisi warisan maritim beylik-beylik Anatolia Barat, Utsmaniyah untuk pertama kalinya menjadi kekuatan laut yang membuat kapalnya sendiri. Galangan yang terletak di titik kunci Selat Çanakkale ini melayani sebagai pangkalan utama armada Utsmaniyah selama satu setengah abad, dari pengepungan Istanbul hingga ekspedisi Aegea.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Hamîd-ili bergabung ke Utsmaniyah: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Yıldırım Bayezid, yang berekspedisi atas serangan Karamanoğlu Alâeddin Bey terhadap Hamîd-ili dan keluhan rakyat, merebut seluruh sisa wilayah Hamîdoğulları dan menyerahkan pemerintahannya kepada putranya İsa Çelebi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Akhir dinasti Muzaffari: kekalahan Şah Mansûr di depan Shiraz", "5fd14eb8"], "d": ["Şah Mansûr, penguasa kuat terakhir Muzaffari yang memerintah Yazd, Fars, Isfahan, dan Kirman sejak 1318, bergabung dengan kerabatnya dan bergerak melawan Timur. Dalam pertempuran dekat Shiraz, karena salah satu emirnya membelot ke pihak lawan, ia kehilangan sebagian besar pasukannya, kalah, dan dibunuh. Dengan Timur kemudian membunuh seluruh anggota dinasti, kekuasaan Muzaffari berakhir dan Fars serta Kirman bergabung ke pemerintahan Timurid.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Bergabungnya Amasya ke wilayah Utsmaniyah", "fe2860cf"], "d": ["Emir Amasya yang dikepung selama operasi Anatolia Tengah Yıldırım Bayezid menyerahkan kota kepada Utsmaniyah dan Bayezid memasuki kota pada 1393. Sultan menyerahkan pemerintahannya kepada putranya Mehmed Çelebi; sebagai sancak şehzade, Amasya sejak itu menjadi salah satu tempat pendidikan terpenting dinasti Utsmaniyah. Pilihan ini akan menentukan pada Masa Fetret mendatang, dan Çelebi Mehmed akan menjalankan perjuangan menyatukan kembali negara justru dari basis Amasya ini.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur merebut Baghdad — Jalayir melarikan diri ke Anatolia", "4d5602b3"], "d": ["Timur merebut Baghdad setelah pengepungan panjang; Sultan Ahmed dari Jalayir, penguasa kota, melarikan diri ke barat dan berlindung pertama kepada Mamluk, lalu kepada istana Utsmaniyah. Perluasan Timur ke barat dengan demikian untuk pertama kalinya bersentuhan langsung dengan lingkup pengaruh Utsmaniyah. Mata rantai pertama permusuhan antara dua penguasa bermula dari sini.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Direbutnya Varna di pesisir Laut Hitam", "a84b2abf"], "d": ["Dalam proses menyempitnya wilayah Kekaisaran Bulgaria antara Danube dan Laut Hitam, Varna, pelabuhan terbesar di pesisir, beralih ke pemerintahan Utsmaniyah. Direbutnya pelabuhan membuka jalan kemajuan ke arah Dobruja dan memberi Utsmaniyah dermaga besar pertama di pesisir barat Laut Hitam. Varna juga akan menjadi panggung kemenangan 1444, ketika pasukan Salib dimusnahkan lima puluh satu tahun kemudian.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Wilayah Nevşehir dan Ürgüp beralih dari Karamanoğulları ke Utsmaniyah", "06ff59e8"], "d": ["Dalam ekspedisi Yıldırım Bayezid melawan Karamanoğulları, wilayah Nevşehir (Muşkara) dan Ürgüp beralih ke pemerintahan Utsmaniyah pada 800/1398; pada 1402, setelah Perang Ankara, Timur mengembalikan wilayah itu kepada Karamanoğulları.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Runtuhnya Negara Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, yang tertawan oleh penguasa Akkoyunlu Karayülük Osman Bey, menawarkan agar dibebaskan dengan imbalan penyerahan Sivas, tetapi rakyat kota melawan dan sultan dieksekusi di depan tembok. Meski tokoh-tokoh Sivas mendudukkan putranya Alâeddin Ali Çelebi di kepala negara, di hadapan tekanan Akkoyunlu mereka meminta bantuan Yıldırım Bayezid; pasukan Utsmaniyah di bawah komando Süleyman Çelebi mengalahkan Karayülük dan menguasai kota. Dengan demikian Negara Kadı Burhâneddin lenyap dari sejarah dan Sivas, Tokat, Niksar, serta Kayseri bergabung ke wilayah Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Perang kata Timur: pengembalian buronan ditolak", "33790bc8"], "d": ["Atas tekanan Timur, Sultan Ahmed dari Jalayir dan pemimpin Kara Koyunlu Kara Yûsuf berlindung di wilayah Utsmaniyah; Timur meminta kedua buronan itu dikembalikan dan Yıldırım Bayezid menolak. Akibatnya antara kedua penguasa mulai dipertukarkan surat berisi hinaan berat timbal balik. Landasan ideologis perang dibangun dengan surat-menyurat ini, sebelum satu prajurit pun bergerak.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Dârüşşifâ Yıldırım di Bursa — rumah sakit Utsmaniyah pertama", "5f0dc59a"], "d": ["Yıldırım Bayezid, pada tahun-tahun ia membangun Masjid Agung yang megah di Bursa, juga menghadiahkan sebuah dârüşşifâ kepada kota; ini adalah mata rantai program amal luas yang terdiri dari imaret, madrasah, han, dan jembatan yang dialokasikan untuk kedokteran. Bangunan ini, rumah sakit pertama yang didirikan negara, juga berfungsi sebagai sekolah kedokteran yang mendidik tabib dan menentukan model lembaga kesehatan Utsmaniyah. Karya yang selesai hanya dua tahun sebelum bencana Ankara ini adalah salah satu mata rantai terakhir dari visi Yıldırım menjadikan Bursa ibu kota kekaisaran.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur meratakan Sivas", "f4d79de6"], "d": ["Timur, yang berbaris ke Sivas dengan petunjuk Karayülük Osman Bey dari Akkoyunlu dan emir Erzincan Mutahharten, mengepung kota delapan belas hari dan setelah menerimanya dengan janji bahwa darah siapa pun tidak akan tertumpah, melakukan pembantaian besar; para pembela dimasukkan ke parit dan ditimbun hidup-hidup. Karya-karya penting kota, terutama tembok, dihancurkan; Sivas runtuh secara demografis. Ini adalah pukulan besar pertama yang dijatuhkan Timur kepada wilayah Utsmaniyah dua tahun sebelum Perang Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid merebut kembali Erzincan dan Kemah", "7047ca08"], "d": ["Yıldırım Bayezid, yang memanfaatkan keberangkatan Timur ke ekspedisi Suriah, merebut Erzincan dan Kemah dari tangan emir Erzincan Mutahharten yang tunduk kepada Timur. Meski tidak ikut campur dalam kehancuran Sivas, langkah ini berarti tantangan langsung terhadap lingkup pengaruh Timur di Anatolia Timur. Hubungan kedua penguasa sejak itu tak dapat diperbaiki.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum Timur dari Tabriz — empat syarat", "3e1ac50e"], "d": ["Timur melalui utusan yang dikirim dari Tabriz menyampaikan empat syarat: pengembalian Kemah kepada Mutahharten, pengembalian wilayah yang diambil dari bey-bey Anatolia kepada pemiliknya, pengiriman seorang şehzade Utsmaniyah sebagai sandera dan penerimaan külâh dan ikat pinggang sebagai tanda ketundukan, serta penyerahan Kara Yûsuf. Bayezid tidak menerima satu pun; meski didesak para negarawan dan dimediasi Mutahharten, perundingan runtuh. Timur bertekad menutup persoalan Anatolia secara pasti sebelum berangkat ke ekspedisi Tiongkok.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruhanoğulları didirikan kembali — Manisa keluar dari Utsmaniyah", "ac747b05"], "d": ["Tiga minggu setelah kekalahan Ankara, dengan dukungan Timur, Orhan Bey naik ke kepala beylik dan wilayah Saruhan kembali merdeka. Wilayah yang berpusat di Manisa itu hilang dari peta dua belas tahun setelah aneksasi Utsmaniyah 1390. Ini salah satu penerapan pertama dengan tanggal yang diketahui pasti dari kebijakan Timur menghidupkan kembali beylik-beylik.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman melarikan diri ke Rumelia dengan kas negara", "0a2b7363"], "d": ["Emir Süleyman, dengan membawa kas negara di Bursa, arsip, keluarga, dan saudara-saudaranya, menyeberang dari Gemlik dengan kapal ke Güzelcehisar (Anadoluhisarı), dari sana mencapai Gelibolu dan memproklamasikan kekuasaannya di Edirne. Dipindahkannya arsip dan kas negara ke Rumelia adalah awal bergesernya pusat gravitasi Utsmaniyah ke Balkan selama satu generasi. Di peta Rumelia sejak tanggal ini digambar dengan warna Emir Süleyman sendiri.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur mendirikan kembali beylik-beylik Anatolia — persatuan Turki bubar", "15187774"], "d": ["Timur, setelah kemenangan Ankara, mengembalikan para bey yang bersamanya ke wilayah lama mereka. Kepada Karamanoğlu Mehmed dan Ali Bey diberikan wilayah Karaman beserta Kayseri, Kırşehir, Sivrihisar, dan Beyşehir; kepada Germiyanoğlu Yâkub Bey II Kütahya dan wilayah Germiyan; kepada Candaroğlu İsfendiyar Bey, selain garis Kastamonu-Sinop, Çankırı dan Kalecik. Wilayah Aydın, Menteşe, dan Teke juga kembali ke dinasti lamanya. Persatuan Turki Anatolia yang dibangun Yıldırım Bayezid dalam sepuluh tahun bubar dalam satu musim panas; di peta beylik-beylik ini muncul kembali dengan warna masing-masing.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur merebut İzmir dari Ksatria Saint Jean", "66dd1dd4"], "d": ["Timur, yang turun ke barat melalui Kütahya, Denizli, Aydın, Ayasuluk, dan Tire, mengepung dan merebut İzmir di pesisir, yang berada di tangan umat Kristen sejak 1344. Timur, yang dalam waktu singkat menaklukkan benteng yang selama bertahun-tahun tidak dapat direbut Yıldırım Bayezid, setelah menguasai benteng-benteng di sekitarnya, menyerahkan wilayah Aydın kepada pemilik lamanya dan kembali ke timur. Kota itu sejak itu masuk ke pemerintahan Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi merebut Bursa — bagian Anatolia lahir", "955128c1"], "d": ["Îsâ Çelebi, yang mundur ke arah Karesi setelah kekalahan Ankara, merebut Bursa ketika Timur berada di İzmir. Di ibu kota lama yang dijarah dan dibakar prajurit Timur, ia memproklamasikan kekuasaannya dan mencetak koin atas namanya sendiri; pada Januari 1403 ia dikenal di Anatolia dengan gelar penguasa 'Turki'. Di peta bagian ini, yang membentang di sepanjang pesisir Asia Marmara, tampak dengan warna Îsâ Çelebi sendiri.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Penarikan Timur dari Anatolia", "93a98839"], "d": ["Timur, yang menerima kabar bahwa Yıldırım Bayezid wafat di Akşehir, menganggap urusannya di Anatolia selesai dan berpaling ke timur. Yang tertinggal adalah beylik-beylik yang menyatakan kesetiaan kepadanya dan şehzade-şehzade Utsmaniyah yang saling bermusuhan; beberapa kota seperti Sivas ditinggalkan di tangan emir-emir seperti Mezid Bey yang tunduk kepada Timur. Timur tidak pernah kembali ke Anatolia, tetapi tatanan terpecah yang ia dirikan ini bertahan sepuluh tahun.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman menyeberang ke Anatolia: Bursa jatuh ke tangannya", "9b27aa5f"], "d": ["Emir Süleyman, yang mendengar kekalahan Îsâ Çelebi, menyeberang ke Anatolia bersama Çandarlı Ali Paşa dengan pasukan kuat dan merebut Bursa; catatan Maret 1404 menunjukkan bahwa Karadeniz Ereğli juga berada di bawah pemerintahannya. Çelebi Mehmed tidak dapat bertahan menghadapi Süleyman, yang dalam waktu singkat menguasai Rumelia maupun sebagian besar Anatolia. Di peta, dari tanggal ini hingga direbutnya kembali Bursa oleh Çelebi Mehmed (1410), kedua tepi tampak dengan satu warna, bagian Emir Süleyman.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Pertempuran Dataran Yenişehir — Çelebi Mehmed mundur ke Amasya", "f1568288"], "d": ["Çelebi Mehmed, yang kehilangan Bursa dan Ankara, kalah dari Emir Süleyman di dataran Yenişehir dan kehilangan semua perolehannya di Anatolia Barat serta mundur ke pangkalan Tokat-Amasya. Setelah kekalahan ini ia menghindari konfrontasi langsung dan beralih mengokohkan otoritasnya di pedalaman Anatolia. Fase paling panjang yang sunyi dari Masa Fetret dimulai demikian.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman merebut Ankara dari Çelebi Mehmed", "d6a2acd6"], "d": ["Ankara, yang tetap di tangan Çelebi Mehmed setelah penarikan Timur dari Anatolia, dikepung Emir Süleyman pada 1406. Penjaga benteng Yâkub Bey bertahan beberapa waktu, tetapi dengan tipu daya Wazir Agung Çandarlı Ali Paşa menyerahkan benteng kepada Süleyman. Akibatnya Çelebi Mehmed bersepakat dengan Karamanoğlu Mehmed Bey dan bergerak melawan Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed merebut kembali Sivas dari Mezid Bey Timurid", "90079b0c"], "d": ["Setelah invasi Timur, pemerintahan Sivas diserahkan kepada Mezid Bey yang tunduk kepada Timur. Çelebi Mehmed di Amasya mengirim komandannya Bayezid Paşa untuk merebut kota, dan setelah perlawanan sengit Sivas untuk kedua kalinya jatuh ke tangan dinasti Utsmaniyah. Dengan demikian bagian Mehmed enam tahun setelah Perang Ankara mencapai batas lamanya di timur.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Akhir dinasti Artuklu: penyerahan Mardin kepada Kara Koyunlu", "15b06f33"], "d": ["Artuklu, cabang paling lama bertahan dari dinasti yang memerintah Mardin sejak 1106, tidak dapat bertahan di hadapan tekanan Akkoyunlu. Melik Ahmed, yang menyadari tidak dapat mempertahankan kota, bersepakat dengan penguasa Kara Koyunlu Kara Yûsuf dan menyerahkan Mardin kepadanya. Kekuasaan Artuklu yang melebihi tiga abad dengan demikian berakhir; Mardin dan sekitarnya menjadi panggung perebutan Kara Koyunlu-Akkoyunlu hingga beralih ke Utsmaniyah satu abad kemudian.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Pertempuran Yanbolu — Mûsâ Çelebi memasuki Edirne", "8f978408"], "d": ["Mûsâ Çelebi, yang menyeberang ke Rumelia melalui Wallachia, dengan dukungan Wallachia dan Serbia mengalahkan pasukan Emir Süleyman di Yanbolu dan memasuki Edirne. Pada Masa Fetret, Rumelia untuk pertama kalinya lepas dari tangan Emir Süleyman. Namun kekuasaannya tidak bertahan; empat bulan kemudian ia akan kalah di Kosmidion dan mundur ke pedalaman Balkan.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Pertempuran İnceğiz — kekalahan pertama Çelebi Mehmed di Rumelia", "3c35cd43"], "d": ["Çelebi Mehmed, yang menyeberang ke Rumelia dengan kapal Bizantium, bertempur dengan Mûsâ Çelebi di İnceğiz; Mûsâ dengan tujuh ribu janisari di bawah komandonya mengalahkan Mehmed dan Mehmed terpaksa kembali ke Anatolia. Kekalahan ini mengarahkan Mehmed pada strategi menarik para uç bey Rumelia dan despotat Serbia ke pihaknya alih-alih pertempuran langsung. Landasan kemenangan Çamurlu sembilan bulan kemudian dipersiapkan dengan diplomasi ini.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Pengepungan Konya dan perjanjian dengan Karamanoğulları — Hamîd-ili, Said-ili, Beyşehir, Seydişehir, dan Akşehir direbut kembali", "0996257e"], "d": ["Çelebi Mehmed menyelenggarakan ekspedisi besar melawan Karamanoğulları, yang menyerang wilayah Utsmaniyah pada Masa Fetret dan mengepung serta membakar Bursa, dan mengepung Konya pada Muharram 818. Karamanoğlu Mehmed Bey II terpaksa meminta damai; sebagai hasil perjanjian, Hamîd-ili (sekitar Isparta) dan Said-ili kembali bergabung ke wilayah Utsmaniyah, Beyşehir, Seydişehir, dan Akşehir juga dikembalikan; Sivrihisar, yang diberikan Timur kepada Karamanoğulları pada 1402, juga kembali ke Utsmaniyah. Ekspedisi ini, ketika persatuan Anatolia yang terurai oleh Perang Ankara mulai ditambal, adalah salah satu alasan konkret Çelebi Mehmed dianggap 'pendiri kedua'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Direbutnya İzmir dari Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["İzmir, pusat Aydınoğlu Cüneyd Bey yang terus berganti pihak di antara para şehzade selama Fetret, direbut oleh Çelebi Mehmed setelah pengepungan sepuluh hari; Cüneyd diampuni dan dikirim ke sancak beyi Nikopolis. Kota yang dikembalikan Timur kepada Aydınoğulları pada 1402 itu dengan demikian kembali ke Utsmaniyah tiga belas tahun kemudian. Cüneyd akan merebut kota itu kembali pada 1422, dan persoalan itu baru ditutup oleh Murad II pada 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Eksekusi Torlak Kemal — Saruhan secara definitif milik Utsmaniyah", "8a09dbf1"], "d": ["Torlak Kemal, yang menjalankan sayap Anatolia Barat gerakan Syekh Bedreddin, dikalahkan di wilayah Manisa dan dieksekusi. Setelah tanggal ini wilayah Saruhan masuk secara definitif ke kendali Utsmaniyah dan beylik yang dihidupkan Timur pada 1402 lenyap dari sejarah. Sisa politik terakhir Masa Fetret di Anatolia Barat dengan demikian dibersihkan.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Penaklukan Vlora, Berat, dan Kanina", "1e1949b8"], "d": ["Utsmaniyah pada 1417 membawa Vlora di pesisir Adriatik di bawah kekuasaan mereka, bersama kota Berat di pedalaman negeri dan Benteng Kanina. Satu tahun kemudian upaya Venesia merebut kembali kota gagal dan dengan didirikannya organisasi sancak di sana, otoritas Utsmaniyah menjadi permanen. Direbutnya Vlora, untuk pertama kalinya menjadikan Utsmaniyah pemilik pelabuhan langsung di Adriatik dan memberinya papan loncatan seberang laut menghadapi Italia.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Direbutnya kembali Anatolia Tengah: Kayseri dan Kırşehir", "204eacb3"], "d": ["Kota-kota Anatolia Tengah yang jatuh ke tangan Karamanoğulları pada Masa Fetret kembali ke pemerintahan Utsmaniyah selama ekspedisi Çelebi Mehmed untuk menghimpun kembali negara. Dengan bergabungnya Kayseri dan Kırşehir, cekungan Kızılırmak yang hilang dalam Perang Ankara sebagian besar direbut kembali. Kemajuan ini adalah kelanjutan kebijakan berpaling ke timur yang dimulai dengan pengepungan Konya empat tahun sebelumnya.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Mamluk memberikan Kayseri kepada Dulkadırlı Nâsırüddin Muhammed", "aad4b00c"], "d": ["Pasukan Mamluk yang berekspedisi melawan Karamanoğlu Mehmed Bey menduduki Kayseri; komandan Mamluk menyerahkan kota dan sekitarnya kepada Dulkadırlı Nâsırüddin Muhammed dan kembali ke negerinya.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Wafatnya Mehmed I dan naik takhtanya Murad II", "98acac77"], "d": ["Mehmed I, yang mengakhiri Masa Fetret dan menghimpun kembali negeri Utsmaniyah di satu tangan, wafat di Edirne pada 25 Juni 1421 dan putranya Murad naik takhta di Bursa. Menurut pengaturan dengan Bizantium sebelum wafatnya, putra-putra kecilnya akan dikirim sebagai sandera kepada kaisar dan kaisar tidak akan membebaskan penuntut takhta Mustafa Çelebi yang ia tahan; Murad II menolak mengirim saudara-saudaranya kepada kaisar.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Likuidasi definitif Tekeoğulları: direbutnya Antalya", "e65565b2"], "d": ["Beylik Tekeoğulları, yang didirikan kembali dengan dihidupkan Timur setelah Perang Ankara, berakhir ketika pasukan Utsmaniyah di bawah komando Hamza Bey mengepung Antalya; tokoh penting terakhir beylik, Osman Çelebi, disingkirkan. Dengan demikian wilayah Teke di pesisir Mediterania bergabung secara definitif ke Utsmaniyah setelah keterpisahan dua puluh satu tahun. Beylik itu, sebagai cabang yang memisah dari Hamîdoğulları, memerintah di Antalya sejak 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Ekspedisi Mora Turahan Bey dan runtuhnya Tembok Hexamilion", "c6c2706d"], "d": ["Ketika Bizantium mendukung penuntut takhta saingan Mustafa Çelebi, Murad II mengirim Turahan Bey ke Mora. Turahan Bey menghancurkan tembok Hexamilion yang menutup Tanah Genting Korintus dari ujung ke ujung, memasuki semenanjung, dan menyebabkan kehancuran besar. Perdamaian dicapai dengan syarat tembok tidak dibangun lagi dan pajak tahunan dibayar; despotat Mora dengan demikian dibiarkan tak berdaya secara militer dan landasan penaklukan akhir 1460 dipersiapkan tiga puluh tujuh tahun sebelumnya.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Biara-biara Athos masuk ke perlindungan Utsmaniyah", "562de5ea"], "d": ["Pada tahun-tahun ketika Selanik dikepung, republik biara Athos di jari timur Chalkidiki mengajukan permohonan kepada Murad II untuk perlindungan dan menerima kekuasaan Utsmaniyah. Hak milik dan ibadah para biarawan dijamin; biara-biara dibiarkan bebas dalam urusan dalam negeri dengan imbalan pajak. Tatanan ini menjadi contoh terpanjang hubungan perlindungan yang dibangun Utsmaniyah dengan lembaga-lembaga Ortodoks dan berlangsung lima abad.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Aneksasi Beylik Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Atas tekanan beylerbeyi Amasya Yörgüç Paşa, Tâceddinoğlu Hüsâmeddin Hasan Bey menyerahkan kunci negerinya yang berpusat di Niksar pada tahun 830 (1427); kepadanya diberikan sebuah sancak di Rumelia. Beylik yang didirikan pada paruh kedua abad ke-14 dan perbatasannya sesekali membentang hingga Kelkit, Amasya, Samsun, Ordu, dan Giresun itu pun berakhir. Pada tahun yang sama, wilayah milik Hacıemiroğulları juga dicatat (tahrir) dan diikat ke sancak Canik; masa beylik-beylik di Laut Hitam Tengah tertutup.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Penyerahan Beograd kepada Hongaria — Perjanjian Tata", "62481183"], "d": ["Setelah wafatnya despot Serbia Stefan Lazarević, sesuai Perjanjian Tata yang dibuat antara Raja Hongaria Sigismund dan pewarisnya Đurađ Branković, Benteng Beograd diserahkan kepada Hongaria. Benteng yang berdiri di pertemuan Danube dan Sava itu sampai saat itu berada di tangan despotat Serbia dan merupakan kunci gerbang yang membuka ke Eropa Tengah bagi Utsmaniyah. Penyerahan ini menjadikan Beograd rintangan paling keras di depan kemajuan Utsmaniyah selama seratus tahun: pengepungan 1440 dan 1456 akan gagal dan benteng baru jatuh pada 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin beralih dari penjaga Kara Koyunlu ke Karayülük Osman Bey dari Akkoyunlu", "d82bc97f"], "d": ["Mardin, yang direbut Kara Yûsuf pada 1409, diperintah oleh gubernur-gubernur Kara Koyunlu; Emir Nâsır, yang ditinggalkan sebagai penjaga, menyerahkan kota pada 835 (1432) kepada Karayülük Osman Bey dari Akkoyunlu. Pemerintahan Akkoyunlu berlanjut hingga awal abad ke-16.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanoğulları merebut Kayseri dari Dulkadırlı", "2b09e8e8"], "d": ["Bey Karaman, dengan kemenangan atas Dulkadırlı, menggabungkan Kayseri, Ürgüp, Develi Karahisârı, dan Uçhisar ke negerinya.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Peristiwa Buçuktepe — pemberontakan janisari pertama dan kembalinya Murad II ke takhta", "6388dda1"], "d": ["Peristiwa Buçuktepe, pemberontakan janisari pertama yang diketahui sejarah dan pecah di Edirne, bermula dari tuntutan kenaikan setengah akçe dalam ulûfe mereka dan berujung pada diturunkannya Mehmed II muda dari takhta. Murad II berangkat tergesa-gesa dari Manisa pada 8 Safar 850 dan memulai kesultanannya yang kedua. Peristiwa ini menjadi tanda pertama bahwa ocak kapıkulu kini menjadi kekuatan yang memiliki suara atas takhta dan membentuk kewaspadaan Fatih terhadap janisari seumur hidup.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Bergabungnya pesisir Epirus: Arta dan Preveze", "796f7ecf"], "d": ["Sembilan belas tahun setelah menyerahnya Yanya pada 1430, Arta dan Preveze di bagian pesisir despotat Epirus juga masuk ke pemerintahan Utsmaniyah. Dengan demikian Teluk Ambrakia yang membuka ke Laut Ionia dibawa ke bawah kendali dan hubungan laut Yanya lengkap. Preveze adalah titik kunci teluk yang sembilan puluh tahun kemudian akan memberi nama pada kemenangan Barbaros yang tercatat dalam sejarah.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Wafatnya Murad II dan naik takhtanya Mehmed II untuk kedua kali", "8f8256ad"], "d": ["Murad II, yang jatuh sakit setelah pernikahan putranya, wafat di Edirne pada 1 Muharram 855 (3 Februari 1451). Mehmed II yang berusia sembilan belas tahun naik ke takhta Utsmaniyah untuk kedua kalinya pada 16 Muharram 855 (18 Februari 1451) — kali ini secara permanen. Kembalinya penguasa muda yang diturunkan dari takhta lima tahun sebelumnya di Buçuktepe adalah awal pemerintahan yang dua tahun kemudian akan dimahkotai dengan penaklukan Istanbul dan mengubah Beylik Utsmaniyah menjadi kekaisaran dunia.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Pengepungan Kefe pertama oleh pasukan gabungan Utsmaniyah-Krimea", "e346d163"], "d": ["Khan Krimea Hacı Giray, yang bersepakat dengan Fâtih Sultan Mehmed pada Juni 1454, mengepung Kefe dari darat dengan 7000 penunggang kuda; armada Utsmaniyah yang terdiri dari lima puluh-enam puluh galai juga ditempatkan di lepas pantai. Kefe milik Genoa menghentikan pengepungan dengan membayar upeti dan penaklukan definitif tertunda hingga dua puluh satu tahun kemudian, 1475. Operasi bersama pertama ini adalah contoh pertama kerja sama militer Utsmaniyah-Krimea yang akan diulang pada penaklukan definitif Kefe.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Direbutnya pulau-pulau Aegea Utara: Bozcaada, İmroz, dan Taşoz", "76575895"], "d": ["Segera setelah penaklukan Istanbul, Sultan Mehmed Fatih berpaling ke pulau-pulau di mulut Aegea Selat Çanakkale untuk mengamankan jalur laut ibu kota baru; Bozcaada dan İmroz diambil dari Bizantium, sedangkan Taşoz dari keluarga Gattilusio keturunan Genoa. Pulau-pulau yang mengunci kedua tepi selat ini sejak itu menjadi mata rantai pertama jalur perbekalan dan pertahanan Istanbul. Dengan intervensi armada Kepausan dan Venesia, kekuasaan sempat bolak-balik beberapa waktu dan baru pasti pada 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Penaklukan Kosovo: direbutnya Priştine dan Yenipazar", "d7ed2345"], "d": ["Pasukan Utsmaniyah yang berbaris melawan Despotat Serbia merebut Priştine di dataran Kosovo dan Yenipazar, pusat wilayah Raška; dalam operasi yang sama Novo Brdo yang terkenal dengan tambang peraknya juga direbut. Dengan demikian separuh selatan Serbia diikat ke pemerintahan Utsmaniyah langsung dan despotat di Semendire terputus dari wilayah intinya. Penaklukan ini adalah langkah penentu di jalan menuju aneksasi penuh Serbia empat tahun kemudian.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpek (Peć) masuk ke pemerintahan Utsmaniyah — salah satu pusat sancak Dukakin", "19511588"], "d": ["Pada 1455, segera setelah ekspedisi Serbia Fâtih Sultan Mehmed, İpek, pusat patriarkat Serbia, beralih ke pemerintahan Utsmaniyah; dalam sumber-sumber Utsmaniyah tidak ada catatan tentang peralihan ini. Kota kecil itu seiring waktu menjadi kota Muslim kecil dan menjadi salah satu tempat tinggal sancak beyi di sancak Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Penaklukan Enez dan Semadirek — selesainya pesisir Thrakia Barat", "106e723b"], "d": ["Enez, di tempat Sungai Maritsa bermuara ke laut, direbut dari keluarga Gattilusio keturunan Genoa yang menguasainya selama delapan puluh tahun; pulau Semadirek yang terikat padanya juga direbut dalam operasi yang sama. Dengan jatuhnya Enez, jalur pesisir Thrakia Barat dari Selanik hingga Gelibolu menjadi wilayah Utsmaniyah tanpa putus. Di tangan keluarga Gattilusio hanya tersisa Midilli; itu pun akan direbut enam tahun kemudian.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Kegagalan pengepungan Beograd", "3d53a604"], "d": ["Sultan Mehmed Fatih, setelah penaklukan Istanbul, mengepung Beograd yang dianggap kunci Eropa Tengah; namun bala bantuan yang dibawa Jan Hunyadi melalui Danube dan sukarelawan yang dihimpun pendakwah salib Kapistrano mencegah jatuhnya benteng. Sultan, meski menunjukkan keberanian pribadi di depan pengepungan, terluka dan terpaksa mundur. Kegagalan ini akan menutup perbatasan Hongaria bagi kemajuan Utsmaniyah selama enam puluh lima tahun; Beograd baru dapat direbut oleh Kanuni pada 1521.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Penaklukan Mora Utara: Balyabadra (Patras)", "c08a8509"], "d": ["Pasukan Sultan Mehmed Fatih, yang berpaling ke despotat Mora pada tahun-tahun yang sama dengan aneksasi Serbia, merebut Balyabadra di barat laut semenanjung. Pelabuhan yang menguasai mulut Teluk Korintus ini adalah kunci masuk darat ke Mora; direbutnya menyiapkan landasan penaklukan akhir dua tahun kemudian. Kota itu adalah dermaga besar terakhir tempat para despot Bizantium berhubungan dengan dunia Latin.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Direbutnya pesisir Laut Hitam Barat: Amasra", "f43608fc"], "d": ["Amasra, koloni berbenteng Genoa di Laut Hitam Barat, menyerah tanpa perlawanan di bawah tekanan bersama armada dan pasukan darat Sultan Mehmed Fatih. Pelabuhan di pesisir Bartın-Zonguldak ini berdiri sebagai kantong Latin di antara Candaroğulları dan wilayah Utsmaniyah; dengan direbutnya, pesisir menjadi satu. Jatuhnya Amasra adalah langkah pertama ekspedisi besar Laut Hitam yang dua tahun kemudian (1461) akan menuju Sinop dan Trabzon.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Penaklukan Pulau Midilli (Lesbos)", "fe17aeba"], "d": ["Pasukan Utsmaniyah di bawah komando Fâtih Sultan Mehmed menganeksasi Midilli dengan merebutnya dari tangan keluarga Gattilusio keturunan Genoa pada Zulhijah 866 setelah pengepungan singkat tetapi sengit. Jatuhnya pulau terbesar Aegea Utara itu juga melikuidasi pangkalan penting terakhir Genoa di wilayah itu. Pulau itu, berkat kedekatannya dengan pesisir Anatolia, sesudahnya akan berfungsi sebagai pos depan armada Utsmaniyah, dan juga masuk sejarah kelautan sebagai tempat saudara-saudara Barbaros dibesarkan.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Dimulainya Perang Utsmaniyah-Venesia enam belas tahun", "563ddb68"], "d": ["Venesia memulai perang pada 1463 dengan bersekutu bersama penguasa Karaman dan Akkoyunlu untuk menghentikan kemajuan Utsmaniyah di Mora dan Aegea. Strategi pengepungan ini, yang dibangun dengan Uzun Hasan di timur, Venesia di barat, dan Karaman di antaranya, memaksa Fatih bertempur di beberapa front sekaligus. Perjuangan enam belas tahun itu akan mencakup semua operasi besar zamannya dari Otlukbeli hingga ekspedisi Albania dan baru berakhir dengan Perjanjian Istanbul 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Penaklukan sebagian besar Herzegovina: Trebinje dan Mostar", "f54c0100"], "d": ["Wilayah Adipati Herzegovina Stjepan Vukčić-Kosača, yang membentuk pemerintahan terpisah dari Bosnia, sebagian besar beralih ke pemerintahan Utsmaniyah tiga tahun setelah runtuhnya Kerajaan Bosnia: di selatan Trebinje direbut pada 1466 \"bersama hampir seluruh wilayah Herzegovina\". Mostar, yang didirikan di sekitar dua benteng kecil jembatan Neretva, pasti direbut tak lama sebelum penaklukan Blagaj, pusat Herzegovina, pada 1466-1468; ia tercatat dengan nama \"Köprülü Hisar\" dalam tahrir icmal Bosnia 1468-1469. Dengan benteng-benteng adipati yang tersisa, penaklukan Herzegovina tuntas pada 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Ekspedisi Albania II — pawai Fatih sendiri melawan İskender Bey", "9cdd2bfa"], "d": ["Untuk mematahkan perlawanan İskender Bey yang melebihi seperempat abad, Sultan Mehmed Fatih menyelenggarakan ekspedisi besar yang ia komandoi sendiri pada 1466-1467. Pasukan Utsmaniyah mengepung Akçahisar dan membangun Benteng İlbasan (Elbasan) untuk mengendalikan wilayah. Ekspedisi mematahkan tulang punggung perlawanan Albania tetapi gagal merebut benteng; ketundukan penuh wilayah itu akan memakan waktu sepuluh tahun setelah wafatnya İskender Bey.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Pasukan depan Akkoyunlu merebut Benteng Bingöl dari Kara Koyunlu", "51b94cbc"], "d": ["Pada minggu-minggu terakhir ekspedisi Cihan Şah melawan Uzun Hasan, pasukan depan Akkoyunlu merebut Benteng Bingöl; dengan terbunuhnya Cihan Şah pada 10 November 1467, kekuasaan Kara Koyunlu di wilayah itu berakhir.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Runtuhnya Negara Kara Koyunlu: terbunuhnya Cihan Şah", "30bc6358"], "d": ["Penguasa Kara Koyunlu Cihan Şah, yang disergap saat kembali dari ekspedisi melawan Uzun Hasan karena desakan musim dingin, terbunuh saat melarikan diri antara Bingöl dan Kiğı. Setelah pukulan ini negara tidak dapat pulih; penguasa terakhir Hasan Ali pada 1469 ditawan dan dibunuh oleh Uğurlu Mehmed, putra Uzun Hasan. Kekuasaan Kara Koyunlu yang berlangsung hampir satu abad di Anatolia Timur, Azerbaijan, dan Irak dengan demikian beralih kepada Akkoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Wafatnya İskender Bey — padamnya perlawanan Albania", "9158c35f"], "d": ["İskender Bey, yang dibesarkan di istana Utsmaniyah, memberontak setelah kekalahan Zlatica 1444 dan melawan di Albania selama lebih dari seperempat abad, wafat di Lezhë tempatnya berlindung. Perlawanan yang berulang kali menyibukkan pasukan Utsmaniyah pada masa Murad II dan Fatih ini kehilangan kepemimpinan sentralnya dengan wafatnya. Dengan runtuhnya front Albania yang diberi makan Kepausan dan Venesia, Utsmaniyah dalam sepuluh tahun merebut Akçahisar dan İşkodra dan memasukkan wilayah itu secara pasti ke wilayahnya.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Pemerintahan Utsmaniyah didirikan di Kayseri: Gedik Ahmed Paşa mengakhiri Karamanoğulları", "33cf35fc"], "d": ["Dengan Gedik Ahmed Paşa mengakhiri Karamanoğulları pada 1474, Kayseri masuk ke pemerintahan Utsmaniyah; kota itu sepanjang abad ke-15 berpindah tangan antara Dulkadıroğulları, Ramazanoğulları, dan Karamanoğulları. Dengan pemerintahan Utsmaniyah, Kayseri menjadi pusat sancak beylerbeylik Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos ditinggalkan: kepemilikan Genoa (Maona) berakhir", "5bdc380c"], "d": ["Menurut TDV, pulau ditinggalkan setelah 1475; pada 1479 Sultan Mehmed Fatih menaklukkan pulau dan membangun benteng.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Kekalahan Racova (Vaslui) di Moldavia", "a1a74bf7"], "d": ["Voivode Moldavia Stefan cel Mare menarik pasukan Utsmaniyah di bawah komando Beylerbeyi Rumelia Hadım Süleyman Paşa ke medan berawa dan menimbulkan kekalahan berat. Kekalahan ini, salah satu kekalahan darat terberat masa Fatih, menimbulkan gaung besar di Eropa dan memberi Stefan nama di dunia Salib. Sultan akan berangkat sendiri berekspedisi tahun berikutnya sebagai pembalasan.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Kemenangan Akdere (Valea Albă) — ekspedisi Moldavia", "45a66791"], "d": ["Fatih Sultan Mehmed, yang berangkat sendiri berekspedisi untuk membalas kekalahan Racova setahun sebelumnya, menimbulkan kekalahan besar atas pasukan Utsmaniyah dan pasukan Moldavia di tempat bernama Akdere dan memasuki Suceava, pusat beylik. Namun benteng-benteng tidak dapat direbut; karena kesulitan perbekalan, wabah yang muncul di antara janisari, dan persiapan Hongaria, pasukan terpaksa mundur. Kesetiaan pasti Moldavia baru dapat dicapai pada tahun-tahun berikutnya dan dengan direbutnya Kili dan Akkirman pada 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Penaklukan Akçahisar (Krujë) dan selesainya Albania", "559a79b4"], "d": ["Sepuluh tahun setelah wafatnya İskender Bey, pada 1478, dengan direbutnya Akçahisar, Drivasto, Lezhë, dan Jabyak, penaklukan Albania sebagian besar selesai. Jatuhnya Benteng Krujë, yang bertahun-tahun melawan pasukan Utsmaniyah dan menjadi simbol perlawanan İskender Bey, berarti akhir aliansi Venesia-Albania di wilayah itu. İşkodra yang tersisa akan diserahkan kepada Utsmaniyah dengan Perjanjian Istanbul yang akan ditandatangani tahun berikutnya.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Bergabungnya Semenanjung Taman", "4ef917b8"], "d": ["Setelah direbutnya Kefe dan Kerç pada 1475, armada yang dikirim Sultan Mehmed Fâtih ke pesisir Kaukasus merebut Matrega (Tamatarkha) milik Genoa di Semenanjung Taman bersama Anapa dan Kopa. Dengan demikian kedua tepi selat dibawa ke bawah kendali dan pintu masuk Laut Azov sepenuhnya terkendali. Taman diikat ke sancak Kefe sebagai gerbang yang membuka ke Kaukasus Utara.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Masuknya Samos ke pemerintahan Utsmaniyah (Fatih)", "c877bc14"], "d": ["Sultan Mehmed Fatih menaklukkan Samos, membangun benteng, dan menata ulang sensus; benteng dirobohkan Bayezid II pada 1483 karena alasan politik.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Kegagalan pengepungan Rhodes", "35a85c28"], "d": ["Armada 160 kapal di bawah komando Mesih Paşa atas perintah Fatih Sultan Mehmed mengepung Rhodes pada musim semi 885 (1480) dan pulau tetap terblokade selama tiga bulan. Ksatria Saint-Jean di bawah pimpinan grandmaster Pierre d'Aubusson melawan dengan sengit meski kerugian berat; ketika serangan besar terakhir pada 20 Cemâziyelevvel 885 juga dipukul mundur, armada mundur pada 3 Agustus. Setelah kegagalan ini tembok kota dibangun kembali dari awal dan dijadikan benteng terkuat Eropa, dan pulau itu baru dapat direbut oleh Kanuni pada 1522.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikaria (Ikaria) masuk ke pemerintahan Ksatria Saint Jean Rhodes", "5cbc2669"], "d": ["Nikaria, antara Samos dan Sakız, berada di bawah pemerintahan Ksatria Saint Jean Rhodes dari 1481 hingga 1521.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Pertempuran Yenişehir — kekalahan Sultan Cem", "c35abee2"], "d": ["Dua saudara yang bergerak memperebutkan takhta setelah wafatnya Fatih berhadapan di dataran Yenişehir, dan Sultan Cem menderita kekalahan telak. Şehzade yang memerintah delapan belas hari di Bursa dan mengumandangkan khutbah atas namanya itu setelah kekalahan terpaksa berlindung pertama ke Konya, lalu ke wilayah Mamluk. Yenişehir memulai krisis dinasti terpanjang dalam sejarah Utsmaniyah: persoalan Cem akan melumpuhkan kebijakan luar negeri Utsmaniyah menghadapi Eropa selama empat belas tahun.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Aneksasi Herzegovina", "bf247891"], "d": ["Wilayah Kadipaten Herzegovina, yang bertahan setelah penaklukan Bosnia pada 1463, beralih ke pemerintahan Utsmaniyah secara bertahap: Trebinje dan Mostar direbut pada 1466, sancak Herzegovina dibentuk pada 1470, dan wilayah terakhir kadipaten di pesisir Adriatik, bersama Herceg Novi, ditaklukkan pada awal 1482 dan digabungkan ke sancak. Dengan demikian wilayah pegunungan di belakang Adriatik seluruhnya menjadi milik Utsmaniyah dan Bosnia serta Herzegovina menjadi satu geografi administratif. Putra adipati terakhir yang masuk ke istana Utsmaniyah adalah Hersekzâde Ahmed Paşa, yang kelak naik hingga jabatan sadrazam.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Zakynthos diserahkan kepada Venesia dengan upeti tahunan", "268a691a"], "d": ["Zaklise (Zakynthos), salah satu pulau Ionia yang diambil dari keluarga Tocco pada akhir masa Fatih, diserahkan kepada Venesia karena sultan baru yang sibuk dengan persoalan Sultan Cem mencari ketenangan di Barat. Pulau itu diserahkan kepada pemerintahan Venesia yang mengakui kekuasaan sultan Utsmaniyah dan membayar upeti tahunan lima ratus dukat. Dengan demikian pemerintahan langsung Utsmaniyah di Laut Ionia tinggal di Ayamavra.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Sultan Cem berlindung ke Rhodes", "2228d6da"], "d": ["Sultan Cem, yang upaya mengepung Konya juga tidak berhasil, melarikan diri dari Anatolia dengan sekitar tiga puluh orang, mencapai Rhodes, dan disambut dengan upacara oleh Ksatria Saint-Jean. Namun keramahan itu dengan cepat berubah menjadi penawanan; şehzade diserahkan pertama kepada Prancis, kemudian kepada Kepausan, dan menjadi kartu di tangan politik Eropa. Bayezid II terpaksa membayar tahunan sebagai imbalan ditahannya saudaranya, dan langkah-langkah militer Utsmaniyah menghadapi Barat ditangguhkan hingga wafatnya Cem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Dimulainya Perang Utsmaniyah-Mamluk (front Çukurova)", "3fe3f0c7"], "d": ["Perebutan pengaruh atas Dulkadıroğulları dan permusuhan yang ditinggalkan berlindungnya Sultan Cem di wilayah Mamluk memulai pada 1485 perang antara dua kekuatan besar Sunni yang akan berlangsung enam tahun. Dalam pertempuran di sekitar Adana dan Tarsus di Çukurova, kedua pihak tidak dapat meraih keunggulan atas satu sama lain; pasukan Utsmaniyah menerima beberapa pukulan berat. Perang ini adalah fase pertama patahnya hubungan Utsmaniyah-Mamluk dan pembukaan proses yang akan diakhiri tiga puluh tahun kemudian oleh ekspedisi Yavuz ke Marj Dabiq dan Ridaniye.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Perdamaian Utsmaniyah-Mamluk — mediasi Tunisia", "60dd6719"], "d": ["Dalam perang Utsmaniyah-Mamluk yang dimulai pada 1485, kedua pihak tidak dapat meraih kemenangan pasti; dengan mediasi Penguasa Tunisia Osman Hafsî, kesepakatan dicapai pada 1491. Perjanjian itu sebagian besar mengembalikan perbatasan ke keadaan sebelum perang dan perhitungan antara dua negara Islam ditunda selama satu generasi. Perjuangan melelahkan enam tahun adalah salah satu alasan utama kebijakan luar negeri Bayezid II yang berhati-hati dan penekanannya pada penataan dalam negeri alih-alih berpaling ke timur.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Diterimanya Yahudi Sefardi yang diusir dari Spanyol oleh Utsmaniyah", "5c2b5c24"], "d": ["Sebagian orang Yahudi yang melarikan diri dari kekejaman inkuisisi di Spanyol setelah jatuhnya Granada berlindung di wilayah Utsmaniyah dan dimukimkan di berbagai kota. Di bawah pemerintahan Utsmaniyah, komunitas-komunitas Sefardi ini memperoleh kebebasan yang belum pernah mereka alami sampai saat itu, seperti bermukim di mana pun yang mereka inginkan, menjalankan kepercayaan, membuka lembaga pendidikan, dan membangun sinagoga baru. Migrasi yang mengubah kehidupan ekonomi Selanik dan Istanbul dengan percetakan, kedokteran, dan pengetahuan keuangan yang mereka bawa ini menjadi contoh tatanan toleransi Utsmaniyah yang paling banyak dibicarakan di Eropa.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Wafatnya Sultan Cem — berakhirnya penyanderaan empat belas tahun", "f6588b70"], "d": ["Sultan Cem, yang diserahkan dari Kepausan kepada Raja Prancis Charles VIII, wafat di tempat bernama Castel Capuana setelah berangkat dari Roma pada 27 Januari 1495; sumber-sumber mencatat bahwa ia mungkin diracun oleh kalangan kepausan. Wafatnya şehzade yang selama empat belas tahun ditahan di tangan negara-negara Eropa sebagai kartu ancaman terhadap Utsmaniyah akhirnya membebaskan tangan Bayezid II. Memang sultan sesudahnya menyatakan perang kepada Venesia dan membawa armadanya ke kemenangan besar pertama.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Kemenangan laut Sapienza (Zonchio) — keberhasilan armada besar pertama di Mediterania", "9754aaef"], "d": ["Bayezid II, yang menemukan tangannya bebas dengan berakhirnya persoalan Cem, menyatakan perang kepada Venesia pada 1499; armada Utsmaniyah mengalahkan armada Venesia di lepas Sapienza (Zonchio) dan meraih kemenangan laut besar pertama di Mediterania. Dengan kemenangan ini armada menyatakan bahwa kini ia dapat menghadapi Venesia di laut.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Hilangnya Kefalonia dan Ithaca", "60f0f687"], "d": ["Venesia, yang terguncang oleh direbutnya Modon dan Koron, bersatu dengan Spanyol dan beralih ke serangan balik dan mengepung Kefalonia yang berada di tangan Utsmaniyah sejak 1479. Setelah perlawanan empat puluh tujuh hari benteng jatuh, pulau beralih ke Venesia bersama Ithaca dan tidak kembali ke pemerintahan Utsmaniyah selama tiga ratus tahun. Kehilangan ini menciptakan keseimbangan ketika apa yang diperoleh di Mora dikembalikan di Ionia.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Runtuhnya Khanat Gerombolan Emas dan bangkitnya Krimea", "0d1dc515"], "d": ["Penguasa terakhirnya Şeyh Ahmed Han (1481-1502) tidak dapat menyelamatkan negerinya dari kemelut yang ia alami dan Khanat Gerombolan Emas lenyap dari sejarah pada 1502 dengan pukulan Khan Krimea Mengli Giray. Sebagai hasil perebutan takhta dan perpecahan, di wilayah Gerombolan Emas lama muncul khanat-khanat Krimea, Kazan, Nogai, Astrakhan, dan Sibir. Kemenangan Krimea di bawah perlindungan Utsmaniyah ini menjadikan pengaruh Utsmaniyah di utara Laut Hitam tak terbantahkan, sementara kekosongan yang muncul di wilayah itu akan diisi Moskow pada abad berikutnya.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Berakhirnya Perang Utsmaniyah-Venesia dan perdamaian", "125b1526"], "d": ["Perang yang dimulai pada 1499 dan mengguncang Venesia dengan Sapienza, Lepanto, serta hilangnya Modon dan Koron berakhir dengan perdamaian pada 1502. Venesia, setelah kehilangan pangkalan terpentingnya di Mora, terpaksa mengakui keunggulan Utsmaniyah sebagai imbalan mempertahankan imtiyaz dagangnya di Mediterania Timur. Pemerintahan Bayezid II yang dianggap berhati-hati telah mengangkat Utsmaniyah dengan perang ini untuk pertama kalinya ke kedudukan kekuatan laut yang serius di Mediterania.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Pemberontakan Şahkulu — pemberontakan Kızılbaş dari wilayah Teke hingga Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, yang memperlihatkan pemberontakannya pada 1510 dengan pengaruh propaganda Safawi di Anatolia, menyerbu pasar Antalya pada Maret 1511 dan mengalahkan pasukan Utsmaniyah di Kütahya dan sekitarnya pada April. Dalam pertempuran terakhir dengan sadrazam Hadım Ali Paşa dekat Sivas kedua pihak menderita kerugian berat; baik sadrazam maupun pemimpin pemberontakan tewas. Pemberontakan yang mengguncang otoritas negara di Anatolia ini memperlihatkan kekosongan kekuasaan tahun-tahun terakhir Bayezid II dan menjadi alasan terkuat bagi pawai Şehzade Selim ke takhta.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Pengunduran diri Bayezid II dari takhta dan naik takhtanya Yavuz Sultan Selim", "c4cfab69"], "d": ["Atas tekanan Şehzade Selim, yang memperoleh dukungan janisari dalam perebutan takhta dengan saudara-saudaranya, Bayezid II mengundurkan diri dari takhta pada 24 April 1512 dan Selim I naik takhta pada hari yang sama sebagai penguasa Utsmaniyah kesembilan. Sultan tua itu wafat di tengah jalan, di desa Abalar dekat Çorlu, pada 25 Rebîülevvel 918 (10 Juni 1512) dalam perjalanan ke Dimetoka tempat ia lahir. Kesultanan yang berhati-hati dan berorientasi ke dalam selama tiga puluh satu tahun digantikan oleh masa Yavuz yang dalam delapan tahun akan melipatgandakan perbatasan kekaisaran.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Penaklukan Benteng Sinj", "83271ea5"], "d": ["Pasukan akıncı Utsmaniyah di perbatasan Bosnia merebut Benteng Sinj yang membentang ke pedalaman Dalmatia dari Kerajaan Hongaria. Ini adalah mata rantai awal garis perbatasan Dalmatia yang sembilan tahun kemudian akan meluas dengan penaklukan Knin dan sekitarnya oleh Gazi Hüsrev Bey; benteng akan hilang ke Venesia pada 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Pertempuran Yenişehir dan disingkirkannya Şehzade Ahmed", "e2ed15dd"], "d": ["Yavuz Sultan Selim mengalahkan kakaknya Şehzade Ahmed, saingan terkuat untuk takhta, di dataran Yenişehir dekat Bursa dan melenyapkannya setelah menawannya. Dengan demikian pertikaian saudara yang berlangsung sejak 1511 tertutup dan perpecahan internal di Anatolia berakhir. Selim, setelah mengamankan punggungnya, memperoleh kebebasan untuk berpaling ke persoalan Safawi.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Masuknya Yavuz Sultan Selim ke Tabriz", "dad2e227"], "d": ["Setelah kemenangan Çaldıran, pasukan Utsmaniyah memasuki Tabriz, ibu kota Safawi, dan khutbah di kota dibacakan atas nama sultan. Selim tinggal seminggu di sana dan memindahkan sebagian seniman dan ulama Tabriz ke Istanbul; pemindahan ini akan sangat memengaruhi seni istana Utsmaniyah. Meski kota ditinggalkan karena mendekatnya musim dingin dan ketidakpuasan janisari, keunggulan Safawi di Timur telah patah. Di peta tempat-tempat yang beralih ke Utsmaniyah pada hari ini tidak saling bersambungan, dan itu benar: Tabriz adalah pendudukan pasukan selama sembilan hari; dataran Erzincan menyerah tanpa perang selama ekspedisi, sedangkan benteng Kemah di tengahnya bertahan di pihak Safawi hingga 19 Mei 1515; Siirt direbut kembali dari Safawi oleh Halil Bey, penguasa Hasankeyf yang dibebaskan dari penjara Syah Ismail di Tabriz, dengan tunduk kepada Utsmaniyah — Diyarbakır di sekitarnya tetap Safawi hingga 1515 dan Hasankeyf hingga 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş dan Bingöl (Çapakçur) beralih dari Safawi ke pemerintahan Utsmaniyah", "b0a53b5a"], "d": ["Dengan direbutnya Anatolia Timur dari Safawi setelah Çaldıran, Muş masuk ke pemerintahan Utsmaniyah pada 921/1515; Çapakçur (Bingöl) di dekatnya bergabung ke Utsmaniyah dalam proses yang sama.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Penaklukan Benteng Kemah dari Safawi", "73fd8671"], "d": ["Yavuz Sultan Selim, yang melewati musim dingin di Amasya dalam perjalanan pulang dari Çaldıran, menugaskan Bıyıklı Mehmed Paşa untuk menaklukkan Benteng Kemah yang menguasai titik penyeberangan Efrat. Pada akhir pengepungan yang diikuti sultan sendiri, benteng direbut dari tangan Safawi dan gerbang Anatolia Timur terbuka. Penaklukan ini adalah langkah konkret pertama yang mengubah kemenangan Çaldıran menjadi perolehan wilayah yang permanen.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Kemenangan Turnadağ — Beylik Dulkadir menjadi vasal Utsmaniyah", "fd879145"], "d": ["Pasukan Utsmaniyah mengalahkan Bey Dulkadir Alâüddevle Bozkurt, yang bersikap mendua selama ekspedisi Çaldıran, di tempat bernama Ördekli antara Göksun dan Andırın; Alâüddevle tewas dalam pertempuran ini. Beylik tidak dianeksasi pada tanggal ini: setelah Alâüddevle, Şehsuvaroğlu Ali Bey diangkat Yavuz Sultan Selim menjadi kepala Beylik Dulkadıroğulları dan negeri yang berpusat di Maraş-Elbistan berlanjut sebagai beylik vasal Utsmaniyah. Penyangga di perbatasan Mamluk dengan demikian masuk ke kendali Utsmaniyah dan jalan ekspedisi Mesir dua tahun kemudian terbuka; aneksasi baru akan terjadi setelah Ali Bey dibunuh.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Penaklukan Âmid (Diyarbakır) dan pendirian beylerbeylik Diyarbekir", "a6867d5b"], "d": ["Setelah İdrîs-i Bitlisî memenangkan bey-bey Kurdi Sunni di wilayah itu bagi Utsmaniyah, pasukan Safawi tidak dapat bertahan menghadapi pengepungan panjang dan kunci-kunci Âmid diserahkan kepada Bıyıklı Mehmed Paşa. Kota dijadikan pusat beylerbeylik Diyarbekir yang baru didirikan. Dengan demikian inti administratif Mesopotamia Hulu jatuh ke tangan Utsmaniyah.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Penaklukan Harput — terbukanya jalan Diyarbekir", "564eb269"], "d": ["Beylerbeyi Karaman Hüsrev Paşa, yang berangkat untuk menyelamatkan Diyarbekir, yang direbut setelah Çaldıran, dari pengepungan Safawi, merebut Benteng Harput, yang sekitarnya sudah lebih dulu direbut Çerkez Hüseyin Bey, pada akhir pengepungan tiga hari. Jalan yang membentang ke Diyarbekir di sebelah timur Efrat dengan demikian diamankan.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Pertempuran Koçhisar (Kızıltepe) — kekalahan Kara Han", "9ea9e843"], "d": ["Pasukan Utsmaniyah di bawah komando Bıyıklı Mehmed Paşa mengalahkan gubernur Safawi Kara Han dalam pertempuran terbuka sehari penuh di tempat bernama Koruk di padang Dede Garkın dekat Koçhisar; kepala Kara Han yang terpenggal dikirim ke perkemahan sultan. Meskipun pasukan Utsmaniyah kemudian memasuki kota Mardin, mereka tinggal beberapa hari dan pergi; Benteng Mardin, yang dijaga penjaga Safawi, baru dapat diterima penyerahannya setahun kemudian. Kemenangan ini mengamankan perbatasan selatan Yavuz dan memungkinkannya berpaling ke ekspedisi Mesir. Tempat-tempat lain yang bergabung pada tanggal yang sama: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Keberangkatan Yavuz Sultan Selim dari Istanbul untuk ekspedisi Mesir", "ac258b4b"], "d": ["Yavuz Sultan Selim berangkat dari Istanbul dengan tampak mempersiapkan ekspedisi timur baru melawan Safawi dan berbelok ke selatan melalui Akşehir. Kontak Sultan Mamluk Kansu Gavri dengan Syah Ismail dan ancamannya terhadap sayap timur Utsmaniyah akan menyebabkan sasaran berubah dalam waktu singkat. Ekspedisi ini adalah awal operasi besar yang akan berlangsung dua tahun dan mengubah Utsmaniyah menjadi kekaisaran Timur Tengah.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Direbutnya Zabid: masuknya pertama pelaut Utsmaniyah ke Laut Merah", "38740e0c"], "d": ["Menghadapi tekanan Portugis di Samudra Hindia, pelaut-pelaut keturunan Utsmaniyah Hüseyin Bey dan Selman Reis, yang dikirim ke Laut Merah atas permintaan Sultan Mamluk Kansu Gavri, merebut Zabid dengan armada mereka. Operasi yang masih dijalankan dalam dinas Mamluk ini adalah keberadaan faktual pertama angkatan laut Utsmaniyah di jalur Laut Merah-India. Satu tahun kemudian ketika Mesir beralih ke Utsmaniyah, armada yang sama akan langsung diikat ke Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Pengumuman resmi sasaran ekspedisi sebagai Mamluk dan Aleppo", "689e310d"], "d": ["Yavuz Sultan Selim, ketika Kansu Gavri bersepakat dengan Safawi dan menggerakkan pasukannya ke Aleppo, mengumumkan secara terbuka bahwa sasaran ekspedisi adalah sultan Mamluk dan Aleppo. Dengan demikian persaingan terselubung antara dua negara Sunni yang telah berlangsung bertahun-tahun berubah menjadi perang terbuka. Pengumuman ini memulai hitungan mundur empat minggu menuju Marj Dabiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Kegagalan pengepungan Aden: upaya Laut Merah pertama melawan Portugis", "8ffd46f2"], "d": ["Selman Reis dan Hüseyin Bey melakukan pengepungan selama delapan hari untuk merebut Aden, gerbang Laut Merah yang membuka ke Samudra Hindia, tetapi terpaksa mundur menghadapi benteng kota yang kuat. Tidak direbutnya Aden akan mengganggu strategi selatan melawan Portugis selama bertahun-tahun. Upaya ini adalah ujian pertama Utsmaniyah dalam politik samudra.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Beylik Ramazanoğulları diikat kepada Utsmaniyah", "cfaa3754"], "d": ["Dalam penugasan yang dilakukan setelah kemenangan Marj Dabiq, Beylik Ramazanoğulları yang berpusat di Adana diberikan kepada Mahmud Bey dan dibawa ke kekuasaan Utsmaniyah. Beylik yang keluar dari ketundukan Mamluk itu, alih-alih dihapus, dibiarkan pada keluarga itu dengan status 'ocaklık'; Ramazanoğulları melanjutkan pemerintahan Çukurova sebagai sancak beyi Utsmaniyah. Tatanan istimewa ini berlanjut hingga 1608, tahun ketika Pîr Mansûr meninggalkan beylik. Tempat-tempat lain yang bergabung pada tanggal yang sama: Malatya, Tarsus, Musul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa, dan Deir ez-Zor masuk ke kekuasaan Utsmaniyah", "2088eb6a"], "d": ["Empat hari setelah Marj Dabiq, Yavuz Sultan Selim memasuki Aleppo tanpa menemui perlawanan dan khutbah di masjid-masjid kota dibacakan atas namanya. Jatuhnya Aleppo, yang dianggap ibu kota dagang dan administratif Suriah, dengan secepat ini menunjukkan bahwa otoritas Mamluk di wilayah itu telah runtuh. Direbutnya kota seketika membuka jalan ke Damaskus dan dari sana ke Mesir. Tempat-tempat lain yang bergabung pada tanggal yang sama: Antakya, Rakka, Deyrizor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Pertemuan di Gökmeydan Aleppo dengan Khalifah Abbasiyah Mutawakkil III", "22979f42"], "d": ["Khalifah Abbasiyah Kairo Mutawakkil III, yang tertawan bersama pasukan Mamluk di Marj Dabiq, dihadirkan di hadapan sultan di Gökmeydan di Aleppo dan Yavuz Sultan Selim menunjukkan penghormatan besar kepadanya. Kekhalifahan Kairo, jabatan simbolis di bawah bayang-bayang sultan Mamluk sejak 1261, dengan pertemuan ini secara de facto beralih ke perlindungan Utsmaniyah. Khalifah kemudian akan dibawa ke Istanbul bersama sultan.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli dan Hama masuk ke pemerintahan Utsmaniyah", "a1e19a79"], "d": ["Setelah Aleppo dan Hama, Tripoli di pesisir Suriah juga beralih ke pemerintahan Utsmaniyah tanpa perlawanan. Kota yang merupakan salah satu pelabuhan tersibuk Mediterania Timur itu adalah gerbang Damaskus ke laut dan pusat perdagangan sutra dan gula. Dengan direbutnya, jalur pesisir Bilâdüşşam seluruhnya berpindah tangan.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Masuknya Damaskus (Dımaşk) ke kekuasaan Utsmaniyah", "2b844d91"], "d": ["Yavuz Sultan Selim, yang jalannya terbuka dengan menyerahnya Hama dan Homs setelah Aleppo, tiba di depan Damaskus pada 27 September; ia tidak segera memasuki kota, tetapi mendirikan tendanya di luar, di tempat bernama Mastaba, dan memasuki kota dengan upacara besar pada hari kedua belas kedatangannya. Dengan tinggal lama di Damaskus ia menata tatanan administratif Suriah dan membangun makam Muhyiddin Ibnu Arabi. Dengan demikian seluruh Bilâdüşşam keluar dari pemerintahan Mamluk. Tempat-tempat lain yang bergabung pada tanggal yang sama: Beyrut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tomanbay dinyatakan sultan Mamluk di Kairo", "6020d90d"], "d": ["Setelah wafatnya Kansu Gavri di Marj Dabiq, para emir Mamluk mendudukkan Tomanbay, yang akan menjadi sultan terakhir negara, ke takhta. Sultan baru keturunan Cerkez itu mewarisi negara yang telah kehilangan Suriah, kehabisan kas, dan tanpa senjata api. Meskipun demikian ia akan membangun garis pertahanan di depan Kairo dan mengorganisasi perlawanan terakhir terhadap kemajuan Utsmaniyah.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Pertempuran Gaza (Khan Yunus): kekalahan Canbirdi Gazâlî", "9f1eb8cb"], "d": ["Yavuz Sultan Selim mengirim Sadrazam Hadım Sinan Paşa ke Gaza dengan pasukan depan empat ribu orang. Canbirdi Gazâlî, yang diangkat Tomanbay sebagai nâib Damaskus, berusaha menghentikan pasukan depan Utsmaniyah di garis Gaza-Khan Yunus tetapi menderita kekalahan berat dan melarikan diri ke Mesir. Dengan bubarnya pasukan penyangga Mamluk terakhir di Palestina, jalan menuju gurun Sinai terbuka sepenuhnya.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Sebelah timur Yordan: Amman masuk ke pemerintahan Utsmaniyah", "9db62667"], "d": ["Ketika pasukan Utsmaniyah yang bersiap menuju ekspedisi Mesir setelah pertempuran Gaza turun ke selatan, Amman di sebelah timur Yordan juga masuk ke pemerintahan Utsmaniyah. Kota-kota pesisir dan pedalaman Palestina (Yafa, Nablus, Sayda, Akka, Yerusalem) sudah berpindah tangan pada musim gugur 1516 setelah Marj Dabiq. Kota-kota ini diperintah selama empat abad sebagai sancak provinsi Damaskus.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Kedatangan Yavuz Sultan Selim ke Yerusalem", "66d7bfad"], "d": ["Setelah pertempuran Gaza, Yavuz Sultan Selim datang bersama para pembesar negara dan pasukan ke Yerusalem, yang telah beralih ke pemerintahan Utsmaniyah tanpa perlawanan setelah Marj Dabiq. Sultan mengunjungi Kubah Batu dan Masjid al-Aqsa dan menegaskan status suci kota. Yerusalem sejak tanggal ini akan tetap di bawah pemerintahan Utsmaniyah selama empat abad penuh hingga Desember 1917.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Masuknya Yavuz Sultan Selim ke Gaza dan perjalanannya menuju gurun Sinai", "2106bfc7"], "d": ["Setelah kekalahan Canbirdi Gazâlî di Khan Yunus (21 Desember 1516), Gaza berada di tangan pasukan depan. Sultan memasuki Gaza pada 2 Januari 1517 dan bertemu di sana dengan Sinan Paşa yang memimpin pasukan depan; pasukan membuat persiapan terakhir untuk menyeberang ke Mesir. Di gurun Katya (Sinai) tanpa air yang membentang dari Gaza hingga Salihiye akan ditempuh delapan etape dan air akan diangkut dengan unta. Penyeberangan ini adalah fase paling berisiko dan paling sulit secara logistik dari ekspedisi.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Direbutnya Suez — gerbang yang membuka ke Laut Merah", "05f3324e"], "d": ["Dengan memasukinya pasukan Utsmaniyah ke Kairo setelah kemenangan Ridaniye, Suez di ujung utara Laut Merah juga beralih ke pemerintahan Utsmaniyah. Galangan-pelabuhan tempat Mamluk mengirim armada ke Samudra Hindia ini menjadi pangkalan kebijakan selatan yang akan dijalankan melawan Portugis. Suez adalah mulut utara garis tempat terusan akan dibuka tiga abad kemudian.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Masuknya pertama pasukan Utsmaniyah ke Kairo", "0a3f4f4d"], "d": ["Sehari setelah kemenangan Ridaniye, pasukan Utsmaniyah diizinkan memasuki Kairo dan pada 24 Januari unit-unit menetap di kota. Namun masuknya ini tidak berarti kendali penuh atas kota; Tomanbay telah mundur ke Mesir Hulu dan perlawanan Mamluk belum patah. Penaklukan Kairo akan selesai bukan dalam satu hari, melainkan dalam proses berdarah yang menyebar selama berminggu-minggu.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Serbuan Tomanbay ke Kairo dan pertempuran jalanan selama tiga hari", "b83b6ce6"], "d": ["Tomanbay, yang mundur ke Mesir Hulu, dengan sekitar tujuh ribu orang bersamanya tiba-tiba memasuki Kairo pada malam 27-28 Januari dan memulai perlawanan di dalam kota, membuat pasukan Utsmaniyah dalam keadaan sangat sulit. Dalam bentrokan jalanan sengit selama tiga hari, Mamluk untuk sementara menguasai sebagian besar kota. Perlawanan baru dapat dipatahkan dengan masuknya artileri Utsmaniyah dan pasukan bantuan.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Canbirdi Gazâlî masuk ke dinas Utsmaniyah", "a94ea459"], "d": ["Canbirdi Gazâlî, mantan emir Mamluk yang mundur ke Salihiye setelah Ridaniye, mengajukan permohonan kepada sultan dan meminta aman. Yavuz Sultan Selim menerimanya ke dalam dinasnya karena berpendapat ia akan berguna dalam menegakkan ketertiban di Mesir dan Suriah. Pilihan ini adalah contoh besar pertama kebijakan Utsmaniyah memasukkan kader Mamluk ke dalam sistem alih-alih melikuidasi mereka.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Masuknya Yavuz Sultan Selim ke Kairo dengan upacara dan pembacaan khutbah", "6d98080c"], "d": ["Setelah pertempuran jalanan ditumpas, sultan memasuki Kairo pada 15 Februari 1517 dengan upacara yang sangat gemilang dan khutbah dibacakan atas namanya di masjid-masjid. Dibacakannya khutbah atas nama sultan Utsmaniyah di Kairo adalah pernyataan bahwa kekuasaan Mamluk yang berlangsung sejak 1250 berakhir secara hukum. Tanggal ini dianggap saat penyelesaian simbolis penaklukan faktual Mesir.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Tertangkapnya sultan Mamluk terakhir Tomanbay di Terrûce", "7058e6ad"], "d": ["Tomanbay, yang bersembunyi di delta Nil setelah meninggalkan Kairo, dilaporkan oleh suku Badui yang melindunginya dan ditangkap di wilayah Terrûce. Penangkapannya melenyapkan pusat terorganisasi perlawanan Mamluk. Sultan terakhir sesudahnya akan ditahan di tangan Utsmaniyah selama empat belas hari.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Eksekusi Tomanbay di Bâbüzüveyle dan berakhirnya Negara Mamluk", "ad9820be"], "d": ["Empat belas hari setelah penangkapannya Tomanbay digantung di Bâbüzüveyle, gerbang terkenal Kairo; jenazahnya kemudian dimakamkan di madrasah yang dibangun pamannya. Dengan demikian Negara Mamluk yang memerintah Mesir dan Suriah sejak 1250 secara resmi lenyap dari sejarah. Dengan patahnya perlawanan, kota-kota di Mesir Hulu (Said) seperti Asyut dan Asvan juga diikat ke pemerintahan Utsmaniyah.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Serangan armada Portugis ke Jeddah dan pertahanan Selman Reis", "52322cf5"], "d": ["Armada Portugis yang terdiri dari sekitar tiga puluh galai dan galiung menyerang Jeddah; Selman Reis memimpin pertahanan kota, mencegah musuh mendarat dan menenggelamkan beberapa kapal Portugis. Pertahanan ini mencegah pelabuhan Makkah, dan dengan demikian jalur haji, jatuh ke tangan sebuah negara Kristen. Jeddah beberapa bulan kemudian akan dimasukkan secara resmi ke pemerintahan Utsmaniyah dengan baiat Hijaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Penerimaan Iskandariyah dengan armada — selesainya penaklukan Mesir", "386878fe"], "d": ["Tepat empat bulan setelah Ridaniye dan tiga puluh enam hari setelah eksekusi Tomanbay, dengan tibanya armada Utsmaniyah di bawah komando Câfer Bey di pelabuhan, Iskandariyah beralih ke pemerintahan Utsmaniyah; pelabuhan-pelabuhan delta seperti Reşîd dan Dimyat juga diikat dalam proses yang sama. Diterimanya penyerahan pelabuhan besar Mesir yang membuka ke Mediterania ini berbulan-bulan setelah jatuhnya Kairo dan bukan melalui darat melainkan melalui laut dengan jelas menunjukkan bahwa penaklukan diselesaikan bukan dengan satu pertempuran melainkan wilayah demi wilayah. Iskandariyah sesudahnya akan menjadi pelabuhan vital yang menghubungkan Istanbul dan Kairo. Tempat-tempat lain yang bergabung pada tanggal yang sama: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Bergabungnya Hijaz tanpa perang: baiat Ebû Nümeyy, putra Syarif Makkah", "c13b98c7"], "d": ["Yavuz Sultan Selim pada mulanya mempertimbangkan mengirim pasukan untuk merebut Makkah dan sekitarnya, tetapi mengurungkannya ketika Amir Makkah Şerîf Berekât menyatakan ketaatannya. Ebû Nümeyy, putra Berekât yang berusia dua belas tahun, datang ke Kairo dengan hadiah-hadiah ayahnya dan kunci-kunci Makkah dan diterima di hadapan sultan. Dengan demikian Hijaz bergabung ke Utsmaniyah bukan sebagai akibat otomatis Ridaniye, melainkan lima setengah bulan kemudian dan tanpa satu peluru pun ditembakkan, secara damai dan melalui baiat. Tempat-tempat lain yang bergabung pada tanggal yang sama: Tâif.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Diterimanya gelar Hâdimü'l-Haremeyn dan khutbah di Madinah", "63b32b59"], "d": ["Setelah penerimaan kedua delegasi Makkah, Yavuz Sultan Selim secara resmi memikul perlindungan atas Haramain dan mulai menggunakan gelar 'hâdimü'l-Haremeyni'ş-şerîfeyn'. Şerîf Berekât mengenakan jubah kehormatan yang dikirimkan kepadanya dan mengumandangkan khutbah atas nama sultan; dengan perginya delegasi Madinah ke Istanbul, keamiran Berekât dikukuhkan dengan berat. Sultan mengirim dua ratus ribu emas dan perbekalan melimpah kepada penduduk Haramain dan memulai tradisi surre yang akan diulang setiap tahun. Tempat-tempat lain yang bergabung pada tanggal yang sama: Yenbu, Tebük.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis masuk ke dinas Utsmaniyah dan pengalihan kebijakan Laut Merah", "771da99a"], "d": ["Selman Reis, yang mempertahankan Jeddah melawan Portugis, datang ke Kairo dan menghadap Yavuz Sultan Selim; meski ditahan beberapa waktu, ia dipanggil ke Istanbul pada 1519 dan berjanji menyiapkan tiga puluh galai dan beberapa kalyata melawan ancaman Portugis. Pertemuan ini adalah awal pengambilalihan kebijakan Laut Merah dan Samudra Hindia dari warisan Mamluk dan pengikatannya langsung ke Istanbul. Utsmaniyah kini, selain menjadi negara Mediterania, adalah kekuatan yang juga menjalankan politik samudra.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Keberangkatan Yavuz Sultan Selim dari Kairo dan beylerbeylik Hayır Bey", "8cd4fb23"], "d": ["Yavuz Sultan Selim, yang tinggal sekitar delapan bulan di Mesir dan menegakkan tatanan administratif, keuangan, dan militer, meninggalkan Kairo; Hayır Bey, mantan nâib Aleppo yang menarik sayap kiri di Marj Dabiq dan mempercepat kekalahan Mamluk, mulai memerintah dari Kal'atülcebel sebagai beylerbeyi Utsmaniyah pertama Mesir. Dipilihnya seorang gubernur keturunan Mamluk adalah kebijakan peralihan yang disengaja agar pemerintahan baru tidak tampak asing bagi penduduk lokal. Dalam perjalanan pulang sultan membawa ke Istanbul khalifah Abbasiyah terakhir Mutawakkil III dan seniman serta ulama pilihan Mesir.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Berakhirnya Kekhalifahan Abbasiyah Kairo — riwayat 'upacara penyerahan'", "1d357640"], "d": ["Ketika Yavuz Sultan Selim menaklukkan Mesir, ia membawa khalifah terakhir Mutawakkil III Alellah, yang tertawan di Marj Dabiq, ke Istanbul; kekhalifahan Abbasiyah Kairo, yang berlanjut tanpa wewenang di bawah bayang-bayang sultan Mamluk sejak 1261, dengan demikian berakhir. Sebaliknya riwayat terkenal bahwa kekhalifahan diserahkan kepada Yavuz dalam upacara resmi di Hagia Sophia pertama kali muncul dalam karya d'Ohsson pada akhir abad ke-18 dan tidak terdapat dalam satu pun sumber masa Yavuz. TDV İslâm Ansiklopedisi menganggap riwayat itu rekaan karena tidak ada sumber asli yang mendokumentasikan upacara; namun juga mencatat bahwa untuk beralihnya kekhalifahan secara syar'i tidak diperlukan upacara penyerahan semacam itu.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum bergabung ke pemerintahan Utsmaniyah — pengaruh Safawi di Anatolia Timur patah", "78d1be02"], "d": ["Meski pengaruh Utsmaniyah di wilayah itu meningkat setelah kemenangan Çaldıran (1514), perebutan penuh Erzurum tertunda hingga patahnya pengaruh Iran; kota baru bergabung ke pemerintahan Utsmaniyah pada 1518-19 setelah ekspedisi Mesir. Erzurum masuk ke kekuasaan Safawi pada 1502 ketika Syah Ismail mengakhiri Beylik Akkoyunlu; masa enam belas tahun ini dengan demikian tertutup. Beylerbeylik Erzurum akan didirikan pada 1534 selama Ekspedisi Irakeyn. Antara 1518-1519 Aşkale bergabung ke pemerintahan Utsmaniyah bersama wilayah Erzurum (hari tidak terkonfirmasi).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Awal pemberontakan Celali: pemberontakan Şeyh Celâl dari Bozok", "99bd8a99"], "d": ["Seseorang bernama Şeyh Celâl di wilayah Bozok memproklamasikan kemahdiannya dan memberontak di sekitar Tokat; meski pemberontakan ditumpas, namanya menjadi nama bagi semua gerakan bandit dan pemberontakan di Anatolia selama satu abad. Celalisme, bergabung dengan terurainya sistem timar dan tekanan penduduk pada akhir abad ke-16, berubah menjadi masalah keamanan dalam negeri terpanjang kekaisaran. Pemberontakan-pemberontakan menyebabkan migrasi massal di Anatolia yang disebut 'büyük kaçgunluk' (pelarian besar).", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Aljir diikat ke Negara Utsmaniyah", "b8eba4c1"], "d": ["Hayreddin Reis, yang melawan tekanan Spanyol di Afrika Utara, untuk dapat bertahan mengajukan permohonan ke Istanbul dan mempersembahkan Aljir kepada sultan, dan khutbah dibacakan atas nama Yavuz Sultan Selim. Dengan demikian Aljir secara resmi bergabung ke wilayah Utsmaniyah, dan pasukan serta meriam dikirim kepada Hayreddin dengan gelar beylerbeyi. Pengikatan ini meletakkan dasar supremasi laut Utsmaniyah di Mediterania Barat yang akan berlangsung berabad-abad. Tempat-tempat lain yang bergabung pada tanggal yang sama: Konstantin, Şerşel (Cherchell), Medea (Titteri), Setif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Wafatnya Yavuz Sultan Selim di Çorlu", "9fe83744"], "d": ["Selim I, yang dalam delapan tahun memperluas wilayah negara lebih dari dua kali lipat, berangkat dari Istanbul untuk ekspedisi baru pada 18 Juli 1520; karena tumor besar yang muncul di punggungnya, ia tidak dapat maju melewati Çorlu. Meski ada intervensi para tabib, penyakitnya memburuk dan setelah pengobatan tanpa harapan selama dua bulan ia wafat di sana pada 8-9 Syawal 926 (21-22 September 1520). Dengan Çaldıran, Marj Dabiq, dan Ridaniye ia telah menghentikan Iran dan melenyapkan Negara Mamluk, serta membawa kekhalifahan dan perlindungan Haramain kepada Utsmaniyah. Ia meninggalkan satu putra laki-laki: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Masuknya Pulau Nikaria (Ikaria) ke pemerintahan Utsmaniyah", "6afa972b"], "d": ["Nikaria, antara Samos dan Sakız, berada di bawah pemerintahan Ksatria Saint Jean Rhodes dari 1481 hingga 1521; masa Utsmaniyah pertama di pulau dimulai pada 1522 dan berlangsung hingga 1822. Pada masa ini kaymakam bertanggung jawab atas pemungutan dan pembayaran pajak; seperti di pulau-pulau Aegea lainnya, dewan sesepuh lokal (demogerontia) juga tetap ada dan sesekali berbenturan dengan pemerintahan Utsmaniyah.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksasi negeri Dulkadir — eyalet Dulkadır yang berpusat di Maraş", "595c3c30"], "d": ["Negeri Dulkadir, yang berlanjut sebagai beylik vasal Utsmaniyah setelah kekalahan Turnadağ 1515, setelah Şehsuvaroğlu Ali Bey dibantai bersama anak-anaknya di Artukova, digabungkan langsung ke wilayah Utsmaniyah dan dijadikan eyalet dengan Maraş sebagai pusat. Wilayah Bozok beylik diikat ke pemerintahan Utsmaniyah sebagai sancak tersendiri. Dengan demikian masa Dulkadır yang sekitar dua abad di Maraş, Elbistan, Göksun, Gürün, Zamantı, dan Darende tertutup; beylik penyangga di perbatasan Mamluk lenyap sepenuhnya.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Penaklukan Knin", "a46d3117"], "d": ["Dengan serbuan Bey Sancak Bosnia Gazi Hüsrev Bey pada tahun 927-928 (1521-1522), serangkaian benteng Venesia, terutama Knin, Skradin, dan Ostrovica, beralih ke pemerintahan Utsmaniyah; perbatasan didorong melampaui barisan pegunungan kedua. Rantai penaklukan ini meletakkan dasar sancak Dalmatia yang akan dilengkapi lima belas tahun kemudian dengan direbutnya Klis.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Penarikan para ksatria: penyerahan Bodrum, İstanköy, dan Dodekanesos", "ea01666e"], "d": ["Sesuai syarat penyerahan Rhodes, Ksatria Saint Jean tidak hanya mengosongkan pusat pulau tetapi juga semua posisi yang mereka pegang selama dua ratus tahun. Benteng Bodrum (Saint Pierre) di pesisir Anatolia serta pulau Kos, Kalymnos, dan Leros dengan demikian beralih ke pemerintahan Utsmaniyah tanpa pertempuran. Dengan penyerahan yang selesai dua minggu setelah jatuhnya Rhodes ini, keberadaan Latin di sudut tenggara Aegea berakhir sepenuhnya.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Pemberontakan Hain Ahmed Paşa di Mesir", "b18bb805"], "d": ["Ahmed Paşa, yang dikirim ke jabatan gubernur Mesir ketika menantikan jabatan sadrazam, memproklamasikan dirinya di Kairo sebagai 'el-Melikü'l-Mansûr Sultan Ahmed' dan mengumumkan kemerdekaannya. Pemberontakan itu cepat ditumpas dan sang paşa dibunuh, tetapi peristiwa itu menunjukkan rapuhnya kendali sentral di provinsi terkaya kekaisaran. Karena itu İbrahim Paşa pergi ke Mesir dan menyusun Kanunname Mesir yang terkenal yang menata ulang pemerintahan provinsi.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksasi Bosnia Utara: Yayça dan Banja Luka", "8ec86cfa"], "d": ["Ketika garis pertahanan Hongaria runtuh setelah Mohács, sancak beyi Bosnia Gazi Hüsrev Bey berbaris ke lembah Vrbas dan merebut benteng-benteng Bosnia terakhir yang tersisa di tangan kerajaan Hongaria. Dengan jatuhnya Yayça dan Banja Luka, eyalet Bosnia mencapai Sungai Sava di utara dan front Kroasia lahir. Banja Luka dalam waktu singkat menjadi pusat kedua eyalet.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Direbutnya Buda dan penyerahannya kepada Zápolya", "fba4f89b"], "d": ["Dalam perjalanan ekspedisi Wina, pasukan Utsmaniyah mengepung dan merebut kembali Buda yang telah jatuh ke tangan Ferdinand, dan menyerahkan kota kepada raja Hongaria János Szapolyai di bawah perlindungan Utsmaniyah. Dengan demikian model kerajaan vasal sebagai penyangga dalam persaingan Habsburg–Utsmaniyah dibangun di atas Hongaria. Tatanan ini akan berlangsung hingga 1541 dan setelah wafatnya Zápolya Buda akan dijadikan provinsi Utsmaniyah langsung.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Kanuni berangkat dalam Ekspedisi Jerman — menantang Charles V", "7c3d7055"], "d": ["Setelah pengepungan Wina yang tanpa hasil dan pengepungan Buda kembali oleh Ferdinand, sultan kali ini berangkat dari Istanbul untuk menarik Kaisar Charles V langsung ke pertempuran terbuka. Pasukan akan tertahan pada Agustus oleh perlawanan benteng kecil Güns; karena kaisar tidak keluar berperang, ekspedisi akan terbatas pada serbuan. Ekspedisi ini menyiapkan landasan perdamaian pertama dengan Habsburg pada tahun berikutnya.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Ekspedisi Jerman dan pengepungan Güns (Kőszeg)", "8aec937a"], "d": ["Kanuni berbaris melawan Austria dengan pasukannya untuk memaksa Charles V ke pertempuran terbuka; benteng kecil Güns bertahan dua puluh lima hari dan menunda kemajuan pasukan. Ketika kaisar tidak keluar berperang, para akıncı menyerang sekitar Wina dan pasukan kembali karena musim yang bergeser. Ekspedisi tidak membawa perolehan wilayah, tetapi mendudukkan Habsburg ke meja perundingan dan menyiapkan landasan perdamaian tahun berikutnya.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Perjanjian Istanbul — perdamaian pertama dengan Habsburg", "b085767a"], "d": ["Sultan, yang menerima utusan Ferdinand Cornelius, menyetujui gencatan senjata, dan teks perdamaian resmi pertama antara Utsmaniyah dan Austria muncul. Dengan perjanjian itu Ferdinand menerima membayar pajak tahunan sebagai imbalan wilayah Hongaria yang dikuasainya, dan archduke Austria dalam protokol dianggap setara dengan sadrazam. Status tidak setara ini adalah pernyataan terbuka klaim keunggulan diplomasi Utsmaniyah pada abad ke-16.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Direbutnya Kars dan terbukanya perbatasan timur laut", "742e3101"], "d": ["Ketika kolom depan Ekspedisi Irakeyn berbelok dari Erzurum ke timur, Benteng Kars, yang berada di tangan atabeg Georgia dan tak terawat sejak Timur, diterima penyerahannya tanpa perlawanan. Kota ini, karena menguasai lintasan antara lengkungan Aras dan Çıldır, dianggap kunci gerbang utara yang membuka ke Iran. Perolehan ini menjadi mata rantai pertama beylerbeylik Kars dan garis Kaukasus yang akan didirikan tiga puluh tahun kemudian.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Masuknya pertama ke Tabriz — pembukaan Ekspedisi Irakeyn", "cf7ed4e3"], "d": ["İbrahim Paşa, yang bergerak lebih dulu dengan gelar serdâr-ı ekrem, memasuki Tabriz, ibu kota Safawi, tanpa perlawanan ketika Syah Tahmasb menghindari pertempuran terbuka dan mundur ke pedalaman. Kanuni juga tiba di kota pada bulan September; namun karena musim dingin yang mendesak dan jalur pasokan yang terlalu panjang, pasukan berbelok ke arah Baghdad dan Tabriz tidak dapat dipertahankan lama. Kota yang direbut untuk kedua kalinya setelah Çaldıran ini menjadi tempat Utsmaniyah belajar bahwa merebut di timur mudah, mempertahankan sulit.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Penaklukan Tunisia oleh Barbaros", "d8754216"], "d": ["Kaptan-ı deryâ Barbaros Hayreddin Paşa, setelah menyerang pesisir Italia dengan armadanya, berpaling ke Tunisia dan memasuki kota dengan mengusir penguasa Hafsiyah Mevlây Hasan. Direbutnya Tunisia, dengan kedudukannya yang mengendalikan Selat Sisilia, seketika membalikkan keseimbangan kekuatan di Mediterania Barat ke pihak Utsmaniyah. Namun dominasi ini tidak akan bertahan lama; Charles V akan membalas dengan armada besar pada tahun berikutnya.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Hilangnya Tunisia ke Charles V", "a691f0f8"], "d": ["Charles V, dengan ekspedisi besar yang didukung armada Genoa dan Kepausan, merebut Tunisia setelah menjatuhkan Halq al-Wadi dan mengembalikan Mevlây Hasan ke takhta di bawah perlindungan Spanyol. Dengan ditempatkannya garnisun Spanyol di kota, kemajuan Utsmaniyah di Mediterania Tengah dihentikan untuk sementara. Penaklukan pasti Tunisia baru mungkin empat puluh tahun kemudian, pada 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Operasi Gazi Hüsrev Bey di sepanjang Sava: Bosna Brod dan Jasenovac", "3740ec83"], "d": ["Setelah direbutnya Yayça dan Banja Luka pada 1528, benteng-benteng di sepanjang Sungai Sava untuk beberapa waktu tetap di perbatasan Kroasia-Slavonia yang terikat pada mahkota Habsburg. Gazi Hüsrev Bey, yang menjadi sancak beyi Bosnia untuk ketiga kalinya pada 1536, pada tahun yang sama merebut Požega dan sekitarnya, serta menggabungkan benteng Brod dan Jasenovac di tepi Sava ke pemerintahan Utsmaniyah. Dengan demikian perbatasan utara Bosnia mencapai Sava; wilayah itu dilengkapi dua tahun kemudian dengan direbutnya Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Eksekusi Makbul İbrahim Paşa", "348aa7b8"], "d": ["İbrahim Paşa, yang menjabat sadrazam tiga belas tahun, sahabat terdekat Kanuni dan orang kedua de facto negara, dicekik dan dieksekusi tanpa alasan apa pun di istana tempat ia diundang berbuka puasa. Sikapnya dalam ekspedisi Irakeyn, penggunaan gelar 'serasker sultan', dan keseimbangan dalam istana dianggap berpengaruh dalam kematiannya. Eksekusi ini adalah titik balik yang menunjukkan bahwa keamanan mutlak para wazir agung tidak ada dalam pemerintahan pusat Utsmaniyah.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Penaklukan Benteng Klis dan pendirian sancak Dalmatia", "6ffd4ebf"], "d": ["Murad Bey, kethüdâ Gazi Hüsrev Bey dan mualaf keturunan Kroasia, merebut Benteng Klis yang strategis di utara Split dari Venesia. Segera setelah penaklukan, Klis dijadikan pusat sancak dan kaza baru yang mencakup sekitarnya; batas sancak ini sebagian besar menggambar kerangka Kroasia Utsmaniyah. Penaklukan ini, yang datang lima belas tahun setelah Knin, melengkapi kerangka administratif pedalaman Dalmatia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Pengepungan Korfu dan perang dengan Venesia", "11af95bd"], "d": ["Setelah ekspedisi Apulia, pasukan Utsmaniyah mendaratkan prajurit di Korfu dan mengepung benteng Venesia yang kuat di pulau itu. Karena benteng yang terjal, kerugian berat, dan kondisi musim, blokade dicabut dan pasukan mundur pada 6 September. Meski pengepungan tanpa hasil, perang yang dibuka dengan Venesia berujung pada bergabungnya banyak pulau di Aegea dan Adriatik ke Utsmaniyah serta kemenangan Preveza pada tahun berikutnya.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Ekspedisi Aegea Barbaros: direbutnya pulau-pulau yang diperintah langsung Venesia", "1b32ed96"], "d": ["Armada yang kembali dari pengepungan Korfu, dengan memanfaatkan dinyatakannya perang kepada Venesia, menerima penyerahan satu per satu pulau-pulau di Aegea yang terikat bukan pada kadipaten melainkan langsung pada Venesia. Aegina direbut setelah perlawanan sengit, Astypalaia milik keluarga Querini serta Karpathos dan Kasos menyerah, dan Patmos di bawah pemerintahan biara juga menerima perlindungan Utsmaniyah. Kadipaten Naxos diikat dengan upeti dan dibiarkan di tempatnya; aneksasinya akan menunggu hingga 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Ekspedisi Aegea Utara Barbaros: direbutnya Skyros dan Sporades Utara", "20ab688e"], "d": ["Dalam perjalanan ke Preveza, armada menerima penyerahan satu per satu pulau-pulau Aegea Utara yang berlindung kepada Venesia setelah penaklukan Istanbul. Skyros di utara Eğriboz serta Skiathos, Skopelos, dan Alonissos yang menguasai mulut Teluk Selanik dengan demikian masuk ke pemerintahan Utsmaniyah. Pulau-pulau ini menutup kekosongan Aegea Utara terakhir yang tetap di tangan Venesia selama enam puluh delapan tahun lagi meski Eğriboz direbut pada 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Direbutnya Aden dan aneksasi pesisir Yaman", "e7d46d8f"], "d": ["Armada yang berangkat dari Suez untuk ekspedisi India lebih dulu menuju pesisir Yaman karena samudra tidak dapat dimasuki tanpa mengamankan Laut Merah. Hadım Süleyman Paşa memasuki pelabuhan Aden pada 3 Agustus 1538; penguasa Tahiriyah Âmir b. Dâvud, yang condong kepada Portugis, dibawa ke gerbang kapten dan dieksekusi, dan 500 penjaga ditinggalkan di kota. Dalam ekspedisi yang sama Mocha dan pulau-pulau Kamaran dan Farasan yang menguasai selat juga diterima penyerahannya dan dasar beylerbeylik Yaman diletakkan. Dengan demikian Negara Utsmaniyah untuk pertama kalinya memiliki seluruh pesisir utara Bab al-Mandab; Sana'a dan wilayah pedalaman harus menunggu sembilan tahun lagi.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Ekspedisi Moldavia dan aneksasi wilayah Bucak (Bender)", "90a88a56"], "d": ["Dalam ekspedisi melawan voivode Moldavia Petru Rareş, yang tidak memenuhi kewajibannya kepada Utsmaniyah, Suceava direbut dan kota Iași dijarah oleh Khan Krimea Sâhib Giray. Sultan mengangkat Ștefan Lăcustă ke voivodat dan menganeksasi wilayah Bucak (Besarabia Selatan) bersama Bender langsung ke wilayah Utsmaniyah. Aneksasi ini menjadi salah satu mata rantai yang menjadikan pesisir barat laut Laut Hitam laut pedalaman Utsmaniyah. Moldavia sudah merupakan voivodat vasal Utsmaniyah; ekspedisi ini tidak mengambil tanah dari negara asing, hanya mengambil pemerintahan dalam negeri Bender dan Bucak dari voivode dan mengikatnya langsung ke sultan; sisa voivodat mempertahankan status vasalnya. Struktur yang sama akan diulang pada 1484 di Kili dan Akkirman, dan pada 1713 di Hotin: benteng-benteng perbatasan langsung, wilayah dalam vasal.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Penerimaan Anabolu (Nauplion) dengan perjanjian", "104d0937"], "d": ["Perang Venesia tiga tahun setelah Preveza berakhir dengan republik menerima menyerahkan dua benteng terakhirnya di Mora. Anabolu (Nauplion) dan Benefşe (Monemvasia), yang tidak dapat direbut dengan pengepungan, diserahkan kepada Utsmaniyah di meja perundingan di samping ganti rugi perang tiga ratus ribu dukat. Semenanjung Mora dengan demikian menjadi satu tanpa meninggalkan satu pun jejak Venesia.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Masuknya Szeged ke pemerintahan Utsmaniyah dan pembentukan liva Szeged", "019aa000"], "d": ["Setelah pemerintahan Utsmaniyah di Buda didirikan sepenuhnya pada 1541, tokoh-tokoh Szeged menerima kekuasaan Ferdinand I dan bersiap membela diri dengan senjata. Beylerbeyi Buda Küçük Bâlî Paşa pada awal 1543 memanggil para pengurus kota kepadanya dan mengeksekusi mereka dengan alasan pengkhianatan, lalu mengirim pasukan untuk merebut kota. Pada saat itu liva Szeged dibentuk dan sancak beyi pertama diangkat putra Bâlî Paşa, Derviş Bey; liva pada awalnya membentang antara Danube dan Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Penaklukan Valpó, Siklós, dan Pécs", "2ca030a3"], "d": ["Sasaran pertama ekspedisi Hongaria yang dilancarkan dua tahun setelah aneksasi Buda adalah mengamankan sayap selatan provinsi baru antara Drava dan Danube. Setelah benteng Valpó dan Siklós direbut, Pécs, pusat Baranya, menyerah. Kota itu akan menjadi pusat paling ramai dan paling banyak dibangun di Hongaria Utsmaniyah, dan sejarawan İbrahim Peçuylu mengambil namanya dari sini.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Penaklukan Esztergom dan Székesfehérvár", "efca9e05"], "d": ["Dalam ekspedisi Hongaria yang diikuti Kanuni sendiri, setelah pengepungan dua setengah minggu, Esztergom, pusat keagamaan dan kota keuskupan agung Kerajaan Hongaria, masuk ke pemerintahan Utsmaniyah. Kemudian Székesfehérvár, kota penobatan raja-raja Hongaria, juga direbut dan sabuk pertahanan provinsi Buda dilengkapi. Esztergom akan tetap di tangan Utsmaniyah sebagai benteng kunci garis Danube hingga 1595.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Sabuk pertahanan utara dan barat Buda: Vác, Hatvan, dan Simontornya", "733ee5ce"], "d": ["Setelah Esztergom dan Székesfehérvár direbut, beylerbeyi Buda bergerak tanpa ekspedisi sultan untuk melengkapi lingkar benteng yang mengelilingi ibu kota. Vác di tikungan Danube, Hatvan, gerbang Alföld, dan Simontornya di garis Sió diterima penyerahannya satu per satu. Perolehan tahun sunyi ini mengubah Buda dari kota uç menjadi pusat provinsi yang akan bertahan seratus empat puluh tahun.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksasi Basra dan keluar ke Teluk Basra", "02f87c11"], "d": ["Pada penaklukan Baghdad (1534), penguasa Basra Râşid b. Megāmis menyatakan ketaatan kepada Kanuni dan pada 1538 mengirim kunci-kunci kota. Ketika penggantinya Şeyh Yahyâ menghadapi Utsmaniyah, Beylerbeyi Baghdad Ayas Paşa berbaris dari darat dan sancak beyi Mosul dengan 120 kapal melalui Efrat; Ayas Paşa memasuki Basra pada 26 Desember 1545 dan kota menjadi pusat beylerbeylik. Pelabuhan di mulut Shatt al-Arab ini adalah gerbang yang membuka Utsmaniyah ke teluk yang dikendalikan Portugis dari Hormuz; dengan Perjanjian Amasya 1555 Iran juga mengakui keadaan ini.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Penaklukan Sana'a dan pedalaman Yaman", "d31ded85"], "d": ["Setelah Taiz, Sana'a juga direbut dan seluruh negeri diikat ke beylerbeylik. Namun karena geografi terjal dan perbedaan mazhab, kekuasaan ini tidak pernah nyaman; Yaman menjadi front yang terus-menerus menelan pasukan bagi Utsmaniyah.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Penaklukan Taiz", "d4509df9"], "d": ["Di Yaman yang selama sembilan tahun dicukupkan dengan jalur pesisir, atas semakin kuatnya imam-imam Zaidi di pedalaman pegunungan, pasukan Özdemir Paşa naik ke dataran tinggi dan merebut Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Perjanjian Istanbul — perdamaian lima tahun dengan Habsburg", "41f81773"], "d": ["Perdamaian lima tahun ditandatangani antara Utsmaniyah dan Habsburg; Ferdinand menerima membayar 30.000 dukat per tahun untuk wilayah Hongaria yang dikuasainya. Perjanjian itu mengesahkan secara hukum keadaan faktual Hongaria yang terbagi tiga. Dengan diamankannya front barat, Kanuni memperoleh kesempatan menyelenggarakan ekspedisi baru atas Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Ekspedisi Iran Kedua dan direbutnya kembali Tabriz", "e82365df"], "d": ["Dalam ekspedisi yang dilancarkan atas dorongan Elkas Mirza, saudara Syah Tahmasb yang memberontak dan berlindung di Istanbul, pasukan memasuki Tabriz untuk kedua kalinya. Karena Safawi kembali tidak masuk pertempuran terbuka dan mundur sambil membakar tanah, hanya dapat tinggal beberapa minggu di kota. Ekspedisi mengukuhkan bahwa Tabriz tidak dapat dipertahankan dan mengarahkan strategi Utsmaniyah ke pembentukan garis perbatasan permanen, yakni memperkuat Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Penaklukan Van dan penetapan perbatasan timur", "fc8f930b"], "d": ["Benteng Van, yang dikepung dalam perjalanan pulang dari Tabriz, dengan kedudukannya yang menjulang di atas karang di tepi timur danau, adalah kunci wilayah yang tak terbantahkan dan menyerah setelah pengepungan singkat. Kota segera dijadikan pusat beylerbeylik; sancak Erciş, Adilcevaz, dan Hakkâri diikat ke sana. Berbeda dengan Tabriz, Van dipertahankan dan tetap menjadi posisi permanen paling maju Utsmaniyah di timur selama empat ratus tahun.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksasi Lahsa dan Qatif — pesisir Arabia Teluk", "f6701e60"], "d": ["Setelah direbutnya Basra, Qatif, yang telah menjadi pos depan Portugis di pesisir barat teluk, direbut dan beylerbeylik baru didirikan bersama oasis-oasis Lahsa di pedalaman. Titik keberangkatan operasi ke Bahrain dan Hormuz adalah di sini. Negara Utsmaniyah dengan demikian memiliki suara sekaligus di pesisir Laut Merah dan Teluk Basra Semenanjung Arabia.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Lepasnya Şehrizor — bey Erdelan Sührâb condong ke Safawi", "5600efc9"], "d": ["Wilayah Şehrizor, yang mengakui pemerintahan Utsmaniyah selama Ekspedisi Irakeyn (1535), berada di bawah pemerintahan emir Erdelan Bige Bey yang bermukim di Benteng Zalm. Saudaranya Sührâb, yang merebut Benteng Zalm dan menguasai beylik setelah wafatnya Bige Bey pada 1550, berpaling kepada Safawi dan melepaskan ketaatan kepada Utsmaniyah; wilayah Şehrizor dengan demikian keluar dari pengaruh Utsmaniyah. Wilayah itu baru direbut kembali dengan pengepungan dan direbutnya Benteng Zalm pada 1554 selama ekspedisi Nakhchivan.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Direbutnya Ardahan dan cekungan Çıldır", "14c9eb76"], "d": ["Beylerbeyi Erzurum, dalam perang yang berlanjut dengan Safawi, berbelok ke wilayah para atabeg Georgia di lengkungan Kura dan mengikat Ardahan dan sekitar Çıldır ke pemerintahan Utsmaniyah. Garis Kars-Ardahan dengan demikian menyatu dan dataran tinggi yang membuka ke Georgia di timur laut dibawa ke bawah kendali. Tatanan administratif pasti wilayah itu akan dilengkapi dengan eyalet Çıldır yang akan didirikan dua puluh tujuh tahun kemudian.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Paşa menyeberangi Danube — dimulainya perang Transilvania", "38fde931"], "d": ["Atas kekacauan yang ditimbulkan wali raja Transilvania János Zsigmond yang masih kecil, biarawan Martinuzzi, dan penyerahan benteng-benteng Banat oleh Transilvania kepada Ferdinand, ekspedisi baru dianggap perlu; komando diberikan kepada beylerbeyi Rumelia Sokollu Mehmed Paşa. Pasukan menyeberangi Danube meski ada upaya Martinuzzi mengulur waktu, merebut Becse, Becskerek, Csanád, dan Lippa; namun pengepungan Timișoara dicabut pada 16 November karena dingin. Dengan demikian perang Utsmaniyah-Habsburg baru dibuka di Hongaria.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Kota Lipova (Lippa) jatuh ke tangan pasukan Austria Castaldo — benteng menyerah pada 5 Desember", "a0e1ff0d"], "d": ["Lipova, yang direbut Sokollu Mehmed Paşa pada Oktober 1551, dikepung pasukan Jenderal Castaldo pada 4 November; dua hari kemudian kota jatuh ke tangan Austria. Ulama Paşa mempertahankan benteng sembilan hari lagi dengan penjaga 5.000 orang dan keluar dengan kesepakatan pada 5 Desember 1551. Lipova tetap di tangan Habsburg hingga jatuhnya Timișoara pada 1552.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Pasukan yang dikirim dari Timișoara menguasai palanka Banat Selatan — Versec, Haram, Keve", "edca0921"], "d": ["Setelah Timișoara menyerah kepada pasukan Utsmaniyah, unit-unit yang memisahkan diri dari pasukan pengepung beralih ke palanka-palanka kecil Banat; menurut penuturan Bánlaky, palanka Versec, Facset, Mehádia, Csákóvár, Haramvár, dan Keve dikuasai oleh pasukan ini. Dengan demikian Haram di tepi Danube juga jatuh ke tangan Utsmaniyah.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Penaklukan Szolnok dan kegagalan pengepungan Eger", "a7156e8f"], "d": ["Dua pasukan Utsmaniyah yang bersatu setelah direbutnya Timișoara merebut Szolnok di Tisza hampir tanpa pertempuran ketika para penjaga bayaran meninggalkan benteng. Kemudian Benteng Eger yang dikepung tidak dapat direbut menghadapi perlawanan tiga puluh delapan hari garnisun dua ribu orang di bawah komando István Dobó dan pasukan mundur ketika musim dingin tiba. Satu benteng jatuh dengan mudah sementara yang lain bertahan dalam ekspedisi yang sama adalah tanda terbuka pertama bahwa perbatasan di Hongaria tidak lagi maju dengan sendirinya demi keuntungan Utsmaniyah.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Aliansi Utsmaniyah-Prancis — armada Prancis di bawah perintah Utsmaniyah", "a8e01b22"], "d": ["Dengan perjanjian tertanggal 1 Februari 1553, armada Prancis ditempatkan di bawah perintah armada Utsmaniyah; operasi bersama di Mediterania Barat melawan Spanyol direncanakan. Setelah perjanjian itu, Turgut Reis berangkat pada 15 Juni 1553 dengan empat puluh lima galai untuk mendukung Prancis. Ini adalah perjanjian aliansi resmi pertama yang membawa landasan dagang kapitulasi 1536 ke kerja sama militer.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Eksekusi Şehzade Mustafa di Konya Ereğli", "dec36858"], "d": ["Şehzade Mustafa, yang memasuki tenda ayahnya untuk bergabung dengan pasukan yang dihimpun untuk ekspedisi Nakhchivan, bertemu dengan para algojo saat akan menghadap dan dicekik hingga tewas. Pembunuhan calon penerus takhta yang sangat dicintai di dalam pasukan itu menimbulkan kemarahan mendalam di kalangan janisari dan Rüstem Paşa dicopot dari jabatan sadrazam. Peristiwa ini masuk ke sastra dan ingatan rakyat sebagai salah satu patahan paling diperdebatkan dalam politik şehzade Utsmaniyah.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Dipindahkannya perbatasan Ibrim dan Nubia ke selatan", "c57d5d77"], "d": ["Perbatasan selatan beylerbeylik Mesir dipindahkan ke seberang katarak kedua ketika Benteng Ibrim, yang menjulang di atas tanjung berbatu di Nil, diperkuat oleh Özdemir Bey dan Nubia Hilir sepenuhnya digabungkan ke Mesir Utsmaniyah. (Organisasi administratif Utsmaniyah di Ibrim telah dibentuk setelah penaklukan Mesir; di peta Ibrim ditampilkan Utsmaniyah sejak 1517. Tahun ini perkiraan, sumber tidak memberi tahun.) Benteng itu adalah benteng penghalang serbuan dari Nubia sekaligus titik kendali jalur emas dan budak menuju Sennar. Pasukan penjaga asal Bosnia yang ditempatkan di sini begitu permanen sehingga keturunan mereka masih berada di benteng tiga ratus tahun kemudian. Sumber-sumber memberi dua riwayat berbeda tentang waktu masuknya Ibrim ke pemerintahan Utsmaniyah: entri Sudan di TDV mengaitkan bergabungnya Nubia Hilir ke Mesir Utsmaniyah dengan operasi Özdemir Paşa pada pertengahan abad ke-16, sedangkan entri Nubia menulis bahwa wilayah hingga lembah Halfa dan organisasi administratif di Ibrim dibentuk segera setelah penaklukan 1517. Sancak Ibrim diikat ke eyalet Habesh pada 26 Juli 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Direbutnya Bejaia (Bougie) dari Spanyol", "49691cda"], "d": ["Bejaia, yang berada di tangan Spanyol selama empat puluh tiga tahun dan membagi dua pesisir antara Aljir dan Konstantin, menyerah setelah dikepung dari darat dan laut. Dengan jatuhnya benteng, pesisir ocak Aljir menjadi tak terputus hingga Oran. Kehilangan ini menimbulkan kemarahan sedemikian besar di Spanyol sehingga komandan yang menyerahkan benteng, Alonso de Peralta, dieksekusi di negerinya.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Bergabungnya Zeila ke Eyalet Habesh", "7bbf369a"], "d": ["Pelabuhan Zeila di ujung selatan eyalet Habesh, di pesisir Afrika Teluk Aden, diikat ke pemerintahan Utsmaniyah. Kota yang merupakan gerbang Kesultanan Adal ke laut ini adalah titik pasokan terakhir bagi kapal-kapal yang keluar dari Bab al-Mandab. Dengan bergabungnya Zeila, perbatasan Negara Utsmaniyah di Afrika mencapai titik paling selatannya.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Pertempuran Şehzade di Konya", "1c8de387"], "d": ["Şehzade Bayezid, yang masuk ke perebutan takhta, datang ke depan Konya dengan sekitar 30.000 pasukan dan dalam pertempuran dua hari dikalahkan oleh saudaranya Şehzade Selim. Bayezid yang kalah berlindung kepada Syah Tahmasb di Iran melalui Amasya. Pertempuran itu mengubah krisis suksesi takhta pada tahun-tahun terakhir Kanuni menjadi masalah kebijakan luar negeri.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Kemenangan laut Djerba", "c7b905c1"], "d": ["Armada Utsmaniyah di bawah komando Piyâle Paşa menceraiberaikan armada sekutu Spanyol-Genoa-Malta, yang dihimpun untuk merebut kembali Tripoli, di depan Djerba dengan manuver membelah diri. Para sekutu kehilangan sebagian besar armadanya dan benteng di pulau itu segera jatuh. Djerba dianggap kemenangan laut besar kedua, setelah Preveza, yang memantapkan keunggulan Utsmaniyah di Mediterania.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Eksekusi Şehzade Bayezid di Qazvin", "a759de14"], "d": ["Şehzade Bayezid, yang berlindung di Iran, setelah tawar-menawar panjang diserahkan oleh Syah Tahmasb kepada delegasi Utsmaniyah dan dicekik hingga tewas bersama keempat putranya. Sebagai imbalan penyerahan, Safawi memperoleh konsesi material penting dan jaminan perbatasan. Dengan eksekusi ini rintangan terakhir naiknya Selim II ke takhta hilang dan tatanan damai Perjanjian Amasya terpelihara.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Direbutnya Sakız dari Genoa", "a4559b96"], "d": ["Sakız, yang selama dua ratus tahun diperintah sebagai koloni dagang milik keluarga Giustiniani dari Genoa dan membayar upeti kepada Utsmaniyah, diterima penyerahannya oleh Piyâle Paşa tanpa satu peluru pun ditembakkan dengan alasan ia menunggak upeti dan memberi pelabuhan kepada kapal musuh. Bersama Sakız dan İpsara, keberadaan Genoa terakhir di pesisir timur Aegea juga dilikuidasi. Produksi mastik dan imtiyaz orang Sakız dipertahankan dan pulau diikat ke eyalet Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Aneksasi Kadipaten Naxos — seluruh Kepulauan Cyclades", "68f0ec0b"], "d": ["Kadipaten Naxos Latin, yang berlangsung sejak 1207 dan membayar upeti kepada Utsmaniyah sejak 1537, dihapus dengan alasan keluhan yang datang atas penindasan rakyat oleh adipati terakhir Giacomo Crispo. Naxos, Paros, Değirmenlik, Andros, Syros, Mykonos, Ios, Amorgos, dan semua pulau Cyclades di sekitarnya dibawa ke pemerintahan Utsmaniyah langsung dengan satu keputusan. Kanuni menyerahkan pemerintahan pulau-pulau kepada Yasef Nasi untuk beberapa waktu; dominasi Latin selama tiga setengah abad dengan demikian berakhir di tengah Aegea.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Pemberontakan Yaman dan ekspedisi Yaman Koca Sinan Paşa", "c8218d8e"], "d": ["Imam Zaidi Mutahhar memberontak dengan alasan pajak dipungut dengan paksa dan mencabut pemerintahan Utsmaniyah dari sebagian besar Yaman. Koca Sinan Paşa, yang dikirim dari Istanbul, dengan operasi yang dijalankan antara 1568-1570 merebut Kawkaban setelah pengepungan panjang dan membangun kembali kekuasaan Utsmaniyah di wilayah itu. Ekspedisi itu sangat penting untuk menjaga kendali gerbang selatan Laut Merah dan jalur dagang Samudra Hindia.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Aliansi pertahanan dengan Kesultanan Aceh dan bantuan Samudra Hindia", "8e835f24"], "d": ["Para utusan Aceh yang meminta bantuan Kanuni menghadapi serangan Portugis menyampaikan kesetiaan mereka kepada Selim II setelah wafatnya sultan di Szigetvár, dan perjanjian pertahanan ditandatangani dengannya. Sultan memerintahkan agar meriam, senapan, amunisi, dan ahli dikirim dari Iskandariyah; tujuh belas kapal perang disiapkan untuk dikirim ke perairan India. Membesarnya pemberontakan Yaman mencegah armada berangkat, tetapi para ahli artileri dan pengrajin Utsmaniyah yang mencapai Aceh meninggalkan jejak permanen di wilayah itu.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Pendaratan di Siprus: direbutnya Limasol", "9074ccc9"], "d": ["Pasukan Utsmaniyah yang mendarat di pulau merebut Limasol tanpa menemui banyak perlawanan dan keesokan harinya bergerak ke Larnaka. Berkat ketidakpuasan penduduk lokal terhadap pemerintahan Venesia dan bantuan mereka kepada pasukan Utsmaniyah, tidak ada perlawanan serius juga di Larnaka; dermaga Tuzla dijadikan pangkalan pendaratan pasukan dan perlengkapan. Venesia memusatkan pertahanannya di Lefkoşa dan Magosa; gubernur Baf baru menyatakan ketaatan kepada serdar setelah Lefkoşa jatuh.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Penaklukan Lefkoşa", "413d866b"], "d": ["Setelah pengepungan empat puluh lima hari yang dimulai pada 25 Juli 1570, Lefkoşa, ibu kota Siprus di bawah pemerintahan Venesia, menyerah kepada pasukan Utsmaniyah. Jatuhnya pusat pulau menyudutkan perlawanan Venesia ke Benteng Magosa. Penaklukan menimbulkan gaung besar di Barat dan mempercepat proses menuju terbentuknya armada Liga Suci di bawah pimpinan Paus.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Penyerahan Girne — pesisir utara Siprus", "39fdeea5"], "d": ["Jatuhnya Lefkoşa dengan pembantaian pada 9 September mematahkan perlawanan di utara Siprus. Benteng Girne di balik Pegunungan Beşparmak, ketika mengetahui nasib ibu kota, menyerah dengan syarat delapan hari kemudian dan garnisunnya dikirim dengan diizinkan keluar dari pulau. Di pulau bendera Venesia hanya tinggal di Magosa; itu pun akan bertahan sebelas bulan lagi.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Pembangunan kembali armada setelah Lepanto", "db51fe44"], "d": ["Pekerjaan pertama Kılıç Ali Paşa, yang diangkat kaptan-ı deryâ setelah bencana Lepanto, adalah membangun kembali armada yang menderita kerugian berat; galangan bekerja tanpa henti sepanjang musim dingin 1571-1572. Pada Juni 1572 armada baru yang terdiri dari sekitar 250 galai dan 300 galai reis sukarelawan berlayar ke Mediterania. Pemulihan cepat ini menunjukkan bahwa Lepanto tidak mematahkan kekuatan laut Utsmaniyah secara permanen.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Perjanjian Istanbul dengan Venesia — pengakuan Siprus", "4d08ef50"], "d": ["Venesia, yang tinggal sendirian setelah bubarnya Liga Suci, membuat perdamaian terpisah dengan Utsmaniyah, secara resmi mengakui bahwa Siprus milik Utsmaniyah, dan menerima membayar ganti rugi perang. Perjanjian itu dengan jelas menunjukkan bahwa kemenangan Lepanto tidak memberi keuntungan politik kepada dunia Kristen. Venesia sesudahnya akan menghindari perang langsung dengan Utsmaniyah selama tujuh puluh tahun.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Wafatnya Selim II", "c289f5ee"], "d": ["Selim II, setelah jatuh, tidak dapat menghadiri divan selama sekitar dua bulan dan wafat. Kematiannya disembunyikan di istana selama dua belas hari hingga putra sulungnya Murad dari Manisa tiba di Istanbul. Sumber-sumber berbeda tentang hari kematian: Selânikî menyebut 15 Desember; Gerlach, Mehmed b. Mehmed, dan Cenâbî menyebut 13 Desember.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Pengumuman kematian Selim II dan naik takhtanya Murad III", "84334d70"], "d": ["Kematian Selim II dan naik takhtanya Murad III, yang dibawa dari Manisa, diumumkan secara resmi pada 22 Desember 1574. Sultan baru akan tetap di takhta selama dua puluh satu tahun, dan kesultanannya akan dikenang dengan perang Iran yang panjang di timur, menjelang Perang Panjang di barat, dan debasemen akçe di dalam negeri. Hingga wafatnya Sokollu Mehmed Paşa pada 1579 tatanan lama berlanjut dalam pemerintahan negara.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Pertempuran Wadi al-Makhazin (Alcácer Quibir) — Abdülmelik yang didukung Utsmaniyah memusnahkan pasukan Portugis", "21280dac"], "d": ["Abdülmelik, yang menduduki takhta Maroko dengan dukungan Utsmaniyah, memusnahkan pasukan besar Raja Portugis Sebastião di Wadi al-Makhazin; karena tiga penguasa tewas sekaligus dalam pertempuran, dalam sumber-sumber Barat ia disebut 'Pertempuran Tiga Raja'. Kekuatan militer Portugis runtuh dan negeri itu tak lama kemudian jatuh ke tangan Spanyol. Abdülmelik juga tewas dalam pertempuran; saudaranya Ahmed el-Mansûr yang menggantikannya mengabarkan kemenangan ke Istanbul melalui sebuah delegasi. Hubungan antara kedua negara tetap pada tingkat pertukaran utusan dan hadiah, bukan upeti atau ketundukan, dan tak lama kemudian menegang karena persoalan hadiah.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Penduduk Derbent menyatakan kesetiaan kepada Lala Mustafa Paşa — Demirkapı di bawah pemerintahan Utsmaniyah", "9c55aeff"], "d": ["Selama ekspedisi Şirvan, delegasi tujuh orang dari penduduk Derbent pergi ke Serdar Lala Mustafa Paşa di Ereş dan menyatakan kesetiaan. Derbent (Demirkapı), yang menutup lintasan sempit antara tembok Kaukasus dan Laut Kaspia, memainkan peran kunci dalam mempertahankan Şirvan sebagai lintasan wajib jalan-jalan darat dari utara. Kekuasaan Utsmaniyah di sini berlanjut hingga 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Penaklukan Şirvan: direbutnya Şamahı", "9afae4c1"], "d": ["Pasukan yang membuka ke Kaukasus setelah Kemenangan Çıldır memasuki Şirvan, eyalet Safawi terkaya di pesisir Kaspia, dan merebut kota pusat Şamahı. Özdemiroğlu Osman Paşa diangkat sebagai beylerbeyi di sana dan cabang utara Jalur Sutra dibawa ke bawah kendali Utsmaniyah. Şirvan akan menjadi front perang timur dua belas tahun yang paling sering berpindah tangan dan paling mahal.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Direbutnya Baku — keluar ke pesisir Kaspia", "eb5adab8"], "d": ["Sebagai mata rantai terakhir operasi Şirvan, pelabuhan Baku di pesisir barat Laut Kaspia direbut. Sumur-sumur minyak di sekitar kota bahkan pada masa itu adalah sumber pendapatan yang dikenal dan pelabuhan itu adalah titik keluar sutra Iran yang datang melalui Kaspia. Negara Utsmaniyah dengan demikian untuk pertama dan satu-satunya kali dalam sejarahnya memiliki pesisir di Laut Kaspia.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Penaklukan Revan (Yerevan) dan pembangunan benteng", "7f623b7b"], "d": ["Ferhad Paşa, yang menerima perintah di Kars untuk pergi ke Revan dan membangun benteng di sana, berbaris ke Revan dan kota dibawa ke kendali Utsmaniyah pada awal Ramadan 991 (pertengahan September 1583). Di Revan, yang menguasai gerbang utara lembah Aras, sebuah benteng baru yang besar dibangun; kota dijadikan pusat beylerbeylik. Revan, yang berdiri di tengah jalur pasukan antara Kars dan Tabriz, adalah tulang punggung logistik front timur. Benteng dibangun begitu kokoh sehingga selama dua ratus tahun berikutnya menjadi sasaran tetap perang Utsmaniyah-Iran.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Aneksasi Karabakh dan Ganja", "29abaead"], "d": ["Sebagai perolehan terakhir perang timur sepuluh tahun, Ferhad Paşa berbaris ke Ganja pada 1588 dan memasuki kota pada 1 September; wilayah Karabakh antara Kura dan Aras dan pusatnya Ganja dibawa ke pemerintahan Utsmaniyah. Dengan demikian Şirvan, Revan, dan Karabakh menyatu membentuk garis Utsmaniyah tak terputus di Kaukasus. Perjanjian Ferhad Paşa yang ditandatangani pada 1590 akan mencatat perbatasan ini, tetapi perolehan hanya dapat dipertahankan dua puluh tahun.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Penaklukan Bihać", "651a7275"], "d": ["Beylerbeyi Bosnia Telli Hasan Paşa, setelah merebut Ripaç, benteng depan Bihać, pada November 1591, pada 1592 merebut kota dan benteng itu sendiri; komandan Lamberg menyerah setelah pengepungan sepuluh hari. Penaklukan ini mendorong perbatasan Bosnia maju di sepanjang Sungai Una dan menjadi perolehan besar Utsmaniyah terakhir menjelang Perang Panjang, yang akan pecah satu tahun kemudian dengan gugurnya Telli Hasan Paşa sebagai syahid di depan Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Dimulainya 'Perang Panjang' Utsmaniyah-Austria", "bd22c392"], "d": ["Ketika Beylerbeyi Bosnia Telli Hasan Paşa dikalahkan dan gugur di depan Kulpa (Sisak), Negara Utsmaniyah menyatakan perang kepada Austria dan Perang Panjang yang akan berlangsung tiga belas tahun dimulai. Perang ini, di mana infanteri bersenjata api menentukan, mempercepat dipekerjakannya prajurit sekban dan bersenapan dalam tatanan tentara Utsmaniyah dan memperdalam kemunduran sipahi bertimar. Perang akan berakhir pada 1606 dengan Perjanjian Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Paşa berangkat ke ekspedisi Austria — ekspedisi pertama Perang Panjang", "d4a2f46d"], "d": ["Setelah Beylerbeyi Bosnia Hasan Paşa dikalahkan dan gugur sebagai syahid di depan Siska (Sisak), sadrazam Koca Sinan Paşa membujuk sultan berperang dengan kata-kata dan janji yang gemilang dan berangkat dengan 12.000 janisari dan unit-unit lain. Dengan demikian ekspedisi pertama perang Utsmaniyah-Austria yang akan berlangsung tiga belas tahun dibuka.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Penaklukan Yanıkkale (Győr)", "14b75207"], "d": ["Sadrazam Koca Sinan Paşa, setelah pengepungan lebih dari sebulan, menerima penyerahan Yanıkkale yang dianggap kunci jalan ke Wina. Jatuhnya benteng menimbulkan kepanikan besar di Eropa dan menjadi perolehan paling gemilang Utsmaniyah dalam Perang Panjang. Namun benteng itu hanya dapat dipertahankan selama empat tahun.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Wafatnya Murad III", "1b62e886"], "d": ["Setelah kesultanan dua puluh satu tahun, Murad III wafat pada hari-hari ketika pasukan Wallachia membakar İbrâil dan mencapai Silistre, dan dimakamkan di hazire Hagia Sophia. Putranya Mehmed III, yang dipanggil dari Manisa, tiba di Istanbul sepuluh hari kemudian dan naik takhta (27 Januari 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Hilangnya Esztergom ke Austria", "f420d333"], "d": ["Penjaga Esztergom, yang tidak memperoleh bantuan memadai dalam pengepungan yang dipimpin Karl von Mansfeld, menyerahkan benteng kepada Archduke Matthias. Dengan berakhirnya pemerintahan Utsmaniyah lima puluh dua tahun, rantai pertahanan di garis Danube patah dan Buda terancam langsung. Benteng baru dapat direbut kembali sepuluh tahun kemudian, pada 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Penaklukan Benteng Eger", "3e511629"], "d": ["Setelah pergulatan tiga minggu, Benteng Eger yang kuat, yang sebelumnya tidak pernah dapat direbut Utsmaniyah, jatuh dengan menyerahnya para penjaga. Penaklukan yang dihadiri sultan sendiri ini memulihkan semangat yang ditimbulkan hilangnya Esztergom sampai taraf tertentu dan provinsi Eger didirikan. Dengan kemenangan Mezőkeresztes yang diraih dua minggu kemudian, 1596 menjadi tahun paling sukses bagi Utsmaniyah dalam Perang Panjang.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Hilangnya Yanıkkale (Győr)", "b4ccc679"], "d": ["Unit-unit di bawah komando Miklós Pálffy dan Adolf von Schwarzenberg meledakkan gerbang benteng dengan serbuan dan merebut kembali Yanıkkale. Hilangnya benteng yang empat tahun sebelumnya diperoleh Koca Sinan Paşa dengan susah payah itu meruntuhkan garis depan Utsmaniyah di Hongaria. Meski pasukan musuh yang mengepung Buda pada tahun yang sama dipukul mundur, keseimbangan perang secara bertahap berubah menjadi perang atrisi.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Pemberontakan Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, yang menghimpun sekban dan levend yang melarikan diri dari pasukan dalam Perang Panjang, menguasai wilayah luas di Anatolia Tengah, merebut Benteng Urfa (November 1599), dan memproklamasikan kesultanannya dengan gelar 'Halim Şah' serta mengirim firman yang memuat tughra-nya sendiri. Karayazıcı, yang dianggap pemimpin pertama gelombang Celali besar, wafat pada 1602 dan gerakannya dilanjutkan saudaranya Deli Hasan. Pemberontakan itu adalah awal periode 'büyük kaçgunluk' ketika petani Anatolia meninggalkan tanahnya secara massal.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Pertahanan Kanije oleh Tiryaki Hasan Paşa", "d56a5e6a"], "d": ["Archduke Ferdinand dan para sekutunya, yang ingin merebut kembali Kanije yang ditaklukkan setahun sebelumnya, mengepung benteng lebih dari dua bulan; Tiryaki Hasan Paşa bertahan dengan 9000 pasukannya. Meski tidak memperoleh bantuan dari luar, ia memukul mundur serangan-serangan umum dan dengan operasi keluar memaksa musuh mundur dengan kerugian berat. Pertahanan itu menjadi epos dalam penulisan sejarah Utsmaniyah dan 'Pengepungan Kanije' menjadi genre sastra tersendiri.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Wafatnya Mehmed III dan naik takhtanya Ahmed I", "da735fde"], "d": ["Dengan wafatnya Mehmed III pada 20 Desember, putranya Ahmed I yang berusia empat belas tahun naik takhta. Karena ia sultan pertama yang naik takhta pada usia anak-anak dan tanpa pergi ke sancak, ini menunjukkan bahwa kebiasaan membesarkan şehzade di daerah secara de facto berakhir. Pada masa Ahmed I pembunuhan saudara ditinggalkan dan beralih ke asas 'ekberiyet' (anggota laki-laki tertua naik takhta).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Direbutnya kembali Esztergom", "7330f273"], "d": ["Sadrazam Lala Mehmed Paşa mengepung Esztergom, yang hilang sepuluh tahun sebelumnya, dan menggabungkannya kembali ke pemerintahan Utsmaniyah. Dalam ekspedisi yang sama Pest dan Vác juga diselamatkan dan Utsmaniyah menghimpun kembali garis mereka di Hongaria. Keberhasilan ini memungkinkan duduk dengan relatif kuat di meja perundingan di Zsitvatorok pada tahun berikutnya; Esztergom akan tetap di tangan Utsmaniyah hingga 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Kemenangan Dataran Oruç dan penumpasan pemberontakan Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Paşa, yang mendirikan beylik merdeka di Aleppo dan mencari aliansi dengan Toskana, dikalahkan telak di Dataran Oruç oleh Sadrazam Kuyucu Murad Paşa. Dengan dibangunnya kembali otoritas sentral di Suriah, cabang paling berbahaya gelombang Celali dipatahkan. Likuidasi kejam selama dua tahun oleh Kuyucu Murad Paşa menjamin ketertiban di Anatolia, meski sementara.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Kemenangan Alaçayır dan penumpasan pemberontakan Kalenderoğlu", "55db0485"], "d": ["Pemimpin Celali Kalenderoğlu, yang memeras wilayah Manisa dan Bursa, dikalahkan di Alaçayır oleh Kuyucu Murad Paşa dan terpaksa melarikan diri ke Iran. Dengan kemenangan ini pasukan Celali besar terakhir di Anatolia dibubarkan. Likuidasi keras Kuyucu Murad Paşa, yang menurut riwayat mengisi sumur-sumur yang digali dengan para pemberontak yang dibunuhnya, menjamin ketertiban dalam jangka pendek tetapi tidak dapat menebus hilangnya penduduk dan produksi Anatolia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Diberikannya ahidname pertama kepada Belanda", "5d9d117e"], "d": ["Utusan Republik Serikat Belanda, Cornelis Haga, berhasil memperoleh dari Ahmed I sebuah ahidname dengan cakupan yang sama dengan yang diberikan kepada Prancis dan Inggris. Dengan demikian Belanda memperoleh hak membuka kedutaan di Istanbul, konsulat di dermaga-dermaga Utsmaniyah, dan berdagang dengan benderanya sendiri. Ahidname ini melambangkan masuknya kekuatan laut utara, yang menggantikan Venesia dalam perdagangan Mediterania, ke pasar Utsmaniyah.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Wafatnya Ahmed I dan naik takhtanya Mustafa I — tata cara ekberiyet", "9901c09e"], "d": ["Ahmed I yang berusia dua puluh delapan tahun wafat setelah sakit perut selama lima puluh satu hari dan saudaranya Mustafa I, bukan putranya, dinaikkan ke takhta. Dengan demikian tatanan suksesi dari ayah ke anak ditinggalkan dan secara de facto beralih ke sistem 'ekberiyet' ketika anggota laki-laki tertua dinasti naik takhta. Kesultanan pertama selama sembilan puluh enam hari ini juga merupakan awal era şehzade dibesarkan di 'kafes'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Pemakzulan Mustafa I dan naik takhtanya Genç Osman (Osman II)", "e0f552f2"], "d": ["Mustafa I diturunkan dari takhta setelah sembilan puluh enam hari dengan alasan kesehatan jiwanya tidak baik dan Osman II, putra Ahmed I yang berusia empat belas tahun, menjadi sultan. Menurut riwayat yang bertumpu pada Hasanbeyzâde, Kepala Kasim Mustafa Ağa berpengaruh dalam keputusan pemakzulan ini. Genç Osman, dengan rencananya menghapus korps janisari dan membangun tentara baru, dianggap tokoh radikal pertama perdebatan reformasi Utsmaniyah. Rencana ini empat tahun kemudian akan merenggut nyawanya sendiri.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Perjanjian Serav — pembaruan perdamaian dengan Iran", "e778aca8"], "d": ["Perjanjian Serav, yang dicapai dengan Iran setelah kekalahan Pül-i Şikeste, sebagian besar menegaskan syarat-syarat Perjanjian Nasuh Paşa 1612; jumlah sutra tahunan yang akan dikirim Safawi diturunkan dari dua ratus muatan menjadi seratus muatan. Dengan demikian fase kedua perang timur yang berlangsung sejak 1603 tertutup. Perdamaian tidak akan berumur panjang; dengan lepasnya Baghdad pada 1623 perang akan berkobar kembali.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Ekspedisi Khotyn dan Perjanjian Khotyn", "bc4c823c"], "d": ["Terhadap pasukan besar yang dikomandoi Osman II sendiri, perkemahan berbenteng yang dibangun Chodkiewicz di depan Khotyn tidak dapat ditembus dan tidak ada hasil dari serangan selama berbulan-bulan. Dengan perjanjian yang ditandatangani pada 9 Oktober, Sungai Dniester diterima sebagai perbatasan dan orang Polandia berjanji mencegah serbuan Kosak. Ekspedisi yang tidak membuahkan hasil meski dipresentasikan sebagai kemenangan ini memperkuat ketidakpercayaan sultan muda kepada janisari dan niatnya melikuidasi korps.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Direbutnya Hormuz dari Portugis", "93e5f6cf"], "d": ["Pasukan Safawi mengepung dan merebut kembali Hormuz, yang berada di tangan Portugis sejak 1515; Qeshm dan Gamrûn (Bandar Abbas) di pesisir juga beralih ke pemerintahan Safawi dan perdagangan Teluk bergeser ke pelabuhan baru.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Pemakzulan kedua Mustafa I dan naik takhtanya Murad IV", "1b3a9e74"], "d": ["Mustafa I, yang dinaikkan ke takhta untuk kedua kalinya setelah pembunuhan Osman II, diturunkan lagi setelah satu tahun tiga bulan dan Murad IV yang berusia sebelas tahun dinyatakan sultan. Selama sembilan tahun pertama negara secara de facto diperintah ibunya Kösem Sultan dan para tokoh istana. Murad IV sejak 1632 akan mengambil alih pemerintahan sendiri dan memulai periode sentralisasi yang keras.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Hilangnya Baghdad ke Safawi", "db81be0c"], "d": ["Setelah tawar-menawar Bekir Subaşı, yang memberontak di Baghdad, dengan Safawi, putranya Derviş Mehmed, yang mempertahankan benteng dalam, menyerahkan kota kepada pasukan Syah Abbas. Hilangnya salah satu kota simbol warisan kekhalifahan dan sebagian besar Irak menimbulkan kemarahan besar di Istanbul. Merebut kembali Baghdad akan menjadi satu-satunya sasaran kebijakan timur Utsmaniyah selama lima belas tahun.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Penumpasan pemberontakan Abaza Mehmed Paşa yang berpusat di Erzurum", "e6da2729"], "d": ["Abaza Mehmed Paşa, Beylerbeyi Erzurum yang memberontak melawan janisari dengan dalih membalas pembunuhan Osman II, menguasai Anatolia Timur selama bertahun-tahun dan melawan pusat. Ia terpaksa menyerah akibat pengepungan Erzurum oleh Sadrazam Hüsrev Paşa, diampuni, dan diangkat ke Bosnia. Berakhirnya pemberontakan adalah prasyarat bagi Murad IV untuk dapat berekspedisi ke Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Eksekusi şeyhülislâm pertama: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Şeyhülislâm Ahîzâde Hüseyin Efendi dieksekusi di dekat Büyükçekmece dengan alasan menjadi penengah dalam kekacauan militer dan mengirim peringatan tertulis kepada sultan tentang tata cara peradilan. Sebagai şeyhülislâm Utsmaniyah pertama yang dieksekusi, hal ini mematahkan tradisi lama bahwa hukuman terberat bagi anggota ilmiye adalah pengasingan. Peristiwa itu dianggap simbol mengerasnya otoritas Murad IV dan rusaknya keseimbangan negara-ulama.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Penaklukan Revan oleh Murad IV", "b65a9b73"], "d": ["Murad IV, yang berangkat dari Istanbul pada 28 Maret 1635, mengepung Revan pada 28-29 Juli dan menerima penyerahan benteng pada 8 Agustus; kemudian ia memasuki Tabriz yang telah dikosongkan dan menghancurkan kota. Sultan membangun Paviliun Revan di Istana Topkapı untuk mengenang kemenangan. Ekspedisi ini adalah operasi timur besar pertama setelah jeda tiga puluh tahun ketika sultan memimpin pasukan secara langsung.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Hilangnya Revan ke Safawi", "fbb8dd25"], "d": ["Setelah penarikan pasukan Utsmaniyah, pasukan Syah Safi mengepung Revan dan merebutnya kembali dalam delapan bulan. Cepatnya benteng lepas menunjukkan betapa sulitnya kekuasaan permanen di Kaukasus secara logistik. Revan akan ditinggalkan di Iran dengan Perjanjian Qasr-e Shirin 1639 dan Utsmaniyah melepaskan klaim Azerbaijan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Penaklukan kembali Baghdad", "4d2f27f3"], "d": ["Murad IV, yang berangkat dari Istanbul pada 8 Mei 1638, merebut kembali Baghdad yang berada di tangan Safawi selama lima belas tahun setelah pengepungan sengit empat puluh hari; wazir Tayyar Mehmed Paşa gugur sebagai syahid dalam pengepungan. Dengan penaklukan kota, pemerintahan Utsmaniyah di Irak dibangun kembali dan sultan menyandang gelar 'Penakluk Baghdad'. Penaklukan itu dimantapkan oleh Perjanjian Qasr-e Shirin tahun berikutnya dan meletakkan dasar perbatasan Turki-Iran saat ini.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Wafatnya Murad IV dan naik takhtanya Sultan İbrahim", "e2ca1ca0"], "d": ["Setelah wafatnya Murad IV pada usia dua puluh tujuh (dua puluh delapan menurut hitungan hijriah), saudaranya İbrahim, satu-satunya anggota laki-laki dinasti yang masih hidup, naik takhta. Pada kesultanan sultan baru yang bertahun-tahun hidup di kafes, pengeluaran istana dan perebutan pengaruh dalam istana mengguncang tatanan negara. Delapan tahun kemudian, dengan dimakzulkan dan dibunuhnya, pembunuhan sultan kedua dalam sejarah Utsmaniyah akan terjadi.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Direbutnya kembali Benteng Azak dari Kosak", "e5fcf160"], "d": ["Benteng Azak, yang direbut Kosak Don pada 1637, dikosongkan menghadapi operasi bersama Sultanzâde Mehmed Paşa dan Khan Krimea Mehmed Giray IV; Kosak membakar benteng dan mundur. Direbutnya kembali gerbang utara Laut Hitam menutup periode berbahaya ketika serbuan Kosak mencapai Selat Istanbul. Benteng akan hilang lagi pada 1696, kali ini kepada Tsar Rusia Petrus I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Dimulainya ekspedisi Kreta dan penaklukan Hanya", "a1b0c77f"], "d": ["Perang dinyatakan kepada Venesia dengan dalih bajak laut Malta menyerang kapal haji Utsmaniyah dan berlindung di Kreta, dan armada di bawah komando Yûsuf Paşa mendaratkan pasukan di pulau itu. Setelah pengepungan lima puluh empat hari, benteng Hanya direbut dan pangkalan Utsmaniyah permanen pertama di Kreta didirikan. Dengan demikian perang terpanjang dalam sejarah Utsmaniyah dimulai; pulau itu baru dapat ditaklukkan seluruhnya dua puluh empat tahun kemudian, pada 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Penaklukan Resmo — Kreta terbagi dua", "8f2c4353"], "d": ["Satu tahun setelah direbutnya Hanya, benteng Resmo di bagian tengah pulau juga jatuh dan separuh barat Kreta seluruhnya masuk ke pemerintahan Utsmaniyah. Di tangan Venesia hanya tinggal ibu kota Kandiye dan ujung timur; pulau itu hidup terbagi dua selama dua puluh tiga tahun. Direbutnya Resmo menjadi langkah yang memulai pengepungan Kandiye — pengepungan terpanjang dalam sejarah dimulai di sini.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Hilangnya Klis ke Venesia", "5473c22c"], "d": ["Serangan balik komandan Venesia Leonardo Foscolo di front Dalmatia dalam Perang Kreta (Candia) mencakup Klis, pusat sancak sejak 1537; benteng beralih ke Venesia. Fokus Utsmaniyah dengan seluruh kekuatannya pada Kreta membuat tidak mungkin merebut kembali kehilangan di perbatasan Dalmatia ini — Klis tidak akan kembali ke pemerintahan Utsmaniyah; pusat sancak dipindahkan ke Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Dimulainya pengepungan Kandiye", "13016b10"], "d": ["Setelah direbutnya Hanya dan Resmo, pasukan Utsmaniyah mengepung Kandiye, tumpuan besar terakhir Venesia di pulau itu. Blokade yang akan berlangsung dua puluh satu tahun ini tercatat sebagai salah satu pengepungan terpanjang dalam sejarah militer dunia. Selama pengepungan, upaya armada Venesia menutup Selat Çanakkale akan membawa perang ke jantung Aegea.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Pembunuhan Valide Agung Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan yang berusia sekitar enam puluh dua tahun dibunuh setelah ditemukan di sebuah ruangan di Harem oleh Başlala Uzun Süleyman Ağa dan anak buahnya yang bertindak atas perintah Turhan Sultan, ibu Mehmed IV. Kematian perempuan dinasti yang kuat ini, yang mengarahkan politik negara pada masa tiga sultan, dianggap berakhirnya secara de facto periode yang disebut 'Kesultanan Perempuan'. Otoritas yang kosong membuka jalan bagi Köprülü Mehmed Paşa menjadi sadrazam dengan wewenang luar biasa lima tahun kemudian.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Kekalahan Çanakkale dan hilangnya Bozcaada dan Limni", "e01a1f7e"], "d": ["Kemenangan laut besar yang diraih Laksamana Venesia Mocenigo di depan Selat Çanakkale pada Juni 1656 hampir sepenuhnya memusnahkan armada Utsmaniyah; kemudian Bozcaada, Limni, dan Semadirek diduduki. Dengan masuknya selat ke dalam blokade Venesia, harga pangan di Istanbul melonjak dan ketakutan akan serangan atas ibu kota menyebar. Bencana ini menjadi penyebab langsung diangkatnya Köprülü Mehmed Paşa sebagai sadrazam dengan syarat dan wewenang luar biasa pada September 1656.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Kemenangan Çanakkale dan direbutnya kembali Bozcaada", "603da863"], "d": ["Armada yang dimobilisasi Köprülü Mehmed Paşa mengalahkan armada Venesia di depan Selat pada 19 Juli 1657; kemudian pasukan di bawah komando Kurd Paşa merebut kembali Bozcaada pada 25 Agustus dan pada 30 Agustus Venesia mengosongkan pulau sepenuhnya. Pada bulan November Limni juga dibebaskan, blokade Çanakkale dipatahkan, dan jalur perbekalan Istanbul dibuka kembali. Köprülü sendiri menyeberang ke pulau dan memperbaiki benteng-benteng; keberhasilan ini adalah perolehan militer besar pertama masa Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["Direbutnya kembali Limni dari Venesia", "a4c3c69b"], "d": ["Limni, yang direbut Venesia pada Juli 1656, kembali ke Utsmaniyah pada November 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Penaklukan Yanova (Ineu) dan ekspedisi Transilvania", "d1089616"], "d": ["Köprülü Mehmed Paşa, yang berangkat berekspedisi untuk menghukum Pangeran Transilvania György Rákóczi II yang melanggar perlindungan Utsmaniyah dengan melancarkan ekspedisi Polandia tanpa izin, berbaris melalui Beograd dan merebut benteng strategis Yanova. Seorang pangeran baru diangkat untuk Transilvania dan ikatan vasalase diingatkan dengan keras. Ekspedisi ini adalah mata rantai pertama upaya Utsmaniyah membangun kembali otoritasnya di Eropa Tengah. Transilvania sudah merupakan kepangeranan vasal Utsmaniyah; direbutnya Yanova bukan penaklukan dari negara asing, melainkan mengeluarkan benteng ini dari pemerintahan kepangeranan dan mengikatnya langsung ke sancak Utsmaniyah; sisa kepangeranan tetap dalam status vasal.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Penumpasan pemberontakan Abaza Hasan Paşa", "4ba74321"], "d": ["Abaza Hasan Paşa, yang memperoleh dukungan para beylerbeyi Anatolia dan aga sekban menentang likuidasi keras Köprülü Mehmed Paşa, memulai pemberontakan besar dengan menuntut pemecatan sadrazam. Pemberontakan ditumpas di Aleppo dan para pemimpinnya dilenyapkan; ini menjadi perlawanan kolektif terakhir para paşa provinsi terhadap pusat. Otoritas Köprülü dengan demikian tak terbantahkan dan kedudukan sadrazam kembali naik menjadi pusat eksekutif sejati negara.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Penaklukan Várad (Oradea)", "0e6ad300"], "d": ["Benteng dan kota Várad direbut dalam rangka ekspedisi melawan Pangeran Transilvania György Rákóczi II yang menyatakan perang kepada Utsmaniyah. Dengan jatuhnya salah satu benteng kunci Transilvania, provinsi Utsmaniyah baru (Eyalet Várad) didirikan di wilayah itu. Penaklukan itu membuat Habsburg waspada dan menjadi salah satu penyebab langsung perang Utsmaniyah-Austria yang akan dimulai tiga tahun kemudian. Tempat-tempat lain yang bergabung pada tanggal yang sama: Varat. Di sini pun tanah tidak diambil dari negara asing: Transilvania sudah merupakan kepangeranan vasal Utsmaniyah; menjadi eyaletnya Várad hanya mengambil pemerintahan kota ini dari kepangeranan vasal dan mengikatnya langsung ke sultan, seperti dua tahun sebelumnya di Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Pertempuran Szentgotthárd (St. Gotthard)", "61ebc1f2"], "d": ["Pasukan Utsmaniyah yang menyeberangi Sungai Raab dihentikan oleh pasukan gabungan Eropa di bawah komando Montecuccoli dan menderita kerugian berat. Pertempuran itu dianggap titik balik dalam sejarah militer karena untuk pertama kalinya secara terbuka memperlihatkan keunggulan tembakan senapan infanteri berdisiplin atas serbuan kavaleri Utsmaniyah. Meski kalah, Utsmaniyah berhasil memperoleh syarat yang menguntungkan dalam Perjanjian Vasvár yang ditandatangani sembilan hari kemudian.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Perjanjian Vasvár", "089c978c"], "d": ["Perjanjian yang ditandatangani meski ada kekalahan Szentgotthárd menetapkan bahwa Uyvar dan Várad tetap di tangan Utsmaniyah, Transilvania dibiarkan netral di bawah perlindungan Utsmaniyah, dan Austria membayar 200.000 kuruş sebagai 'hadiah'. Perdamaian dua puluh tahun ini adalah salah satu contoh langka pihak yang kalah perang menang di meja perundingan. Ketidakpuasan yang ditimbulkan perjanjian itu dalam opini publik Habsburg akan memberi makan gerakan Hongaria Tengah dan secara tidak langsung ekspedisi Wina 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Dimulainya pemerintahan dey di Aljir", "e99faa51"], "d": ["Ocak Aljir dan taife-i reîs (kapten-kapten korsan) memecat aga terakhir dan memilih Hacı Mehmed sebagai dey seumur hidup. Setelah tanggal ini Aljir tidak lagi diperintah beylerbeyi yang diangkat Istanbul, melainkan dey yang dipilih ocak lokal dari antara mereka sendiri; ikatan Utsmaniyah terbatas pada pembacaan nama sultan dalam khutbah, panji, dan kewajiban ekspedisi. Aljir dengan demikian berubah dari provinsi menjadi ocaklık — transformasi yang sama dialami Tunisia dengan Husainiyah pada 1705 dan Tripolitania dengan Karamanlı pada 1711.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Ekspedisi Polandia dimulai — Mehmed IV dan Fâzıl Ahmed Paşa di kepala pasukan", "75e15a39"], "d": ["Ketika serangan Polandia terhadap hetman Ukraina Petro Doroshenko, yang masuk ke perlindungan Utsmaniyah, berlanjut, Istanbul meminta raja Polandia menghentikan serangan; ketika tidak ada jawaban positif, diputuskan ekspedisi ke Polandia. Wazir Agung Fâzıl Ahmed Paşa berangkat ke Polandia pada 4 Juni 1672 dengan pasukan yang juga diikuti sultan. Ekspedisi akan berujung pada penaklukan Kamieniec dan Perjanjian Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Penaklukan Kamieniec dan pendirian Eyalet Podolia", "c3f4f6d0"], "d": ["Setelah pengepungan sembilan hari, Kamieniec, yang dianggap benteng terkuat Polandia di timur, diterima penyerahannya; Mehmed IV menunaikan salat Jumat pertama pada 2 September di masjid yang diubah dari katedral. Benteng dijadikan pusat dan Eyalet Podolia didirikan; panji Utsmaniyah mencapai titik paling utara di wilayah Ukraina saat ini. Kamieniec akan tetap menjadi ujung barat laut kekaisaran hingga Perjanjian Karlowitz 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Paşa menerima penyerahan Uman dari Polandia", "0d3543a0"], "d": ["Kara Mustafa Paşa, yang dikirim melawan Polandia, menerima penyerahan Uman, salah satu benteng di tangan Polandia; kota tetap di bawah pemerintahan Utsmaniyah hingga Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Penaklukan Benteng Chyhyryn", "a17cedd0"], "d": ["Setelah operasi yang tidak membuahkan hasil bagi Melek İbrahim Paşa pada tahun sebelumnya, Sadrazam Merzifonlu Kara Mustafa Paşa memimpin sendiri dan mengepung Benteng Chyhyryn yang berbenteng (19/21 Juli) dan merebutnya pada 21 Agustus. Jatuhnya benteng yang menjadi simbol persaingan Utsmaniyah-Rusia atas hetmanat Kosak di Ukraina memaksa Rusia berdamai. Keberhasilan ini juga menjadi salah satu sumber kepercayaan diri Merzifonlu yang akan mengarah ke Wina.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Perjanjian Bahçesaray — perdamaian resmi pertama dengan Rusia", "df82bc0b"], "d": ["Pada akhir perundingan yang dijalankan dengan mediasi Khan Krimea setelah ekspedisi Chyhyryn, perdamaian dua puluh tahun ditandatangani antara Negara Utsmaniyah dan Rusia dengan Sungai Özü (Dnieper) diterima sebagai perbatasan. Ini dianggap dokumen awal hubungan Utsmaniyah-Rusia karena merupakan perjanjian komprehensif pertama antara kedua negara. Berkat perdamaian, front timur diamankan dan pasukan dapat diarahkan ke Eropa Tengah.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Pemberian berat raja Hongaria Tengah kepada Thököly Imre", "3cd8d51d"], "d": ["Imre Thököly, bangsawan Hongaria Protestan yang memberontak melawan tekanan Habsburg, mulai dianggap 'raja terpilih Hongaria Tengah' sejak April 1682 dan pada 16 September Beylerbeyi Buda İbrahim Paşa mempersembahkan tanda-tanda kepangeranan kepadanya. Dengan demikian sebuah negara vasal Hongaria baru didirikan di bawah perlindungan Utsmaniyah. Intervensi ini membuat perang dengan Austria tak terelakkan dan memulai rantai menuju Pengepungan Wina II pada tahun berikutnya.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Hilangnya Ayamavra (Lefkada) ke Venesia", "e6905fee"], "d": ["Armada Venesia, yang bergabung dengan Liga Suci, setelah membombardir kota menduduki Pulau Ayamavra di Laut Ionia. Dengan jatuhnya Preveze pada tahun yang sama, kendali Utsmaniyah di mulut Adriatik patah. Kehilangan-kehilangan ini adalah langkah-langkah awal operasi yang dengannya Morosini akan merebut seluruh Mora dalam tiga tahun.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Hilangnya Koron ke Venesia", "2ed762bc"], "d": ["Pasukan Venesia di bawah komando Morosini merebut Benteng Koron di ujung barat daya semenanjung Mora; kota itu sesudahnya akan tetap di bawah pemerintahan Venesia selama tiga puluh tahun. Jatuhnya Koron adalah perolehan besar pertama operasi Venesia untuk menaklukkan Mora. Benteng baru dapat direbut kembali pada 1715 oleh pasukan Utsmaniyah di bawah komando Silâhdar Ali Paşa.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Direbutnya kembali Athena — penarikan Venesia", "03393b46"], "d": ["Morosini, yang membombardir Akropolis dan meledakkan Parthenon pada September 1687, setelah melewati musim dingin di Athena menyadari tidak akan dapat bertahan di kota. Karena wabah, kesulitan pasokan, dan pulihnya pasukan Utsmaniyah, garnisun Venesia mengosongkan kota dan mundur ke Mora. Athena dengan demikian kembali ke pemerintahan Utsmaniyah tanpa pertempuran, tetapi kehancuran yang diderita Parthenon tidak dapat dikembalikan.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) menyerah kepada Caraffa — jatuh ke tangan Austria", "7f0a8d38"], "d": ["Setelah pengepungan tiga hari oleh Antonio Caraffa, Lipova menyerah antara 12-22 Juni 1688 dan jatuh ke tangan Austria. Utsmaniyah kemudian merebut kembali kota, Austria menguasainya lagi pada 1691; dalam ekspedisi 1695 Utsmaniyah kembali mengendalikannya. Permukiman lain dalam atlas yang beralih dari Utsmaniyah ke Habsburg pada tanggal yang sama: Arad dan Világos (Şiria). Untuk Arad sumber hanya memberi tahun (MKL, Arad: di tangan Utsmaniyah antara 1551-1688); hari diambil dari Lipova, Világos mengikuti rantai Arad (pendekatan yang dinyatakan).", "0dfcf5af"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Dipukul mundurnya pengepungan Eğriboz oleh Venesia", "aae7e6a0"], "d": ["Morosini, yang berpaling ke Aegea setelah merebut Mora, berusaha merebut Eğriboz dengan pengepungan lebih dari tiga bulan; namun menghadapi benteng yang diperkuat pada musim dingin 1687-1688 dan perlawanan garnisun, ia terpaksa mundur dengan kerugian berat. Kegagalan ini menghentikan kemajuan Venesia di Aegea dan mengguncang gengsi militer Morosini. Eğriboz akan tetap di tangan Utsmaniyah juga di Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Hilangnya Benteng Kanije ke Austria", "553b45f3"], "d": ["Kanije, yang diblokade ketat pasukan Habsburg 60.000 orang sejak Januari 1690, setelah bertahan berbulan-bulan tanpa menerima bantuan, lepas dengan perjanjian penyerahan yang ditandatangani penjaga terakhirnya Mustafa Paşa. Dengan demikian pemerintahan Utsmaniyah sembilan puluh tahun di benteng yang dikenang dengan pertahanan epik Tiryaki Hasan Paşa itu berakhir. Hilangnya Kanije adalah runtuhnya tumpuan besar terakhir Utsmaniyah di Hongaria barat.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Wafatnya Süleyman II", "d2478080"], "d": ["Süleyman II, yang dinaikkan ke takhta pada 1687 setelah menghabiskan sekitar empat puluh tahun di kafes, wafat di Edirne menjelang siang hari Jumat 22 Juni 1691 sambil mengamati persiapan pasukan dalam keadaan sakit; kesultanannya berlangsung tiga tahun delapan bulan dua hari. Sadrazam sebelumnya telah memberi instruksi yang diperlukan agar saudaranya Ahmed dinaikkan ke takhta jika sultan wafat. Salat jenazah dilaksanakan pada hari yang sama di Alay Köşkü; jenazahnya dibawa ke Istanbul dan dimakamkan di makam Sultan Süleyman Kanuni di sebelah kanannya.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Naik takhtanya Ahmed II", "52947b14"], "d": ["Setelah wafatnya Süleyman II, saudaranya Ahmed II yang berusia empat puluh sembilan tahun naik takhta di Edirne. Kesultanannya bertepatan dengan tahun-tahun terberat perang Liga Suci; dua bulan setelah naik takhta, Sadrazam Fâzıl Mustafa Paşa gugur sebagai syahid di Slankamen. Sebaliknya sistem mâlikâne yang diberlakukan pada masanya menjadi salah satu pengaturan terpenting yang mengubah struktur jangka panjang keuangan Utsmaniyah.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Wafatnya Mehmed IV di Edirne", "17388b7e"], "d": ["Avcı Mehmed, yang diturunkan dari takhta pada 1687, dibawa ke Edirne selama ekspedisi Hongaria Süleyman II tahun 1689 dan juga menyaksikan kesultanan saudaranya Ahmed II yang lain. Ia wafat di kota yang sangat dicintainya ini. Jenazahnya dibawa ke Istanbul dan dimakamkan di makam ibunya Turhan Sultan di samping Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Wafatnya Ahmed II di Edirne", "c6306c08"], "d": ["Ahmed II, yang kesultanannya selama empat tahun berlalu dalam perang, wafat di Edirne pada usia lima puluh dua tahun karena istiskā (busung air). Jenazahnya dibawa ke Istanbul dan dimakamkan di makam Sultan Süleyman Kanuni. Keponakannya Mustafa II naik menggantikannya.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Direbutnya Basra oleh Iran", "a9cdf3a3"], "d": ["Ketika Negara Utsmaniyah sibuk dengan perang Liga Suci di barat, Basra, setelah wabah pada 1690, dijarah pertama oleh syekh Müntefik Mâni' dan kemudian oleh Khan Huveyze Ferecullah. Dengan memanfaatkan kekacauan ini, Iran merebut kota pada 1696 dan menempatkan penjaga di Basra.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Perjanjian Istanbul — penyerahan Azak kepada Rusia", "79db4724"], "d": ["Di Karlowitz hanya dapat dicapai gencatan senjata dua tahun dengan Rusia; perdamaian permanen ditandatangani di Istanbul setelah tawar-menawar sengit selama satu setengah tahun. Negara Utsmaniyah secara resmi menyerahkan Benteng Azak yang hilang pada 1696 dan wilayah sekitarnya kepada Rusia dan melepaskan pajak tahunan yang diterima khan Krimea dari Moskow. Sebagai imbalan Rusia memperoleh hak menempatkan duta tetap di Istanbul; dengan demikian kehadiran Rusia di pesisir utara Laut Hitam tercatat secara hukum.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Paşa merebut kembali Kurna dan Basra", "7adb777d"], "d": ["Daltaban Mustafa Paşa, yang diangkat sebagai gubernur Baghdad dan serasker Basra setelah Perjanjian Karlowitz, berbaris ke selatan dengan pasukan Aleppo, Raqqa, Sivas, dan Karaman dan armada sungai yang turun dari Birecik. Para syekh suku di sekitarnya tunduk satu per satu, penjaga Basra Iran Dâvud Han meninggalkan kota, dan Kurna serta Basra kembali masuk ke pemerintahan Utsmaniyah.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Wafatnya Mustafa II", "626c394d"], "d": ["Mustafa II, yang menyerahkan takhta kepada saudaranya Ahmed III dengan Peristiwa Edirne, wafat sekitar lima bulan setelah diturunkan di Edirne yang sangat dicintainya. Kesedihan atas perkembangan terakhir juga menambah penyakitnya. Beberapa sumber Barat menulis bahwa kepercayaan ia diracun tersebar di kalangan rakyat.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Dimulainya pemerintahan Kölemen (Mamluk) di Baghdad", "abe52618"], "d": ["Dengan diangkatnya Hasan Paşa keturunan Georgia sebagai gubernur Baghdad, dimulailah periode ketika di Irak kelompok pemerintah yang dibesarkan dari budak mereka sendiri berkuasa menggantikan gubernur yang diangkat dari pusat. Dengan jabatan gubernur Süleyman Paşa pada 1749 sistem itu semakin mapan dan Bâbıâli tidak lagi dapat mengangkat orang yang diinginkannya, melainkan terpaksa mengangkat salah satu kölemen yang telah menguasai pengaruh. Struktur semi-otonom ini, meski berguna dalam mempertahankan perbatasan Iran, melemahkan kendali otoritas sentral atas Irak selama satu setengah abad.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Pendirian dinasti Husainiyah di Tunisia", "cb1a98f9"], "d": ["Dalam kekosongan otoritas yang muncul akibat invasi pasukan Aljir ke Tunisia, aga sipahi keturunan Turki Hüseyin b. Ali menguasai beylik dan memperoleh legitimasi dengan menyatakan kesetiaan kepada sultan Utsmaniyah. Dinasti yang ia dirikan memerintah Tunisia pada 1705-1735 dan 1756-1957; tatanan beylik yang diwariskan dari ayah ke anak menggantikan pemerintahan ocak. Dengan demikian contoh pertama struktur dinasti yang terikat pada pusat tetapi secara faktual otonom di ocak-ocak Garp lahir.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Direbutnya Oran (Vahran) dan Mers el-Kébir dari Spanyol", "b67ce06a"], "d": ["Pasukan beylerbeyi Ocak Aljir merebut Oran, yang berada di tangan garnisun Spanyol selama dua abad, dan pelabuhan Mers el-Kébir setelah pengepungan panjang. Ini adalah keberhasilan terbesar ocak-ocak Garp di bawah perlindungan Utsmaniyah melawan Spanyol di Mediterania Barat dan mengamankan sayap barat Aljir. Kota akan mengalami pendudukan Spanyol lagi pada 1732, tetapi akan direbut kembali secara pasti pada 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Perjanjian Prut — direbutnya kembali Azak dan Taganrog", "bac5d2a1"], "d": ["Perjanjian tujuh pasal yang ditandatangani dengan menyerahnya pasukan Rusia yang terkepung di tepi Prut menetapkan dikembalikannya Benteng Azak beserta tanah dan amunisinya kepada Utsmaniyah. Benteng Taganrog, Kamenka, dan Yenikale akan dihancurkan dan kedua pihak tidak akan membangun benteng baru di wilayah ini. Tatanan armada dan pangkalan yang dibangun Petrus I di Voronezh dan Azak selama enam belas tahun runtuh; turunnya Rusia ke Laut Hitam tertunda sekitar lima puluh tahun.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Pendirian dinasti Karamanlı di Tripolitania", "e1105d4a"], "d": ["Di Tripolitania yang jenuh dengan pertikaian para aga ocak, perwira kavaleri Ahmed Karamanlı menguasai pemerintahan dan meresmikan kedudukannya dengan berat beylerbeylik yang diperoleh dari Istanbul. Melalui Ahmed Paşa, putranya Mehmed Paşa, dan cucunya Yûsuf Paşa lahir sebuah dinasti yang berlangsung antara 1711-1835; muncul struktur semi-merdeka yang membangun armadanya sendiri dan menandatangani perjanjian langsung dengan negara-negara Eropa. Masa ini baru akan berakhir pada 1835 dengan terikatnya provinsi langsung ke pusat.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Perjanjian Edirne dengan Rusia", "14901a70"], "d": ["Karena janji-janji di Prut tidak dipenuhi, perang dinyatakan dua kali lagi, dan akhirnya ketika Rusia menerima komitmen, perdamaian permanen ditandatangani di Edirne. Perjanjian menegaskan syarat-syarat Prut; Rusia tidak akan mencampuri urusan Polandia, akan mundur dari tanah Kosak, dan tidak akan menghalangi kembalinya raja Swedia Demirbaş Şarl ke negerinya. Tertutupnya front utara memungkinkan Negara Utsmaniyah memalingkan wajahnya ke front Mora dan Venesia. Tempat-tempat lain yang bergabung pada tanggal yang sama: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Pernyataan perang kepada Venesia — persiapan ekspedisi Mora", "d970b122"], "d": ["Keputusan perang diambil di Divan dengan alasan Venesia mendukung pemberontak Montenegro, menyita kapal dagang Utsmaniyah, dan menindas Mora yang diperolehnya di Karlowitz dengan pajak berat. Ekspedisi yang dipersiapkan Sadrazam Silâhdar Damad Ali Paşa akan berujung pada direbutnya kembali seluruh semenanjung Mora dalam kurang dari seratus hari pada tahun berikutnya. Namun keberhasilan ini akan menggerakkan Austria dan membuka pintu perang yang jauh lebih berat pada 1716.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["İstendil (Tinos): penyerahan pulau Venesia terakhir di Aegea", "4abec891"], "d": ["Armada yang berangkat ke ekspedisi Mora berlabuh di depan İstendil, satu-satunya pulau yang tersisa di tangan Venesia di Aegea. Pulau itu, yang berkat penduduk Latinnya tetap menyandang bendera Venesia seratus lima puluh tahun lagi meski Kadipaten Naxos jatuh pada 1566, menyerah tanpa pertumpahan darah setelah pengepungan singkat. Dengan demikian jejak terakhir Venesia di Laut Aegea terhapus dan laut itu seluruhnya menjadi laut pedalaman Utsmaniyah.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Penaklukan Anabolu — benteng kunci Mora", "62a5808a"], "d": ["Anabolu (Nauplion), ibu kota dan benteng terkuat Venesia di Mora, jatuh dengan direbutnya benteng Palamidi setelah pengepungan sembilan hari. Direbutnya benteng secepat ini mematahkan perlawanan di sisa semenanjung. Direbutnya kembali Mora, yang hilang di Karlowitz, secara faktual selesai di sini. Permukiman lain dalam atlas yang beralih dari Venesia ke Utsmaniyah pada tanggal yang sama: Argos — mengikuti rantai abi-merkez Anabolu (TDV anabolu; pendekatan yang dinyatakan).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Penyerahan Modon", "43faa909"], "d": ["Setelah jatuhnya Anabolu, Benteng Modon di ujung barat daya Mora dikepung oleh pasukan dari darat dan armada dari laut dan segera menyerah. Pelabuhan yang digunakan Venesia selama dua ratus tahun dalam ekspedisi Mediterania Timur ini adalah titik singgah wajib tempat kapal mengambil air dan perbekalan. Hilangnya mengakhiri kemampuan gerak armada Venesia di Aegea.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Penyerahan Koron — selesainya ekspedisi Mora", "e4b9c8a4"], "d": ["Dengan menyerahnya Benteng Koron yang menguasai mulut Teluk Messenia, pemerintahan Venesia di semenanjung Mora berakhir sepenuhnya. Semenanjung yang hilang di Karlowitz direbut kembali seluruhnya hanya tiga bulan setelah ekspedisi dibuka. Dalam kelanjutan ekspedisi yang sama, pada September 1715, pulau Ayamavra (Lefkada) di Laut Ionia juga direbut dari Venesia. Kecepatan ini memaksa Venesia membawa Austria ke dalam perang dan tiga tahun kemudian jalan menuju Passarowitz terbuka.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Direbutnya Pulau Çuha (Kythira)", "494de6c6"], "d": ["Pulau Çuha di ujung selatan Mora diterima penyerahannya oleh armada setelah selesainya semenanjung. Pulau yang mengawasi lintasan antara Laut Ionia dan Aegea itu adalah pos depan yang digunakan Venesia untuk mengendalikan perairan ini. Namun ia tidak tetap menjadi satu-satunya pulau yang dipertahankan Utsmaniyah: tiga tahun kemudian ia dikembalikan kepada Venesia di Passarowitz.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria dan Venesia membentuk aliansi — pintu Perang Utsmaniyah-Austria 1716-1718", "99511ca2"], "d": ["Setelah Utsmaniyah merebut kembali Mora dari Venesia, Austria, dengan mengklaim bahwa Perjanjian Karlowitz dilanggar, menandatangani perjanjian aliansi dengan Venesia; Pangeran Eugène dalam surat kepada sadrazam meminta dikembalikannya tempat-tempat yang diambil dari Venesia. Dalam musyawarah di perkemahan Davutpaşa, atas desakan sadrazam Ali Paşa, perang dinyatakan kepada Austria dan untuk itu fatwa diperoleh dari şeyhülislâm.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Sadrazam Ali Paşa berangkat ke ekspedisi Austria", "2fbdce42"], "d": ["Setelah perang dinyatakan kepada Austria, serdâr-ı ekrem Ali Paşa berangkat ke ekspedisi Austria dengan pasukan lebih dari 100.000 orang; sementara armada pada musim panas yang sama berbelok ke Korfu. Pasukan akan berbaris dari Beograd menuju Varadin dan sadrazam akan gugur sebagai syahid dalam kekalahan pada awal Agustus.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Kekalahan Varadin (Petrovaradin) — syahidnya Damad Ali Paşa", "265c1d81"], "d": ["Pasukan Utsmaniyah yang menyeberangi Danube melalui Beograd bertemu dengan pasukan Austria di bawah komando Pangeran Eugène di depan Varadin; meski dalam serangan pertama serbuan janisari menembus parit musuh, barisan buyar dengan runtuhnya sayap kavaleri. Sadrazam Silâhdar Damad Ali Paşa tertembak di dahi dan gugur sebagai syahid, dan perkemahan serta seluruh baterai artileri jatuh ke tangan musuh. Kekalahan ini, yang disebut 'tahun Varadin' dalam vekayi'name Utsmaniyah, adalah mata rantai pertama dalam rantai menuju hilangnya Timișoara dan hilangnya Beograd pada tahun berikutnya.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Pengepungan Korfu berakhir gagal", "b2aa7011"], "d": ["Serasker Mora Kara Mustafa Paşa menyerang Korfu dari darat dan Kaptanıderyâ Canım Hoca Mehmed Paşa dari laut dengan armada; pulau itu adalah pangkalan kunci Venesia di Adriatik. Namun tembok benteng yang sangat kuat, bala bantuan yang dibawa armada Venesia, dan kabar kekalahan dari front Danube menyebabkan pengepungan dicabut. Tidak direbutnya Korfu memadamkan semangat yang meningkat dengan penaklukan kembali Mora dan menggeser pusat gravitasi perang ke Hongaria.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Hilangnya Timișoara (Timişvar) ke Austria", "27fe1365"], "d": ["Setelah kekalahan Varadin, Pangeran Eugène berbaris langsung ke Timișoara dan benteng diserahkan dengan perjanjian setelah pengepungan lebih dari empat puluh hari. Kota yang direbut pada 1552 masa Kanuni dan selama 164 tahun sebagai pusat beylerbeylik dianggap tiang timur pertahanan Hongaria itu pun lepas. Dengan jatuhnya Timișoara seluruh wilayah Banat beralih ke Austria dan perbatasan Utsmaniyah didorong ke selatan Danube. Permukiman lain dalam atlas yang beralih dari Utsmaniyah ke Habsburg pada tanggal yang sama: Csákóvár, Facset, dan Karánsebes (Caransebeș) — bersama penyerahan eyalet Timișoara (TDV timisvar; hari tingkat tempat tidak ada dalam sumber, rantai abi-merkez, pendekatan yang dinyatakan).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Penyerahan Benteng Haram (Yeni Palanka) kepada Austria — tepi Danube Banat lepas", "38ee4c6d"], "d": ["Mercy, jenderal kavaleri Austria yang ditugaskan merebut sisa Banat setelah jatuhnya Timișoara, berbaris ke Haram (Yeni Palanka) di tepi Danube pada 14 November; ketika tiba di benteng pada 16 November, garnisun Utsmaniyah 200 orang menyerah dengan mengibarkan bendera putih dan syarat mundur dengan bebas. Dengan demikian garis Danube Banat Selatan yang berada di tangan Utsmaniyah sejak 1552 juga beralih ke Austria. Permukiman lain dalam atlas yang beralih dari Utsmaniyah ke Habsburg pada tanggal yang sama: Versec — mengikuti rantai abi-merkez Haram (Bánlaky 0019/1703; pendekatan yang dinyatakan).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Perjanjian Passarowitz — Mora diperoleh, Beograd dan Banat hilang", "d46aa216"], "d": ["Mora telah direbut kembali dari Venesia, tetapi Austria, yang masuk perang, unggul di meja dengan kemenangannya di Petrovaradin dan Beograd. Perjanjian yang ditandatangani dengan mediasi Inggris dan Belanda membiarkan Mora di tangan Utsmaniyah; sebagai imbalannya Serbia Utara bersama Beograd, Banat, dan Wallachia Kecil diserahkan kepada Austria; dengan ungkapan TDV 'Bosnia Utara seluruhnya diserahkan kepada Austria' — benteng-benteng seperti Bosna Dubiçası dan Bosna Brod di sepanjang Sava di peta beralih ke Austria sejak hari ini (perbatasan pasti ditarik satu per satu oleh komisaris, TDV tidak menyebut benteng-benteng ini namanya); sementara Venesia mempertahankan posisinya di pesisir Ionia seperti Preveze dan Çuha. Dengan perjanjian dagang yang ditandatangani pada hari yang sama, bea cukai yang dipungut dari barang Austria diturunkan dari lima persen menjadi tiga. Sementara perjanjian itu mencatat mundurnya Negara Utsmaniyah di Eropa Tengah, perdamaian dua puluh tujuh tahun yang dibukanya membentuk landasan Era Tulip (1718-1730): percetakan Utsmaniyah pertama (1727, İbrahim Müteferrika) di bawah pemerintahan Nevşehirli Damad İbrahim Paşa, komite-komite penerjemah, pengamatan vaksin cacar, dan kehidupan istana-budaya baru adalah produk tahun-tahun damai ini. Permukiman lain yang berpindah tangan pada hari yang sama dalam atlas: Krayova (Craiova), Rimnik (Râmnicu Vâlcea), dan Turnu Severin (Wallachia Kecil/Oltenia, dari Utsmaniyah ke Austria) serta Ayamavra (Lefkada) (dari Utsmaniyah ke Venesia; TDV ayamavra: pulau diserahkan kepada Venesia dengan Perjanjian Passarowitz 1718). Di Wallachia Kecil juga Tırgu Jiu beralih ke Austria; Vonitsa (Voniçe, TDV pasarofca-antlasmasi) dan Pulau Çuha (Kythira, TDV cuka-adasi: pasal 3 Passarowitz) beralih ke Venesia.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Ekspedisi timur: direbutnya Tiflis dan dimulainya perang Iran", "78343dc2"], "d": ["Ketika Negara Safawi runtuh akibat invasi Afghan dan Rusia turun ke pesisir Kaspia, Negara Utsmaniyah mengirim pasukan ke timur agar kekosongan itu tidak sepenuhnya jatuh ke pengaruh Rusia. Tiflis direbut dan Georgia diikat ke pemerintahan Utsmaniyah; kemudian kemajuan berlanjut ke arah Ganja, Revan, dan Nakhchivan. Ekspedisi yang dijalankan di balik wajah damai Era Tulip ini menjadi awal petualangan timur panjang yang akan berlangsung tiga belas tahun dan berakhir dengan dikembalikannya semua yang diperoleh.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Ekspedisi Iran 1723: masuk ke Şirvan dan Georgia", "c81189fc"], "d": ["Atas runtuhnya Negara Safawi akibat invasi Afghan, ekspedisi ke timur dilancarkan dengan alasan mencegah turunnya Rusia ke pesisir Kaspia. Pasukan Erzurum memasuki Tiflis melalui Georgia dan kolom Şirvan memasuki Şamahı, merebut kembali wilayah yang hilang seratus tiga puluh tahun sebelumnya. Ekspedisi ini menjadi kemajuan besar terakhir Utsmaniyah di Kaukasus.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Direbutnya Kermanshah — gerbang Zagros", "ad14799f"], "d": ["Pasukan Baghdad melintasi celah-celah Zagros dan merebut Kermanshah, yang dianggap gerbang barat Iran. Kota itu berada di jalur kafilah dan pasukan dari Baghdad ke Isfahan dan direbutnya menjamin keamanan timur eyalet Irak. Kemajuan ini memulai perlombaan pembagian antara Utsmaniyah dan Rusia atas negeri Safawi yang bubar.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukāsemenâme Istanbul — pembagian Iran dengan Rusia", "fce8eec2"], "d": ["Untuk mencegah berhadapannya Utsmaniyah dan Rusia atas negeri Safawi yang runtuh, perjanjian pembagian ditandatangani dengan mediasi duta Prancis. Pesisir barat dan selatan Laut Kaspia diserahkan kepada Rusia, dan kota-kota Georgia, Şirvan, Azerbaijan, dan Iran Barat kepada Negara Utsmaniyah. Pembagian yang tampak sebagai perolehan besar di atas kertas ini tak lama kemudian akan menjadi tidak berlaku secara de facto dengan bangkitnya Nadir Syah. Menurut perjanjian, wilayah subur Şirvan seperti Şabran dan Müşkür ditinggalkan di pihak Rusia (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Direbutnya Nakhchivan", "bdf14d0a"], "d": ["Pasukan Utsmaniyah yang maju di sepanjang Aras merebut Nakhchivan dan Ordubad; Culfa juga digabungkan ke liva Nakhchivan. Kota itu diikat ke eyalet Revan yang baru dibentuk sebagai gerbang barat laut Iran. Dengan demikian perbatasan Utsmaniyah kembali mencapai garis paling timur masa Kanuni.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Penaklukan Hamadan", "e1339a97"], "d": ["Pasukan yang berbaris ke timur dari Kermanshah merebut Hamadan, di ambang barat dataran tinggi Iran, setelah pengepungan panjang. Kota itu adalah persinggahan besar terakhir di jalan Isfahan, titik paling timur yang dapat dicapai pasukan Utsmaniyah sejak Ekspedisi Irakeyn. Mukavelenâme Istanbul yang ditandatangani dengan Rusia pada tahun yang sama menuangkan pembagian Iran yang bubar antara Utsmaniyah dan Rusia ke atas kertas.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Penaklukan kembali Revan", "88acabef"], "d": ["Setelah pengepungan sengit sembilan puluh hari, Revan, benteng kunci lembah Aras, kembali masuk ke pemerintahan Utsmaniyah. Benteng yang dibangun pada 1583 dan hilang pada 1604 itu kali ini diperkuat dengan garnisun yang lebih kuat. Panjangnya pengepungan menunjukkan bahwa pasukan Utsmaniyah tidak lagi maju dengan mudah. Nahiye Karpi (Üçkilise), Şerür, Makû, dan Şüregel juga diikat ke eyalet Revan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Direbutnya Tabriz — direbutnya Azerbaijan", "e502a4f7"], "d": ["Tabriz, yang dikepung kembali setelah percobaan gagal satu tahun sebelumnya, menyerah kepada pasukan Utsmaniyah setelah pertempuran sengit yang berlangsung jalan demi jalan. Merend, Meraga, dan Sovukbulak (Mahabad) yang terikat pada eyalet Tabriz juga masuk ke pemerintahan Utsmaniyah. Pada tahun yang sama Lori, Ganja, Ardabil, dan Khurramabad juga direbut dan wilayah-wilayah yang menjadi bagian Utsmaniyah menurut Mukāsemenâme Istanbul diduduki secara faktual. Luas yang dicapai di timur ini adalah perbatasan terjauh sejak masa Perjanjian Ferhad Paşa; namun mempertahankannya menimbulkan beban berat bagi pasukan dan kas.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Penaklukan Ganja — berakhirnya ekspedisi Kaukasus", "875bca7a"], "d": ["Ganja, sasaran terakhir operasi Kaukasus, diterima penyerahannya sebagai pusat Karabakh antara Kura dan Aras. Dengan lengkapnya garis Şirvan, Revan, Nakhchivan, dan Ganja, Negara Utsmaniyah mencapai luas 1590 di Kaukasus. Namun perolehan ini berumur pendek: bangkitnya Nadir Syah dalam sepuluh tahun akan merebut kembali seluruh wilayah itu.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Perjanjian Hamadan — bergabungnya Iran Barat ke Utsmaniyah", "94a29dc3"], "d": ["Dengan perjanjian yang ditandatangani dengan penguasa Afghan Eşref Şah, perang empat tahun berakhir dan wilayah Iran Barat yang diduduki Negara Utsmaniyah diakui secara hukum. Eşref Şah sebagai imbalan mengakui kekhalifahan sultan Utsmaniyah dan berjanji agar khutbah di Iran dibacakan atas nama sultan. Kemenangan diplomatik ini berumur pendek; serangan balik yang dimulai Nadir Syah pada 1730 akan menghapus perolehan perjanjian dalam beberapa tahun.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Paşa merebut Urmia", "eac7f64d"], "d": ["Dalam ekspedisi Iran, Hekimoğlu Ali Paşa merebut pertama Urmia (Rûmiye), kemudian Tabriz, yang dikosongkan untuk Utsmaniyah, pada 15 November 1731. TDV tidak memberi hari direbutnya Urmia; hanya tahun dan bahwa itu mendahului Tabriz yang diketahui.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Perjanjian Ahmed Paşa — dikembalikannya sebagian besar Iran Barat", "590d839f"], "d": ["Atas kemenangan Nadir Syah di Malayir dan serangan-serangan Iran yang beruntun, gubernur Baghdad Ahmed Paşa menandatangani teks perdamaian tanpa berkonsultasi dengan pusat. Menurut perjanjian, Sungai Aras diterima sebagai perbatasan; kota-kota Iran Barat seperti Hamadan, Kermanshah, Erdelan, Ardabil, dan Tabriz dikembalikan ke Iran, Ganja dan Tiflis tetap di Utsmaniyah. Teks yang disambut dengan reaksi di Istanbul ini juga dianggap tidak memadai oleh Nadir Syah dan perang berkobar kembali sebelum tahun 1732 berakhir. Atlas juga menganggap Kotur, yang mengikuti rantai Hoy, beralih dari Utsmaniyah ke Safawi pada hari ini (TDV hoy; hari khusus Kotur tidak ada dalam sumber — pendekatan yang dinyatakan).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Hilangnya Oran (Vahran) kembali ke Spanyol", "20485027"], "d": ["Armada pendarat besar yang dikirim raja Spanyol Felipe V tiba di depan Oran di bawah komando Conde de Montemar dan, dengan mengalahkan pasukan Ocak Aljir, merebut kembali kota. Pelabuhan yang ditaklukkan dua puluh empat tahun sebelumnya itu akan tetap di tangan garnisun Spanyol lagi selama enam puluh tahun. Kehilangan yang menunjukkan batas kekuatan ocak-ocak Garp di Mediterania Barat ini baru dapat ditebus dengan penaklukan pasti Oran pada 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reformasi Ocak Humbaracı ala Eropa dan pendirian Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Paşa keturunan Prancis, yang masuk dinas Utsmaniyah, dengan dukungan sadrazam Hekimoğlu Ali Paşa menjadikan ocak humbaracı sebuah unit bergaji dan tertata ala Eropa. Tiga ratus prajurit yang direkrut dari Bosnia diberi latihan teratur berdasarkan berhitung dan geometri; peraturan baru untuk organisasi, perlengkapan, dan pensiun disiapkan, dan dengan teknik mutakhir seratus meriam granat dan lima puluh ribu granat dibuat. Humbarahâne, tempat geometri diajarkan, dianggap inti pertama pendidikan rekayasa militer modern di Utsmaniyah.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Wafatnya Ahmed III", "455f7fba"], "d": ["Ahmed III, yang diturunkan dari takhta pada 1730 dengan pemberontakan Patrona Halil, menghabiskan enam tahun terakhir hidupnya di apartemen Istana Topkapı yang dialokasikan bagi sultan yang diturunkan dan wafat pada usia enam puluh tiga tahun. Ia dimakamkan di Bahçekapı di makam neneknya Turhan Sultan di samping Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Perjanjian Istanbul — penyerahan Kaukasus Selatan kepada Iran", "8c205aab"], "d": ["Perang Iran kedua yang berlangsung empat tahun berakhir dengan perjanjian yang ditandatangani setelah kekalahan Arpaçay dan hilangnya Ganja serta Tiflis. Negara Utsmaniyah mundur dari seluruh Kaukasus Selatan dan Iran Barat yang direbutnya sejak 1723 dan perbatasan kembali ke garis Qasr-e Shirin 1639. Dari ekspedisi timur tiga belas tahun yang tersisa adalah beban keuangan berat dan kas yang terkuras; sebaliknya, tertutupnya front timur untuk perang baru dengan Rusia adalah keuntungan vital.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Jatuhnya Benteng Özi (Ochakov) ke Rusia", "f93e61f3"], "d": ["Pasukan Rusia di bawah komando Marsekal Münnich mengepung Benteng Özi di muara Dnieper; dengan meledaknya gudang amunisi pertahanan runtuh dan benteng jatuh dengan korban jiwa besar. Lepasnya Özi, yang dianggap kunci pesisir barat laut Laut Hitam, membuka jalan ke Krimea bagi Rusia dan menimbulkan kepanikan besar di Istanbul. Benteng akan dikosongkan oleh Rusia pada tahun berikutnya karena wabah dan kesulitan pasokan dan kembali ke Utsmaniyah.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Kemenangan Banja Luka — pembebasan Bosnia", "f603865a"], "d": ["Ketika pasukan Austria memasuki Bosnia dan mengepung Banja Luka, gubernur Bosnia Hekimoğlu Ali Paşa datang menolong dengan pasukan yang dihimpunnya dari rakyat setempat dan menimbulkan kekalahan berat atas musuh yang unggul jumlah. Kemenangan ini menggagalkan rencana Austria menduduki Bosnia pada langkah pertama dan utara eyalet direbut kembali sepenuhnya. Banja Luka menjadi salah satu titik balik yang memperbaiki semangat pasukan Utsmaniyah yang terus mundur menghadapi Austria setelah 1683.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Kemenangan Hisarcık (Grocka) — terbukanya jalan Beograd", "2101cdff"], "d": ["Pasukan Austria yang maju untuk melindungi Beograd disergap di selat sempit di tepi Danube dan menderita kerugian berat dalam pertempuran sehari penuh. Ketika pasukan Marsekal Wallis mundur ke Beograd secara tidak teratur, pasukan Utsmaniyah tiba di depan benteng dan memulai pengepungan. Hisarcık adalah kemenangan terbuka paling pasti yang diraih melawan Austria sejak Karlowitz dan secara langsung memungkinkan direbutnya kembali Beograd.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Perjanjian Niš — perdamaian dengan Rusia, netralisasi Azak, dan dihentikannya serbuan Krimea", "674f974e"], "d": ["Rusia, yang tinggal sendirian ketika Austria menerima perdamaian di Beograd, terpaksa mengakhiri perang dengan mediasi duta Prancis Villeneuve. Benteng-benteng Azak dihancurkan dan wilayah itu dinyatakan tanah netral antara kedua negara; Rusia menerima syarat tidak memiliki kapal perang dan dagang di Laut Hitam. Dengan demikian sasaran Rusia berlayar ke laut tertunda satu generasi lagi dan Negara Utsmaniyah untuk terakhir kalinya pada abad ke-18 bangkit dari meja dengan untung.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi kembali dari pendudukan Rusia: diserahkan setelah benteng dihancurkan dengan perdamaian 1739", "7ecc2bef"], "d": ["Rusia merebut Özi pada 11 Juli 1737. Sesuai perdamaian dengan Rusia pada 1739, setelah benteng-benteng dihancurkan, ia diserahkan kembali kepada Utsmaniyah; Utsmaniyah menguasai Özi hingga 1788, sebelum Perjanjian Iași.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Pertahanan Mosul — Nadir Syah dipukul mundur", "c03ffbc1"], "d": ["Nadir Syah, yang merebut Kirkuk dan Erbil dan tiba di depan Mosul, membombardir kota selama empat puluh hari dan melancarkan serangan umum beruntun. Pertahanan yang dijalankan gubernur Hüseyin Paşa el-Celîlî dengan mempersenjatai juga rakyat kota memaksa pasukan Iran mencabut pengepungan dengan kerugian berat. Bertahannya Mosul mencegah lepasnya seluruh Irak dan memperkuat pengaruh keluarga Celîlî di kota selama satu abad.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Aliansi Dir'iyah — pendirian Emirat Saudi pertama di Najd", "188751bf"], "d": ["Emir Muhammad b. Saud, yang menaungi ulama Muhammad b. Abdul Wahhab yang diusir dari Uyaynah di Dir'iyah, membentuk aliansi dengannya yang menempatkan otoritas politik di pelayanan dakwah agama. Kesepakatan ini memulai sejarah baru bagi keluarga Saud dan menyatukan emirat-emirat oasis Najd yang tercerai-berai di sekitar satu gerakan. Kekuatan ini, yang dalam setengah abad akan menjangkau Karbala, Makkah, dan Madinah, akan memaksa Negara Utsmaniyah mempertahankan kekuasaannya di Hijaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Perjanjian Kerden — berakhirnya perang Utsmaniyah-Iran", "1d3a919e"], "d": ["Dengan perjanjian yang ditandatangani setelah perang terakhir selama empat tahun, perbatasan Qasr-e Shirin 1639 diperbarui persis; kedua pihak tidak memperoleh perolehan wilayah. Tuntutan gigih Nadir Syah agar Ja'fari diakui sebagai mazhab kelima tidak dipenuhi, sebagai gantinya diputuskan jamaah haji Iran dapat berhaji dengan bebas dan pertukaran utusan timbal balik. Perang Utsmaniyah-Iran yang melebihi dua abad dengan demikian secara de facto tertutup; perbatasan ini sebagian besar terpelihara hingga hari ini.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Wafatnya Mahmud I dan naik takhtanya Osman III", "30203700"], "d": ["Mahmud I, yang dalam kesultanan dua puluh empat tahun merebut kembali wilayah yang hilang dengan Perjanjian Beograd dan mendukung reformasi Ocak Humbaracı, wafat ketika kembali dari selamlık Jumat. Saudaranya Osman III, yang menjalani kehidupan kafes hingga usia lima puluh delapan tahun, naik menggantikannya. Kesultanan yang singkat dan gelisah dimulai; pada masa Osman III, yang mengganti enam sadrazam dalam tiga tahun, kemandekan nyata menguasai urusan negara.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Wafatnya Osman III dan naik takhtanya Mustafa III", "3ac10f85"], "d": ["Dengan wafatnya Osman III setelah kesultanan tiga tahun, Mustafa III, yang terbuka pada gagasan reformasi dan menunjukkan minat dekat pada urusan negara, naik takhta. Sultan baru berusaha memperbaiki keuangan dan memperbarui pasukan dengan bertumpu pada pengalaman sadrazam Koca Râgıb Paşa; artileri kilat Baron de Tott dibentuk pada masa ini. Namun perang Rusia yang dimasuki pada 1768 akan membayangi semua perolehan kesultanan tujuh belas tahun.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Pernyataan perang kepada Rusia — peristiwa Balta dan dimulainya perang 1768-1774", "9c6aabe0"], "d": ["Ketika pasukan Rusia dan Kosak yang mengejar Konfederasi Bar di Polandia menyerbu dan membakar kota Balta di perbatasan Utsmaniyah, Divan mengambil keputusan perang dan duta Rusia dipenjarakan di Yedikule. Perang yang dimasuki tanpa persiapan militer serius dan dinyatakan enam bulan sebelumnya itu berjalan buruk sejak awal. Perjuangan enam tahun ini akan berubah menjadi salah satu rangkaian kekalahan terberat dalam sejarah Utsmaniyah dengan serbuan Çeşme, kekalahan Kartal, dan pendudukan Krimea.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Hilangnya Benteng Khotyn ke Rusia", "66d43ea4"], "d": ["Ketika dua percobaan pasukan Rusia di bawah komando Pangeran Golitsyn dipukul mundur, dengan kekalahan yang dialami sadrazam antara Kamieniec dan Khotyn, pasukan mundur dan para penjaga mengosongkan benteng. Lepasnya benteng Utsmaniyah terkuat di utara Danube tanpa perlawanan membuka gerbang Wallachia dan Moldavia bagi Rusia. Kedua kepangeranan diduduki pada tahun yang sama; Khotyn baru dapat direbut kembali dengan Perjanjian Küçük Kaynarca pada 1774.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Kekalahan Dataran Kartal (Kagul)", "6f408eaf"], "d": ["Tiga minggu setelah armada dibakar di Çeşme, pasukan utama Utsmaniyah di tepi Danube bubar di dataran Kartal menghadapi unit-unit Marsekal Rumyantsev yang jauh lebih kecil tetapi berdisiplin. Perkemahan, perbekalan, dan ratusan meriam jatuh ke tangan musuh; unit-unit yang melarikan diri menderita kerugian besar saat menyeberangi Danube. Musnahnya baik armada maupun pasukan darat dalam musim panas yang sama menyebabkan jatuhnya Kili, Akkirman, İsmail, dan Bender satu demi satu dan pendudukan Krimea.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Pendudukan Rusia atas Semenanjung Krimea", "217837b0"], "d": ["Pasukan Rusia, yang setahun sebelumnya merebut Bucak, menyerbu seluruh semenanjung Krimea dengan menembus Or Kapı di bawah komando Pangeran Dolgorukov. Khan diturunkan dari takhta dan Sâhib Giray yang pro-Rusia ditempatkan, mengambil langkah pertama ke arah lepasnya khanat dari Utsmaniyah. Lepasnya Krimea, perisai utara Utsmaniyah selama tiga abad, adalah awal proses kemerdekaan pada 1774 dan aneksasi langsung pada 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Wafatnya Mustafa III dan naik takhtanya Abdülhamid I", "42cba8e2"], "d": ["Menggantikan Mustafa III yang wafat pada saat paling genting perang Rusia, saudaranya Abdülhamid I, yang menghabiskan empat puluh tiga tahun di kafes istana, naik takhta pada usia empat puluh sembilan. Sultan baru, yang mewarisi salah satu masa tersulit negara, terpaksa menghadapi syarat-syarat berat Perjanjian Küçük Kaynarca yang akan ditandatangani pada tahun yang sama. Kesultanannya selama lima belas tahun akan dilalui dengan hilangnya Krimea dan perang Rusia baru, dan akan berakhir pada 1789 dengan stroke yang dideritanya ketika membaca kabar jatuhnya Özi.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Kekalahan Kozluca — kekalahan menuju Küçük Kaynarca", "8e0542f9"], "d": ["Pasukan Utsmaniyah yang berkumpul di depan Şumnu dikalahkan oleh kolom-kolom gabungan Suvorov dan Kamensky di Kozluca dan sebagian besar pasukan bubar. Dengan kekalahan ini tidak ada lagi kekuatan untuk melawan di Balkan; pasukan depan Rusia mengepung Şumnu dan markas sadrazam terancam. Duduk di meja di Küçük Kaynarca tidak sampai satu bulan kemudian dan diterimanya syarat-syarat yang luar biasa berat adalah akibat langsung kekalahan ini.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Penyerahan Bukovina (Moldavia Utara) kepada Austria", "190f9caa"], "d": ["Austria, yang memanfaatkan kelemahan yang ditimbulkan Küçük Kaynarca, menuntut wilayah Bukovina yang menghubungkan Moldavia dan Transilvania, dan memperoleh tanah ini tanpa masuk perang, dengan ancaman dan suap. Hilangnya wilayah subur dan strategis di barat daya Khotyn ini secara de facto membagi voivodat Moldavia menjadi dua. Penyerahan yang terjadi tanpa satu peluru pun ditembakkan ini dianggap salah satu indikator paling jelas bahwa Negara Utsmaniyah tidak lagi memiliki daya cegah. Pada 1775, dengan penyerahan Bukovina, Suceava dan Czernowitz beralih ke Austria (hari tidak terkonfirmasi).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Pendudukan Basra oleh Iran", "0161e709"], "d": ["Sâdık Han, saudara penguasa Zand Kerim Han, merebut Basra setelah pengepungan satu tahun dan Negara Utsmaniyah kehilangan pelabuhan terpentingnya di Teluk Basra. Pendudukan itu secara langsung mengguncang jalur dagang India, pendapatan kurma dan mutiara, dan pertahanan selatan Irak. Kota baru dapat direbut kembali pada 1779 selama perebutan takhta yang pecah di Iran dengan wafatnya Kerim Han.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Tenkihname Aynalıkavak — kesepakatan sementara atas Krimea", "9b3b0468"], "d": ["Kedua negara, yang nyaris berperang karena siapa yang akan menjadi kepala Khanat Krimea, menandatangani teks penjelasan di Istana Aynalıkavak dengan mediasi Prancis. Rusia menerima menarik pasukannya dari Krimea, sedangkan Negara Utsmaniyah menerima mengakui kekhanan Şâhin Giray yang pro-Rusia; hak kekhalifahan agama sultan atas Krimea ditegaskan. Keseimbangan rapuh yang akan berlangsung empat tahun ini runtuh sepenuhnya dengan aneksasi langsung semenanjung oleh Rusia pada 1783.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Pembangunan Benteng Anapa — garis pertahanan Kaukasus", "be92a80f"], "d": ["Ketika Krimea lepas dengan Küçük Kaynarca, pembangunan benteng baru di muara Sungai Kuban dilakukan untuk mempertahankan pengaruh Utsmaniyah di Kaukasus. Anapa, yang didirikan di atas sisa koloni Genoa, dengan pasarnya, pemandiannya, dan lebih dari dua ratus lima puluh tokonya dalam waktu singkat menjadi kota yang menjamin hubungan dengan suku-suku Cerkes. Benteng itu tetap menjadi pos terdepan Utsmaniyah selama empat puluh delapan tahun melawan turunnya Rusia ke Kaukasus.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Pemecatan dan eksekusi Sadrazam Halil Hamîd Paşa", "c44001ca"], "d": ["Sadrazam reformis Halil Hamîd Paşa, yang kepuasan Abdülhamid I atas pelayanannya ditunjukkan pada berbagai kesempatan, tiba-tiba dipecat menjelang pagi 31 Maret 1785 dan diasingkan ke Gelibolu dan seluruh hartanya disita. Mula-mula kepadanya diberikan eyalet Habesh, sancak Jeddah, dan kedudukan şeyhülharem Makkah; ketika ia melewatkan April 1785 di Bozcaada dengan persiapan perjalanan, ia juga dipecat dari jabatan gubernur ini dan dibunuh dengan firman eksekusi yang keluar oleh Karakethüdâzâde Ali, salah satu anak buah Cezayirli Gazi Hasan Paşa. Kepalanya yang terpenggal dikirim ke Istanbul dan dipamerkan di Ortakapı. Menurut TDV, kejatuhan mendadak ini meski ditafsirkan dengan tuduhan persekongkolan menurunkan sultan dari takhta dan menggantinya dengan Şehzade Selim, sebab sebenarnya mungkin adalah kemarahan atas diamnya terhadap aneksasi Krimea, permusuhan lingkungan yang dirugikan reformasinya, dan oposisi Gazi Hasan Paşa.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Pernyataan perang kepada Rusia — Perang Utsmaniyah-Rusia 1787-1792 dimulai", "3bfb870c"], "d": ["Atas perjalanan megah Katarina II ke Krimea dan penempatan Georgia di bawah perlindungannya, Divan mengambil keputusan perang dengan tujuan membalikkan aneksasi dan duta Rusia kembali dikurung di Yedikule. Namun pasukan belum siap, kas kosong, dan pencarian sekutu tidak membuahkan hasil. Perang lima tahun itu akan berujung pada jatuhnya Özi dengan pembantaian, hilangnya İsmail, dan syarat-syarat berat Perjanjian Iași.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Masuknya Austria ke perang — perjuangan dua front", "ae912290"], "d": ["Sesuai aliansi rahasia yang dibuatnya dengan Rusia pada 1781, Kaisar Austria Josef II menyatakan perang kepada Negara Utsmaniyah dan bergerak ke arah Beograd dan Bosnia. Pasukan Utsmaniyah tiba-tiba terpaksa berperang di dua front sekaligus, Rusia di utara dan Austria di barat. Meski kemenangan atas Austria di Lazarethane, Mehadia, dan Şebeş, front barat juga akan runtuh dengan hilangnya Beograd pada 1789.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Aliansi Utsmaniyah-Prusia", "03b88e51"], "d": ["Selim III, yang mencari sekutu di Eropa segera setelah naik takhta, menandatangani perjanjian aliansi dengan Prusia yang menetapkan bantuan timbal balik; Prusia berjanji menyatakan perang kepada Rusia dan Austria, dan Negara Utsmaniyah berjanji tidak berdamai sebelum Krimea direbut kembali. Ini adalah teks aliansi timbal balik sungguhan pertama yang ditandatangani dengan sebuah negara Eropa dalam sejarah Utsmaniyah dan menunjukkan ditinggalkannya pemahaman klasik 'tidak ada aliansi dengan kaum kafir'. Prusia tidak masuk perang, tetapi dengan memaksa Austria berdamai membuka jalan bagi Perjanjian Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Jatuhnya Benteng İsmail dan pembantaiannya", "6a296b0c"], "d": ["Benteng İsmail, yang dianggap benteng terkuat di delta Danube, direbut dalam satu hari oleh serangan umum berdarah yang dilancarkan Jenderal Suvorov; garnisun dan penduduk kota sebagian besar dibantai dengan pedang. Pembantaian ini, yang menimbulkan gaung luas di Eropa, menimbulkan syok mendalam dalam opini publik Utsmaniyah dan mematahkan tulang punggung garis pertahanan Danube. Benteng akan direbut kembali setahun kemudian dengan Perjanjian Iași, tetapi nasib perang sudah ditentukan.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Perjanjian Sistova — tertutupnya front Austria", "58741f1d"], "d": ["Berkat tekanan Prusia dan sibuknya Austria di barat oleh Revolusi Prancis, kedua negara mencapai perdamaian dengan perbatasan sebelum perang sebagai dasar. Austria mengembalikan semua tempat yang didudukinya, termasuk Beograd; Negara Utsmaniyah hanya menerima koreksi kecil di perbatasan Kroasia. Tertutupnya front barat dengan syarat-syarat ini memungkinkan Negara Utsmaniyah memusatkan seluruh kekuatannya melawan Rusia dan membatasi kerugian dalam Perjanjian Iași. Dengan koreksi di perbatasan Kroasia ini Cetin (Cetingrad) dan Drežnik Grad beralih dari Utsmaniyah ke Habsburg (TDV zistovi-antlasmasi; Korić 2016, n. 118, pasal 4). Orsova (Eski Orsova) adalah satu-satunya tempat yang tidak dikembalikan (Bánlaky 0019/1796); atlas mencatat peralihan hukumnya pada hari ini (pendudukan faktual 16 April 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Perjanjian Iași — hilangnya Krimea secara pasti dan perbatasan Dniester", "a56fd194"], "d": ["Dengan perjanjian yang ditandatangani pada akhir perang lima tahun, Sungai Turla (Dniester) diterima sebagai perbatasan; tepi kiri sungai tetap pada Rusia dan tepi kanan pada Utsmaniyah, dan Özi serta sekitarnya lepas secara pasti. Negara Utsmaniyah sepenuhnya melepaskan harapan merebut kembali Krimea dan mengakui aneksasi 1783 secara hukum; Wallachia dan Moldavia dikembalikan dengan pembebasan pajak dua tahun. Dengan diterimanya kewajiban ganti rugi perang dua belas juta kuruş, utara Laut Hitam diserahkan secara permanen kepada Rusia. Tempat-tempat lain yang bergabung pada tanggal yang sama: İsmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Pengosongan Oran (Vehrân) oleh Spanyol dan penyerahannya kepada Aljir", "9f95cee6"], "d": ["Ketika benteng dan kota sebagian besar hancur dalam gempa 1790, Spanyol, yang tidak lagi dapat memikul garnisun mahal yang dipertahankannya selama tiga abad, bersepakat dengan ocak Aljir dan menyerahkan Oran dan Mers el-Kébir tanpa perang. Dengan demikian pos Eropa terakhir di pesisir Afrika Utara juga dilikuidasi. Aljir Utsmaniyah tetap menguasai seluruh pesisir selama tiga puluh delapan tahun hingga pendudukan Prancis.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Kekuasaan faktual Pazvandoğlu Osman di Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, yang memberontak melawan penataan Nizâm-ı Cedîd, mengusir gubernur Vidin, merebut kota, dan memperkuatnya dengan parit-parit dalam di sepanjang Danube. Pada puncak kekuatannya pada 1797, dengan menghimpun pasukan hampir delapan puluh ribu, ia menguasai Nikopolis, Sistova, Rusçuk, Sofia, dan Niš; ia memperkenalkan dirinya bukan sebagai pemberontak melainkan reformis. Pengepungan Bâbıâli yang berlangsung berbulan-bulan pada 1798-1799 tidak membuahkan hasil dan ia memerintah secara semi-merdeka di Bulgaria Utara hingga wafatnya pada 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Dibukanya Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Sekolah teknik darat dibuka di Hasköy untuk mendidik perwira artileri, zeni, dan kartografi bagi pasukan Nizâm-ı Cedîd; ia adalah padanan di pasukan darat bagi Sekolah Teknik Angkatan Laut yang didirikan pada 1773. Dalam program diajarkan aljabar, geometri, mekanika, zeni, dan balistik, dan buku-buku matematika dan artileri dari bahasa-bahasa Eropa diterjemahkan. Sekolah ini, yang dianggap akar pendidikan teknik modern di Turki, dianggap awal Universitas Teknik Istanbul saat ini.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Pernyataan perang kepada Prancis dan aliansi dengan Rusia-Inggris", "80e95bd7"], "d": ["Atas pendudukan Napoleon di Mesir, Negara Utsmaniyah menyatakan perang kepada Prancis dengan memutus persahabatan tradisional Prancis selama dua setengah abad. Dalam proses yang sama untuk pertama kalinya dalam sejarahnya ia beraliansi dengan Rusia dan mengizinkan armada Rusia melewati Selat ke Mediterania; kemudian aliansi dengan Inggris juga ditandatangani. Berkat aliansi ini pulau-pulau Ionia direbut dari Prancis, tetapi dibukanya Selat bagi armada asing menciptakan preseden yang kelak berharga mahal.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Direbutnya Preveze dari Prancis — Pertempuran Nikopolis", "d8e5e892"], "d": ["Ketika Republik Venesia runtuh pada 1797, pulau-pulau Ionia dan Preveze, Parga, serta Vonitsa di daratan jatuh ke tangan Prancis. Gubernur Yanya Tepedelenli Ali Paşa, dengan memanfaatkan perang yang dibuka atas pendudukan Mesir oleh Prancis, berbaris ke Preveze dan menimbulkan kekalahan berat atas garnisun Prancis di reruntuhan Nikopolis di luar kota. Dengan demikian pelabuhan yang ditinggalkan kepada Venesia di Passarowitz ini masuk ke pemerintahan Utsmaniyah delapan puluh tahun kemudian. Butrint (Butrinto) jatuh pada 25 Oktober ketika garnisun Prancis meledakkan benteng dan mundur ke Korfu (Curlin, Preveza B, 2010; hari atlas diambil dari Preveze) dan masuk ke pemerintahan Utsmaniyah.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Pertahanan Akka — Napoleon dipukul mundur", "56b5c45b"], "d": ["Napoleon, yang maju dari Mesir ke Suriah, mengepung Akka dan melancarkan serangan beruntun selama dua bulan; kota dipertahankan oleh Cezzâr Ahmed Paşa dengan dukungan armada Inggris dan pasukan Nizâm-ı Cedîd yang dikirim dari Istanbul. Napoleon, yang terpaksa mencabut pengepungan dan mundur ke Mesir, mengubur mimpi menjangkau ke timur di depan tembok-tembok ini. Kabar itu disambut dengan sukacita besar di Istanbul dan dianggap bukti bahwa tentara terlatih yang baru dibentuk telah lulus ujian serius pertamanya.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Serbuan Wahhabi ke Karbala", "522341ed"], "d": ["Pasukan Wahhabi yang berangkat dari Najd memasuki Karbala, menjarah kota, merusak makam Imam Husain, dan membunuh lebih dari tiga ribu orang. Para gubernur kölemen Negara Utsmaniyah di Irak tidak dapat mencegah serbuan; peristiwa itu menimbulkan reaksi besar baik di Iran maupun di Istanbul. Serangan ini adalah pernyataan bahwa gerakan Saudi tidak lagi sekadar emirat oasis, tetapi telah menjadi kekuatan regional yang mengancam kota-kota suci Utsmaniyah.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kakheti (Georgia Timur) dianeksasi ke Rusia", "3b650c5e"], "d": ["Kerajaan Kartli-Kakheti, yang menerima perlindungan Rusia pada 1783 dan mengalami ekspedisi menghancurkan Iran pada 1795, dibubarkan; dengan perintah tertanggal 12 September 1801 dinyatakan sebagai provinsi Rusia dan sistem pemerintahan Rusia mulai diterapkan. Georgia sejak tanggal ini kehilangan kemerdekaannya; dalam beberapa tahun Megrelia (1803), Imeretia dan Guria (1804) juga masuk ke kekuasaan Rusia dan Rusia mencapai perbatasan Kaukasus Utsmaniyah. Dengan peristiwa ini Gori, Dusheti (Kartli), dan Telavi (Kakheti) beralih ke Rusia.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Pengosongan Mesir dari Prancis", "00cfdc8c"], "d": ["Sebagai hasil operasi gabungan pasukan Utsmaniyah dan Inggris dari darat dan laut, pertama Kairo, kemudian Iskandariyah diterima penyerahannya dan pasukan Prancis dikirim pulang dengan kapal. Ketika pendudukan tiga tahun berakhir, Mesir kembali ke pemerintahan Utsmaniyah di atas kertas, tetapi perebutan kekuasaan antara bey-bey kölemen dan pasukan Albania menyeret negeri ke dalam kekacauan. Kekosongan ini dalam beberapa tahun akan menyiapkan landasan bangkitnya Kavalalı Mehmed Ali.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Perjanjian Paris — dibangunnya kembali perdamaian dengan Prancis", "1b76991f"], "d": ["Dengan perjanjian yang ditandatangani setelah pengosongan Mesir, keadaan perang antara Negara Utsmaniyah dan Prancis berakhir secara resmi dan kapitulasi lama diperbarui. Kapal dagang Prancis diizinkan memasuki Laut Hitam; sebagai imbalannya Prancis mengakui keutuhan wilayah Utsmaniyah. Terbangunnya perdamaian memberi kebijakan luar negeri Selim III, yang terjepit di samping Rusia dan Inggris, ruang manuver kembali.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Wahhabi merebut Tâif", "7b791359"], "d": ["Pasukan Wahhabi di bawah komando Saud b. Abdulaziz, dalam gerakan pertama menuju Hijaz, mengepung dan menjarah Tâif; kota jatuh sebagai gerbang pertama yang membuka ke tanah suci. Bagi sultan Utsmaniyah yang menyandang gelar pelindung Haramain, ini adalah pukulan yang secara langsung mengguncang legitimasi kesultanan. Dua setengah bulan kemudian pasukan yang sama akan berbaris ke Makkah.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Wahhabi merebut Makkah untuk pertama kali", "21157c05"], "d": ["Dua setengah bulan setelah jatuhnya Tâif, pasukan Wahhabi memasuki Makkah, merobohkan makam-makam, dan mendirikan tatanan menurut pemahaman mereka; Şerif Gālib terpaksa mundur ke Jeddah. Tertutupnya jalur haji bergema di seluruh dunia Islam dan memaksa Istanbul meminta bantuan militer dari gubernur Mesir Mehmed Ali. Kekuasaan pertama ini hanya akan berlangsung tiga bulan.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Şerif Gālib merebut kembali Makkah", "83d08dff"], "d": ["Şerif Gālib, yang mundur ke Jeddah, mengepung Makkah dengan pasukan yang dihimpunnya dan setelah pengepungan dua puluh lima hari merebut kembali kota dari Wahhabi; khutbah kembali dibacakan atas nama Utsmaniyah. Kekuasaan kedua ini juga tidak akan permanen; pasukan Saud akan merebut kota kembali pada 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Dimulainya Pemberontakan Serbia Pertama", "0f6e8767"], "d": ["Ketika para dayı janisari pemberontak yang menguasai pemerintahan di Beograd membantai tokoh-tokoh Serbia secara massal, perlawanan bersenjata dimulai di bawah pimpinan Karađorđe. Gerakan yang pada mulanya tetap setia kepada sultan dan hanya dijalankan melawan para dayı itu dengan cepat berubah menjadi pemberontakan nasional yang menuntut otonomi dan kemerdekaan. Pasukan Serbia merebut Beograd pada 1806; pemberontakan ini menjadi mata rantai pertama gerakan kemerdekaan nasionalis di Balkan.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Pendudukan Madinah oleh Wahhabi", "84e310d7"], "d": ["Setelah Makkah, Madinah juga jatuh ke tangan pasukan Wahhabi; perbendaharaan Raudhah Mutahharah dibagi-bagikan dan makam-makam berkubah di kota dirobohkan. Dengan demikian kedua kota suci sekaligus keluar dari kendali Utsmaniyah dan kafilah haji dari Damaskus dan Mesir tidak dapat berangkat selama bertahun-tahun. Madinah baru dapat direbut kembali tujuh tahun kemudian, pada 1812, oleh pasukan Mesir di bawah komando Tosun Paşa, putra Mehmed Ali Paşa.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Dimulainya perang dengan Rusia (Perang Utsmaniyah-Rusia 1806-1812) dan ditutupnya Selat", "ea170804"], "d": ["Setelah Selim III, yang mendekat kepada Prancis setelah kemenangan Austerlitz Napoleon, memecat voivode Wallachia dan Moldavia meski ada tekanan Rusia, pasukan Rusia menduduki kedua kepangeranan dan perang dimulai. Negara Utsmaniyah menutup Selat bagi armada Rusia; sebagai balasan Inggris juga berpihak kepada Rusia dan mengirim armada ke Istanbul. Perang enam tahun ini, yang terjalin dengan Pemberontakan Kabakçı dan diturunkannya Selim III dari takhta, akan berakhir dengan hilangnya Bessarabia dalam Perjanjian Bukares 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Armada Inggris tiba di depan Istanbul (operasi Duckworth)", "195bb58f"], "d": ["Inggris, yang ingin memaksa Negara Utsmaniyah memutus ikatannya dengan Prancis, melewati Çanakkale dengan armada di bawah komando Laksamana Duckworth dan berlabuh di depan Istanbul. Dengan arahan duta Prancis Sébastiani juga, rakyat Istanbul dimobilisasi, baterai pantai diperkuat dalam beberapa hari, dan armada terpaksa mundur tanpa sempat membombardir kota; dalam perjalanan pulang ia menderita kerugian berat di Çanakkale. Terancamnya ibu kota oleh armada asing sedekat ini untuk pertama kalinya menempatkan persoalan Selat di pusat diplomasi Eropa.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Pembunuhan Mustafa IV dengan dicekik", "eeb75c20"], "d": ["Ketika Alemdar Mustafa Paşa diserbu dan wafat dan para pemberontak ingin berbaris ke istana, Mustafa IV yang diturunkan dari takhta dicekik hingga tewas atas perintah saudaranya Mahmud II. Jenazahnya dimakamkan di Bahçekapı di makam ayahnya Abdülhamid I; rumor bahwa peti mati kosong menyebar di antara para pemberontak.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Perjanjian Kal'a-i Sultâniyye — perdamaian dengan Inggris dan kaidah Selat", "fe282117"], "d": ["Dengan perjanjian yang ditandatangani dengan Inggris setelah kegagalan operasi Duckworth, perang antara kedua negara berakhir dan imtiyaz lama pedagang Inggris dikembalikan. Ketentuan dalam teks yang disebut 'kaidah lama' mencatat bahwa pada masa damai tidak ada kapal perang asing yang boleh melewati Selat. Prinsip ini menjadi landasan hukum semua pengaturan internasional yang akan membentuk rezim Selat sepanjang abad ke-19.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Kekalahan Slobozia — terkepungnya pasukan Danube", "54b60fd1"], "d": ["Sebagian besar pasukan Utsmaniyah yang menyeberangi Danube di depan Rusçuk terjepit di Slobozia dan dibiarkan kelaparan oleh manuver pengepungan Kutuzov dari tepi seberang sungai. Ribuan prajurit terpaksa menyerah; kekuatan di tangan sadrazam secara de facto lenyap dan Bâbıâli terpaksa meminta gencatan senjata sebulan kemudian. Kekalahan ini adalah penyebab langsung diterimanya penyerahan Bessarabia dalam Perjanjian Bukares 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Direbutnya kembali Beograd dan penumpasan Pemberontakan Serbia Pertama", "06f56f52"], "d": ["Para pemberontak Serbia, yang kehilangan dukungan Rusia dengan Perjanjian Bukares, tidak dapat bertahan menghadapi operasi bersama pasukan dari Bosnia dan Rumelia; Hurşid Ahmed Paşa memasuki Beograd dan pemberontakan sembilan tahun ditumpas sepenuhnya. Karađorđe melarikan diri ke Austria dan sancak Semendire kembali diikat ke pemerintahan Utsmaniyah langsung. Namun tindakan keras yang diterapkan akan memicu pemberontakan kedua yang permanen dua tahun kemudian di bawah pimpinan Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Pemberontakan Serbia Kedua dan kepemimpinan başknez Miloš Obrenović", "e6e82ad2"], "d": ["Pemberontakan baru pecah di bawah pimpinan Miloš Obrenović melawan tindakan berat yang diterapkan setelah ditumpasnya pemberontakan pertama; kali ini Bâbıâli memilih kompromi alih-alih kekuatan. Dengan kesepakatan yang dicapai, Miloš diakui dengan gelar 'başknez' dan wewenang memungut pajak serta menjalankan urusan dalam negeri diserahkan kepada para knez Serbia. Inti pertama otonomi faktual ini menjadi titik awal proses yang berlanjut ke dekret 1830 dan kemerdekaan 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Pemberontakan Wallachia — Ypsilanti menyeberangi Prut dan pemberontakan Vladimirescu", "67d46a98"], "d": ["Aleksandr Ypsilanti, jenderal dalam pasukan Rusia, atas nama Filiki Eterya menyeberangi Prut dan berusaha memulai pemberontakan umum Yunani di Wallachia dan Moldavia; pada hari-hari yang sama Tudor Vladimirescu juga menggerakkan petani setempat. Kedua gerakan tidak dapat bersatu: Vladimirescu menjawab seruan Ypsilanti untuk berperang bersama melawan Turki dengan 'Aku memberontak bukan melawan Turki melainkan melawan Yunani' dan tak lama kemudian dibunuh oleh anak buah Ypsilanti. Pemberontakan ditumpas oleh pasukan Utsmaniyah pada bulan Mei, tetapi tatanan voivodat Fener berakhir dan api pemberontakan menjalar ke Mora.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Pendirian Negara Saudi Kedua di Riyadh", "34dad3bd"], "d": ["Enam tahun setelah jatuhnya Dir'iyah pada 1818 dan runtuhnya Negara Saudi pertama, Turki b. Abdullah mengeluarkan garnisun Mesir dari Najd dan mendirikan emirat Saudi baru yang berpusat di Riyadh. Struktur baru ini menghindari meluas ke Hijaz dan memilih tetap di Najd dan menjauhi bentrokan langsung dengan pasukan Utsmaniyah-Mesir. Negara kedua ini akan berlangsung hingga akhir abad dan membentuk mata rantai kedua rantai yang menuju berdirinya Arab Saudi saat ini. Permukiman lain yang lepas pada tanggal yang sama: Dir'iye (Necid).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Perjanjian Akkerman — konsesi kepada Serbia dan kepangeranan", "c75f15d0"], "d": ["Negara Utsmaniyah, yang tanpa pasukan segera setelah dihapusnya Korps Janisari, terpaksa menerima perjanjian bersyarat berat menghadapi ultimatum Rusia. Otonomi yang dijanjikan kepada Serbia ditegaskan, diterima bahwa voivode Wallachia dan Moldavia tidak dapat dipecat tanpa persetujuan Rusia, dan kapal dagang Rusia diberi kebebasan penuh di Selat. Ketika Bâbıâli dua tahun kemudian menyatakan tidak mengakui perjanjian itu karena persoalan Yunani, Rusia akan menganggapnya alasan perang.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Likuidasi sistem timar", "84d5d1d6"], "d": ["Satu tahun setelah dihapusnya Korps Janisari, sekitar 5.200 sipahi bertimar di lima puluh tiga sancak di Rumelia dan Anatolia diubah, bersama pendapatan timar mereka, menjadi kavaleri Asâkir-i Mansûre. Dengan demikian rezim timar, tulang punggung tatanan tanah, pajak, dan tentara Utsmaniyah selama empat abad, secara de facto berakhir. Timar yang kosong diserahkan kepada kas dan jalan menuju peralihan ke tentara bergaji sentral dan sistem pajak tunai terbuka.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Pendirian Tıphâne-i Âmire — awal pendidikan kedokteran modern", "ac3e57c0"], "d": ["Untuk mendidik tabib dan ahli bedah bagi pasukan Asâkir-i Mansûre yang baru dibentuk, atas usul hekimbaşı Mustafa Behçet Efendi, Tıphâne-i Âmire dibuka di Şehzadebaşı. Kuliah disusun menurut kurikulum di Eropa dan pengajaran pada mulanya dilakukan dalam bahasa Prancis; beberapa tahun kemudian Cerrahhâne-i Âmire juga didirikan dan kedua lembaga disatukan. Sekolah ini, yang dianggap awal pengajaran kedokteran modern di Turki, dianggap asal Fakultas Kedokteran Istanbul saat ini.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Dimulainya Perang Utsmaniyah-Rusia 1828-1829", "9dff4e05"], "d": ["Atas dibakarnya armada di Navarino dan pernyataan Bâbıâli bahwa tidak mengakui Perjanjian Akkerman, Rusia menyatakan perang dari dua front sekaligus. Karena Korps Janisari baru saja dihapuskan dan tentara baru masih dalam tahap pembentukan, pertahanan Utsmaniyah lemah sejak awal; ketika Rusia menyeberangi Danube, di timur mereka merebut Kars dan Ahıska. Pasukan Rusia yang dalam satu tahun maju hingga Edirne akan memaksakan syarat-syarat berat Perjanjian Edirne 1829 dan kemerdekaan Yunani.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Perjanjian pertama dengan Amerika Serikat", "d737516f"], "d": ["Dengan perjanjian dagang dan pelayaran yang ditandatangani setelah kontak bertahun-tahun, AS memperoleh status bangsa yang paling diistimewakan di wilayah Utsmaniyah dan hak lintas dagang di Selat. Sebuah pasal rahasia terpisah menetapkan bahwa Utsmaniyah dapat, jika menghendaki, membuat kapal di galangan Amerika dan membeli kapal jadi dan kayu; Senat AS meratifikasi perjanjian tetapi menolak pasal rahasia ini dengan 27 suara melawan 18. Jalur kapal tetap tidak tertutup: Henry Eckford pada 1831 menjual kapal yang dibawanya kepada Utsmaniyah, dan para ahli Amerika yang bekerja di Aynalıkavak memberi armada kapal-kapal jenis baru. Perjanjian ini menjadi dokumen hubungan komprehensif pertama yang dibangun Negara Utsmaniyah dengan sebuah negara di luar Eropa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Diakhirinya pemerintahan Kölemen di Baghdad", "7e1d38a3"], "d": ["Mahmud II, yang menjalankan kebijakan sentralisasi, menyatakan gubernur Baghdad Dâvud Paşa, yang tidak mengirim uang yang diminta dan membunuh petugas yang datang dari pusat, sebagai pemberontak. Pasukan di bawah komando Ali Rızâ Paşa merebut kota setelah pengepungan sembilan puluh hari dan hampir seluruh kölemen dilikuidasi. Dengan demikian pemerintahan Kölemen semi-merdeka yang berlangsung sejak 1704 berakhir dan Irak kembali diikat langsung ke pusat.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Pendirian Mekteb-i Harbiye di Barak Maçka", "bf31c7d9"], "d": ["Mekteb-i Fünûn-ı Harbiyye dibuka di Barak Maçka untuk menyediakan perwira terdidik ala Eropa bagi Asâkir-i Mansûre-i Muhammediyye. Kepada murid-murid diajarkan matematika, peta, zeni, dan bahasa asing; tak lama kemudian murid dikirim ke Wina dan Paris untuk memperkuat kader. Sekolah ini menjadi tempat lahirnya tradisi perwira lulusan sekolah dalam pasukan Utsmaniyah dan dengan demikian generasi baru tentara-intelektual yang akan muncul pada akhir abad ke-19.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Tripolitania diikat langsung ke pusat — akhir dinasti Karamanlı", "faabcb96"], "d": ["Atas pertikaian perebutan takhta di dalam keluarga Karamanlı dan meningkatnya tekanan Eropa setelah pendudukan Aljazair oleh Prancis pada 1830, Bâbıâli campur tangan langsung di Tripolitania. Armada yang dikirim dari Istanbul memasuki kota, bey Karamanlı terakhir dipecat dan dibawa ke Istanbul, dan provinsi diserahkan kepada gubernur yang diangkat dari pusat. Ketika masa dinasti 124 tahun berakhir, bagian wilayah terakhir yang diperintah langsung oleh Negara Utsmaniyah di Afrika Utara diperkuat.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Dihapuskannya defterdarlık dan didirikannya Kementerian Keuangan", "89f8125e"], "d": ["Jabatan defterdar, kepala tatanan keuangan klasik Utsmaniyah, dihapuskan dan Maliye Nezâreti, sebuah kementerian ala Eropa, didirikan dan perbendaharaan yang tersebar dihimpun di satu tangan. Pada tahun yang sama unit-unit lain Bâbıâli juga ditata ulang dengan nama nezâret dan beralih ke struktur dewan menteri modern. Penataan ini adalah salah satu langkah terpenting yang menyiapkan infrastruktur administratif Dekret Tanzimat yang akan diumumkan setahun kemudian.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Menetapnya Inggris di Aden", "ddbd556b"], "d": ["Inggris, bertumpu pada perjanjian dagang dan persahabatan yang ditandatanganinya dengan sultan Lahij Ahmed b. Abdulkarim pada 1802, mendaratkan pasukan di pelabuhan Aden dan menguasai kota. Pelabuhan yang menguasai mulut Laut Merah ini berubah menjadi titik kunci strategi imperial Inggris sebagai pangkalan pasokan batu bara jalur India. Meski klaim Negara Utsmaniyah atas Yaman berlanjut di atas kertas, kekuasaan faktualnya di pesisir selatan tidak pernah kembali lagi setelah tanggal ini.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Kembali ke pesisir Tihama: direbutnya Hudaydah, Zabid, dan Mocha", "353982d2"], "d": ["Ke pesisir Yaman yang tak bertuan setelah penarikan pasukan Mesir pada 1840, pasukan di bawah komando Tevfik Paşa mendarat di bawah pengawasan syarif Makkah dan mengikat pelabuhan Hudaydah, Zabid, dan Mocha ke pemerintahan Utsmaniyah. Meski dikehendaki maju hingga Sana'a, mereka kembali ke Hudaydah karena perlawanan penduduk; dengan demikian dataran tinggi tetap di tangan imam-imam Zaidi dan kekuasaan Utsmaniyah berlanjut hanya di jalur Tihama selama dua puluh tiga tahun. Yaman pedalaman baru akan direbut kembali pada 1872 dengan ekspedisi Ahmed Muhtar Paşa.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Konvensi Balta Limanı: perlindungan bersama Utsmaniyah-Rusia di Wallachia dan Moldavia", "d3bb22e9"], "d": ["Ketika revolusi 1848 menjalar ke Wallachia dan Moldavia, pasukan Utsmaniyah dan Rusia telah menduduki kedua kepangeranan bersama. Dengan konvensi yang ditandatangani di Balta Limanı diputuskan bahwa voivode tidak dipilih melainkan diangkat sultan untuk tujuh tahun dan kedua negara membangun kendali bersama di wilayah itu. Kesepakatan itu memelihara kedaulatan Utsmaniyah di atas kertas tetapi memberi Rusia hak kemitraan faktual, dan mempercepat terlepasnya kepangeranan Danube dari Utsmaniyah.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Persoalan pengungsi Hongaria: Kossuth dan rekan-rekannya berlindung ke Utsmaniyah", "1c7d7ef4"], "d": ["Setelah revolusi Hongaria 1848-1849 ditumpas dengan intervensi Rusia-Austria, Lajos Kossuth dan ribuan pengungsi Hongaria-Polandia berlindung di wilayah Utsmaniyah. Austria dan Rusia dengan keras menuntut pengembalian para pengungsi; Bâbıâli, dengan dukungan Inggris dan Prancis, menolak pengembalian dan menempatkan kelompok itu di Kütahya. Lingkungan Kossuth tinggal di sini sekitar delapan belas bulan, dan ratusan pengungsi memeluk Islam dan masuk dinas Utsmaniyah. Peristiwa ini dianggap salah satu kemenangan diplomatik langka yang meningkatkan gengsi Utsmaniyah masa Tanzimat dalam opini publik Eropa.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Pendirian Encümen-i Dâniş: akademi Utsmaniyah pertama di Istanbul", "6fda1365"], "d": ["Encümen-i Dâniş, yang didirikan dengan keputusan Meclis-i Maârif-i Umûmiyye, adalah akademi ilmu Utsmaniyah pertama yang dibentuk untuk menyiapkan buku ilmu dan pelajaran dalam bahasa Turki. Ia dibuka dengan upacara di gedung Dârülmaârif pada 18 Juli 1851; di antara anggotanya, lokal dan asing, terdapat juga Ahmed Cevdet Paşa. Meski berumur pendek, karya-karya seperti Târih Cevdet Paşa dan Kavâid-i Osmâniyye adalah produk lembaga ini dan dianggap batu penjuru menjadikan bahasa Turki bahasa ilmu.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Kemenangan Oltenița: keberhasilan Utsmaniyah pertama di front Danube", "a660ad2f"], "d": ["Pada fase pembukaan Perang Krimea, Serdâr-ı Ekrem Ömer Lütfi Paşa menyeberangi Danube dan memukul mundur pasukan Rusia dengan kerugian berat di Oltenița. Kemenangan itu, dengan menghentikan kemajuan Rusia segera di awal perang, menunjukkan kepada Eropa kekuatan yang diperoleh tentara Utsmaniyah dengan pelatihan pasca-Tanzimat. Keberhasilan ini menyiapkan landasan psikologis yang memudahkan keputusan Inggris dan Prancis masuk perang di pihak Utsmaniyah.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Perjanjian aliansi dengan Inggris dan Prancis di Istanbul", "04809278"], "d": ["Perjanjian aliansi yang ditandatangani antara Negara Utsmaniyah dan Inggris serta Prancis melawan Rusia dalam Perang Krimea menetapkan bahwa ketiga negara menjalankan operasi bersama dan para sekutu tidak membuat perdamaian terpisah sebelum perang berakhir. Dengan demikian Negara Utsmaniyah untuk pertama kalinya dalam sejarahnya memasuki aliansi militer dengan kekuatan-kekuatan Eropa besar sebagai pihak yang setara. Perjanjian ini juga membentuk landasan hukum diterimanya Utsmaniyah secara resmi ke dalam sistem negara-negara Eropa di Paris dua tahun kemudian.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Pendirian Şehremaneti Istanbul: organisasi kotamadya modern pertama", "be4af27f"], "d": ["Krisis infrastruktur yang ditimbulkan oleh prajurit sekutu yang menumpuk di Istanbul selama Perang Krimea dan bertambahnya penduduk menyingkapkan ketidakcukupan pemerintahan kota klasik yang berpusat pada kadi. Dengan Şehremaneti yang dibentuk menurut contoh Eropa, kebersihan, narh, pengawasan pasar, dan urusan pembangunan dihimpun di satu tangan; tahun berikutnya Daire-i Belediye Keenam di Beyoğlu-Galata dibentuk sebagai wilayah percontohan. Langkah ini dianggap awal kotamadya modern di Utsmaniyah.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Perjanjian Paris: berakhirnya Perang Krimea dan diterimanya Utsmaniyah ke sistem negara Eropa", "4aee0e2a"], "d": ["Dengan Perjanjian Paris yang mengakhiri Perang Krimea, Negara Utsmaniyah dinyatakan anggota setara hukum antarnegara Eropa dan keutuhan wilayahnya ditempatkan di bawah jaminan bersama kekuatan-kekuatan besar. Laut Hitam dinetralkan, klaim perlindungan Rusia atas rakyat Ortodoks yang diperolehnya sejak Küçük Kaynarca dinyatakan tidak berlaku, dan Bessarabia Selatan (kaza Kili, Kahul, İsmail, dan Bolgrad) diserahkan kepada Moldavia. Namun perjanjian yang sama menjadikan Dekret Islahat sebagai komitmen internasional dan dengan demikian juga membuka pintu campur tangan dalam urusan dalam negeri.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Dibukanya Istana Dolmabahçe: pemindahan pusat pemerintahan dari Topkapı", "71ad26d0"], "d": ["Istana yang dipesan Abdülmecid pada 1842 dari keluarga Balyan dibuka setelah pembangunan empat belas tahun dan pusat pemerintahan negara dipindahkan dari Topkapı yang berusia empat abad ke tepi Selat. Dengan gaya Eropanya, tangga kristal, dan Ruang Muayede, istana menjadi ungkapan dalam batu atas klaim Westernisasi Tanzimat. Biayanya yang sangat besar menjadi salah satu pos yang paling banyak dikritik pada tahun-tahun ketika keuangan Utsmaniyah memasuki spiral utang luar negeri.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Penyatuan Wallachia dan Moldavia di bawah Cuza: lahirnya Rumania", "baef4da5"], "d": ["Dalam pemilihan yang diselenggarakan setelah Perjanjian Paris, kedua kepangeranan memilih Kolonel Alexandru Ioan Cuza sebagai voivode dan mewujudkan penyatuan faktual. Meski Bâbıâli dan Austria menentangnya, dengan dukungan Prancis fait accompli itu terpaksa diterima. Penyatuan ini, yang di atas kertas tetap terikat pada Utsmaniyah, akan mengambil nama Rumania pada 1862 dan menyatakan kemerdekaan sepihaknya pada 1877; ia merupakan titik balik dalam terurainya kekuasaan Utsmaniyah di tepi Danube.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Peristiwa Kuleli: upaya kudeta pertama terhadap Abdülmecid di Istanbul", "e3653b21"], "d": ["Sebuah perkumpulan rahasia campuran militer-sipil, yang bereaksi terhadap kebijakan Tanzimat dan kesetaraan yang diberikan Dekret Islahat kepada non-Muslim, digerebek dalam pertemuan di Masjid Kılıç Ali Paşa ketika merencanakan menurunkan sultan dari takhta. Karena para terdakwa diadili di Barak Kuleli, peristiwa itu dikenal dengan nama ini; hukuman mati diubah menjadi pengasingan. Dianggap upaya kudeta istana pertama oleh organisasi yang dibentuk dengan alasan ideologis dalam sejarah Utsmaniyah.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Perang saudara Druze-Maronit di Gunung Lebanon dan peristiwa Damaskus", "5595fdd6"], "d": ["Bentrokan yang pecah dengan terbunuhnya dua orang Druze dekat Sidon pada Mei 1860 berubah menjadi perang saudara Druze-Maronit paling berdarah di pegunungan dan pada Juli menjalar ke Damaskus dan berujung pada tewasnya ribuan orang Kristen. Atas pendaratan pasukan Prancis, Bâbıâli mengirim Fuad Paşa ke wilayah itu dengan wewenang luar biasa; operasi penumpasan keras dijalankan. Peristiwa itu membentuk dalih bagi intervensi Eropa dan menjadi penyebab langsung Lebanon memperoleh status khusus.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Terbitnya Tercümân-ı Ahvâl: surat kabar Turki swasta pertama di Istanbul", "24792957"], "d": ["Tercümân-ı Ahvâl, yang diterbitkan Agâh Efendi dan redaksinya dipegang Şinâsi, adalah surat kabar Turki pertama yang terbit tanpa dukungan negara. Dalam pendahuluan edisi pertamanya dibela hak rakyat berbicara tentang urusannya sendiri, dan surat kabar itu, dengan menerbitkan Şair Evlenmesi karya Şinâsi secara bersambung, juga membuka pintu sastra Turki modern. Lahirnya konsep opini publik dan pers oposisi di Utsmaniyah dikembalikan pada tanggal ini.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Peraturan Gunung Lebanon: status mutasarrifat istimewa untuk Lebanon", "bf375603"], "d": ["Peraturan yang disiapkan dengan tekanan kekuatan-kekuatan besar setelah pembantaian 1860 menjadikan Gunung Lebanon mutasarrifat istimewa yang terikat langsung kepada Bâbıâli dan diperintah dengan dewan administratif yang dibentuk menurut keseimbangan antar-mazhab. Disyaratkan bahwa mutasarrıf adalah rakyat Utsmaniyah yang beragama Kristen Katolik dan pengangkatannya diajukan untuk disetujui kekuatan-kekuatan besar; mutasarrıf pertama adalah Dâvud Paşa. Tatanan ini akan berlangsung hingga 1915 dan membentuk inti negara Lebanon modern.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Wafatnya Abdülmecid dan naik takhtanya Sultan Abdülaziz", "27204d7c"], "d": ["Saudaranya Abdülaziz naik takhta karena Abdülmecid, yang menandatangani dekret Tanzimat dan Islahat dalam kesultanan dua puluh dua tahun, menyerah pada tuberkulosis. Sultan baru memberi harapan pada tahun-tahun pertama dengan langkah penghematan dan kehidupan sederhananya; ia menjadikan armada salah satu yang terkemuka di dunia. Namun pada akhir kesultanannya utang luar negeri yang berat, kebangkrutan 1875, dan pemberontakan Balkan menumpuk dan menyiapkan landasan gerakan pemakzulan 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Kepangeranan-kepangeranan bersatu mengambil nama Rumania", "d960e3fc"], "d": ["Wallachia dan Moldavia, yang bersatu secara faktual dengan terpilihnya Cuza dua kali pada 1859, pada 1862 menghimpun majelis dan pemerintahannya di bawah satu atap di Bukares dan secara resmi mengambil nama Rumania. Meski Negara Utsmaniyah secara hukum mempertahankan kedudukan suzerain dan pajak tahunan, secara faktual ia kehilangan kendali atas kepangeranan. Berakhirnya pengaruh Utsmaniyah empat abad di utara Danube dilambangkan dengan tanggal ini.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Suakin, Massawa, dan Dahlak diikat ke Mesir", "a0924860"], "d": ["Massawa, yang pada 1846 diberikan Sultan Abdülmecid kepada Khedive Mesir Mehmed Ali Paşa bersama Suakin sebagai sâlyâne (alokasi pendapatan), pada masa Khedive İsmâil Paşa dimasukkan ke milik Mesir bersama Dahlak dan Suakin dan diorganisasi dengan status kaymakamlık. Dengan demikian ketiga pelabuhan di pesisir Afrika Laut Merah ini, meski secara hukum tetap tanah Utsmaniyah, secara administratif beralih dari Bâbıâli langsung ke Kairo — masuk ke lapisan vasal yang sama dengan tetangganya Mesir dan Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Dimulainya Pemberontakan Kreta (1866-1869)", "3679b861"], "d": ["Pemberontakan berskala luas yang pecah di pulau dengan dukungan terbuka Yunani untuk pertama kalinya menjadikan tuntutan enosis (bergabung dengan Yunani) orang Yunani Kreta sebagai persoalan internasional. Perang gunung sengit selama tiga tahun menimbulkan kerugian berat bagi pasukan Utsmaniyah dan menimbulkan gaung besar dalam opini publik Eropa. Pemberontakan baru dapat mereda pada 1868 dengan Âlî Paşa pergi ke pulau dan memberlakukan peraturan yang memberi imtiyaz luas.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Penarikan garnisun Utsmaniyah terakhir dari Beograd dan benteng-benteng Serbia", "b34217db"], "d": ["Atas tekanan kekuatan-kekuatan besar dan tuntutan gigih Pangeran Mihailo, Bâbıâli menerima mengosongkan pangkalan militer terakhir yang tersisa di Serbia; pada 18 April 1867 panji Utsmaniyah di Benteng Beograd diturunkan dan kunci-kunci diserahkan kepada pangeran. Dengan demikian keberadaan militer Utsmaniyah faktual yang berlangsung sejak 1521 berakhir dan rintangan besar terakhir di jalan Serbia menuju kemerdekaan hilang. Suzerainty sultan direduksi menjadi soal bendera simbolis dan pajak semata.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Pemberian gelar khedive kepada gubernur Mesir", "09e10c12"], "d": ["Sebagai hasil lobi intensif İsmâil Paşa dari generasi ketiga dinasti Kavalalı dan uang yang ia alirkan ke Istanbul, gubernur Mesir diberi gelar khedive yang menekankan keunggulannya atas gubernur-gubernur lain. Pada tahun-tahun yang sama tatanan suksesi juga diubah menjadi diwariskan dari ayah ke anak dan Mesir diberi wewenang berciri kedaulatan seperti berutang ke luar negeri, memberikan medali, dan menempatkan konsulat. Langkah-langkah ini adalah mata rantai pertama dalam rantai yang mempercepat lepasnya Mesir secara hukum dari Utsmaniyah.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Peraturan Kreta: imtiyaz administratif luas untuk pulau", "12052262"], "d": ["Untuk mengakhiri pemberontakan tiga tahun, Sadrazam Âlî Paşa sendiri pergi ke pulau dan dengan peraturan yang diterbitkan dengan persetujuan sultan, orang Kreta diberi dewan administrasi campuran, pengadilan lokal, penggunaan bahasa Yunani dalam urusan resmi, dan kemudahan pajak. Pengaturan ini mempertahankan kekuasaan Utsmaniyah di pulau selama tiga puluh tahun lagi. Namun hak istimewa yang diberikan kepada penduduk Kristen melemahkan kedudukan orang Kreta Muslim dan menanam benih krisis 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Dibukanya Şûrâ-yı Devlet: pendirian Dewan Negara Utsmaniyah", "70b16497"], "d": ["Dengan irade tertanggal 5 Maret 1868, Meclis-i Ahkâm-ı Adliyye dibagi dua dan urusan administratif-legislatif diserahkan kepada Şûrâ-yı Devlet dan urusan peradilan kepada Dîvân-ı Ahkâm-ı Adliyye; lembaga dibuka dengan upacara di Bâbıâli dan Midhat Paşa diangkat menjadi presiden pertamanya. Ia ditugaskan menyiapkan rancangan undang-undang, menyelesaikan sengketa administratif, dan menjalankan pengadilan pegawai. Dengan struktur anggota campuran Muslim-non-Muslim, dianggap penerapan kelembagaan pertama gagasan pemisahan kekuasaan di Utsmaniyah.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Dibukanya Terusan Suez: jalur India melalui Mesir dipersingkat", "377ccd04"], "d": ["Pembangunan yang dimulai pada 1859 berlangsung sepuluh tahun dan terusan sepanjang 163 kilometer yang menghubungkan Mediterania dengan Laut Merah dibuka dengan upacara megah. Ketika jalur yang menghubungkan Eropa ke India dipersingkat ribuan mil, Mesir seketika menjadi titik kunci perdagangan dunia. Nilai geostrategis ini akan menjadi alasan utama pendudukan Mesir oleh Inggris tiga belas tahun setelah dibukanya terusan; utang yang dibebankan terusan kepada Mesir akan menyeret kekhedivean ke kebangkrutan.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Pendirian Eksarkat Bulgaria: gereja Bulgaria terpisah dari Fener", "33a8272c"], "d": ["Dengan firman sultan, sebuah gereja Bulgaria (eksarkat) yang mandiri, terpisah dari Patriarkat Yunani, didirikan dan kaza mana yang akan diikat ke eksarkat diserahkan kepada pemungutan suara rakyat. Meski Bâbıâli mengambil langkah ini untuk mematahkan pengaruh Yunani, hasilnya berbalik: gereja itu berubah menjadi pusat terorganisasi identitas nasional Bulgaria dan klaim Bulgaria atas Makedonia. Landasan kelembagaan persaingan Bulgaria-Yunani-Serbia di Balkan dan pemberontakan 1876 pun diletakkan.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Asir diambil ke pemerintahan langsung", "4559e099"], "d": ["Ketika nilai strategis Laut Merah meningkat dengan dibukanya Terusan Suez, disadari bahwa Pegunungan Asir di tengah jalan darat ke Yaman tidak dapat dibiarkan tanpa kendali. Pasukan Redif Paşa, yang berangkat ke ekspedisi Yaman, memasuki Abha dan mengikat wilayah itu langsung ke pemerintahan Utsmaniyah dan sancak Asir didirikan. Karena geografi pegunungan dan pengaruh Idrisi, kekuasaan ini tidak pernah mapan sepenuhnya.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Ekspedisi Najd Midhat Paşa: dibangunnya kembali kekuasaan Utsmaniyah di Lahsâ", "7db51461"], "d": ["Gubernur Baghdad Midhat Paşa, dengan memanfaatkan perebutan takhta di dalam keluarga Saudi, mengirim pasukan ke pesisir barat Teluk Basra dan mengikat wilayah Lahsâ ke vilayet Basra dengan nama sancak Najd. Abdullah b. Faysal diangkat mutasarrıf dan kekuasaan Utsmaniyah didirikan di atas kertas. Ekspedisi bertujuan menghentikan menyebarnya pengaruh Inggris di teluk dan pada tahun yang sama menyebabkan Qatar juga masuk ke kendali Utsmaniyah.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Wafatnya Sadrazam Âlî Paşa: berakhirnya kader Tanzimat", "1cf0141c"], "d": ["Dengan wafatnya Âlî Paşa, yang memikul politik Tanzimat sendirian setelah wafatnya Fuad Paşa pada 1869, generasi diplomat ulung yang mengarahkan kebijakan luar negeri negara selama tiga puluh tahun habis. Pemerintahan Mahmud Nedim Paşa yang menggantikannya, yang pro-Rusia dan sewenang-wenang, memperkuat pemerintahan pribadi Abdülaziz. Dalam lima tahun setelah wafatnya Âlî Paşa keuangan bangkrut, Balkan memberontak, dan pergantian kesultanan menjadi tak terelakkan.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Dibangunnya kendali Utsmaniyah di Qatar", "3b453165"], "d": ["Atas undangan Syekh Kāsım b. Sânî yang berada di bawah tekanan Inggris, pasukan Utsmaniyah mendarat di Semenanjung Qatar dan pada musim gugur 1871 kendali Utsmaniyah dibangun di wilayah itu. Qatar diorganisasi sebagai kaza yang terikat pada sancak Najd dan syekh diangkat kaymakam. Langkah ini menjadi perolehan paling nyata kebijakan maju yang dijalankan Midhat Paşa melawan Inggris di teluk; panji Utsmaniyah berkibar di semenanjung hingga 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Firman suksesi untuk Tunisia — beylik untuk keluarga Mehmed Sâdık Paşa", "1509ebb0"], "d": ["Dengan firman yang keluar atas upaya Hayreddin Paşa, yang dikirim ke Istanbul oleh bey Tunis Mehmed Sâdık Paşa yang memanfaatkan kekalahan Prancis di hadapan Prusia, Tunisia diberikan kepada Mehmed Sâdık Paşa dan keturunannya dengan tata cara suksesi sambil tetap terikat langsung ke Istanbul. Tanpa izin sultan tidak akan dilakukan perundingan perang dan damai, tidak ada tanah dari negeri yang diserahkan kepada pihak lain, dan permintaan pasukan Utsmaniyah akan dipenuhi. Prancis tidak mengakui firman itu; sepuluh tahun kemudian ia menduduki Tunisia.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Direbutnya Sana'a: dibangunnya kembali otoritas Utsmaniyah di Yaman", "978e20a0"], "d": ["Ketika nilai strategis Laut Merah meningkat dengan dibukanya Terusan Suez, Bâbıâli mengirim pasukan fırka-i ihtiyâtiyye di bawah komando Ahmed Muhtar Paşa ke Yaman. Dengan direbutnya Sana'a, otoritas negara dibangun kembali di Yaman pedalaman yang secara faktual hilang selama dua abad dan wilayah itu dijadikan vilayet. Namun perjuangan melawan imam-imam Zaidi tidak pernah berakhir; pemberontakan 1891, 1898, dan 1904 membentuk front dalam negeri Utsmaniyah yang paling mahal dan paling lama. Tempat-tempat lain yang bergabung pada tanggal yang sama: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Dimulainya Pemberontakan Herzegovina: berkobarnya kembali Masalah Timur", "571b18ec"], "d": ["Pemberontakan petani Kristen di sekitar Nevesinje karena pajak berat dan tekanan âyan dengan cepat menjalar ke seluruh Herzegovina dan diberi makan oleh sukarelawan yang datang dari Serbia dan Montenegro. Pemberontakan yang menimbulkan tuntutan reformasi paksa dari Austria dan Rusia itu pada tahun berikutnya memicu pemberontakan Bulgaria dan pernyataan perang Serbia-Montenegro. Dengan demikian mata rantai pertama rantai besar yang menuju Perang 93 dan hilangnya Balkan dengan Perjanjian Berlin patah.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Kebangkrutan keuangan Utsmaniyah: pembayaran utang luar negeri dikurangi separuh", "2cac2fa5"], "d": ["Pinjaman beruntun sejak 1854, biaya Perang Krimea, pembangunan istana, dan kelaparan Anatolia 1873-74 mengubah defisit anggaran menjadi jurang melebihi lima juta lira. Pemerintahan Mahmud Nedim Paşa secara de facto menyatakan moratorium dengan mengumumkan bahwa pembayaran bunga dan pokok utang akan dikurangi separuh selama lima tahun. Keputusan yang menimbulkan reaksi besar di bursa-bursa Eropa ini memulai proses yang enam tahun kemudian akan berujung pada Dekret Muharrem dan pendirian Administrasi Düyûn-ı Umûmiyye.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Pemakzulan Murad V dan naik takhtanya Abdülhamid II", "cffb2271"], "d": ["Murad V, yang naik takhta setelah diturunkannya Abdülaziz, menjadi tidak mampu bertugas karena kesehatan jiwanya terguncang oleh wafatnya pamannya dan Peristiwa Cerkes Hasan; dalam kesultanannya selama sembilan puluh tiga hari, ia hanya waras pada tujuh hari. Ia dimakzulkan dengan fatwa şeyhülislâm dan saudaranya Abdülhamid II dinaikkan menggantikannya. Sultan baru naik takhta dengan janji kepada Midhat Paşa bahwa ia akan memproklamasikan masa konstitusional; masa tiga puluh tiga tahun pun dimulai.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Konferensi Galangan Kapal: paksaan reformasi Balkan oleh kekuatan-kekuatan besar", "b5006a2c"], "d": ["Konferensi yang dihimpun kekuatan-kekuatan besar di Istanbul untuk menyelesaikan krisis Balkan menuntut agar Bulgaria dibagi menjadi dua vilayet otonom dan reformasi dengan pengawasan internasional diterapkan di Bosnia-Herzegovina. Bâbıâli, dengan mengumumkan Kanûn-ı Esâsî dengan tembakan meriam pada hari dibukanya konferensi, berusaha menjawab paksaan itu dengan reformasi konstitusional. Para delegasi menganggapnya penundaan dan bubar pada 20 Januari 1877; empat bulan kemudian Rusia menyatakan perang.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Dibukanya Meclis-i Meb'ûsan pertama di Dolmabahçe", "429bb279"], "d": ["115 anggota parlemen yang dipilih menurut Kanûn-ı Esâsî berkumpul untuk pertama kali pada 19 Maret 1877 dengan upacara di Ruang Muayede Istana Dolmabahçe; dengan demikian masa majelis perwakilan dalam sejarah Utsmaniyah dimulai. Anggota Muslim dan non-Muslim mengkritik pemerintah dengan keras, mendebatkan pengelolaan perang dan tanggung jawab para menteri. Oposisi berani ini akan menjadi alasan utama memendeknya usia majelis.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Dimulainya pertahanan Plevne: perlawanan Gazi Osman Paşa", "0e04a878"], "d": ["Osman Paşa, yang berbaris dari Vidin ke Plevne untuk memotong jalan Istanbul bagi pasukan Rusia yang menyeberangi Danube dalam Perang 93, memperkuat kota itu dengan benteng dan parit dan memulai pertahanan legendaris selama lima bulan. Tiga serangan besar Rusia-Rumania berturut-turut dipukul mundur dengan kerugian berat, dan pasukan yang dipimpin langsung Tsar Aleksandr II terpaksa mengepung. Plevne tercatat dalam sejarah sebagai keberhasilan pertahanan paling gemilang tentara Utsmaniyah pada abad ke-19.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Jatuhnya Plevne: runtuhnya front Danube", "185e7602"], "d": ["Osman Paşa, yang perbekalannya habis dalam pengepungan lima bulan, melakukan operasi keluar melalui Sungai Vit; ketika ia terluka dan tertawan, kota menyerah. Para komandan Rusia menyalami sang paşa yang mereka tawan dengan mengembalikan pedangnya, dan Osman Paşa diberi gelar 'Gazi'. Dengan jatuhnya Plevne jalan pasukan Rusia terbuka; dalam dua bulan Sofia, Filibe, dan Edirne jatuh dan pasukan depan Rusia mencapai Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Pendudukan Sofia oleh pasukan Rusia", "ef369d22"], "d": ["Setelah jatuhnya Plevne, pasukan Rusia yang melintasi Balkan memasuki Sofia yang tidak terlindungi. Kota tidak akan pernah kembali ke pemerintahan Utsmaniyah; pada akhir 1878 akan menjadi bagian Kepangeranan Bulgaria otonom dan pada 1879 menjadi ibu kotanya secara de facto. Di peta Sofia sejak tanggal ini keluar dari pemerintahan langsung Utsmaniyah dan beralih ke pendudukan Rusia sementara, kemudian ke pemerintahan Bulgaria otonom.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Gencatan Senjata Edirne: senjata diam dalam Perang 93", "1f899180"], "d": ["Dengan berturut-turut jatuhnya Sofia, Filibe, dan Edirne dan pasukan Rusia tiba di pesisir Marmara, Bâbıâli terpaksa meminta gencatan senjata. Gencatan senjata yang ditandatangani di Edirne memaksa Utsmaniyah menerima syarat-syarat perdamaian pendahuluan seperti otonomi bagi Bulgaria, kemerdekaan Montenegro-Serbia-Rumania, dan ganti rugi perang berat. Syarat-syarat ini sebulan kemudian akan menjadi teks perjanjian di San Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Abdülhamid II menangguhkan Meclis-i Meb'ûsan tanpa batas waktu", "e770b540"], "d": ["Atas kritik keras para anggota parlemen yang menganggap pemerintah dan istana bertanggung jawab atas berakhirnya perang dengan bencana, Abdülhamid II, bertumpu pada wewenang yang diberikan Kanûn-ı Esâsî kepadanya, menangguhkan majelis tanpa batas waktu. Parlemen Utsmaniyah pertama yang bekerja sekitar sebelas bulan itu pun tertutup dan masa istibdat yang akan berlangsung tiga puluh tahun dimulai. Majelis baru dapat berkumpul kembali setelah Revolusi 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Perjanjian San Stefano: rencana Bulgaria Raya", "2c7cc611"], "d": ["Perjanjian San Stefano yang mengakhiri Perang 93 mendirikan Bulgaria otonom raksasa yang membentang hingga Aegea dan mencakup Makedonia; mengakui kemerdekaan Serbia, Montenegro, dan Rumania; menyerahkan Kars, Ardahan, Batum, dan Doğubayazıt kepada Rusia, serta membebankan ganti rugi perang yang mustahil dibayar. Teks yang menurunkan Rusia ke Mediterania ini menimbulkan reaksi keras Inggris dan Austria. Ia ditata ulang oleh Kongres Berlin dalam empat bulan tanpa diterapkan; meski begitu tetap menjadi dokumen yang menyatakan berakhirnya Rumelia Utsmaniyah.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan, dan Batum ditinggalkan kepada Rusia — Elviye-i Selâse", "99bdfad2"], "d": ["Dengan Perjanjian Berlin Negara Utsmaniyah menyerahkan Kars, Ardahan, dan Batum kepada Rusia sebagai imbalan sebagian ganti rugi perang; Doğubayazıt dan lembah Eleşkirt, yang diberikan kepada Rusia di San Stefano, tetap pada Utsmaniyah. Meski Batum diberikan sebagai pelabuhan bebas, ia hanya dapat mempertahankan status ini hingga 1886. Rusia menjadikan Kars vilayet yang terikat pada gubernur jenderal Transkaukasia yang berpusat di Tiflis; penduduk Elviye-i Selâse, yang jumlahnya mencapai 100.000, terpaksa bermigrasi ke arah Erzurum. Dengan perjanjian yang sama Bessarabia Selatan (Kili, Kahul, Bolgrad) dikembalikan dari Rumania ke Rusia.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Pendudukan Bosnia-Herzegovina dan Novi Pazar oleh Austria-Hongaria", "e5f901df"], "d": ["Bertumpu pada wewenang yang diberikan Perjanjian Berlin, pasukan Austria-Hongaria memasuki Bosnia; meski pemerintah Utsmaniyah menerima tidak melawan, penduduk Muslim-Ortodoks setempat di Sarajevo dan Mostar mengangkat senjata dan melakukan perlawanan sengit selama tiga bulan. Pendudukan baru dapat diselesaikan pada 20 Oktober 1878. Kedaulatan hukum sultan berlanjut di atas kertas hingga 1908, tetapi Bosnia Utsmaniyah yang berusia empat abad lepas secara faktual dan gelombang besar migrasi Muslim dimulai. Permukiman lain yang lepas pada tanggal yang sama: Banaluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Dekret Muharrem dan pendirian Administrasi Düyûn-ı Umûmiyye", "02b7cc03"], "d": ["Perundingan yang dijalankan dengan wakil-wakil negara kreditor setelah kebangkrutan 1875 berujung pada dekret tertanggal 28 Muharram 1299 (20 Desember 1881): pokok utang dikurangi lebih dari separuh, sebagai imbalannya pos-pos pendapatan paling produktif seperti garam, tembakau, sutra, bea meterai, dan retribusi ikan diserahkan kepada Administrasi Düyûn-ı Umûmiyye yang dikelola langsung para kreditor. Administrasi ini, yang mempekerjakan ribuan pegawai, berubah menjadi organisasi keuangan tersendiri di dalam negara. Dianggap tanggal berakhirnya kemerdekaan keuangan Utsmaniyah secara de facto.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — satu-satunya pelabuhan yang tidak jatuh ke Mahdi", "5a37b198"], "d": ["Ketika seluruh wilayah Sudan Timur kecuali Suakin beralih ke kekuasaan Muhammad Ahmad al-Mahdi sejak Februari 1884, pelabuhan itu bertahan dengan perlindungan militer pasukan Inggris tiga batalion di bawah komando Jenderal Graham. Ini adalah awal periode ketika keadaan faktual dan hukum terpisah: meski pesisir secara faktual di bawah kendali militer Inggris, ikatan administratifnya pada 1885 diambil dari Mesir dan diikat langsung ke vilayet Yaman, yaitu ke Bâbıâli — tatanan itu berlanjut hingga berakhir dengan pendudukan Zeila oleh Prancis pada 1888.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Terbunuhnya Midhat Paşa di penjara Tâif", "f4562261"], "d": ["Midhat Paşa, arsitek Kanûn-ı Esâsî dan nama simbol Masa Konstitusional I, dinyatakan bersalah di Pengadilan Yıldız terkait kematian Abdülaziz dan hukuman matinya diubah menjadi pengasingan, lalu dikirim ke Tâif. Menurut catatan TDV, ia dicekik di selnya pada malam 7-8 Mei 1884 dan penyebab resmi diumumkan sebagai penyakit 'şîrpençe'. Kematiannya menjadi simbol likuidasi oposisi konstitusional pada masa Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Pemberian konsesi kereta api Haydarpaşa-Ankara kepada Jerman", "5705b163"], "d": ["Dengan irade sultan, konsesi pembangunan dan pengoperasian jalur Haydarpaşa-Ankara diberikan kepada bankir Alfred von Kaulla yang mewakili Deutsche Bank dan Perusahaan Kereta Api Anatolia didirikan. Konsesi ini menjadi titik balik yang mematahkan monopoli Inggris-Prancis dalam transportasi dan kebijakan luar negeri Utsmaniyah dan menanamkan pengaruh Jerman. Dengan konsesi jalur Baghdad yang akan diberikan kepada perusahaan yang sama sebelas tahun kemudian, mimpi 'Berlin-Baghdad' lahir dan menjadi salah satu poros utama persaingan kekuatan besar menjelang Perang Dunia I.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Pendirian Cemiyet İttihâd-ı Osmânî di Istanbul", "b7187939"], "d": ["Empat murid Tıbbiye Militer mendirikan Cemiyet İttihâd-ı Osmânî sebagai organisasi rahasia melawan pemerintahan istibdat; struktur ini dalam waktu singkat berubah menjadi Komite Persatuan dan Kemajuan yang akan menghimpun semua unsur oposisi gerakan Turki Muda di bawah atapnya. Organisasi berbasis sel ini bergabung dengan para buangan di Eropa dan perwira di Selanik. Kader yang akan memproklamasikan Masa Konstitusional II pada 1908 dan akan memerintah negara sendirian setelah 1913 lahir dari sel murid kecil ini.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Serbuan Bank Utsmaniyah: aksi kaum Dashnak di Galata", "08b3095f"], "d": ["Sebuah kelompok bersenjata organisasi Armenia Dashnaksutyun menyerbu dan menyandera kantor pusat Bank Utsmaniyah di Galata dengan tujuan menarik perhatian Eropa pada persoalan Armenia dan mengancam meledakkan gedung. Krisis berakhir dengan campur tangan para duta besar dengan imbalan para pelaku dikeluarkan dari negeri dengan kapal. Peristiwa berdarah yang terjadi di Istanbul pada hari-hari setelah serbuan itu menentukan dalam berubahnya persoalan Armenia menjadi pengungkit intervensi internasional.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Dimulainya Perang Utsmaniyah-Yunani 1897: front Thessalia", "33e490ab"], "d": ["Atas pendaratan armada dan pasukan Yunani di Kreta dan serangan gerombolan di perbatasan Rumelia, Negara Utsmaniyah menyatakan perang. Pasukan Utsmaniyah yang dilatih misi reformasi Jerman maju cepat di Thessalia dan dalam satu bulan merebut Yenişehir, Çatalca, dan Domokos; pasukan Yunani bubar. Dengan campur tangan kekuatan-kekuatan besar, wilayah yang diperoleh dikembalikan, tetapi perang tetap menjadi satu-satunya kemenangan militer pasti masa Abdülhamid II dan tidak dapat mencegah hilangnya Kreta secara faktual.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Pemberian konsesi jalur Konya-Baghdad kepada Jerman", "fd8b6cbd"], "d": ["Setelah kunjungan Kaisar Wilhelm II ke Istanbul dan Damaskus pada 1898, konsesi pendahuluan jalur yang membentang dari Konya ke Baghdad dan Basra diberikan kepada Perusahaan Kereta Api Anatolia. Proyek Kereta Api Baghdad berarti bagi Utsmaniyah memperkuat kendali sentral atas vilayet-vilayet Arab, dan bagi Jerman mencapai Teluk Basra. Proyek yang ditentang keras Inggris dan Rusia ini menjadi salah satu berkas paling diperdebatkan dalam persaingan imperialis yang menuju Perang Dunia I.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Dimulainya pembangunan Kereta Api Hijaz di Damaskus", "62f58f68"], "d": ["Jalur yang diperintahkan dengan irade Abdülhamid II tertanggal 2 Mei 1900 mulai dibangun dengan upacara resmi di Damaskus pada 1 September 1900. Proyek yang dibangun sepenuhnya dengan sumbangan yang dihimpun dari dunia Islam dan jerih payah insinyur-prajurit Utsmaniyah ini mempersingkat perjalanan jamaah haji Damaskus-Madinah dari empat puluh hari menjadi lima hari. Ia adalah karya prestise yang memperkuat otoritas spiritual kekhalifahan sekaligus investasi strategis yang memperkuat kendali militer atas Hijaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Program Mürzsteg: pengawasan reformasi internasional di Makedonia", "4c7464da"], "d": ["Setelah pemberontakan Ilinden, para kaisar Rusia dan Austria bertemu di Mürzsteg dan menyiapkan paket reformasi baru untuk Makedonia. Program ini menetapkan ditempatkannya dua agen sipil asing di samping inspektur umum Utsmaniyah, penataan ulang jandarma oleh perwira Eropa, dan perubahan batas administratif menurut asas kebangsaan. Meski Bâbıâli menolak dengan alasan hak kedaulatannya dirugikan, ia terpaksa menerima di hadapan tekanan bersama; program menjadi salah satu faktor pokok yang mempercepat pengorganisasian Ittihadis di antara perwira muda.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Wafatnya Murad V", "396659a7"], "d": ["Murad V, yang bertahan di takhta sekitar tiga bulan pada 1876 dan dimakzulkan, setelah upaya menaikkannya kembali ke takhta hidup sebagai tahanan di bawah penjagaan ketat selama dua puluh delapan tahun dan wafat karena diabetes. Ia dimakamkan di samping ibunya di Makam Cedîd Havâtîn di Yenicami. Ia tercatat dalam sejarah sebagai sultan Utsmaniyah yang paling sebentar di takhta.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Hilangnya Sana'a ke Imam Yahya", "e7f876cb"], "d": ["Pemberontakan Imam Zaidi Yahya Hamiduddin yang dimulai pada 1904 berujung pada jatuhnya Sana'a pada April 1905 setelah pengepungan; kota keluar dari pemerintahan Utsmaniyah dan kelaparan serta wabah muncul selama pengepungan. Geografi pegunungan Yaman, panjangnya jalur pasokan, dan legitimasi lokal imamat Zaidi membuat kekuasaan Utsmaniyah di sana rapuh sejak awal berdirinya. Kota akan direbut kembali lima bulan kemudian dengan kerugian berat, tetapi persoalan Yaman tidak tertutup hingga 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Percobaan pembunuhan Yıldız: serangan bom terhadap Abdülhamid II", "1ee2e1a6"], "d": ["Organisasi Dashnaksutyun melakukan pembunuhan dengan meledakkan landau berbom waktu di kereta sultan yang keluar dari selamlık Jumat; terlambatnya Abdülhamid beberapa menit karena berbicara dengan şeyhülislâm menyelamatkan nyawanya. Dalam ledakan dua puluh enam orang tewas dan lebih dari lima puluh orang terluka. Peristiwa itu semakin mengeraskan obsesi keamanan sultan dan pemerintahan istibdat yang bertumpu pada organisasi mata-mata; ia juga menjadi subjek puisi 'Bir Lahza-i Taahhur' karya Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Direbutnya kembali Sana'a: penumpasan pemberontakan Imam Yahya", "dec3b8f9"], "d": ["Pemberontakan yang dimulai pada 1904 di bawah pimpinan Imam Zaidi Yahya berujung pada jatuhnya Sana'a pada April 1905 dan kelaparan serta wabah muncul di kota. Pasukan bantuan di bawah komando Ali Rızâ Paşa dan Ahmed Feyzi Paşa, dengan operasi yang mereka jalankan antara 15 Juli - 1 September 1905 dan didukung pula oleh pasukan di Taiz, merebut kembali kota dengan kerugian berat dan pemberontakan ditumpas. Operasi Yaman membawa puluhan ribu korban dan beban keuangan luar biasa bagi tentara Utsmaniyah; di antara perwira di Rumelia, ketakutan 'diasingkan ke Yaman' adalah salah satu keluhan utama yang memberi makan pengorganisasian Ittihadis.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Berkumpulnya Meclis-i Meb'ûsan pertama Masa Konstitusional II", "e7fd2716"], "d": ["Majelis yang terbentuk dengan pemilihan dua tingkat setelah jeda tiga puluh tahun dibuka pada 17 Desember 1908 dengan pidato sultan dan pemimpin gerakan Turki Muda Ahmed Rızâ Bey dipilih sebagai ketuanya. Majelis yang terdiri dari anggota Turki, Arab, Albania, Yunani, Armenia, dan Yahudi ini adalah percobaan besar terakhir cita-cita Utsmanisme. Namun kemerdekaan Bulgaria, aneksasi Bosnia, dan pernyataan bergabungnya Kreta dengan Yunani telah membayangi optimisme ini bahkan sebelum majelis dibuka.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Tentara Aksi dan pemakzulan Abdülhamid II: naik takhtanya Mehmed V Reşad", "6a65a704"], "d": ["Tentara Aksi yang berangkat dari Selanik atas Peristiwa 31 Mart memasuki Istanbul dari empat kolom pada malam 22-23 April dan pada 24 April Istana Yıldız menyerah. Meclis-i Umûmî-i Millî memutuskan pemakzulan Abdülhamid II pada 27 April; sultan dikirim ke Selanik dan saudaranya Mehmed V Reşad dinaikkan ke takhta. Pemerintahan pribadi tiga puluh tiga tahun dengan demikian berakhir, tetapi digantikan oleh masa baru ketika sultan menjadi simbol dan Komite Persatuan dan Kemajuan memerintah dengan dukungan tentara.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Pemberontakan Albania: perlawanan bersenjata di Kosovo dan İşkodra", "93ed30c6"], "d": ["Kebijakan pajak sentralistis pemerintah Ittihadis, kampanye pengumpulan senjata, dan perdebatan alfabet Latin membuat suku-suku Albania, yang sampai saat itu dianggap salah satu unsur paling setia kepada negara, memberontak. Meski pasukan di bawah komando Mahmud Şevket Paşa menumpas pemberontakan dengan keras, kegelisahan berkobar lagi pada 1911 dan 1912. Pemberontakan-pemberontakan ini, selain melelahkan tentara Utsmaniyah menjelang Perang Balkan, juga mempercepat lahirnya gerakan nasional Albania.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Perjanjian Ouchy: penyerahan Tripolitania dan Benghazi kepada Italia", "4ffa1fd2"], "d": ["Bâbıâli, yang tidak dapat berani menghadapi konflik dua front menghadapi persiapan perang negara-negara Balkan, menandatangani perdamaian rahasia dengan Italia di kota Ouchy, Swiss, dan melepaskan Tripolitania dan Benghazi. Negara Utsmaniyah dengan demikian kehilangan wilayah terakhirnya di Afrika; sebagai imbalannya dijanjikan dikembalikannya Rhodes dan Dodekanesos yang diduduki Italia, tetapi janji itu tidak pernah dipenuhi. Ketika perjanjian ditandatangani, Perang Balkan sudah lama dimulai. Dengan peristiwa ini Murzuk (Fezzan), Ghat, Sebha, Ubari, Tırgan (Traghan), Zevîle (Zawila), dan el-Katrûn (Fezzan (sancak vilayet Tripolitania)) beralih ke pemerintahan Italia.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Pendudukan Limni oleh Yunani", "9555af1d"], "d": ["Dalam Perang Balkan I armada Yunani menduduki Limni; pelabuhan Mudros di pulau itu menjadi pangkalan untuk blokade Selat Çanakkale. Pulau ditinggalkan kepada Yunani di Lausanne (24 Juli 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Pendudukan Thasos oleh Yunani", "6c03c7f0"], "d": ["Dalam Perang Balkan I Yunani menduduki Thasos dan Samothrace.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Pendudukan Samothrace oleh Yunani", "911e82a3"], "d": ["Dalam Perang Balkan I Yunani menduduki Samothrace.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Pendudukan Midilli oleh Yunani", "6b2b07ba"], "d": ["Armada Yunani mendarat di Midilli; pulau direbut oleh tentara dan armada Yunani pada akhir Perang Balkan I. Konferensi London (Mei 1913) menegaskan keadaan itu.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Pendaratan Yunani di Sakız", "901c6539"], "d": ["Yunani mendarat di Sakız, yang dibombardir pada 7 April 1912 dalam Perang Balkan I; garnisun Utsmaniyah menyerah pada 3 Januari 1913. Pulau ditinggalkan kepada Yunani dengan Perjanjian Lausanne (24 Juli 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Pembunuhan Sadrazam Mahmud Şevket Paşa di Istanbul", "68e60e63"], "d": ["Mahmud Şevket Paşa, yang diangkat menjadi sadrazam setelah Serbuan Bâb-ı Âli, tewas ditembak dari kereta ketika menuju Kementerian Perang dekat Çarşıkapı. Komite Persatuan dan Kemajuan menimpakan pembunuhan itu kepada oposisi dan memulai gelombang penangkapan dan eksekusi luas; Partai Kebebasan dan Persetujuan secara de facto dilikuidasi. Dengan peristiwa ini kediktatoran satu partai Ittihadis yang bertumpu pada trio Enver-Talat-Cemal dibangun secara pasti.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Dimulainya Perang Balkan II: perebutan pembagian di antara sekutu", "48d088a2"], "d": ["Sekutu-sekutu Balkan yang tidak dapat membagi wilayah yang mereka ambil dari Utsmaniyah dengan Perjanjian London saling berhadapan; perang kedua dimulai dengan Bulgaria menyerang posisi Serbia dan Yunani. Ketika Rumania dan Montenegro juga masuk front melawan Bulgaria, pasukan Bulgaria runtuh. Negara Utsmaniyah memanfaatkan kesempatan ini untuk melampaui garis Midye-Enez yang digambar Perjanjian London dan merebut kembali Thrakia Timur bersama Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Perjanjian Istanbul: perdamaian dengan Bulgaria dan pencatatan Edirne", "c8c18b2d"], "d": ["Perjanjian yang ditandatangani antara Negara Utsmaniyah dan Bulgaria setelah Perang Balkan II mencatat secara hukum, dengan menerima Sungai Maritsa sebagai perbatasan, bahwa Edirne, Kırklareli, Dimetoka, dan Thrakia Timur tetap pada Utsmaniyah. Dedeağaç ditinggalkan pada Bulgaria (sedangkan Kavala telah beralih ke Yunani pada Juli 1913 setelah pendudukan Bulgaria pada musim gugur 1912 dan dicatat di Yunani dengan Perjanjian Bukares 10 Agustus 1913), pertukaran penduduk timbal balik antara kedua negara dan hak-hak Muslim di Bulgaria diatur. Jaminan satu-satunya bagian wilayah yang dapat direbut kembali dari bencana Balkan adalah teks ini. Tempat-tempat lain yang bergabung pada tanggal yang sama: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Direbutnya kembali Bozcaada dan İmroz — Perjanjian Athena", "ec084d09"], "d": ["Bozcaada dan İmroz, dua pulau Aegea Utara yang diduduki Yunani dalam Perang Balkan dan yang menguasai mulut Selat, dianggap tak tergantikan bagi pertahanan Çanakkale dalam perundingan Perjanjian Athena dan dikembalikan kepada Utsmaniyah. Pulau-pulau lain tetap di Yunani. Kedua pulau ini menjadi wilayah terakhir yang dipertahankan kekaisaran di Aegea dan di Lausanne juga ditinggalkan kepada Turki.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Perjanjian Athena: perdamaian dengan Yunani dan penyerahan Selanik-Yanya", "8e94def7"], "d": ["Perjanjian yang ditandatangani antara Negara Utsmaniyah dan Yunani secara resmi mengakui beralihnya Selanik, Yanya, dan Makedonia Selatan, yang hilang dalam Perang Balkan, kepada Yunani dan melepaskan hak Utsmaniyah atas Kreta. Hak agama dan kepemilikan Muslim yang tinggal di Yunani, status wakaf, dan pengangkatan mufti diatur secara rinci. Status pulau-pulau Aegea dibiarkan tidak terselesaikan dan tetap menjadi sumber ketegangan terus-menerus antara kedua negara.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Penandatanganan perjanjian aliansi rahasia Utsmaniyah-Jerman di Istanbul", "0472efb3"], "d": ["Segera setelah perang pecah di Eropa, perjanjian aliansi rahasia ditandatangani antara Negara Utsmaniyah dan Jerman di kediaman Sadrazam Said Halim Paşa; teksnya menetapkan bahwa jika Rusia masuk perang melawan Jerman, Utsmaniyah juga akan berada di pihak Jerman. Perjanjian itu disembunyikan bahkan dari kabinet, hanya diketahui empat orang. Tiga bulan kemudian, dengan Serbuan Laut Hitam, Negara Utsmaniyah akan ditarik secara de facto ke dalam perang dan nasib kekaisaran terikat dengan dokumen ini.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Dihapuskannya kapitulasi secara sepihak", "ec773d18"], "d": ["Pemerintah Utsmaniyah, pada saat Eropa disibukkan perang, mengumumkan bahwa kapitulasi, yang memberi orang asing hak istimewa peradilan, keuangan, dan bea cukai, dihapuskan secara sepihak mulai 1 Oktober 1914. Berakhirnya tatanan imtiyaz berusia empat abad ini disambut dalam negeri dengan semangat kemerdekaan besar dan perayaan dilangsungkan di Istanbul. Semua negara, termasuk sekutu Jerman, memprotes keputusan itu; kapitulasi baru akan lenyap secara pasti dari sejarah di Lausanne pada 1923.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Serbuan Laut Hitam: pemboman pelabuhan Rusia oleh armada Utsmaniyah", "8ad4ef61"], "d": ["Goeben dan Breslau (Yavuz dan Midilli), yang melarikan diri dari Jerman dan bergabung ke armada Utsmaniyah seolah 'dibeli', berlayar ke Laut Hitam di bawah komando Laksamana Souchon dan membombardir pelabuhan Rusia serta menenggelamkan kapal. Perintah yang diberikan Enver Paşa secara rahasia dari kabinet ini mengakhiri netralitas secara de facto. Dalam seminggu Rusia, Inggris, dan Prancis menyatakan perang dan Negara Utsmaniyah masuk Perang Dunia I secara tak dapat kembali.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Pasukan Inggris-India merebut Fao — pembukaan front Irak", "08663813"], "d": ["Pagi hari setelah negara-negara Entente menyatakan perang kepada Negara Utsmaniyah, brigade Inggris-India yang menunggu di Bahrain mendarat di Fao di mulut Shatt al-Arab. Unit Utsmaniyah kecil di benteng Fao yang rusak mundur di bawah tembakan kapal perang dan stasiun jalur telegraf India jatuh ke tangan Inggris. Front Irak dengan demikian dibuka.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proklamasi Jihad Akbar: pembacaan fatwa jihad di Masjid Fatih", "2a6174e8"], "d": ["Lima fatwa yang dikeluarkan Şeyhülislâm Ürgüplü Hayri Efendi dibacakan atas nama khalifah-sultan di Masjid Fatih dan seluruh Muslim diserukan berjihad melawan negara-negara Entente. Langkah yang digantungi harapan besar oleh Jerman ini bertujuan membangkitkan umat Islam di koloni-koloni Inggris dan Prancis. Pemberontakan umum yang diharapkan tidak terjadi; sebaliknya, dua tahun kemudian pemberontakan Amir Makkah Şerif Hüseyin dengan dukungan Inggris menunjukkan dengan pahit batas-batas pengaruh politik kekhalifahan.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Penyerahan Kurna kepada Inggris", "621d36b0"], "d": ["Pasukan Gubernur Basra Subhi Bey, yang mundur ke Kurna tempat bertemunya Tigris dan Efrat setelah jatuhnya Basra, menyerah pada pagi 9 Desember 1914 setelah pertempuran 4-8 Desember.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Penempatan Mesir di bawah perlindungan Inggris dan proklamasi kesultanan", "55d4e520"], "d": ["Atas masuknya Negara Utsmaniyah ke perang, Inggris mengumumkan secara resmi menempatkan Mesir, yang didudukinya secara faktual sejak 1882, di bawah perlindungannya; Khedive Abbas Hilmi Paşa, yang tetap setia kepada Utsmaniyah, dipecat dan Hüseyin Kâmil dinaikkan dengan gelar 'sultan'. Dengan demikian kedaulatan hukum Utsmaniyah yang berlangsung sejak 1517 diakhiri secara sepihak. Bâbıâli tidak mengakui keputusan itu dan dua bulan kemudian berupaya merebut kembali Mesir dengan Operasi Terusan.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operasi Sarıkamış: bencana di front Kaukasus", "5cbde7f0"], "d": ["Enver Paşa, dengan tujuan merebut kembali Kars-Ardahan-Batum yang hilang pada 1878 dan membangkitkan orang Turki di Kaukasus, menggerakkan Angkatan Darat III pada musim dingin dalam manuver untuk mengepung pasukan Rusia melalui Pegunungan Allahuekber. Karena perlengkapan musim dingin yang tidak memadai, pasokan yang habis, dan badai salju hingga minus tiga puluh derajat, pasukan musnah bahkan sebelum masuk pertempuran; puluhan ribu prajurit tewas membeku. Operasi ini menjadi salah satu bencana terberat Utsmaniyah dalam perang dan membiarkan front timur tak berlindung selama dua tahun.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Operasi Terusan Pertama: serangan ke Suez melalui gurun Sinai", "02dd72f5"], "d": ["Komandan Angkatan Darat IV Cemal Paşa melancarkan serangan yang melintasi gurun Sinai dengan tujuan menyelamatkan Mesir dari pendudukan Inggris dan menutup Terusan Suez bagi pelayaran. Meski pasukan Utsmaniyah mencapai tepi timur terusan dan sebagian berhasil menyeberang, mereka mundur karena keunggulan Inggris dan tidak terjadinya pemberontakan rakyat Mesir yang diharapkan. Operasi gagal mencapai sasarannya, tetapi menimbulkan dampak strategis tidak langsung dengan memaksa Inggris menempatkan pasukan besar di Mesir.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Diundangkannya Undang-Undang Pengiriman dan Permukiman (Tehcir)", "2f2bc22c"], "d": ["Setelah pemberontakan Van dan kemajuan Rusia, pemerintah mengeluarkan undang-undang sementara yang mengizinkan komandan pasukan memindahkan penduduk yang dinilai mengganggu keamanan di belakang front ke wilayah lain, dan sultan mengesahkannya pada 27 Mei 1915. Sebagai hasil penerapan, sebagian besar penduduk Armenia di vilayet-vilayet timur dan selatan Anatolia dikirim ke arah Suriah dan Mosul; selama pengiriman terjadi korban jiwa yang sangat besar akibat penyakit, kelaparan, dan serangan. Keputusan itu tetap menjadi persoalan terberat dan hingga kini paling diperdebatkan dari tahun-tahun terakhir Utsmaniyah.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Pasukan Utsmaniyah merebut kembali Muş dari pendudukan Rusia", "fb1be113"], "d": ["Enam bulan setelah pendudukan Rusia pertama atas Muş, Korps ke-16 Utsmaniyah memasuki kota dalam serangan balik Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş kembali jatuh ke tangan Rusia", "43ad8a03"], "d": ["Atas serangan balik Rusia, detasemen Utsmaniyah mengosongkan Muş; kota masuk lagi ke pendudukan Rusia antara 22-25 Agustus 1916 dan tetap di tangan mereka hingga musim semi 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş dibebaskan secara pasti dari pendudukan Rusia", "f0e89703"], "d": ["Muş, yang masuk ke pendudukan Rusia dalam Perang Dunia I, direbut kembali secara pasti oleh pasukan Utsmaniyah pada 1 Mei 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Wafatnya Abdülhamid II di Istana Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, yang diturunkan dari takhta pada 1909 dan dibawa pertama ke Selanik, kemudian ke Istanbul karena hilangnya kota dalam Perang Balkan, dan ditahan dalam tahanan rumah di Istana Beylerbeyi, wafat. Dalam kesultanannya selama tiga puluh tiga tahun ia berusaha mengulur waktu dengan menjauhkan negara dari perang, tetapi juga dikenal dengan pemerintahan istibdat. Jenazahnya dimakamkan dengan kerumunan besar di Makam Mahmud I di Divanyolu; wafatnya bertepatan dengan tahun perang ketika tatanan yang didirikannya telah lama dilikuidasi.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Perjanjian Brest-Litovsk: direbutnya kembali Kars, Ardahan, dan Batum", "da82636f"], "d": ["Perjanjian yang ditandatangani antara Rusia, yang menarik diri dari perang setelah Revolusi Bolshevik, dan Blok Sentral menutup front Timur dan mengembalikan kepada Negara Utsmaniyah Kars, Ardahan, dan Batum (Elviye-i Selâse) yang hilang dengan Perjanjian Berlin 1878. Ini adalah satu-satunya perolehan wilayah dalam sejarah Utsmaniyah setelah jeda empat puluh tahun. Namun wilayah itu akan lepas lagi setelah Gencatan Senjata Mudros, dan penyelesaian pasti akan datang dengan Perjanjian Kars 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Pasukan Utsmaniyah memasuki Artvin", "ca7d1778"], "d": ["Pasukan Utsmaniyah yang melintasi perbatasan 1914 pada 25 Maret berbaris ke Elviye-i Selâse, yang perbatasannya sebelum 1878 dikembalikan Brest-Litovsk, dan memasuki Artvin pada 28 Maret 1918. Artvin telah ditinggalkan kepada Rusia pada 1878 sebagai bagian sancak Batum; entri Artvin di TDV hanya menulis kembalinya sebagai 'Maret 1918', harinya diberikan oleh Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan jatuh ke tangan tentara Turki", "7fd9e3db"], "d": ["Dalam operasi Elviye-i Selâse, pasukan Utsmaniyah merebut Ardahan pada 3 April 1918 setelah Artvin; Ardahan telah jatuh pada 1877 dalam Perang 93 dan ditinggalkan kepada Rusia pada 1878. Kars akan direbut sebulan kemudian, pada 25 April.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Direbutnya kembali Batum", "d37a1a0d"], "d": ["Pasukan Utsmaniyah yang maju ke timur setelah Rusia menarik diri dari perang dengan Brest-Litovsk merebut kembali pelabuhan Batum, yang hilang pada 1878, setelah empat puluh tahun. Pelabuhan di ujung timur Laut Hitam ini adalah pintu keluar laut minyak Baku. Perolehan hanya berlangsung tujuh bulan; setelah Gencatan Senjata Mudros wilayah itu akan dikosongkan.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars masuk ke pemerintahan Utsmaniyah", "02cbf0b3"], "d": ["Di Brest-Litovsk diputuskan dikembalikannya tiga sancak yang hilang dengan Perjanjian Berlin 1878 — Kars, Ardahan, dan Batum; pasukan Utsmaniyah memasuki Ardahan pada 3 April, Batum pada 14 April, dan Kars pada 25 April 1918 dan pemerintahan didirikan secara faktual. Wilayah-wilayah yang disebut 'Elviye-i Selâse' ini dianggap kompensasi atas kehilangan yang berlangsung sejak Perang 93. Setelah gencatan senjata wilayah itu akan lepas lagi dan baru terikat secara pasti pada Turki dengan Perjanjian Kars 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır direbut — kemajuan di lembah Aras", "87ebf4d3"], "d": ["Dalam kerangka operasi maju yang dimulai pada Februari 1918, pasukan Turki mengalahkan unit-unit Armenia di Serderabad di utara Aras dan merebut Iğdır pada 20 Mei 1918. Iğdır tidak termasuk Elviye-i Selâse, melainkan kaza Surmali di guberniya Erivan; pemerintahan Utsmaniyah pertama di wilayah itu didirikan setelah sekitar 180 tahun.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Wafatnya Mehmed V Reşad dan naik takhtanya Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, yang kesultanannya sembilan tahun dilalui dengan perang Tripolitania, Balkan, dan Dunia, wafat pada periode paling kritis perang dan saudaranya Vahdeddin naik takhta dengan nama Mehmed VI. Sultan baru berusaha membebaskan diri dari perwalian kader Ittihadis; empat bulan kemudian, ketika gencatan senjata ditandatangani, ia akan terpaksa mengelola likuidasi kekaisaran. Ia adalah sultan Utsmaniyah ketiga puluh enam dan terakhir dari dinasti Utsmaniyah.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Kedatangan armada Entente di depan Istanbul dan pendudukan faktual kota", "d10cb14d"], "d": ["Setelah Gencatan Senjata Mudros, armada sekutu yang terdiri dari lebih dari enam puluh kapal Inggris, Prancis, Italia, dan Yunani berlabuh di depan Dolmabahçe dan Istanbul masuk ke pendudukan secara faktual. Setelah empat ratus enam puluh lima tahun, ibu kota untuk pertama kalinya berada di bawah kendali prajurit asing. Ucapan 'Mereka pergi seperti mereka datang', yang menurut riwayat diucapkan Mustafa Kemal Paşa ketika turun di Haydarpaşa dan melihat pemandangan itu pada hari yang sama, akan menjadi salah satu kalimat simbol Perjuangan Nasional.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Penarikan di wilayah Aras: Iğdır dikosongkan", "57572ab4"], "d": ["Sesuai ketentuan Gencatan Senjata Mudros tentang mundur ke belakang perbatasan 1914, Yakup Şevki Paşa dengan perintah 21 November memerintahkan unit-unit di luar perbatasan Brest-Litovsk ditarik hingga 4 Desember; Iğdır dan sekitarnya dikosongkan sepenuhnya pada tanggal ini. Kemudian Pemerintahan Aras-Turki dihancurkan oleh orang Armenia pada akhir Desember 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Inggris menetap di Artvin", "e2cb3153"], "d": ["Karena Gencatan Senjata Mudros 30 Oktober 1918 mensyaratkan pasukan Utsmaniyah mundur ke belakang perbatasan 1914, Artvin dikosongkan dan diduduki Inggris pada 17 Desember 1918. Menurut entri Artvin di TDV, pendudukan Inggris berlangsung hingga April 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Pemerintahan Inggris di Batum setelah Mudros", "9dd768fc"], "d": ["Sesuai Gencatan Senjata Mudros 30 Oktober 1918, Negara Utsmaniyah terpaksa mundur dari Batum; kota dikuasai pasukan Britania pada 24 Desember 1918. Batum, yang dijadikan pusat sancak mandiri pada April 1918, tetap di bawah kendali Inggris dari tanggal ini hingga Juli 1920.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan beralih ke kekuasaan Georgia", "97cf47f6"], "d": ["Ardahan yang dikosongkan setelah Mudros diduduki pasukan Georgia pada 20 April 1919, pada hari-hari ketika Pemerintahan Kaukasus Barat Daya dibubarkan oleh Inggris. Kekuasaan Georgia akan berlanjut hingga 23 Februari 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston menyerahkan pemerintahan Kars kepada gubernur Armenia", "efa81cb0"], "d": ["Komandan Inggris Preston, yang membubarkan Pemerintahan Kaukasus Barat Daya pada 12-13 April 1919, menghapus pemerintahan syura sementara pada 30 April 1919 dan menyerahkan pemerintahan kota kepada Karganof asal Armenia, yang dijadikan Gubernur Kars; masa pemerintahan Armenia di Kars dimulai dan berlangsung hingga kemenangan Kâzım Karabekir pada 30 Oktober 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Kongres Erzurum: keputusan perlawanan nasional vilayet-vilayet Timur", "41ef0457"], "d": ["Kongres yang dihimpun Cemiyet Müdafaa-i Hukuk Anatolia Timur dibuka dengan lima puluh enam delegasi setelah ditunda atas tekanan Inggris dan Mustafa Kemal Paşa, yang telah mengundurkan diri dari dinas militer, dipilih sebagai ketuanya. Kongres menyatakan bahwa tanah air adalah satu kesatuan dalam batas-batas nasional, bahwa mandat dan perlindungan tidak dapat diterima, dan bahwa jika pemerintah bubar bangsa akan mengambil nasibnya ke tangannya sendiri. Keputusan-keputusan ini enam bulan kemudian akan membentuk inti teks Misak-ı Millî.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Kongres Sivas: bersatunya perlawanan nasional di bawah satu atap", "0e9ad36b"], "d": ["Kongres yang memulai kerjanya di Sivas Sultânîsi pada 4 September 1919 menyatukan perkumpulan-perkumpulan pembelaan hak di seluruh negeri di bawah nama Cemiyet Müdafaa-i Hukuk Anatolia dan Rumelia dan memilih sebuah Heyet-i Temsîliyye. Tawaran mandat Amerika ditolak setelah perdebatan panjang. Dengan deklarasi yang diterbitkan pada 11 September, Perjuangan Nasional menjadi gerakan politik yang sah dan berpusat tunggal dan perebutan kekuasaan terbuka dengan pemerintah Istanbul dimulai.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protokol Amasya: pertemuan Heyet-i Temsîliyye dengan pemerintah Istanbul", "40e6a6ab"], "d": ["Setelah jatuhnya Damat Ferid dan terbentuknya pemerintahan Ali Rızâ Paşa, Menteri Angkatan Laut Salih Paşa dikirim ke Amasya untuk bertemu Heyet-i Temsîliyye. Dengan protokol yang dicapai, pemerintah Istanbul secara faktual mengakui keberadaan gerakan Anatolia; berkumpulnya Meclis-i Meb'ûsan, pemilihan yang bebas, dan terpeliharanya batas nasional diterima. Ini adalah perolehan politik resmi pertama Perjuangan Nasional di hadapan Istanbul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Diterimanya Misak-ı Millî di Majelis Utsmaniyah terakhir", "6322865e"], "d": ["Teks Ahd-i Millî yang ditandatangani 121 anggota parlemen di Meclis-i Meb'ûsan Utsmaniyah terakhir menetapkan keutuhan tak terbagi tanah yang berada di dalam garis Mudros dan dihuni mayoritas Muslim-Turki, referendum di vilayet-vilayet Arab dan Thrakia Barat, dihapuskannya kapitulasi, dan kemerdekaan politik-keuangan penuh. Teks diterima dengan suara bulat pada 17 Februari 1920 dan diumumkan ke dunia. Deklarasi ini adalah peta batas-batas yang akan dipertahankan di Lausanne sekaligus program politik Perjuangan Nasional; ia menjadi penyebab langsung pendudukan resmi Istanbul oleh negara-negara Entente pada 16 Maret.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Ketika Inggris mundur, Artvin tetap di Georgia", "6d086b06"], "d": ["Menurut entri Artvin di TDV, pendudukan Inggris berlangsung hingga April 1920; ketika mundur, Inggris meninggalkan kota kepada Georgia. Artvin tetap di tangan Georgia hingga ultimatum TBMM 23 Februari 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum diserahkan kepada pemerintahan Georgia", "6523d095"], "d": ["Penyerahan resmi Batum oleh Inggris kepada Georgia terjadi pada 7 Juli 1920 (entri Batum di TDV hanya 'Juli 1920'). Pemerintah Ankara pada 25 Juli memprotes penyerahan itu sebagai 'pendudukan'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Perjanjian Gyumri: perjanjian internasional pertama pemerintah TBMM", "9232c690"], "d": ["Atas direbutnya kembali Sarıkamış dan Kars oleh pasukan front Timur di bawah komando Kâzım Karabekir, Armenia meminta damai dan dengan perjanjian yang ditandatangani di Gyumri menerima bahwa ia tidak mengakui Sèvres dan melepaskan tuntutan wilayah di timur. Perjanjian pertama yang ditandatangani pemerintah Ankara ini menjadi dokumen internasional pertama yang secara faktual menolak Sèvres dan membuka jalan pengakuan hukum bagi TBMM. Perbatasan timur dengan demikian diamankan dan pemindahan kekuatan ke front Barat menjadi mungkin.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Pertempuran İnönü Pertama: kemenangan pertama tentara reguler", "4add3719"], "d": ["Tentara reguler yang baru dibentuk menghentikan pasukan Yunani yang maju dari arah Bursa di posisi İnönü dan memaksanya mundur. Keberhasilan yang secara militer berskala terbatas ini sangat besar akibat politiknya: pemerintah Ankara diundang ke Konferensi London, jalan ke Perjanjian Moskow dengan Rusia Soviet terbuka, dan Undang-Undang Teşkilât-ı Esâsiyye diterima. Kepercayaan opini publik dalam negeri kepada tentara reguler juga diperkuat dengan kemenangan ini.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Pertempuran İnönü Kedua: serangan Yunani patah untuk kedua kalinya", "a974521c"], "d": ["Pasukan Yunani, yang tidak memperoleh hasil dari Konferensi London, beralih ke serangan baru dari arah Bursa dan Uşak, tetapi lagi-lagi dihentikan di punggung bukit İnönü dan terpaksa mundur. Telegram Mustafa Kemal Paşa kepada İsmet Paşa, 'Di sana Anda tidak hanya mengalahkan musuh, tetapi juga nasib sial bangsa', ditulis setelah kemenangan ini. Pertempuran itu mengangkat gengsi internasional Perjuangan Nasional dan mempercepat proses penarikan Italia dari Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Persetujuan Ankara: perdamaian dengan Prancis dan tertutupnya front selatan", "35fc32db"], "d": ["Dengan persetujuan yang ditandatangani di Ankara dengan Prancis setelah kemenangan Sakarya, perang di front selatan berakhir; pasukan Prancis mengosongkan Çukurova dan Tenggara termasuk Adana, Antep, Maraş, dan Urfa dan mundur ke perbatasan Suriah. Salah satu negara Entente dengan demikian secara faktual mengakui pemerintah Ankara dan retakan pertama di front Sèvres terbuka. Senjata yang diambil alih dari wilayah yang dikosongkan dan unit-unit yang dibebaskan memainkan peran penting dalam persiapan Serangan Besar.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Gencatan Senjata Mudanya: penyerahan Istanbul dan Selat tanpa perang", "ac0d9baf"], "d": ["Konferensi yang berkumpul di Mudanya setelah tentara Turki berhadapan dengan pasukan Inggris di Çanakkale dan İzmit setelah Serangan Besar berujung pada gencatan senjata setelah tawar-menawar sengit sebelas hari. Diterima bahwa Thrakia Timur hingga Maritsa dikosongkan oleh Yunani dalam lima belas hari dan diserahkan ke pemerintahan Turki, dan bahwa Istanbul dan Selat juga diserahkan dengan perjanjian damai. Dengan demikian fase bersenjata Perjuangan Nasional tertutup dengan kemenangan diplomatik yang diraih tanpa satu peluru pun ditembakkan dan pintu Lausanne terbuka.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Kepergian Mehmed VI Vahdeddin dari Istanbul dan terpilihnya Abdülmecid Efendi sebagai khalifah", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, sultan terakhir yang kedudukannya menjadi diperdebatkan setelah dihapusnya kesultanan, meninggalkan Istanbul dengan kapal perang Inggris Malaya pada pagi Jumat 17 November 1922 dan pergi ke Malta. TBMM dua hari kemudian, pada 19 November, memilih Abdülmecid Efendi sebagai khalifah tanpa wewenang politik. Pemerintahan dinasti Utsmaniyah selama enam ratus dua puluh tiga tahun dengan demikian berakhir secara faktual; kekhalifahan akan berlanjut secara simbolis lima belas bulan lagi. Vahdeddin, yang pergi ke Malta dan kemudian Italia, menetap di Villa Nobel di San Remo; ia tidak memperoleh hasil dari permohonannya untuk diterima di sebuah negeri Muslim dan wafat di sana pada 16 Mei 1926 dengan menegaskan bahwa ia tidak pernah melepaskan hak kesultanan dan kekhalifahannya.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Wafatnya sultan terakhir Mehmed VI Vahdeddin di San Remo", "7149ed0e"], "d": ["Mehmed Vahdeddin, sultan Utsmaniyah terakhir yang menetap di kota San Remo, Italia, setelah meninggalkan Istanbul, wafat pada 16 Mei 1926 tanpa menerima kabar berkumpulnya kongres kekhalifahan (13 Mei 1926) tempat ia menyatakan tidak pernah melepaskan hak kesultanan dan kekhalifahan. Ia berada dalam kesulitan uang berat; ia berutang 60.000 lira kepada para pedagang San Remo dan para kreditor yang mendengar wafatnya menyita perabot rumahnya.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Penaklukan wilayah Bolu oleh Konuralp — Mudurnu, Konurapa, dan Bolu", "e245cd27"], "d": ["Konuralp, salah satu komandan Orhan Gazi, berpaling ke wilayah pegunungan di timur Sakarya dan mengikat wilayah Mudurnu, Konurapa, dan Bolu ke pemerintahan Utsmaniyah; kota di dataran Düzce dikenal dengan namanya. Tanggal pasti penaklukan tidak diketahui; kisah itu bertumpu pada riwayat Âşıkpaşazâde. Wilayah itu pada saat itu adalah medan uç yang berpindah tangan antara Candaroğulları dan Bizantium; penaklukan itu untuk pertama kalinya mendekatkan Utsmaniyah ke pesisir barat Laut Hitam. Setelah Perang Ankara wilayah itu akan beralih lagi ke Candaroğulları, tetapi akan direbut kembali secara pasti pada masa Fâtih.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Direbutnya kota-kota Bizantium di selatan Marmara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Setelah İznik dan İzmit direbut, kota-kota yang tersisa di tangan Bizantium di barat dataran Bursa masuk ke pemerintahan Utsmaniyah satu per satu. Gölyazı di sekitar Danau Uluabat, Kirmasti di tepi Sungai Susurluk, dan Mihaliç melengkapi koridor yang menghubungkan pesisir selatan Marmara ke wilayah Karesi. Kota-kota ini menyerah dalam waktu lama tanpa melihat pengepungan, dengan terputusnya lingkungan mereka; keberadaan Bizantium di wilayah itu dengan demikian terhimpit ke Teluk Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Korintus) beralih ke Despotat Mora", "392495eb"], "d": ["Korintus, yang sejak 1358 adalah timar keluarga Acciaiuoli dari Florence yang terikat pada kepangeranan Akhaia, jatuh ke tangan despot Mora Bizantium Theodoros pada 1395. Kota sesudahnya tetap di bawah pemerintahan despotat hingga penaklukan Utsmaniyah.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Aneksasi Beylik Hacıemîroğulları — Ordu dan Ünye", "c064f07f"], "d": ["Beylik Turkmen yang didirikan Bayram Bey di sekitar Ordu dan diperluas putranya Hacı Emîr pada 1350-an adalah negara pesisir kecil tetapi strategis yang pusatnya berada di Eskipazar saat ini: ia adalah satu-satunya wilayah kekuasaan merdeka antara Samsun dan Trabzon. Emîr Süleyman telah menyatakan kesetiaan pada operasi Canik Yıldırım Bayezid pada 1398, dan setelah Perang Ankara beylik kembali bebas. Pada masa Murad II, pada tahun-tahun yang sama dengan likuidasi Tâceddinoğulları, wilayah beylik diikat langsung ke pemerintahan Utsmaniyah dan pesisir Laut Hitam dari Samsun hingga Giresun menyatu di satu tangan.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Penaklukan Gördüs (Korintus)", "87a2bc59"], "d": ["Dalam ekspedisi Mora Fâtih, Benteng Akrokorintos dikepung tiga bulan dan akhirnya diterima penyerahannya dengan perdamaian. Tanah Genting Korintus, yang dianggap gerbang Mora, dengan demikian beralih ke Utsmaniyah.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Montenegro diikat ke pemerintahan Utsmaniyah — Cetinje", "7fdb7cc8"], "d": ["Ketika dinasti Crnojević yang memerintah Zeta melepaskan kekuasaannya pada 1496, wilayah pegunungan Montenegro, yang merupakan halaman belakang İşkodra, dibawa ke pemerintahan Utsmaniyah langsung dan diorganisasi pertama sebagai sancak tersendiri, kemudian sebagai bagian sancak İşkodra. Biara Cetinje dibiarkan di tempatnya sebagai pusat keagamaan wilayah. Karena kerasnya geografi, pemerintahan di sini tidak pernah berjalan seketat di dataran; dua abad kemudian pemerintahan vladika yang lahir dari biara yang sama akan menjadi inti kemerdekaan faktual.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Benteng Bayezid menerima kekuasaan Utsmaniyah dalam Ekspedisi Irakeyn", "f29e2e17"], "d": ["Ketika Sadrazam İbrahim Paşa tiba di sekitar Bingöl dalam Ekspedisi Irakeyn, benteng Van, Toprakkale, Avnik, dan Bayezid, bersama banyak suku Kurdi di wilayah itu, setuju masuk ke kekuasaan Utsmaniyah. Bayezid telah bergabung ke Utsmaniyah dalam ekspedisi Yavuz pada 1514, tetapi ketika pasukan kembali Safawi merebut kembali wilayah itu.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz kembali ke Safawi — kepulangan Irakeyn", "80b8b761"], "d": ["Pasukan telah memasuki Tabriz dalam Ekspedisi Irakeyn, tetapi karena sasaran sebenarnya adalah Baghdad, tidak ada garnisun permanen yang ditinggalkan di kota. Ketika pasukan yang melewati musim dingin di Baghdad kembali ke barat, Syah Tahmasb kembali memasuki Azerbaijan yang dikosongkan dan merebut kembali Tabriz. Ini adalah pola yang berulang dalam perang Utsmaniyah-Safawi: Tabriz direbut lima kali dan tidak dapat dipertahankan pada kelimanya; kota baru akan memperoleh garnisun Utsmaniyah jangka panjang pada 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van dan Erciş jatuh ke tangan Tahmasb (sikap Utsmaniyah berakhir pada 1534-35)", "cb93d561"], "d": ["Di wilayah yang menyerahkan Van kepada kekuasaan Utsmaniyah pada 1534, Ulama Paşa bertahan di Benteng Van menghadapi pengepungan Safawi; benteng jatuh ke tangan Safawi, dan pasukan Safawi yang mengepung Erciş juga mundur dengan bantuan Utsmaniyah. Ketika Kanuni tiba di Ahlat (23 September 1535), Van sudah berada di tangan Tahmasb. Van tetap Safawi hingga 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Sancak Bayezid beralih ke kekuasaan Safawi (Van dan Erciş sudah Safawi pada 1535)", "806a2cf1"], "d": ["Sancak Bayezid di tengah perbatasan Utsmaniyah-Safawi kembali jatuh ke tangan Iran (Kaya 2017 menyebutnya 'bersama Van dan Erciş'; namun menurut Karataş 2025 dan TDV, Van dan Erciş telah kembali ke Safawi pada 22 September 1535 — lihat entri sebelumnya); dalam perpindahan tangan ini beberapa tempat di sancak menjadi puing. Sancak berpindah tangan berulang kali antara kedua negara hingga seperempat terakhir abad ke-16.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Sancak Bayezid kembali beralih ke Utsmaniyah selama Ekspedisi Nakhchivan", "cf0171fa"], "d": ["Selama ekspedisi Iran (Nakhchivan) ketiga Kanuni, sancak Bayezid kembali dibawa ke pemerintahan Utsmaniyah. Pada ekspedisi 1554 Bayazıt menjadi pangkalan penting bagi pasukan; sancak masuk secara pasti ke kedaulatan Utsmaniyah pada 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Hilangnya Revan ke Syah Abbas", "34413cf2"], "d": ["Ketika front timur tak terlindungi pada tahun-tahun ketika pemberontakan Celali mengunci Anatolia, Syah Abbas, yang menata ulang pasukannya ala Eropa, beralih ke serangan. Benteng Revan, yang dibangun Ferhad Paşa pada 1583, menyerah setelah dikepung tujuh bulan. Mata rantai pertama garis Kaukasus yang diperoleh dengan Perjanjian Ferhad Paşa telah terputus dan dalam tiga tahun berikutnya seluruh Kaukasus Selatan akan lepas.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Hilangnya Tiflis dan Ganja", "3fb51753"], "d": ["Setelah jatuhnya Revan, pasukan Safawi maju di sepanjang lembah Kura; Ganja, pusat Karabakh, dan Tiflis, ibu kota Georgia, lepas berturut-turut. Negara Utsmaniyah pada saat yang sama menjalankan perang panjang tiga belas tahun di front Austria dan menghadapi Celali di Anatolia; tidak ada pasukan yang dapat dikirim ke timur. Dengan demikian tatanan eyalet-eyalet Kaukasus luas yang didirikan dengan Perjanjian Ferhad Paşa 1590 berakhir secara faktual.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Hilangnya Şirvan — Şamahı, Baku, dan Derbent", "81beab11"], "d": ["Eyalet Şirvan di pesisir Kaspia, yang diperoleh dengan ekspedisi Özdemiroğlu Osman Paşa 1578-1585, telah memberi keuangan Utsmaniyah pendapatan penting sebagai sumber utama perdagangan sutra. Operasi Syah Abbas yang berpaling ke utara melikuidasi eyalet ini dengan merebut Şamahı, Baku, dan Derbent berturut-turut. Kehilangan itu bukan hanya wilayah: jalur sutra Iran yang mengalir ke Eropa melalui Utsmaniyah juga keluar dari kendali dan Negara Safawi mulai memasarkan sutra melalui Samudra Hindia.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Hilangnya Taiz", "65f20d53"], "d": ["Utsmaniyah pada 1038 (1629) meninggalkan Taiz bersama kekuasaan di Yaman yang diserahkan kepada pemerintahan Kasimi di Sana'a — langkah besar pertama proses ketika imam-imam Zaidi merebut kembali Yaman pedalaman.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Hilangnya Yaman — kekuasaan imam-imam Kasimi", "49e83e3c"], "d": ["Yaman adalah eyalet Utsmaniyah sejak 1538; namun perlawanan imam-imam Zaidi tidak pernah berhenti. Pemberontakan yang dimulai Imam Kasim menjalar ke seluruh negeri pada masa putranya el-Müeyyed Muhammed dan garnisun-garnisun Utsmaniyah dikepung satu per satu. Pada tahun-tahun ketika Murad IV berfokus pada Baghdad dan Revan, bala bantuan tidak dapat dikirim; Taiz lepas pada 1629, sedangkan Mocha dikosongkan pada tahap akhir keruntuhan yang sama pada 22 Oktober 1635. Pada 1635 unit-unit terakhir di Sana'a dan Zabid juga mengosongkan Yaman. Dengan demikian pesisir timur Laut Merah tetap di luar kekaisaran selama dua ratus tiga puluh tujuh tahun dan baru dapat direbut kembali pada 1872. Lahij (el-Havta), menurut TDV İslâm Ansiklopedisi, berada di tangan Utsmaniyah hingga 1635; sejak tanggal itu imam-imam Zaidi berpengaruh.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Pengosongan Mocha", "c6b3061a"], "d": ["Mustafa Bey mengosongkan Mocha dengan pasukan dan senjata yang tersisa pada 10 Cemâziyelevvel 1045 (22 Oktober 1635); kemudian Hasan b. Kasim, putra Imam Kasim, mengangkat orang-orangnya sendiri di Zabid dan Mocha dan membangun kendali Kasimi juga di jalur pesisir Tihama.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Hilangnya Lahsa ke Emirat Bani Khalid", "a9b6131a"], "d": ["Lahsa adalah eyalet yang didirikan pada 1550 untuk menutup pesisir barat Teluk Basra bagi Portugis; namun ia sangat jauh dari Istanbul, di ujung satu jalan gurun. Pada tahun-tahun ketika pengepungan Kreta menguras sumber daya, suku Bani Khalid di wilayah itu di bawah pimpinan Barrak b. Ghurayr mengeluarkan garnisun Utsmaniyah dan mendirikan emiratnya sendiri. Pesisir barat teluk tetap di emirat-emirat suku selama satu setengah abad; pada 1795 beralih ke Saudi dan pada 1871 akan kembali ke Utsmaniyah.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Hilangnya Preveze dan Vonitsa ke Venesia — terbukanya pesisir Epirus", "1201204c"], "d": ["Venesia, yang bergabung ke Liga Suci, sebelum memulai ekspedisi Mora merebut dua benteng yang menguasai mulut Teluk Ambrakia: Preveze dan Vonitsa di tepi seberang. Pada musim panas yang sama Ayamavra (Lefkada) juga jatuh. Ketiga posisi ini memungkinkan armada memasuki pedalaman Yunani dari Laut Ionia dengan aman dan menjadi pangkalan operasi Mora yang akan dimulai pada tahun berikutnya. Preveze dan Vonitsa juga ditinggalkan kepada Venesia di Passarowitz; baru akan kembali ke pemerintahan Utsmaniyah pada 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Hilangnya Szolnok — terurainya garis Tisza", "51c2c8ef"], "d": ["Setelah jatuhnya Uyvar pada bulan Agustus, pasukan Habsburg berbalik ke selatan dan merebut Szolnok, kepala jembatan di Sungai Tisza. Kota itu adalah satu-satunya lintasan aman antara Buda dan Transilvania; hilangnya berarti terputusnya benteng-benteng Utsmaniyah di separuh timur Hongaria satu sama lain. Terputusnya jalur pasokan dalam pengepungan Buda pada tahun berikutnya menjadi penentu.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Hilangnya Modon ke Venesia", "114c9cc0"], "d": ["Modon di ujung barat daya semenanjung Mora adalah pelabuhan yang hilang bagi Venesia tiga abad sebelumnya dan disebut 'salah satu dari dua mata negara'. Benteng yang dikepung setelah jatuhnya Koron diterima penyerahannya dengan digempur dari darat dan laut sekaligus. Operasi Mora Morosini dengan demikian merebut seluruh pesisir barat semenanjung dan jalan yang membuka ke pedalaman terbuka.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Hilangnya Pécs", "99d54cf4"], "d": ["Setelah jatuhnya Buda pada bulan September, pasukan Habsburg turun ke selatan di barat Danube dan merebut Pécs, yang Utsmaniyah sejak masa Kanuni. Kota yang dikenal dengan Masjid Gazi Kâsım Paşa itu adalah salah satu pusat sancak paling berkembang di eyalet Buda. Hilangnya berarti terbukanya jalan yang turun ke dataran Mohács; pada tahun berikutnya kekalahan Mohács Kedua akan terjadi tepat di sini.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Hilangnya Szeged", "9fbee1b2"], "d": ["Szeged, di pertemuan Sungai Tisza dan Maros, adalah gerbang selatan dataran Hongaria dan menguasai jalan ke eyalet Timișoara. Benteng yang dikepung setelah jatuhnya Buda dan Pécs pada musim gugur yang sama segera menyerah. Hilangnya tiga benteng dalam satu musim adalah tanda bahwa struktur administratif Utsmaniyah di Hongaria yang didirikan sejak 1541 mulai runtuh. Atlas menganggap Zenta di tepi Tisza juga beralih dari Utsmaniyah ke pihak Habsburg pada hari yang sama (hari penyerahan khusus Zenta tidak terbaca dalam sumber, hari diambil dari Szeged; TDV zenta: sejak Oktober 1686 pertempuran antara Utsmaniyah dan sekutu di bawah pimpinan Habsburg dimulai — pendekatan yang dinyatakan).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Hilangnya Balyabadra (Patras) — gerbang utara Mora", "b9cff63c"], "d": ["Balyabadra di mulut Teluk Korintus adalah pelabuhan yang mengendalikan lintasan antara Mora dan Rumelia. Setelah pasukan Venesia merebut kota, benteng-benteng di kedua tepi teluk juga jatuh berturut-turut dan semenanjung terisolasi sepenuhnya dari darat. Pada akhir operasi ini seluruh Mora beralih ke Venesia; wilayah itu akan diperintah dengan nama 'Regno di Morea' hingga 1715.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Gördüs (Korintus) ditinggalkan kepada Venesia", "9a25b6b9"], "d": ["Setelah jatuhnya Balyabadra, Korintus ditinggalkan kepada Venesia dengan perdamaian dan penduduk Muslim meninggalkan kota. Pada Agustus 1687 pasukan Morosini berkumpul di Korintus untuk ekspedisi Athena.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Hilangnya Eger", "983391aa"], "d": ["Eger direbut pada 1596 dalam ekspedisi yang diikuti Mehmed III sendiri dan menjadi pusat sebuah eyalet dengan namanya sendiri. Benteng Utsmaniyah besar terakhir di Hongaria Utara ini, yang sepenuhnya terkepung setelah kekalahan Mohács Kedua, bertahan satu tahun dan menyerah karena kelaparan. Dengan hilangnya, sayap utara Negara Utsmaniyah di Hongaria dilikuidasi sepenuhnya.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Hilangnya Székesfehérvár — kota penobatan raja-raja Hongaria", "c6147255"], "d": ["Kota tempat raja-raja Hongaria dimahkotai dan dimakamkan selama berabad-abad itu direbut Kanuni pada 1543 dan menjadi salah satu pusat sancak terpenting eyalet Buda. Sekitar dua tahun setelah jatuhnya Buda, benteng yang lingkungannya terputus sepenuhnya menyerah. Dengan kehilangan ini keberadaan Utsmaniyah di barat Danube terhimpit ke sekitar Srem dan Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Hilangnya Szigetvár", "834910a7"], "d": ["Szigetvár adalah benteng tempat Sultan Süleyman Kanuni wafat pada 1566 dalam ekspedisi ketiga belas dan terakhirnya ketika pengepungan masih berlangsung; karena itu ia memiliki tempat simbolis dalam ingatan Utsmaniyah. Seratus dua puluh tiga tahun kemudian, setelah semua benteng di sekitarnya jatuh, benteng yang dilindungi rawa-rawa juga menyerah. Makam tempat organ dalam Kanuni dimakamkan dan kota kecil di sekitarnya dirobohkan setelah beralih ke pemerintahan Habsburg. Permukiman lain dalam atlas yang beralih dari Utsmaniyah ke Habsburg pada tanggal yang sama: Barcs — mengikuti rantai abi-merkez Szigetvár (Bánlaky 0017/1449; pendekatan yang dinyatakan).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Hilangnya Várad", "6cce360d"], "d": ["Várad adalah benteng kunci yang membuka ke Transilvania yang direbut Köprülü Mehmed Paşa pada 1660 dan dijadikan pusat eyalet dengan namanya sendiri. Benteng yang sepenuhnya tinggal sendirian setelah kekalahan Slankamen itu menyerah karena kelaparan setelah blokade hampir dua tahun. Dengan hilangnya, pengaruh Utsmaniyah atas Transilvania berakhir secara faktual dan kekuasaan Habsburg menetap di timur Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Hilangnya Yanova — tertutupnya jalan Transilvania", "4b5e30d8"], "d": ["Yanova adalah benteng yang direbut pada 1658 dan menguasai hubungan antara Várad dan Timișoara. Segera setelah jatuhnya Várad, ketika lingkungannya terputus, ia juga lepas. Dengan demikian eyalet Timișoara terisolasi sepenuhnya dari utara dan terus ada hingga Karlowitz sebagai satu-satunya wilayah Hongaria yang tetap di tangan Utsmaniyah.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Pendirian pemerintahan vladika di Montenegro — keterpisahan faktual Cetinje", "a924b778"], "d": ["Pada tahun-tahun ketika Perang Liga Suci mengendurkan kendali Utsmaniyah di Balkan, jabatan metropolit di kepala biara Cetinje menjadi jabatan yang diwariskan dari ayah ke anak dalam keluarga Petrović dan wilayah itu secara faktual memperoleh pemerintahan tersendiri. Berkat sulitnya dijangkau pegunungan, vladikat ini bertahan selama dua abad dalam kedudukan tidak sepenuhnya merdeka dan tidak sepenuhnya terikat; kemerdekaannya baru akan diakui secara hukum dengan Perjanjian Berlin 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Direbutnya kembali Gördüs (Korintus)", "26f53e3a"], "d": ["Pemberhentian besar pertama ekspedisi Mora Damad Ali Paşa adalah Korintus; Utsmaniyah merebut kembali kota dari Venesia pada Juni 1715 dan maju dari sini ke sisa semenanjung.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Serangan Nadir: hilangnya Tabriz, Nakhchivan, Hamadan, Kermanshah, Maragheh, dan Qasr-e Shirin", "d95efd59"], "d": ["Kota-kota Iran Barat yang direbut antara 1723-1727 dengan memanfaatkan runtuhnya Negara Safawi hilang satu per satu akibat serangan Nadir Khan, yang menguasai kekuasaan faktual di Iran. Di Azerbaijan, Ardabil dan Khalkhal juga jatuh ke tangan Nadir. Hilangnya Hamadan, Kermanshah, dan Qasr-e Shirin menimbulkan gaung berat di Istanbul; pasukan yang tidak berangkat ke ekspedisi dan menunggu di Üsküdar serta upaya menutupi kehilangan itu menjadi salah satu penyebab langsung Pemberontakan Patrona Halil yang pecah enam minggu kemudian. Atlas menganggap Kotur, yang mengikuti rantai Hoy, juga beralih dari Utsmaniyah ke Safawi pada hari ini (Uluerler 2015, Turkish Studies 10/5, h. 6; hari khusus Kotur tidak ada dalam sumber — pendekatan yang dinyatakan).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Kekalahan Baghavard (Arpaçay) — hilangnya Kaukasus ke Nadir Khan", "4262f54c"], "d": ["Eyalet-eyalet Kaukasus yang direbut pada 1723-1725 dengan memanfaatkan runtuhnya Negara Safawi hanya dapat dipertahankan sepuluh tahun. Nadir Khan, yang menguasai kekuasaan faktual di Iran, menimbulkan kekalahan berat atas pasukan Utsmaniyah di Baghavard dekat Revan; serdar Abdullah Köprülü Paşa tewas di medan perang. Setelah kekalahan itu Revan, Tiflis, Ganja, dan Şirvan dikosongkan dalam hitungan bulan. Perbatasan timur kembali ke garis Qasr-e Shirin 1639, yang akan ditegaskan pada 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Hilangnya Bender ke Rusia", "0daca453"], "d": ["Setelah kekalahan Dataran Kartal, pasukan Utsmaniyah mundur ke selatan Danube dan benteng-benteng antara Moldavia dan Özi tinggal sendirian. Bender, yang menguasai titik penyeberangan Sungai Turla, direbut dengan serbuan setelah pengepungan dua bulan; kota dijarah. Hilangnya benteng memutus mata rantai tengah garis pertahanan Laut Hitam Utara, kemudian Akkirman dan Kili juga jatuh. Di Küçük Kaynarca Bender akan dikembalikan, tetapi akan hilang lagi pada 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Masuknya emirat Sabah di Kuwait ke perlindungan Utsmaniyah", "3584dba0"], "d": ["Menurut entri Kuwait di TDV, dermaga didirikan oleh suku Utub yang datang dari Najd pada awal abad ke-18 dan keluarga Sabah mengambil alih pemerintahan menjelang akhir abad. Pada tahun-tahun yang sama ketika Lahsa jatuh ke tangan Saudi, emirat, yang tidak punya pilihan selain bersandar pada Basra menghadapi tekanan Wahhabi, masuk ke perlindungan Utsmaniyah. Ikatan akan diresmikan pada 1871 dengan penataan Basra oleh Midhat Paşa dan Kuwait dianggap salah satu dari tiga kaza sancak Basra; klaim wilayah Irak di kemudian hari juga bertumpu pada catatan ini.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Hilangnya Makkah ke Wahhabi", "2da23acd"], "d": ["Gerakan Wahhabi yang lahir di Najd beralih ke Hijaz pada masa Saud b. Abdulaziz; setelah Tâif dan Madinah, Makkah juga diterima penyerahannya untuk kedua kali — Amir Makkah Şerif Gālib menyerahkan kota kepada Wahhabi dengan syarat tetap di keamiran. Makam-makam dirobohkan dan jalan kafilah haji dari Damaskus dan Kairo terputus; surre yang dikirim sultan setiap tahun ke Haramain juga terputus pada tahun-tahun ini — satu-satunya pengecualian alokasi yang berlangsung tanpa henti hingga 1915 adalah masa kekuasaan Wahhabi. Karena gelar pelindung Haramain adalah salah satu sandaran dasar legitimasi sultan, kehilangan ini menjadi pukulan politik berat melampaui kehilangan wilayah; merebutnya kembali akan memakan tujuh tahun dan menjadi mungkin dengan pasukan Kavalalı Mehmed Ali Paşa.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Berakhirnya Republik Dubrovnik — pendudukan Prancis", "f8e27bf1"], "d": ["Prancis, yang menetap di pesisir Dalmatia dengan Perjanjian Campo Formio (1797), merebut Dubrovnik pada 27 Mei 1806 dan mengakhiri republik pedagang kecil itu. Dengan demikian status vasal Dubrovnik selama tiga setengah abad, yang mempertahankan otonomi dan imtiyaz dagangnya dengan membayar upeti kepada Utsmaniyah sejak 1458, berakhir; kota dan pulau Mljet milik republik di peta beralih ke pemerintahan Prancis langsung.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Hilangnya Sukhumi ke Rusia — terbukanya pesisir Laut Hitam Timur", "adc96bd4"], "d": ["Dalam perang Utsmaniyah-Rusia 1806-1812, armada Rusia berpaling ke pesisir Laut Hitam Timur dan merebut Sohumkale, tempat kekuasaan Utsmaniyah di Abkhazia bertumpu. Benteng itu adalah pusat hubungan dengan suku-suku Kaukasus dan perdagangan pesisir. Dengan hilangnya, Rusia untuk pertama kalinya menetap secara permanen di pesisir timur Laut Hitam; pengaruh Utsmaniyah di Kaukasus terhimpit ke sekitar Anapa dan Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga ditinggalkan kepada pemerintahan Utsmaniyah", "66e0cc5d"], "d": ["Parga berada di tangan Venesia sejak 1401 dan tidak pernah masuk ke pemerintahan Utsmaniyah; setelah runtuhnya Venesia ia beralih berturut-turut ke Prancis dan Inggris. Entri Tepedelenli Ali Paşa di TDV meringkas keadaan sebagai berikut: kota menyerah kepada Inggris dan baru ditinggalkan kepada pemerintahan Ali Paşa pada 1819. Penyerahan itu berujung pada migrasi sebagian besar penduduknya ke pulau-pulau Ionia. Dengan demikian yang terakhir dari tiga serangkai Preveze-Parga-Vonitsa yang ditinggalkan kepada Venesia di Passarowitz juga bergabung ke kekaisaran; Parga akan tetap Utsmaniyah selama sembilan puluh empat tahun.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Gördüs (Korintus) jatuh ke pemberontak Yunani", "892dcdc6"], "d": ["Selama perang kemerdekaan Yunani, Akrokorintos jatuh ke tangan pemberontak dan komandan benteng Kâmil Bey ditawan.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Hilangnya Anabolu (Nauplion) ke pemberontak", "1a67fa50"], "d": ["Anabolu, pelabuhan dengan benteng terkuat di Mora, menyerah karena kelaparan setelah blokade lebih dari setahun. Benteng itu adalah tumpuan besar terakhir kendali Utsmaniyah di semenanjung sejak awal pemberontakan; dengan hilangnya seluruh Mora jatuh ke tangan pemberontak. Kota itu tak lama kemudian akan menjadi ibu kota pertama negara Yunani baru.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Beralihnya Lepanto (İnebahtı) ke pemerintahan Yunani", "c9d19d4b"], "d": ["Lepanto di pesisir utara Teluk Korintus, yang tetap di tangan Utsmaniyah hingga pemberontakan Yunani, lepas pada April 1829 dan masuk ke pemerintahan Yunani; nama kota diubah menjadi Navpaktos zaman kuno. Penduduk Muslim dan Yahudi kota lenyap sepenuhnya dan tempat itu menjadi kota kecil.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Pendudukan Aljazair oleh Prancis — akhir ocak tiga ratus tahun", "0be8f568"], "d": ["Dengan dalih insiden kipas yang timbul dari sengketa piutang, Prancis memblokade pesisir Aljazair selama tiga tahun, kemudian mendaratkan pasukan di Sidi Ferruch. Pada akhir operasi tiga minggu, Dey Hüseyin menyerah dan Ocak Aljir Utsmaniyah yang berlangsung sejak 1516 berakhir. Pendudukan tidak terbatas pada ibu kota; Tlemcen, Cherchell, dan Medea di pedalaman juga lepas pada musim panas yang sama. Masuknya seluruh pesisir ke kendali Prancis masih akan memakan waktu dua puluh empat tahun lagi.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Eğriboz diberikan kepada Yunani — bersama pulau (Karystos, Oreoi)", "7b524aa4"], "d": ["Eğriboz, yang menjadi panggung pertempuran sengit selama perang kemerdekaan Yunani tetapi tetap di tangan Utsmaniyah, diberikan kepada Yunani pada 1831 setelah perjanjian damai berlaku. Penduduk Muslim kota yang sejak 1470 merupakan pangkalan laut penting itu menjual semua harta mereka dengan harga sangat murah dan bermigrasi bersama-sama ke wilayah Utsmaniyah; kota lama kosong dan pelancong Jerman Fallmerayer pada 1842 menyebutnya kota hantu.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Pendudukan Oran (Vehrân) oleh Prancis", "a8415d66"], "d": ["Oran, yang diserahkan Spanyol tanpa perang pada 1792, adalah pelabuhan terbesar di Aljazair barat. Enam bulan setelah jatuhnya ibu kota, pasukan Prancis memasuki kota. Operasi barat yang dimulai dari sini dalam waktu singkat akan menemui perlawanan Emir Abdelkader selama lima belas tahun.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Pendudukan Annaba (Bône)", "21f37fb1"], "d": ["Annaba, pelabuhan Aljazair timur dekat perbatasan Tunisia, direbut pasukan Prancis dan dijadikan pangkalan pawai ke Konstantin. Kota itu sekaligus pelabuhan Afrika terdekat di seberang Pulau Sardinia.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Penyerahan Athena kepada negara Yunani baru (hari pasukan Bavaria menerima penyerahan Akropolis)", "deee4d37"], "d": ["Athena, yang Utsmaniyah sejak 1456, berpindah tangan beberapa kali selama perang kemerdekaan Yunani, dan garnisun di Akropolis kembali ke kendali Utsmaniyah pada 1827. Karena berada di utara perbatasan yang ditarik Protokol London, kota diserahkan kepada kerajaan baru dan garnisun mengosongkan Akropolis. Hari atlas adalah hari pasukan Bavaria menerima penyerahan Akropolis; keluarnya garnisun Utsmaniyah secara faktual terjadi beberapa hari kemudian (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, bab 13; Finlay, Journals and Letters, jil. I, h. 67). Pada tahun berikutnya Athena dinyatakan ibu kota Yunani menggantikan Anabolu.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Pendudukan Bejaia (Bougie)", "a8927e00"], "d": ["Pelabuhan Bejaia, tempat Pegunungan Kabylie terbuka ke laut, adalah mata rantai merdeka terakhir garis pesisir antara Aljir dan Annaba. Ia direbut dengan dukungan artileri laut; namun pedalaman pegunungan di belakangnya tidak akan masuk ke kendali Prancis selama tiga puluh tahun lagi. Pendudukan sepanjang pesisir ini membentuk menyusutnya Aljazair Utsmaniyah di peta tahun demi tahun.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Pendudukan Sétif", "2073731a"], "d": ["Setelah jatuhnya Konstantin setahun sebelumnya, pasukan Prancis naik ke dataran tinggi dan merebut kota Romawi lama Sétif serta mendirikan garnisun permanen di sana. Sétif adalah titik pertemuan jalan kafilah antara pesisir dan Sahara; pendudukannya menunjukkan bahwa Prancis kini mulai mengendalikan bukan hanya pelabuhan tetapi juga jaringan dagang pedalaman.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Pendudukan Biskra — hilangnya gerbang Sahara", "d895cad0"], "d": ["Biskra adalah gerbang yang membuka ke Sahara di kaki selatan Pegunungan Atlas dan pusat oasis kurma. Dengan direbutnya pada tahun-tahun ketika perlawanan Emir Abdelkader mulai patah, kendali Prancis untuk pertama kalinya mencapai tepi utara gurun. Sesudahnya akan berupa operasi gurun yang maju oasis demi oasis.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Pendudukan Touggourt — hilangnya seluruh Aljazair", "33c056e2"], "d": ["Dengan direbutnya kota oasis Touggourt di utara Sahara, pendudukan yang dimulai pada 1830 selesai di separuh utara Aljazair saat ini. Pada tahun-tahun ini Negara Utsmaniyah berperang di sisi yang sama dengan Prancis dalam Perang Krimea; meski tidak pernah secara resmi melepaskan klaim hukumnya atas Aljazair, ia secara faktual tidak dapat mengambil satu langkah pun. Satu-satunya wilayah yang tersisa di Afrika Utara adalah Tripolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Jatuhnya El Obeid — beralihnya Kordofan ke pasukan Mahdi", "58299f62"], "d": ["Gerakan yang dimulai Muhammad Ahmad, yang menyatakan dirinya mahdi, menyebar cepat melawan pemerintahan Mesir di Sudan. El Obeid, pusat Kordofan, jatuh setelah pengepungan empat bulan dan menjadi ibu kota pemberontakan; perbendaharaan dan gudang senjata di kota memungkinkan gerakan itu menjadi tentara. Sudan secara hukum masih tanah kekhedivean Mesir yang terikat pada Utsmaniyah, sehingga kehilangan itu jatuh dari tubuh kekaisaran di peta.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Jatuhnya Khartoum — hilangnya seluruh Sudan", "d4b98464"], "d": ["Setelah pengepungan sepuluh bulan, pasukan Mahdi memasuki Khartoum di titik pertemuan Nil Biru dan Nil Putih; gubernur kota Gordon dibunuh dan kolom Inggris yang dikirim untuk membantu terlambat dua hari. Sesudah tanggal ini seluruh Sudan, termasuk Sennar, Dongola, dan Kordofan, tetap di bawah pemerintahan Negara Mahdi selama empat belas tahun. Wilayah itu baru akan masuk ke pemerintahan bersama Inggris-Mesir pada 1899, dengan ikatan Utsmaniyah telah terputus sepenuhnya.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Pendudukan Massawa oleh Italia — hilangnya pesisir barat Laut Merah", "c333b95b"], "d": ["Pelabuhan Massawa, pusat eyalet Habesh, diduduki Italia yang memanfaatkan kekacauan ketika pemberontakan Mahdi menyelimuti Sudan; ini membentuk inti Eritrea Italia. Suakin di utara dan kepulauan Dahlak di lepas pantai juga lepas dalam proses yang sama. Dengan demikian kekuasaan Utsmaniyah di pesisir barat Laut Merah yang berlangsung sejak masa Yavuz Sultan Selim berakhir dan laut kini menjadi perairan yang kedua tepinya milik asing.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Pendudukan Rhodes oleh Italia", "e08662c5"], "d": ["Italia, yang ingin mendudukkan Negara Utsmaniyah ke meja dalam Perang Tripolitania, membawa perang ke Mediterania dan mendaratkan pasukan di Rhodes. Pulau diterima penyerahannya dalam beberapa hari. Rhodes, yang direbut Kanuni dengan pengepungan panjang pada 1522 dan dipertahankan tiga ratus sembilan puluh tahun, dengan demikian berhenti menjadi pangkalan pulau terbesar kekaisaran di Mediterania Timur; meski dianggap pendudukan sementara dalam Perjanjian Ouchy, ia tidak pernah dapat direbut kembali.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Pendudukan Dodekanesos oleh Italia", "200aacf2"], "d": ["Dalam seminggu setelah direbutnya Rhodes, armada Italia juga menduduki pulau-pulau di sekitarnya; kepulauan ini kelak akan diberi nama 'Dodekanesos'. Sebagian besar pulau berjarak beberapa mil dari pesisir Anatolia dan menguasai lintasan tenggara Aegea. Pendudukan dianggap sementara dalam Perjanjian Ouchy sebagai imbalan penyerahan Tripolitania, tetapi Italia tidak pernah mengosongkan pulau-pulau; pada 1947 akan diserahkan kepada Yunani.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Pendudukan İstanköy (Kos)", "ab246c62"], "d": ["İstanköy, mata rantai terakhir operasi Dodekanesos, adalah pulau subur dan ramai tepat di seberang semenanjung Bodrum. Dengan pendudukan itu semua pulau di sudut tenggara Aegea masuk ke kendali Italia dan pesisir barat daya Anatolia dikelilingi dari ujung ke ujung oleh rantai pulau asing.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Proklamasi kemerdekaan Nikaria", "c4452033"], "d": ["Di pulau kecil Nikaria antara Samos dan Sakız, rakyat memberontak dalam suasana ketidakpastian yang ditimbulkan pendudukan Italia, mengeluarkan jandarma Utsmaniyah dari pulau, dan menyatakan 'negara bebas' selama lima bulan dengan benderanya, perangkonya, dan majelisnya sendiri. Pada November 1912 pulau bergabung ke Yunani. Meski kecil, peristiwa ini adalah indikator jelas bagaimana pemerintahan sentral terurai di Aegea.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Keluarnya Samos dari pemerintahan Utsmaniyah", "3a862f2b"], "d": ["Samos adalah emirat otonom yang membayar pajak kepada Utsmaniyah sejak 1832 dan diperintah seorang bey yang diangkat Istanbul. Dalam kekosongan yang ditimbulkan Perang Tripolitania, gerakan pro-persatuan di pulau mengambil alih pemerintahan dan tatanan emirat otonom berakhir secara faktual; pulau menyatakan bergabung dengan Yunani pada tahun yang sama. Pulau ini, dua kilometer dari pesisir Anatolia, menjadi salah satu wilayah pertama yang hilang di Aegea.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Jatuhnya Yanya — hilangnya Epirus dan Parga", "d42fce18"], "d": ["Yanya, yang dikepung lima bulan dalam Perang Balkan, menyerah setelah jatuhnya posisi Bizani; bersama kota, seluruh Epirus beralih ke Yunani. Parga, yang terikat pada sancak Yanya, juga lepas pada tanggal ini dan pemerintahan Utsmaniyah sembilan puluh empat tahun berakhir. Hilangnya Yanya berarti tertutupnya jendela terakhir kekaisaran yang membuka ke Adriatik.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Jatuhnya Edirne ke Bulgaria", "459d2e56"], "d": ["Setelah pengepungan lima setengah bulan, Edirne, yang amunisi dan perbekalannya habis, menyerah; Şükrü Paşa ditawan. Jatuhnya kota yang Utsmaniyah sejak 1361 dan menjadi ibu kota selama sembilan puluh dua tahun itu dianggap pukulan terberat Perang Balkan. Edirne akan direbut kembali empat bulan kemudian dengan memanfaatkan runtuhnya Bulgaria di front-front lain dalam Perang Balkan II.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Hilangnya Yanbu ke pasukan Şerif Hüseyin", "e291c816"], "d": ["Pemberontakan yang dimulai Şerif Hüseyin pada Juni menjalar ke pesisir Laut Merah; Yanbu, pelabuhan Madinah, jatuh ke tangan pemberontak dengan dukungan armada Inggris. Pelabuhan itu menjadi gerbang utama aliran senjata dan uang dari luar kepada pemberontakan. Dengan demikian hubungan laut pasukan Fahreddin Paşa di Madinah terputus dan kota tinggal sendirian di ujung Kereta Api Hijaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Pertempuran Gaza Ketiga — hilangnya Gaza dan Khan Yunus", "c142a069"], "d": ["Setelah dua percobaan gagal, Allenby dalam serangan ketiganya menembus front dengan mengitari Beersheba dan garis Gaza yang dipertahankan enam bulan runtuh. Gaza dan Khan Yunus di selatannya dikosongkan pada hari yang sama. Penembusan ini adalah awal terurainya front Palestina; Yerusalem akan jatuh lima minggu kemudian.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Pendudukan Gümülcine — hilangnya Thrakia Barat", "904d813c"], "d": ["Thrakia Barat, yang pertama masuk ke kendali pasukan Entente setelah Mudros, ditinggalkan kepada Yunani dengan keputusan konferensi San Remo dan pasukan Yunani memasuki Gümülcine. Wilayah yang direbut kembali dari Bulgaria pada 1913 itu menjadi wilayah terakhir yang hilang di Rumelia bagi kekaisaran. Status penduduk Turki di wilayah itu tiga tahun kemudian akan diatur di Lausanne dengan rezim minoritas. Dengan pendudukan ini kaza Gümülcine, İskeçe, Dedeağaç, dan Sofulu di Thrakia Barat beralih ke Yunani.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Terurainya Negara Ilkhan: wafatnya Abu Said Bahadur Khan", "0f187469"], "d": ["Menurut entri İlhanlılar di TDV İslâm Ansiklopedisi, wafatnya Abu Said tanpa meninggalkan pewaris menyebabkan terpecahnya Negara Ilkhan yang menguasai Iran selama satu abad; para emir memanfaatkan perebutan takhta dan mendirikan dinasti-dinasti lokal seperti Jalayir, Kara Koyunlu, Muzaffari, Serbedar Khurasan, dan Eretnaoğulları. Perpecahan ini membagi wilayah menjadi mozaik beylik yang akan berlangsung satu abad; pada akhirnya akan bersatu kembali dengan ekspedisi Timur.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Timur menguasai sebagian besar Iran", "1cee2b82"], "d": ["Menurut entri Timur di TDV İslâm Ansiklopedisi, Timur, yang sejak awal 1380-an melikuidasi satu per satu dinasti-dinasti lokal pasca-Ilkhan seperti Serbedar, Kert, dan Muzaffari, secara faktual menguasai sebagian besar Iran selama 'ekspedisi tiga tahun' 1386-1388; akhir pasti dinasti Muzaffari baru akan diberikan pada 1393. Wilayah itu dengan demikian terikat kembali pada satu otoritas sentral setelah perpecahan satu abad.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Kemenangan Aras: Kara Yûsuf mengalahkan Abu Bakr Mirza dari Timurid", "4b61a75a"], "d": ["Kara Yûsuf, bey Kara Koyunlu yang kembali dari pengasingan setelah wafatnya Timur pada 1405, setelah merebut Avnik dan memiliki kembali wilayahnya di Anatolia Timur, berbaris melawan cucu Timur Abu Bakr Mirza, yang dianggap penguasa Azerbaijan dan dua Irak, dan mengalahkannya di tepi Aras. Kemenangan ini tidak memberikan Tabriz kepada Kara Yûsuf: TDV `tebriz` menulis bahwa kota berada di tangan Abu Bakr Mirza pada 1408; pertempuran yang memberikan Azerbaijan adalah Serdrûd, 13 April 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Kemenangan Serdrûd: Tabriz dan Azerbaijan beralih ke Kara Koyunlu", "1f0a429d"], "d": ["Kara Yûsuf mengalahkan Abu Bakr Mirza dari Timurid untuk kedua kalinya setelah Aras, di Serdrûd dekat Tabriz; kemenangan ini memberi Azerbaijan kepada Kara Koyunlu. Kara Yûsuf kemudian menugaskan Bistam Bey menaklukkan Irak Ajam;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Wabah di Istanbul dan pemindahan istana ke Edirne", "70c7a163"], "d": ["Menurut entri Istanbul di TDV İslâm Ansiklopedisi, permukiman kota yang cepat dan padat menyiapkan landasan bagi menyebarnya penyakit epidemi dari waktu ke waktu; selama wabah 1466 istana dan para pembesar negara untuk sementara mundur ke Edirne. Penduduk kota menderita kerugian serius dalam wabah semacam ini.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan mengakhiri Negara Kara Koyunlu", "ef68399e"], "d": ["Menurut entri Uzun Hasan di TDV İslâm Ansiklopedisi, penguasa Akkoyunlu Uzun Hasan mengalahkan dan membunuh penguasa Kara Koyunlu Cihan Şah di wilayah Bingöl-Sancak pada 12 Rebîülâhir 872 / 10 November 1467; putra Cihan Şah, Hasan Ali, dikalahkan di Merend pada September 1468 dan dibunuh di depan Hamadan pada April-Mei 1469 dan Negara Kara Koyunlu diakhiri secara pasti. Wilayah beralih ke kekuasaan Akkoyunlu; negara itu dalam sepuluh tahun berikutnya akan meluas hingga pedalaman Iran.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Dibukanya madrasah-madrasah Sahn-ı Semân untuk pengajaran", "021f2a83"], "d": ["Menurut entri Sahn-ı Semân di TDV İslâm Ansiklopedisi, delapan madrasah yang didirikan dalam Kompleks Fâtih ini dirancang sebagai lembaga pengajaran tertinggi pada zamannya dan membentuk puncak hierarki ilmiye Utsmaniyah. Menjadi müderris dan lulus dari sini pada abad-abad berikutnya dianggap tingkat paling bergengsi dalam karier kadi dan müderris.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Selesainya Istana Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Menurut entri Istana Topkapı di TDV İslâm Ansiklopedisi, sumber-sumber zaman itu berbeda tentang tanggal mulai dan selesainya pembangunan; menurut tanggal 883 (1478) pada inskripsi Bâb-ı Hümâyun, pembangunan yang mungkin dimulai pada 1465 atas perintah Fâtih sebagian besar telah selesai pada tahun ini dan istana menggantikan pusat negara di istana lama. Dengan demikian sultan pindah ke tempat tinggal baru yang selama tiga abad akan menjadi jantung administratif dan seremonial negara.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Naik takhtanya Bayezid II di Istanbul", "9b686d04"], "d": ["Menurut entri Bayezid II di TDV İslâm Ansiklopedisi, Şehzade Bayezid, sancak beyi Amasya, dengan cepat datang ke Istanbul atas kabar wafatnya ayahnya dan naik takhta; ia mengalahkan keberangkatan saudaranya Cem dari Konya dengan dukungan janisari. Pada saat naik takhta dibagikan hadiah naik takhta yang menjadi kebiasaan kepada janisari. Pergantian takhta ini juga menyulut perebutan antara kedua saudara.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Sultan Cem menyatakan dirinya sultan di Bursa", "b355168a"], "d": ["Menurut entri Sultan Cem di TDV İslâm Ansiklopedisi, Cem, yang tiba di Bursa melalui Karaman, merebut kota, menyatakan dirinya sultan, dan mengumandangkan khutbah. Kesultanan singkat ini berakhir ketika pasukan yang dikirim kakaknya Bayezid II mengalahkan Cem di Yenişehir. Setelah kekalahan itu Cem terpaksa melarikan diri ke arah Mesir.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Eksekusi Gedik Ahmed Paşa", "6d75a58c"], "d": ["Menurut entri Gedik Ahmed Paşa di TDV İslâm Ansiklopedisi, paşa yang dikenal dengan ekspedisi Otranto dan jabatan wazir agungnya itu dieksekusi di Edirne atas perintah Bayezid II karena sikapnya dalam persoalan Sultan Cem dan kekhawatiran atas pengaruhnya. Wafatnya salah satu komandan paling berpengalaman masa Fâtih itu menimbulkan gaung luas di istana.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Pendirian percetakan pertama di Istanbul", "04475930"], "d": ["Menurut entri Percetakan di TDV İslâm Ansiklopedisi, bersaudara David dan Samuel ibn Nahmias, pengungsi Yahudi dari Spanyol, mendirikan percetakan pertama yang mencetak dengan huruf Ibrani di Istanbul. Ini tercatat sebagai upaya percetakan pertama yang aktif di wilayah Utsmaniyah; percetakan dengan huruf Turki-Arab baru akan mungkin jauh kemudian, pada abad ke-18.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Syah Ismail merebut Tabriz: berdirinya Negara Safawi", "014d81e6"], "d": ["Menurut entri Safevîler dan Akkoyunlular di TDV İslâm Ansiklopedisi, İsmail, syekh muda tekke Ardabil, dengan pasukan yang dibentuknya dari murid-murid Kızılbaş di Anatolia menimbulkan kekalahan berat atas Sultan Akkoyunlu Elvend di wilayah Nakhchivan; Elvend melarikan diri ke Diyarbekir, İsmail memasuki Tabriz dan duduk di takhta dan menyatakan Syiah Dua Belas Imam sebagai mazhab resmi. Dengan demikian baik kekuasaan Akkoyunlu maupun masa beylik pasca-Ilkhan di wilayah itu tertutup; Negara Safawi yang akan berlangsung tiga abad didirikan.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Gempa 'Kiamat Kecil' di Istanbul", "53e3b1d6"], "d": ["Menurut entri Istanbul di TDV İslâm Ansiklopedisi, gempa kuat yang melanda kota pada masa itu dikenal di kalangan rakyat sebagai 'Kiamat Kecil'; kerusakan berat terjadi pada tembok, masjid, dan banyak bangunan dan banyak korban jiwa jatuh. Atas perintah Bayezid II, mobilisasi perbaikan dan pembangunan skala luas dimulai di kota.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Dimulainya pemberontakan Şahkulu", "3d9a4a90"], "d": ["Menurut entri Şahkulu Baba Tekeli di TDV İslâm Ansiklopedisi, Şahkulu, yang diberi makan propaganda Safawi, menghimpun massa Turkmen luas di sekitarnya di wilayah Teke dan memulai pemberontakan besar bersifat keagamaan-sosial. Pemberontakan itu, sebagai salah satu krisis keamanan dalam negeri paling serius zamannya, mengguncang otoritas sentral negara secara mendalam.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Wafatnya Bayezid II dalam perjalanan ke Dimetoka", "c46e98c9"], "d": ["Mantan sultan, yang meninggalkan Istanbul untuk pergi ke Dimetoka, kota kelahirannya, setelah mundur dari takhta, jatuh sakit di desa Abalar dekat Çorlu ketika maju dengan tandunya yang hanya dapat menempuh 5-6 km sehari, dan wafat pada 25 Rebîülevvel 918 (10 Juni 1512). TDV İslâm Ansiklopedisi menganggap sebab kematian sangat meragukan; menurut beberapa sumber lokal dan asing, kemungkinan ia diracun dibahas. Dengan demikian sultan kedelapan dari keturunan Osman Gazi wafat setelah kesultanan tiga puluh satu tahun.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Eksekusi Şehzade Ahmed atas perintah Yavuz Selim", "65abb2f2"], "d": ["Menurut entri Selim I di TDV İslâm Ansiklopedisi, Şehzade Ahmed, kesayangan ayahnya Bayezid II dan saingan utama untuk takhta, dikalahkan di dataran Yenişehir dalam perebutan yang dilakukannya setelah naik takhtanya saudaranya Selim, dan tertangkap saat melarikan diri dari medan perang dan dibunuh. Dengan peristiwa ini Selim sebagian besar mengakhiri persaingan takhta di antara saudara-saudara dan keponakan-keponakannya.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Paşa diangkat sadrazam", "9c94c1e3"], "d": ["Menurut entri İbrâhîm Paşa, Makbul di TDV İslâm Ansiklopedisi, İbrahim Paşa, yang dinaikkan dari has odabaşı ke beylerbeyi Rumelia dan pada hari yang sama ke wazir agung, menjadi sadrazam pada 13 Şaban 929 (27 Juni 1523). Ini adalah pengangkatan yang belum pernah terlihat, dari dinas istana langsung ke jabatan sadrazam, dan menunjukkan kedekatan luar biasa İbrahim Paşa kepada Kanuni.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hayreddin Paşa diangkat kaptan-ı derya", "a0ff6bab"], "d": ["Menurut entri Barbaros Hayreddin Paşa di TDV İslâm Ansiklopedisi, Hayreddin Paşa, yang dikenal dengan keberhasilannya di Aljir, dipanggil ke Istanbul pada 6 April 1534 dan diangkat sebagai kaptan-ı derya dan beylerbeyi Cezayir-i Bahr-i Sefîd. Pengangkatan ini dianggap awal penataan ulang armada Utsmaniyah dan pelembagaan kekuatan laut di Mediterania.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Paşa menjadi sadrazam untuk pertama kali", "ddfcc014"], "d": ["Menurut entri Rüstem Paşa di TDV İslâm Ansiklopedisi, setelah Hadım Süleyman Paşa dicopot karena perselisihan dengan seorang wazir, Rüstem Paşa diangkat sebagai wazir agung pada 17 Ramadan 951 (2 Desember 1544). Rüstem Paşa, yang kedekatannya dengan istana meningkat berkat pernikahannya dengan Mihrimah Sultan, menjadi dengan jabatan ini salah satu negarawan paling berpengaruh masa Kanuni.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi menjadi şeyhülislâm", "11ed04f8"], "d": ["Menurut entri Ebüssuûd Efendi di TDV İslâm Ansiklopedisi, Ebüssuûd Efendi, yang delapan tahun menjabat kazasker Rumelia, diangkat sebagai şeyhülislâm pada Şaban 952 (Oktober 1545) dan bertahan dalam jabatan ini selama dua puluh delapan tahun sebelas bulan. Ebüssuûd Efendi, yang dikenal dengan fatwa-fatwanya yang menyelaraskan kanunname Kanuni dengan hukum syariat, memainkan peran menentukan dalam terbentuknya lembaga hukum dan pendidikan zamannya.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Wafatnya Barbaros Hayreddin Paşa", "3378a0bf"], "d": ["Menurut entri Barbaros Hayreddin Paşa di TDV İslâm Ansiklopedisi, setelah sakit singkat ia wafat di Istanbul pada 6 Cemâziyelevvel 953 (5 Juli 1546). Wafatnya Barbaros, yang dimakamkan di makam yang bersebelahan dengan madrasah yang dibangunnya sendiri di Beşiktaş, dipandang sebagai tutupnya satu masa dalam supremasi Mediterania yang dibangun armada Utsmaniyah.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Dimulainya pembangunan Masjid dan kompleks Süleymaniye", "101ec36f"], "d": ["Menurut entri Masjid dan Kompleks Süleymaniye di TDV İslâm Ansiklopedisi, kompleks yang batu pertamanya diletakkan pada 1550 di bawah arsitek kepala Mimar Sinan dirancang sebagai kompleks sosial besar yang terdiri dari, di samping masjid, madrasah, dârüşşifâ, imaret, dan perpustakaan. Pembangunan itu adalah salah satu program bangunan terbesar yang melambangkan kekuatan kesultanan Kanuni dan pembangunan Istanbul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Gelombang wabah baru dimulai di Istanbul dan sekitarnya", "547d6bf6"], "d": ["Menurut entri Tâun di TDV İslâm Ansiklopedisi, salah satu epidemi abad ke-16 yang memengaruhi dunia Islam terjadi antara 1552-1566 dan terutama berpengaruh di Istanbul, Anatolia, Rumelia, Mesir, dan Afrika Utara. Jalur dagang yang meluas dan meningkatnya mobilitas penduduk dianggap faktor yang memudahkan menyebarnya penyakit epidemi pada masa paling kuat kekaisaran.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Paşa diangkat sadrazam", "a7d7748e"], "d": ["Menurut entri Kara Ahmed Paşa di TDV İslâm Ansiklopedisi, Kara Ahmed Paşa, yang menjabat sebagai wazir kedua, dinaikkan menjadi wazir agung pada 27 Şewal 960 (5 Oktober 1553) setelah sadrazam yang menjabat tiba-tiba dicopot. Perubahan ini menunjuk pada masa ketika keseimbangan kekuatan dalam istana cepat berpindah tangan, bertepatan dengan hari-hari eksekusi Şehzade Mustafa.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Kaptan-ı derya Pîrî Reis dieksekusi", "3b2ad7a0"], "d": ["Menurut entri Pîrî Reis di TDV İslâm Ansiklopedisi, ketika tuduhan bahwa ia menjarah harta kaum Muslim dengan imbalan suap saat mencabut pengepungan Hormuz dan meninggalkan pasukannya di medan perang sampai ke Mesir, pelaut dan kartograf terkenal itu dieksekusi di Kairo pada akhir tahun 960 (akhir 1553). Wafatnya Pîrî Reis, yang hartanya disita, dinilai sebagai akibat persaingan antar-paşa dalam politik laut Basra dan Samudra Hindia pada masa itu.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Paşa dieksekusi, Rüstem Paşa kembali menjadi sadrazam", "9a85076a"], "d": ["Menurut entri Rüstem Paşa dan Kara Ahmed Paşa di TDV İslâm Ansiklopedisi, menggantikan Kara Ahmed Paşa yang tiba-tiba dieksekusi pada sidang divan pada 13 Zulkaidah 962 (29 September 1555), Rüstem Paşa diangkat sebagai sadrazam untuk kedua kalinya pada hari yang sama dengan dukungan Hürrem dan Mihrimah Sultan. Latar belakang peristiwa itu dibiarkan terbuka dalam sumber dan dinilai sebagai hasil intrik dalam istana.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Wafatnya Hürrem Sultan", "1ae998b5"], "d": ["Menurut entri Hürrem Sultan di TDV İslâm Ansiklopedisi, Hürrem Sultan, yang bertahun-tahun memiliki pengaruh besar dalam istana sebagai haseki sultan Kanuni, wafat di Istanbul pada 26 Cemâziyelâhir 965 (15 April 1558) dan dimakamkan di makamnya di kompleks Masjid Süleymaniye. Wafatnya Hürrem Sultan, yang mengukuhkan otoritasnya atas harem setelah wafatnya Valide Sultan Hafsa pada 1534, juga menghilangkan pengaruh penyeimbang di depan persaingan takhta antara putra-putranya Bayezid dan Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokollu Mehmed Paşa naik menjadi sadrazam", "896391a2"], "d": ["Menurut entri Sokollu Mehmed Paşa di TDV İslâm Ansiklopedisi, Sokollu Mehmed Paşa, yang naik menjadi sadrazam atas wafatnya Semiz Ali Paşa pada 30 Zulkaidah 972 (29 Juni 1565), menjadi sadrazam terakhir Kanuni dan melanjutkan jabatan ini juga pada masa Selim II dan Murad III, menjadi salah satu wazir agung yang menjabat paling lama dalam sejarah Utsmaniyah.", "dfe55e0b"]}
});
